INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-1.1_01', 'criminal_jurisprudence', 'Introduction to the Criminal Justice System', 'Which agency is the lead agency in the enforcement of the Comprehensive Dangerous Drugs Act of 2002?', '[{"text": "Philippine National Police (PNP)", "is_correct": false, "rationale": "The PNP keeps an anti-drug unit, but it acts under the coordination of PDEA, not as the lead agency."}, {"text": "National Bureau of Investigation (NBI)", "is_correct": false, "rationale": "The NBI may investigate drug cases, but R.A. 9165 makes PDEA the lead enforcement agency."}, {"text": "Philippine Drug Enforcement Agency (PDEA)", "is_correct": true, "rationale": "Section 82 of R.A. 9165 created PDEA as the implementing arm and lead agency against illegal drugs."}, {"text": "Dangerous Drugs Board (DDB)", "is_correct": false, "rationale": "The DDB is the policy-making and strategy-formulating body; it does not lead enforcement."}]'::jsonb, 2, 'easy', 'R.A. 9165 separates policy (Dangerous Drugs Board) from enforcement, and names PDEA the lead agency in enforcing the law.', 'R.A. 9165, Sec. 82', 'Study module Criminal Law and Jurisprudence, Chapter 1: Introduction to the Criminal Justice System (CLJ-1.1).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-1.1', 'Remembering') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-1.1_02', 'criminal_jurisprudence', 'Introduction to the Criminal Justice System', 'Why is the Bureau of Fire Protection (BFP) counted as a law enforcement agency in the criminal justice system?', '[{"text": "It prosecutes arson cases in court on behalf of the people", "is_correct": false, "rationale": "Prosecution of crimes belongs to the public prosecutor, not to the BFP."}, {"text": "It enforces the Fire Code and investigates the cause of fires, including arson", "is_correct": true, "rationale": "Besides fire suppression, the BFP enforces fire safety laws and conducts fire and arson investigations that support criminal cases."}, {"text": "It decides administrative cases filed against police officers", "is_correct": false, "rationale": "Administrative cases against police officers are handled by bodies such as NAPOLCOM, IAS and PLEB."}, {"text": "It keeps custody of persons convicted of destructive arson", "is_correct": false, "rationale": "Custody of convicted persons is a function of the correction pillar (BuCor, BJMP, provincial jails)."}]'::jsonb, 1, 'easy', 'The BFP belongs to the law enforcement pillar because it enforces the Fire Code and investigates fires and arson.', 'R.A. 6975; R.A. 9514 (Fire Code of the Philippines)', 'Study module Criminal Law and Jurisprudence, Chapter 1: Introduction to the Criminal Justice System (CLJ-1.1).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-1.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-1.2_01', 'criminal_jurisprudence', 'Introduction to the Criminal Justice System', 'During an inquest, what is the main task of the inquest prosecutor?', '[{"text": "To decide whether the arrested person is guilty beyond reasonable doubt", "is_correct": false, "rationale": "Guilt beyond reasonable doubt is decided by the court after trial, not by the prosecutor."}, {"text": "To issue a warrant of arrest against the person arrested", "is_correct": false, "rationale": "Warrants of arrest are issued only by judges."}, {"text": "To conduct the arraignment and receive the plea of the accused", "is_correct": false, "rationale": "Arraignment takes place in court after the information has been filed."}, {"text": "To determine whether a person arrested without a warrant should be charged and kept in custody", "is_correct": true, "rationale": "An inquest is a summary inquiry by the prosecutor into a warrantless arrest to decide whether the person should be charged in court and remain detained."}]'::jsonb, 3, 'easy', 'Inquest applies to warrantless arrests; preliminary investigation, by contrast, is a fuller inquiry into probable cause when the respondent is not under lawful arrest.', 'Rule 112, Rules of Criminal Procedure; DOJ rules on inquest', 'Study module Criminal Law and Jurisprudence, Chapter 1: Introduction to the Criminal Justice System (CLJ-1.2).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-1.2', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-1.3_01', 'criminal_jurisprudence', 'Introduction to the Criminal Justice System', 'An offense is punishable by imprisonment of up to four years. Which court has exclusive original jurisdiction over it?', '[{"text": "Regional Trial Court (second-level court)", "is_correct": false, "rationale": "The RTC tries offenses punishable by imprisonment exceeding six years."}, {"text": "Court of Appeals", "is_correct": false, "rationale": "The Court of Appeals is an appellate court; it does not try such offenses originally."}, {"text": "Municipal or Metropolitan Trial Court", "is_correct": true, "rationale": "First-level courts try offenses punishable by imprisonment not exceeding six years, regardless of the fine."}, {"text": "Sandiganbayan", "is_correct": false, "rationale": "The Sandiganbayan hears graft and related cases of certain high-ranking public officers."}]'::jsonb, 2, 'easy', 'Under B.P. 129 as amended by R.A. 7691, offenses punishable by imprisonment of not more than six years fall within first-level courts.', 'B.P. 129, Sec. 32, as amended by R.A. 7691', 'Study module Criminal Law and Jurisprudence, Chapter 1: Introduction to the Criminal Justice System (CLJ-1.3).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-1.3', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-1.4_01', 'criminal_jurisprudence', 'Introduction to the Criminal Justice System', 'How do the BJMP and the BuCor differ in the criminal justice system?', '[{"text": "BJMP runs district, city and municipal jails; BuCor runs the national penitentiaries", "is_correct": true, "rationale": "The BJMP manages district, city and municipal jails, while BuCor keeps national (insular) prisoners in the penitentiaries."}, {"text": "BJMP runs the national penitentiaries; BuCor runs the city and municipal jails", "is_correct": false, "rationale": "This reverses the two agencies'' mandates."}, {"text": "BJMP supervises probationers; BuCor supervises parolees", "is_correct": false, "rationale": "Probationers and parolees are supervised by the Probation and Parole Administration."}, {"text": "BJMP is under the DOJ; BuCor is under the DILG", "is_correct": false, "rationale": "It is the other way around: the BJMP is under the DILG and BuCor is under the DOJ."}]'::jsonb, 0, 'easy', 'Both belong to the correction pillar, but at different levels: the BJMP for local jails and BuCor for national prisoners sentenced to more than three years.', 'R.A. 6975, Secs. 60-61; R.A. 9263; R.A. 10575', 'Study module Criminal Law and Jurisprudence, Chapter 1: Introduction to the Criminal Justice System (CLJ-1.4).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-1.4', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-2.1_01', 'criminal_jurisprudence', 'Human Rights Education', 'A city ordinance imposes a curfew on all minors but exempts minors who are working students. Under which test is this classification judged against the equal protection clause?', '[{"text": "Whether it gives every resident exactly the same treatment", "is_correct": false, "rationale": "Equal protection does not require identical treatment of everyone; reasonable classification is allowed."}, {"text": "Whether it rests on substantial distinctions germane to the purpose of the law", "is_correct": true, "rationale": "Equal protection allows classification if it rests on substantial distinctions, is germane to the law''s purpose, is not limited to existing conditions, and applies equally to all members of the class."}, {"text": "Whether the minors were given notice and a hearing before it was passed", "is_correct": false, "rationale": "Notice and hearing is the test of procedural due process, not of equal protection."}, {"text": "Whether it was approved by the President before it took effect", "is_correct": false, "rationale": "Presidential approval has nothing to do with the validity of a city ordinance under equal protection."}]'::jsonb, 1, 'hard', 'Due process asks whether the law and the procedure are fair; equal protection asks whether persons are classified on reasonable grounds.', '1987 Constitution, Art. III, Sec. 1', 'Study module Criminal Law and Jurisprudence, Chapter 2: Human Rights Education (CLJ-2.1).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-2.1', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-2.2_01', 'criminal_jurisprudence', 'Human Rights Education', 'A suspect is brought to the station and investigators begin asking him about a robbery. What must they do first?', '[{"text": "Ask him to sign a waiver of his rights before any counsel arrives", "is_correct": false, "rationale": "A waiver of these rights is valid only if made in writing and in the presence of counsel."}, {"text": "Take his sworn statement first and call a lawyer once he has confessed", "is_correct": false, "rationale": "A confession taken without counsel is inadmissible."}, {"text": "Inform him of his right to remain silent and to have competent and independent counsel", "is_correct": true, "rationale": "Before custodial investigation begins, the person must be informed in a language he understands of his right to remain silent and to counsel."}, {"text": "Allow only his immediate family to visit him after the investigation ends", "is_correct": false, "rationale": "R.A. 7438 lets the family, a doctor or a priest visit him at any time during custodial investigation, not only after it ends."}]'::jsonb, 2, 'medium', 'R.A. 7438 and the Constitution protect the person under custodial investigation; violating these rights makes the confession inadmissible and exposes the officer to liability.', '1987 Constitution, Art. III, Sec. 12; R.A. 7438', 'Study module Criminal Law and Jurisprudence, Chapter 2: Human Rights Education (CLJ-2.2).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-2.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-2.3_01', 'criminal_jurisprudence', 'Human Rights Education', 'Police officers without a warrant search a house because a neighbor said drugs might be inside. No one in the house consented. What is the status of the drugs they seized?', '[{"text": "Admissible, because the neighbor gave reliable information", "is_correct": false, "rationale": "A tip alone does not replace a search warrant issued by a judge."}, {"text": "Admissible, because drugs are contraband and may always be seized", "is_correct": false, "rationale": "Contraband found in plain view during a lawful intrusion may be seized, but this search was not lawful to begin with."}, {"text": "Inadmissible only if the owner later pays the court fees", "is_correct": false, "rationale": "Admissibility does not depend on the payment of court fees."}, {"text": "Inadmissible, because the warrantless search was unreasonable", "is_correct": true, "rationale": "A search of a home without a warrant, consent or any recognized exception violates Art. III, Sec. 2, and its fruits are inadmissible under Sec. 3(2)."}]'::jsonb, 3, 'medium', 'The exclusionary rule bars evidence obtained in violation of the right against unreasonable searches and seizures.', '1987 Constitution, Art. III, Secs. 2 and 3(2)', 'Study module Criminal Law and Jurisprudence, Chapter 2: Human Rights Education (CLJ-2.3).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-2.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-2.4_01', 'criminal_jurisprudence', 'Human Rights Education', 'An accused objects to giving his fingerprints, saying it violates his right against self-incrimination. Is his objection correct?', '[{"text": "No, because the right covers only testimonial compulsion, not physical evidence", "is_correct": true, "rationale": "The privilege protects against being compelled to testify or give communicative evidence; taking fingerprints, photographs or blood samples is not covered."}, {"text": "Yes, because the right covers every kind of evidence taken from the accused", "is_correct": false, "rationale": "The right does not extend to the mechanical taking of physical evidence."}, {"text": "Yes, because fingerprints may be taken only after a final conviction", "is_correct": false, "rationale": "Fingerprints may be taken during booking, long before conviction."}, {"text": "No, because the right against self-incrimination applies only to civil cases", "is_correct": false, "rationale": "The right applies to criminal cases and to proceedings where the answer may incriminate."}]'::jsonb, 0, 'hard', 'The right against self-incrimination is limited to testimonial compulsion; it is not violated by examining the body of the accused.', '1987 Constitution, Art. III, Sec. 17', 'Study module Criminal Law and Jurisprudence, Chapter 2: Human Rights Education (CLJ-2.4).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-2.4', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-2.5_01', 'criminal_jurisprudence', 'Human Rights Education', 'A family learns that soldiers took their relative and the authorities deny holding him. Which remedy specifically addresses this threat to his life, liberty and security?', '[{"text": "Writ of habeas data", "is_correct": false, "rationale": "Habeas data protects the right to privacy regarding data gathered about a person."}, {"text": "Writ of kalikasan", "is_correct": false, "rationale": "The writ of kalikasan is for environmental damage affecting two or more cities or provinces."}, {"text": "Writ of amparo", "is_correct": true, "rationale": "The writ of amparo is the remedy for violations or threats to the right to life, liberty and security, including enforced disappearances."}, {"text": "Petition for certiorari", "is_correct": false, "rationale": "Certiorari corrects grave abuse of discretion by a tribunal; it is not a protection writ for disappearances."}]'::jsonb, 2, 'medium', 'Amparo covers extralegal killings and enforced disappearances; habeas corpus covers illegal detention; habeas data covers unlawful data gathering.', 'Rule on the Writ of Amparo, A.M. No. 07-9-12-SC', 'Study module Criminal Law and Jurisprudence, Chapter 2: Human Rights Education (CLJ-2.5).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-2.5', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-3.1_01', 'criminal_jurisprudence', 'Criminal Law (Book 1)', 'Which characteristic of criminal law means that it binds all persons who live or sojourn in the Philippines?', '[{"text": "Generality", "is_correct": true, "rationale": "Generality means penal laws are obligatory on all who live or sojourn in Philippine territory, subject to treaties and international law."}, {"text": "Territoriality", "is_correct": false, "rationale": "Territoriality means penal laws apply to acts committed within Philippine territory."}, {"text": "Prospectivity", "is_correct": false, "rationale": "Prospectivity means penal laws act on the future and not on past acts, unless favorable to the accused."}, {"text": "Legality", "is_correct": false, "rationale": "Legality (nullum crimen sine lege) means no act is a crime unless a law punishes it."}]'::jsonb, 0, 'easy', 'The three main characteristics of criminal law are generality, territoriality and prospectivity.', 'Revised Penal Code, Art. 2; Civil Code, Art. 14', 'Study module Criminal Law and Jurisprudence, Chapter 3: Criminal Law (Book 1) (CLJ-3.1).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-3.1', 'Remembering') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-3.1_02', 'criminal_jurisprudence', 'Criminal Law (Book 1)', 'Under the Revised Penal Code, felonies committed by means of fault are called what?', '[{"text": "Culpable felonies", "is_correct": true, "rationale": "Felonies committed by fault (culpa) result from imprudence, negligence, lack of foresight or lack of skill."}, {"text": "Intentional felonies", "is_correct": false, "rationale": "Intentional felonies are committed by means of deceit (dolo)."}, {"text": "Complex crimes", "is_correct": false, "rationale": "A complex crime is a single act producing two or more felonies, or an offense that is a necessary means to commit another."}, {"text": "Continuing crimes", "is_correct": false, "rationale": "A continuing crime is a series of acts arising from one criminal impulse."}]'::jsonb, 0, 'easy', 'Article 3 classifies felonies into those committed by deceit (dolo) and those committed by fault (culpa).', 'Revised Penal Code, Art. 3', 'Study module Criminal Law and Jurisprudence, Chapter 3: Criminal Law (Book 1) (CLJ-3.1).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-3.1', 'Remembering') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-3.1_03', 'criminal_jurisprudence', 'Criminal Law (Book 1)', 'What do you call a single act that results in two or more grave or less grave felonies?', '[{"text": "Composite crime", "is_correct": false, "rationale": "A composite or special complex crime is one the law treats as a single crime, such as robbery with homicide."}, {"text": "Compound crime", "is_correct": true, "rationale": "Under Article 48, when a single act constitutes two or more grave or less grave felonies, it is a compound crime."}, {"text": "Continued crime", "is_correct": false, "rationale": "A continued crime is a series of acts from a single criminal impulse."}, {"text": "Impossible crime", "is_correct": false, "rationale": "An impossible crime is an act that would be a crime against persons or property but for its inherent impossibility."}]'::jsonb, 1, 'easy', 'Article 48 covers compound crimes (one act, several felonies) and complex crimes proper (one offense as a necessary means to commit another).', 'Revised Penal Code, Art. 48', 'Study module Criminal Law and Jurisprudence, Chapter 3: Criminal Law (Book 1) (CLJ-3.1).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-3.1', 'Remembering') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-3.2_01', 'criminal_jurisprudence', 'Criminal Law (Book 1)', 'A persuaded B with a promise of money to kill C, and B killed C. How are A and B liable?', '[{"text": "A is an accomplice and B is the principal by direct participation", "is_correct": false, "rationale": "An accomplice cooperates through previous or simultaneous acts, but A''s inducement was the determining cause of the crime."}, {"text": "A is an accessory and B is the principal by direct participation", "is_correct": false, "rationale": "Accessories act only after the crime, such as concealing it; A acted before."}, {"text": "Only B is liable because A did not take part in the killing", "is_correct": false, "rationale": "Inducement for a price makes A a principal even if he did not take part in the act itself."}, {"text": "Both are principals: A by induction and B by direct participation", "is_correct": true, "rationale": "Article 17 makes a principal both the one who directly takes part and the one who directly forces or induces another to commit the crime."}]'::jsonb, 3, 'medium', 'There are three kinds of principals: by direct participation, by induction, and by indispensable cooperation.', 'Revised Penal Code, Art. 17', 'Study module Criminal Law and Jurisprudence, Chapter 3: Criminal Law (Book 1) (CLJ-3.2).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-3.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-3.2_02', 'criminal_jurisprudence', 'Criminal Law (Book 1)', 'After a murder, D, who had no part in the crime, buried the victim''s body to keep the police from finding it. What is D''s liability?', '[{"text": "Principal by indispensable cooperation in the murder", "is_correct": false, "rationale": "Indispensable cooperation must happen in the execution of the crime, not after it."}, {"text": "Accomplice, for cooperating in the execution of the murder", "is_correct": false, "rationale": "An accomplice cooperates by previous or simultaneous acts, not by acts after the crime."}, {"text": "Accessory, for concealing the body to prevent discovery of the crime", "is_correct": true, "rationale": "Article 19 makes an accessory one who, after the crime, conceals or destroys the body of the crime to prevent its discovery."}, {"text": "None, because burying a body is not punishable", "is_correct": false, "rationale": "Concealing the body to prevent discovery is a punishable act of an accessory."}]'::jsonb, 2, 'medium', 'Accessories take part after the commission of the crime by profiting from it, concealing it, or helping the principal escape.', 'Revised Penal Code, Art. 19', 'Study module Criminal Law and Jurisprudence, Chapter 3: Criminal Law (Book 1) (CLJ-3.2).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-3.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-3.2_03', 'criminal_jurisprudence', 'Criminal Law (Book 1)', 'E, the wife of a thief, hid the stolen jewelry to protect her husband from arrest; she did not profit from it. Is she criminally liable as an accessory?', '[{"text": "Yes, because concealing the effects of a crime is always punishable", "is_correct": false, "rationale": "The law exempts certain relatives precisely because of their relationship, unless they profited."}, {"text": "No, because a spouse who acts as an accessory without profiting is exempt", "is_correct": true, "rationale": "Article 20 exempts the spouse, ascendants, descendants, siblings and relatives by affinity in the same degrees, except those who profit from the crime."}, {"text": "Yes, but only as an accomplice because she is his wife", "is_correct": false, "rationale": "Her act came after the crime, so she could only be an accessory, and the exemption applies."}, {"text": "No, because concealment of stolen things is not an act of an accessory", "is_correct": false, "rationale": "Concealing the effects of a crime is an act of an accessory under Article 19, but she is exempt under Article 20."}]'::jsonb, 1, 'medium', 'The exemption of relatives in Article 20 does not cover accessories who profit or help the offender profit from the crime.', 'Revised Penal Code, Arts. 19-20', 'Study module Criminal Law and Jurisprudence, Chapter 3: Criminal Law (Book 1) (CLJ-3.2).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-3.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-3.2_04', 'criminal_jurisprudence', 'Criminal Law (Book 1)', 'F and G agreed to rob a store and planned how to do it, but they were arrested before they took any further step. Robbery is not among the felonies where conspiracy is specially punished. What is their liability?', '[{"text": "Attempted robbery, because they had already agreed on the plan", "is_correct": false, "rationale": "An attempt requires overt acts that directly begin the commission of the felony; agreeing and planning are only preparatory."}, {"text": "Frustrated robbery, because only their arrest stopped them", "is_correct": false, "rationale": "A frustrated stage requires all acts of execution to be performed."}, {"text": "None yet, because mere conspiracy to rob is not punishable by law", "is_correct": true, "rationale": "Article 8 punishes conspiracy and proposal only in cases specially provided by law, such as treason, rebellion and sedition, so a bare agreement to rob is not a crime."}, {"text": "Consummated robbery, because conspiracy makes the act of one the act of all", "is_correct": false, "rationale": "Conspiracy as a manner of committing a crime makes the act of one the act of all only once the crime is executed."}]'::jsonb, 2, 'hard', 'Conspiracy may be a crime in itself (only where the law punishes it) or a manner of incurring liability once the planned crime is carried out.', 'Revised Penal Code, Art. 8', 'Study module Criminal Law and Jurisprudence, Chapter 3: Criminal Law (Book 1) (CLJ-3.2).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-3.2', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-3.3_01', 'criminal_jurisprudence', 'Criminal Law (Book 1)', 'H stabbed I in the chest with intent to kill, inflicting a mortal wound, but a doctor saved I''s life through timely surgery. What stage of the felony was committed?', '[{"text": "Attempted homicide", "is_correct": false, "rationale": "An attempt means the offender did not perform all the acts of execution; here he did."}, {"text": "Frustrated homicide", "is_correct": true, "rationale": "The offender performed all the acts of execution that would produce death, but death did not follow because of a cause independent of his will, the medical help."}, {"text": "Consummated homicide", "is_correct": false, "rationale": "The felony is consummated only if the victim dies."}, {"text": "Physical injuries only", "is_correct": false, "rationale": "Intent to kill and a mortal wound make this a homicide case, not mere physical injuries."}]'::jsonb, 1, 'medium', 'In crimes against persons, a mortal wound with intent to kill, followed by survival due to medical aid, is typically the frustrated stage.', 'Revised Penal Code, Art. 6', 'Study module Criminal Law and Jurisprudence, Chapter 3: Criminal Law (Book 1) (CLJ-3.3).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-3.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-3.3_02', 'criminal_jurisprudence', 'Criminal Law (Book 1)', 'Which statement correctly distinguishes the attempted from the frustrated stage of a felony?', '[{"text": "In the attempted stage not all acts of execution are performed; in the frustrated stage all are, but the felony is not produced", "is_correct": true, "rationale": "Article 6 defines the attempted stage by incomplete acts of execution and the frustrated stage by complete acts that fail to produce the felony for causes independent of the offender''s will."}, {"text": "In the attempted stage the felony is produced; in the frustrated stage it is not", "is_correct": false, "rationale": "In both stages the felony is not produced."}, {"text": "The attempted stage needs intent to kill; the frustrated stage does not", "is_correct": false, "rationale": "Intent is required in both stages; the difference lies in the acts of execution."}, {"text": "The attempted stage applies only to crimes against property; the frustrated stage only to crimes against persons", "is_correct": false, "rationale": "Both stages can apply to different kinds of felonies, although some crimes, like theft, have no frustrated stage."}]'::jsonb, 0, 'hard', 'The key difference is whether the offender has performed all the acts of execution.', 'Revised Penal Code, Art. 6', 'Study module Criminal Law and Jurisprudence, Chapter 3: Criminal Law (Book 1) (CLJ-3.3).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-3.3', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-3.3_03', 'criminal_jurisprudence', 'Criminal Law (Book 1)', 'A felony is punishable by arresto menor or a fine not exceeding forty thousand pesos. How is it classified according to gravity?', '[{"text": "Light felony", "is_correct": true, "rationale": "Article 9, as amended by R.A. 10951, defines light felonies as those punishable by arresto menor or a fine not exceeding P40,000, or both."}, {"text": "Less grave felony", "is_correct": false, "rationale": "Less grave felonies are punished with correctional penalties."}, {"text": "Grave felony", "is_correct": false, "rationale": "Grave felonies are punished with capital or afflictive penalties."}, {"text": "Afflictive felony", "is_correct": false, "rationale": "Afflictive is a class of penalty, not a separate class of felony under Article 9."}]'::jsonb, 0, 'hard', 'Felonies are grave, less grave or light depending on the penalty attached to them.', 'Revised Penal Code, Art. 9, as amended by R.A. 10951', 'Study module Criminal Law and Jurisprudence, Chapter 3: Criminal Law (Book 1) (CLJ-3.3).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-3.3', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-3.4_01', 'criminal_jurisprudence', 'Criminal Law (Book 1)', 'J was suddenly attacked with a knife by K. J grabbed a piece of wood and hit K once, disabling him. J did not provoke the attack. Which circumstance applies to J?', '[{"text": "Passion or obfuscation, a mitigating circumstance", "is_correct": false, "rationale": "J acted to repel an attack, not out of a passion that merely reduces liability."}, {"text": "Accident, an exempting circumstance", "is_correct": false, "rationale": "Accident requires a lawful act done with due care that causes injury by mere accident; J acted deliberately to defend himself."}, {"text": "Uncontrollable fear, an exempting circumstance", "is_correct": false, "rationale": "J''s act was a defense against an actual attack, not compulsion by fear of a threatened injury."}, {"text": "Self-defense, a justifying circumstance", "is_correct": true, "rationale": "There was unlawful aggression by K, reasonable necessity of the means J used, and lack of sufficient provocation on J''s part, the three requisites of self-defense."}]'::jsonb, 3, 'medium', 'Justifying circumstances make the act lawful, so the person incurs neither criminal nor civil liability.', 'Revised Penal Code, Art. 11(1)', 'Study module Criminal Law and Jurisprudence, Chapter 3: Criminal Law (Book 1) (CLJ-3.4).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-3.4', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-3.4_02', 'criminal_jurisprudence', 'Criminal Law (Book 1)', 'L, who suffers from a mental illness that totally deprived him of reason at the time, killed his neighbor. Which circumstance applies?', '[{"text": "Self-defense, a justifying circumstance", "is_correct": false, "rationale": "There was no unlawful aggression from the neighbor to justify the act."}, {"text": "Insanity, an exempting circumstance", "is_correct": true, "rationale": "An insane person who acts without a lucid interval is exempt from criminal liability, although civil liability may remain."}, {"text": "Lack of intent, a mitigating circumstance", "is_correct": false, "rationale": "Insanity that totally deprives a person of reason exempts him entirely, not merely mitigates."}, {"text": "Lucid interval, an aggravating circumstance", "is_correct": false, "rationale": "If L had acted during a lucid interval, he would be liable, but a lucid interval is not an aggravating circumstance."}]'::jsonb, 1, 'medium', 'Exempting circumstances recognize that the act is wrongful but the actor lacks intelligence, freedom or intent.', 'Revised Penal Code, Art. 12(1)', 'Study module Criminal Law and Jurisprudence, Chapter 3: Criminal Law (Book 1) (CLJ-3.4).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-3.4', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-3.4_03', 'criminal_jurisprudence', 'Criminal Law (Book 1)', 'After committing homicide, M went to the police station on his own and surrendered before any warrant was issued. How does this affect his liability?', '[{"text": "It is an exempting circumstance that frees him from liability", "is_correct": false, "rationale": "Surrender after the crime cannot remove liability; it only lowers the penalty."}, {"text": "It is a mitigating circumstance of voluntary surrender", "is_correct": true, "rationale": "Article 13(7) treats voluntary surrender to a person in authority or his agents as mitigating when it is spontaneous and the offender is not yet under arrest."}, {"text": "It is a justifying circumstance that makes the killing lawful", "is_correct": false, "rationale": "Nothing in his surrender makes the killing lawful."}, {"text": "It has no effect because he already committed the crime", "is_correct": false, "rationale": "The law rewards spontaneous surrender by mitigating the penalty."}]'::jsonb, 1, 'medium', 'Voluntary surrender is mitigating when the offender has not been arrested, surrenders to a person in authority or an agent, and does so spontaneously.', 'Revised Penal Code, Art. 13(7)', 'Study module Criminal Law and Jurisprudence, Chapter 3: Criminal Law (Book 1) (CLJ-3.4).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-3.4', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-3.4_04', 'criminal_jurisprudence', 'Criminal Law (Book 1)', 'N attacked a sleeping man who had no chance to defend himself, choosing that means so the victim could not resist. What circumstance attended the killing?', '[{"text": "Treachery (alevosia)", "is_correct": true, "rationale": "Treachery exists when the offender employs means that directly and specially ensure the execution of the crime without risk to himself from any defense by the victim."}, {"text": "Evident premeditation", "is_correct": false, "rationale": "Evident premeditation requires proof of a plan, the lapse of sufficient time, and acts showing the offender clung to his decision."}, {"text": "Nighttime", "is_correct": false, "rationale": "Nighttime is aggravating only when purposely sought to facilitate the crime."}, {"text": "Abuse of superior strength", "is_correct": false, "rationale": "Abuse of superior strength involves a notorious disparity of force, not the victim''s helplessness in sleep."}]'::jsonb, 0, 'medium', 'Attacking a sleeping or helpless victim, deliberately chosen to prevent defense, is a classic example of treachery, which qualifies a killing to murder.', 'Revised Penal Code, Art. 14(16)', 'Study module Criminal Law and Jurisprudence, Chapter 3: Criminal Law (Book 1) (CLJ-3.4).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-3.4', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-3.4_05', 'criminal_jurisprudence', 'Criminal Law (Book 1)', 'O, a habitual drunkard, killed a man while intoxicated. How is the intoxication treated?', '[{"text": "As a mitigating circumstance, because drunkenness reduces control", "is_correct": false, "rationale": "Intoxication is mitigating only if it is neither habitual nor subsequent to the plan to commit the felony."}, {"text": "As an exempting circumstance, because he was not in his right mind", "is_correct": false, "rationale": "Intoxication is an alternative circumstance; it never exempts."}, {"text": "As a justifying circumstance, because he acted without intent", "is_correct": false, "rationale": "Intoxication cannot make an unlawful act lawful."}, {"text": "As an aggravating circumstance, because the intoxication is habitual", "is_correct": true, "rationale": "Under Article 15, intoxication is aggravating if it is habitual or intentional (taken to commit the felony)."}]'::jsonb, 3, 'medium', 'Relationship, intoxication and degree of education are alternative circumstances that may aggravate or mitigate depending on the facts.', 'Revised Penal Code, Art. 15', 'Study module Criminal Law and Jurisprudence, Chapter 3: Criminal Law (Book 1) (CLJ-3.4).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-3.4', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-3.4_06', 'criminal_jurisprudence', 'Criminal Law (Book 1)', 'A boat was sinking, so P threw cargo owned by Q overboard to keep the boat afloat and save the passengers. What applies to P?', '[{"text": "Accident, an exempting circumstance with no civil liability", "is_correct": false, "rationale": "The damage was deliberate, not accidental."}, {"text": "Lawful exercise of a right, an exempting circumstance", "is_correct": false, "rationale": "Fulfillment of duty or lawful exercise of a right is a separate justifying circumstance and does not fit these facts."}, {"text": "State of necessity, a justifying circumstance, though civil liability may arise", "is_correct": true, "rationale": "Article 11(4) justifies causing damage to avoid a greater evil that actually exists when there is no less harmful means; the persons benefited may be civilly liable under Article 101."}, {"text": "Obedience to an order, a mitigating circumstance", "is_correct": false, "rationale": "No superior gave P an order."}]'::jsonb, 2, 'medium', 'State of necessity is the justifying circumstance where civil liability remains, borne by those who benefited.', 'Revised Penal Code, Arts. 11(4) and 101', 'Study module Criminal Law and Jurisprudence, Chapter 3: Criminal Law (Book 1) (CLJ-3.4).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-3.4', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-3.5_01', 'criminal_jurisprudence', 'Criminal Law (Book 1)', 'Which of the following totally extinguishes criminal liability?', '[{"text": "Commutation of sentence", "is_correct": false, "rationale": "Commutation only reduces the penalty and is a partial extinction."}, {"text": "Conditional pardon", "is_correct": false, "rationale": "Conditional pardon partially extinguishes liability; violating its conditions revives the penalty."}, {"text": "Parole", "is_correct": false, "rationale": "Parole suspends the service of the rest of the sentence; it does not totally extinguish liability."}, {"text": "Absolute pardon", "is_correct": true, "rationale": "Article 89 lists absolute pardon among the causes of total extinction of criminal liability."}]'::jsonb, 3, 'easy', 'Total extinction (Art. 89) includes death of the convict, service of sentence, amnesty, absolute pardon, prescription of the crime or penalty, and marriage of the offended woman under Art. 344.', 'Revised Penal Code, Arts. 89 and 94', 'Study module Criminal Law and Jurisprudence, Chapter 3: Criminal Law (Book 1) (CLJ-3.5).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-3.5', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-3.5_02', 'criminal_jurisprudence', 'Criminal Law (Book 1)', 'How does amnesty differ from pardon?', '[{"text": "Amnesty is granted only to individuals; pardon is granted to classes of persons", "is_correct": false, "rationale": "Amnesty is usually granted to classes of persons; pardon is granted to individuals."}, {"text": "Amnesty needs Congress''s concurrence and erases the offense; pardon follows conviction", "is_correct": true, "rationale": "Amnesty is a public act, usually for political offenses, granted by the President with the concurrence of a majority of Congress, and it obliterates the offense; pardon is granted by the President after final conviction."}, {"text": "Amnesty is granted by the courts; pardon is granted by Congress", "is_correct": false, "rationale": "Both are executive acts; neither is granted by the courts."}, {"text": "Amnesty restores only civil rights; pardon erases the offense itself", "is_correct": false, "rationale": "Amnesty, not pardon, looks backward and abolishes the offense."}]'::jsonb, 1, 'easy', 'Both are acts of executive clemency under Art. VII, Sec. 19 of the Constitution.', '1987 Constitution, Art. VII, Sec. 19; Revised Penal Code, Art. 89', 'Study module Criminal Law and Jurisprudence, Chapter 3: Criminal Law (Book 1) (CLJ-3.5).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-3.5', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-3.5_03', 'criminal_jurisprudence', 'Criminal Law (Book 1)', 'R was charged with oral defamation, which prescribes in six months. The complaint was filed eight months after the offended party learned of the remarks. What is the effect?', '[{"text": "The accused may still be convicted because the crime is light", "is_correct": false, "rationale": "Prescription extinguishes liability whatever the classification of the offense."}, {"text": "The penalty is only reduced because of the delay", "is_correct": false, "rationale": "Prescription bars the prosecution entirely; it does not merely lower the penalty."}, {"text": "Criminal liability is extinguished by prescription of the crime", "is_correct": true, "rationale": "Under Article 90, oral defamation prescribes in six months, so filing after eight months means the crime has prescribed."}, {"text": "The case must first be referred to the Lupon to stop prescription", "is_correct": false, "rationale": "Barangay conciliation can suspend prescription only while it is pending; it does not revive a crime that has already prescribed."}]'::jsonb, 2, 'medium', 'Article 90 sets periods: 20 years for crimes punished with reclusion perpetua or temporal, 15 years for other afflictive penalties, 10 for correctional penalties (5 for arresto mayor), 1 year for libel, 6 months for oral defamation and slander by deed, and 2 months for light offenses.', 'Revised Penal Code, Arts. 89(5) and 90', 'Study module Criminal Law and Jurisprudence, Chapter 3: Criminal Law (Book 1) (CLJ-3.5).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-3.5', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-3.5_04', 'criminal_jurisprudence', 'Criminal Law (Book 1)', 'S died while his appeal from a conviction for estafa was pending. What happens to his criminal liability and to the civil liability based solely on the crime?', '[{"text": "Only the criminal liability is extinguished; his heirs must pay the civil liability arising from the crime", "is_correct": false, "rationale": "Civil liability arising solely from the crime dies with the accused if he dies before final judgment; other sources of civil liability may be pursued separately."}, {"text": "Neither is extinguished, because he was already convicted by the trial court", "is_correct": false, "rationale": "A conviction on appeal is not yet final."}, {"text": "Only the civil liability is extinguished; the conviction stands", "is_correct": false, "rationale": "The criminal liability is the one first extinguished by death."}, {"text": "Both are extinguished, because he died before final judgment", "is_correct": true, "rationale": "Death before final judgment extinguishes criminal liability and the civil liability based solely on the offense (Art. 89(1))."}]'::jsonb, 3, 'medium', 'Death of the convict extinguishes personal penalties and, if before final judgment, pecuniary penalties and civil liability ex delicto.', 'Revised Penal Code, Art. 89(1)', 'Study module Criminal Law and Jurisprudence, Chapter 3: Criminal Law (Book 1) (CLJ-3.5).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-3.5', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-4.1_01', 'criminal_jurisprudence', 'Criminal Law (Book 2)', 'T killed his legitimate father. What crime did he commit?', '[{"text": "Murder", "is_correct": false, "rationale": "Murder requires a qualifying circumstance and no relationship covered by parricide."}, {"text": "Parricide", "is_correct": true, "rationale": "Article 246 punishes the killing of one''s father, mother, child, legitimate ascendant or descendant, or spouse as parricide."}, {"text": "Homicide", "is_correct": false, "rationale": "Homicide applies when there is no relationship and no qualifying circumstance."}, {"text": "Infanticide", "is_correct": false, "rationale": "Infanticide is the killing of a child less than three days old."}]'::jsonb, 1, 'medium', 'Relationship is the key element of parricide; it must be alleged and proved.', 'Revised Penal Code, Art. 246', 'Study module Criminal Law and Jurisprudence, Chapter 4: Criminal Law (Book 2) (CLJ-4.1).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-4.1', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-4.1_02', 'criminal_jurisprudence', 'Criminal Law (Book 2)', 'U poisoned his co-worker''s coffee to kill him, and the co-worker died. There is no relationship between them. What crime was committed?', '[{"text": "Murder, qualified by the use of poison", "is_correct": true, "rationale": "Article 248 qualifies a killing as murder when committed by means of poison, among other circumstances."}, {"text": "Homicide, because poison is not a qualifying circumstance", "is_correct": false, "rationale": "Poison is expressly listed as a qualifying circumstance of murder."}, {"text": "Parricide, because they worked together", "is_correct": false, "rationale": "Parricide requires a blood or marital relationship covered by Article 246."}, {"text": "Physical injuries resulting in death", "is_correct": false, "rationale": "Intent to kill and death of the victim make this a killing, not mere physical injuries."}]'::jsonb, 0, 'medium', 'Murder is homicide attended by any qualifying circumstance in Article 248, such as treachery, price or reward, poison, fire, evident premeditation or cruelty.', 'Revised Penal Code, Art. 248', 'Study module Criminal Law and Jurisprudence, Chapter 4: Criminal Law (Book 2) (CLJ-4.1).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-4.1', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-4.1_03', 'criminal_jurisprudence', 'Criminal Law (Book 2)', 'A mother killed her two-day-old baby. What crime did she commit?', '[{"text": "Infanticide", "is_correct": true, "rationale": "Article 255 punishes the killing of a child less than three days of age as infanticide."}, {"text": "Parricide", "is_correct": false, "rationale": "Parricide covers killing one''s child, but when the child is less than three days old the law calls it infanticide."}, {"text": "Murder", "is_correct": false, "rationale": "The age of the child makes it infanticide rather than murder."}, {"text": "Abortion", "is_correct": false, "rationale": "Abortion involves the killing of a fetus before birth; the child here was already born."}]'::jsonb, 0, 'medium', 'If the mother kills the child to conceal her dishonor, the penalty is lower, but the crime is still infanticide.', 'Revised Penal Code, Art. 255', 'Study module Criminal Law and Jurisprudence, Chapter 4: Criminal Law (Book 2) (CLJ-4.1).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-4.1', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-4.1_04', 'criminal_jurisprudence', 'Criminal Law (Book 2)', 'V fired a gun at W during an argument without intent to kill. W was not hit. What crime was committed?', '[{"text": "Attempted homicide with a firearm", "is_correct": false, "rationale": "Attempted homicide requires intent to kill."}, {"text": "Grave threats", "is_correct": false, "rationale": "Grave threats involve threatening another with a wrong amounting to a crime, not actually firing at him."}, {"text": "Illegal discharge of firearm", "is_correct": true, "rationale": "Article 254 punishes discharging a firearm against or at another person when there is no intent to kill."}, {"text": "Alarm and scandal", "is_correct": false, "rationale": "Alarm and scandal covers firing a gun in a public place to cause alarm, not firing at a specific person."}]'::jsonb, 2, 'medium', 'The presence or absence of intent to kill separates illegal discharge of firearm from attempted or frustrated homicide.', 'Revised Penal Code, Art. 254', 'Study module Criminal Law and Jurisprudence, Chapter 4: Criminal Law (Book 2) (CLJ-4.1).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-4.1', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-4.1_05', 'criminal_jurisprudence', 'Criminal Law (Book 2)', 'X punched Y, intending only to hurt him, but Y fell, hit his head and died. What is X''s liability?', '[{"text": "Physical injuries only, because he had no intent to kill", "is_correct": false, "rationale": "Liability follows the result when death is the direct, natural and logical consequence of the felonious act."}, {"text": "Homicide, mitigated by lack of intent to commit so grave a wrong", "is_correct": true, "rationale": "One who commits a felony is liable for all its direct consequences (Art. 4), but the lack of intent to cause so grave a wrong is mitigating (Art. 13(3))."}, {"text": "Murder, because the victim died from the attack", "is_correct": false, "rationale": "There is no qualifying circumstance to make it murder."}, {"text": "No liability, because the death was accidental", "is_correct": false, "rationale": "The punch was a felonious act, so the death is not an accident under Article 12(4)."}]'::jsonb, 1, 'hard', 'Article 4 makes the offender liable for the result of his felony, even if different from what he intended (praeter intentionem).', 'Revised Penal Code, Arts. 4 and 13(3)', 'Study module Criminal Law and Jurisprudence, Chapter 4: Criminal Law (Book 2) (CLJ-4.1).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-4.1', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-4.1_06', 'criminal_jurisprudence', 'Criminal Law (Book 2)', 'Which element separates rape by sexual assault from rape by sexual intercourse under Article 266-A?', '[{"text": "The use of force, which is required only in rape by sexual assault", "is_correct": false, "rationale": "Force, threat or intimidation may be present in both kinds of rape."}, {"text": "The age of the victim, which must be below 16 in rape by sexual assault", "is_correct": false, "rationale": "Age below 16 relates to statutory rape, not to the distinction between the two modes."}, {"text": "The sex of the offender, who must be a woman in rape by sexual assault", "is_correct": false, "rationale": "Either kind of rape may be committed by any person under the law; the act is what differs."}, {"text": "The act, such as inserting an object or instrument into the genital or anal orifice", "is_correct": true, "rationale": "Rape by sexual assault is committed by inserting the penis into another''s mouth or anal orifice, or any instrument or object into the genital or anal orifice."}]'::jsonb, 3, 'hard', 'R.A. 8353 reclassified rape as a crime against persons and created rape by sexual assault; R.A. 11648 raised the age for statutory rape to below 16.', 'Revised Penal Code, Art. 266-A, as amended by R.A. 8353 and R.A. 11648', 'Study module Criminal Law and Jurisprudence, Chapter 4: Criminal Law (Book 2) (CLJ-4.1).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-4.1', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-4.1_07', 'criminal_jurisprudence', 'Criminal Law (Book 2)', 'A victim of a mauling was unable to work for 35 days. Which classification of physical injuries applies?', '[{"text": "Less serious physical injuries", "is_correct": false, "rationale": "Less serious physical injuries cover incapacity or medical attendance of 10 days or more but not more than 30 days."}, {"text": "Slight physical injuries", "is_correct": false, "rationale": "Slight physical injuries cover 1 to 9 days of incapacity or medical attendance."}, {"text": "Serious physical injuries", "is_correct": true, "rationale": "Article 263 makes injuries serious when they incapacitate the victim for labor for more than 30 days."}, {"text": "Mutilation", "is_correct": false, "rationale": "Mutilation requires deliberate cutting off of a body part."}]'::jsonb, 2, 'hard', 'The period of incapacity or medical attendance is the usual basis for classifying physical injuries.', 'Revised Penal Code, Arts. 263, 265 and 266', 'Study module Criminal Law and Jurisprudence, Chapter 4: Criminal Law (Book 2) (CLJ-4.1).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-4.1', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-4.1_08', 'criminal_jurisprudence', 'Criminal Law (Book 2)', 'Z shot two persons in separate bursts during one quarrel, killing both, without any qualifying circumstance. How many crimes did he commit?', '[{"text": "One compound crime of double homicide", "is_correct": false, "rationale": "A compound crime requires a single act producing two or more grave or less grave felonies."}, {"text": "One complex crime, because the killings were related", "is_correct": false, "rationale": "A complex crime proper requires one offense to be a necessary means of committing another."}, {"text": "One homicide, because the quarrel was a single event", "is_correct": false, "rationale": "Each killing by a separate act is a separate homicide, even within one event."}, {"text": "Two separate homicides, because there were separate acts", "is_correct": true, "rationale": "Separate acts of shooting, each producing a death, give rise to separate felonies."}]'::jsonb, 3, 'hard', 'Whether the deaths came from a single act or from several acts decides between a compound crime and separate crimes.', 'Revised Penal Code, Arts. 48 and 249', 'Study module Criminal Law and Jurisprudence, Chapter 4: Criminal Law (Book 2) (CLJ-4.1).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-4.1', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-4.2_01', 'criminal_jurisprudence', 'Criminal Law (Book 2)', 'What element distinguishes robbery from theft?', '[{"text": "Violence against or intimidation of persons, or force upon things", "is_correct": true, "rationale": "Robbery is the taking of personal property with violence or intimidation of persons or force upon things; theft is committed without these."}, {"text": "Intent to gain on the part of the offender", "is_correct": false, "rationale": "Intent to gain is an element of both theft and robbery."}, {"text": "Taking of personal property belonging to another", "is_correct": false, "rationale": "Taking personal property of another is common to both."}, {"text": "Absence of the owner''s consent", "is_correct": false, "rationale": "Lack of consent is common to both."}]'::jsonb, 0, 'easy', 'Theft (Art. 308) and robbery (Art. 293) share most elements; the means of taking separates them.', 'Revised Penal Code, Arts. 293 and 308', 'Study module Criminal Law and Jurisprudence, Chapter 4: Criminal Law (Book 2) (CLJ-4.2).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-4.2', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-4.2_02', 'criminal_jurisprudence', 'Criminal Law (Book 2)', 'What is the essential element of estafa?', '[{"text": "Taking of property by force upon things", "is_correct": false, "rationale": "Taking by force upon things is robbery."}, {"text": "Damage caused through deceit or abuse of confidence", "is_correct": true, "rationale": "Estafa under Article 315 requires deceit or abuse of confidence and damage or prejudice capable of pecuniary estimation."}, {"text": "Destruction of property out of hate or revenge", "is_correct": false, "rationale": "Deliberately damaging property is malicious mischief."}, {"text": "Detention of a person to extract money", "is_correct": false, "rationale": "Detaining a person for ransom is kidnapping."}]'::jsonb, 1, 'easy', 'In estafa the victim parts with the property because of the offender''s deceit or abuse of confidence.', 'Revised Penal Code, Art. 315', 'Study module Criminal Law and Jurisprudence, Chapter 4: Criminal Law (Book 2) (CLJ-4.2).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-4.2', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-4.2_03', 'criminal_jurisprudence', 'Criminal Law (Book 2)', 'Five armed men formed a band to commit robberies on the highway. What crime is committed by forming such a band?', '[{"text": "Robbery in band", "is_correct": false, "rationale": "Robbery in band requires an actual robbery committed by more than three armed persons."}, {"text": "Brigandage", "is_correct": true, "rationale": "Article 306 defines brigandage as more than three armed persons forming a band of robbers to commit robbery in the highway, among other purposes; the mere formation is punished."}, {"text": "Illegal assembly", "is_correct": false, "rationale": "Illegal assembly involves a meeting to commit crimes under the RPC, but forming a band of highway robbers is specifically brigandage."}, {"text": "Kidnapping for ransom", "is_correct": false, "rationale": "Kidnapping for ransom requires an actual detention of a person."}]'::jsonb, 1, 'medium', 'In brigandage, the purpose of the band is the gravamen; actual robbery need not be committed.', 'Revised Penal Code, Art. 306; P.D. 532', 'Study module Criminal Law and Jurisprudence, Chapter 4: Criminal Law (Book 2) (CLJ-4.2).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-4.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-4.2_04', 'criminal_jurisprudence', 'Criminal Law (Book 2)', 'A, angry at his neighbor, deliberately destroyed the neighbor''s fence. There was no fire, no taking and no intent to gain. What crime was committed?', '[{"text": "Theft", "is_correct": false, "rationale": "There was no taking with intent to gain."}, {"text": "Malicious mischief", "is_correct": true, "rationale": "Article 327 punishes deliberately causing damage to the property of another, not constituting arson or other crimes involving destruction."}, {"text": "Robbery with force upon things", "is_correct": false, "rationale": "Robbery requires the taking of personal property."}, {"text": "Arson", "is_correct": false, "rationale": "There was no burning, so it is not arson."}]'::jsonb, 1, 'medium', 'Malicious mischief requires deliberate damage to another''s property, done out of hate, revenge or another evil motive.', 'Revised Penal Code, Art. 327', 'Study module Criminal Law and Jurisprudence, Chapter 4: Criminal Law (Book 2) (CLJ-4.2).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-4.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-4.2_05', 'criminal_jurisprudence', 'Criminal Law (Book 2)', 'A private individual kept a minor locked in a room for two days without any legal ground. What crime was committed?', '[{"text": "Serious illegal detention, because the victim is a minor", "is_correct": true, "rationale": "Under Article 267, detention by a private individual is serious when the victim is a minor, whatever the duration."}, {"text": "Slight illegal detention, because it lasted only two days", "is_correct": false, "rationale": "The minority of the victim makes the detention serious even if it lasted less than three days."}, {"text": "Arbitrary detention, because the victim was deprived of liberty", "is_correct": false, "rationale": "Arbitrary detention is committed by a public officer, not a private individual."}, {"text": "Unlawful arrest, because the victim was detained", "is_correct": false, "rationale": "Unlawful arrest involves detaining a person to deliver him to the authorities without legal ground."}]'::jsonb, 0, 'medium', 'Kidnapping and serious illegal detention apply when the detention lasts more than three days, simulates public authority, involves serious injuries or threats to kill, or the victim is a minor, a female or a public officer.', 'Revised Penal Code, Art. 267', 'Study module Criminal Law and Jurisprudence, Chapter 4: Criminal Law (Book 2) (CLJ-4.2).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-4.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-4.2_06', 'criminal_jurisprudence', 'Criminal Law (Book 2)', 'B threatened to kill C unless C paid him P20,000, and C paid. What crime did B commit?', '[{"text": "Robbery with violence against persons", "is_correct": false, "rationale": "Robbery requires taking with immediate violence or intimidation; threats of future harm with a demand are grave threats."}, {"text": "Grave threats, with the condition attained", "is_correct": true, "rationale": "Article 282 punishes threatening another with a wrong amounting to a crime, here death, under a condition such as a demand for money; the penalty is higher when the purpose is attained."}, {"text": "Light coercion", "is_correct": false, "rationale": "Coercion involves preventing or compelling an act by violence or threats, but threats to kill with a demand for money are specifically grave threats."}, {"text": "Estafa through deceit", "is_correct": false, "rationale": "No deceit was used to obtain the money."}]'::jsonb, 1, 'medium', 'Grave threats concern a future wrong amounting to a crime; coercion concerns immediate compulsion.', 'Revised Penal Code, Art. 282', 'Study module Criminal Law and Jurisprudence, Chapter 4: Criminal Law (Book 2) (CLJ-4.2).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-4.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-4.3_01', 'criminal_jurisprudence', 'Criminal Law (Book 2)', 'A police officer detained a person for several hours without any legal ground. What crime did the officer commit?', '[{"text": "Serious illegal detention", "is_correct": false, "rationale": "Illegal detention is committed by private individuals."}, {"text": "Arbitrary detention", "is_correct": true, "rationale": "Article 124 punishes a public officer or employee who detains a person without legal grounds."}, {"text": "Unlawful arrest", "is_correct": false, "rationale": "Unlawful arrest under Article 269 is committed by any person who arrests another to deliver him to the authorities without reasonable ground."}, {"text": "Grave coercion", "is_correct": false, "rationale": "Grave coercion involves compelling or preventing an act, not detention without legal ground by a public officer."}]'::jsonb, 1, 'medium', 'The offender''s status as a public officer is the key element of arbitrary detention.', 'Revised Penal Code, Art. 124', 'Study module Criminal Law and Jurisprudence, Chapter 4: Criminal Law (Book 2) (CLJ-4.3).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-4.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-4.3_02', 'criminal_jurisprudence', 'Criminal Law (Book 2)', 'Armed men who were not passengers or crew boarded a fishing boat in Philippine waters and took its catch by force. What crime was committed?', '[{"text": "Mutiny on the high seas", "is_correct": false, "rationale": "Mutiny is committed by the crew or passengers against the authority of the master."}, {"text": "Robbery in an inhabited place", "is_correct": false, "rationale": "Robbery in an inhabited place concerns houses and buildings, not vessels."}, {"text": "Brigandage", "is_correct": false, "rationale": "Brigandage concerns bands of robbers on land, especially highways."}, {"text": "Piracy in Philippine waters", "is_correct": true, "rationale": "Piracy is committed by persons who are not passengers or members of the crew who attack or seize a vessel or its cargo; P.D. 532 and Article 122 cover Philippine waters."}]'::jsonb, 3, 'medium', 'Piracy is committed by outsiders; mutiny by those on board.', 'Revised Penal Code, Art. 122, as amended by R.A. 7659; P.D. 532', 'Study module Criminal Law and Jurisprudence, Chapter 4: Criminal Law (Book 2) (CLJ-4.3).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-4.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-4.3_03', 'criminal_jurisprudence', 'Criminal Law (Book 2)', 'A barangay tanod on duty was punched by a resident because the tanod was enforcing a curfew. What crime did the resident commit?', '[{"text": "Direct assault, because he attacked an agent of a person in authority performing his duty", "is_correct": true, "rationale": "Article 148 punishes attacking or employing force against a person in authority or his agent while engaged in the performance of official duties; a barangay tanod is an agent of a person in authority."}, {"text": "Slight physical injuries only, because a tanod is a private individual", "is_correct": false, "rationale": "Barangay tanods are agents of persons in authority under the Local Government Code."}, {"text": "Grave coercion, because he resisted the curfew", "is_correct": false, "rationale": "The resident did not compel or prevent an act by violence; he attacked an agent on duty."}, {"text": "Alarm and scandal, because it happened in public", "is_correct": false, "rationale": "Alarm and scandal concerns disturbances of public peace, not assaults on authorities."}]'::jsonb, 0, 'medium', 'The victim''s status and the fact that he was performing his duty make the attack direct assault.', 'Revised Penal Code, Art. 148; R.A. 7160, Sec. 388', 'Study module Criminal Law and Jurisprudence, Chapter 4: Criminal Law (Book 2) (CLJ-4.3).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-4.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-4.3_04', 'criminal_jurisprudence', 'Criminal Law (Book 2)', 'A jail guard, through negligence, left a cell unlocked, and a detainee escaped. What crime did the guard commit?', '[{"text": "Conniving with or consenting to the escape of a prisoner", "is_correct": false, "rationale": "Connivance (Art. 223) requires consent or agreement to the escape, not mere negligence."}, {"text": "Infidelity in the custody of prisoners through negligence", "is_correct": true, "rationale": "Article 224 punishes a public officer whose negligence allows a prisoner under his custody to escape."}, {"text": "Delivering prisoners from jail", "is_correct": false, "rationale": "Delivering prisoners from jail (Art. 156) is committed by an outsider who helps the escape."}, {"text": "Evasion of service of sentence", "is_correct": false, "rationale": "Evasion of service of sentence is committed by the convict who escapes, not by the guard."}]'::jsonb, 1, 'medium', 'Infidelity in the custody of prisoners covers connivance (Art. 223) and negligence (Art. 224) by public officers.', 'Revised Penal Code, Arts. 223-224', 'Study module Criminal Law and Jurisprudence, Chapter 4: Criminal Law (Book 2) (CLJ-4.3).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-4.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-4.3_05', 'criminal_jurisprudence', 'Criminal Law (Book 2)', 'A traffic enforcer agreed to accept P5,000 in exchange for not issuing a ticket he was supposed to issue. What crime did he commit?', '[{"text": "Indirect bribery", "is_correct": false, "rationale": "Indirect bribery is accepting gifts offered by reason of one''s office, without an agreement to perform or refrain from an act."}, {"text": "Qualified bribery", "is_correct": false, "rationale": "Qualified bribery applies to law enforcers who refrain from arresting or prosecuting offenders of crimes punishable by reclusion perpetua or death."}, {"text": "Corruption of public officials", "is_correct": false, "rationale": "Corruption of public officials is the crime of the one who offers the bribe."}, {"text": "Direct bribery", "is_correct": true, "rationale": "Article 210 punishes a public officer who agrees to refrain from doing something which is his official duty in consideration of a gift or promise."}]'::jsonb, 3, 'medium', 'The giver is liable for corruption of public officials (Art. 212); the receiving officer for bribery.', 'Revised Penal Code, Arts. 210-212', 'Study module Criminal Law and Jurisprudence, Chapter 4: Criminal Law (Book 2) (CLJ-4.3).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-4.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-4.4_01', 'criminal_jurisprudence', 'Criminal Law (Book 2)', 'In front of guests at a party, D slapped E to humiliate him. What crime did D commit?', '[{"text": "Grave oral defamation", "is_correct": false, "rationale": "Oral defamation is committed through spoken words."}, {"text": "Intriguing against honor", "is_correct": false, "rationale": "Intriguing against honor is a scheme or plot to blemish reputation, usually by spreading rumors."}, {"text": "Slander by deed", "is_correct": true, "rationale": "Article 359 punishes performing an act, not words, that casts dishonor, discredit or contempt upon another."}, {"text": "Slight physical injuries", "is_correct": false, "rationale": "When the purpose of the slap is to humiliate rather than to injure, it is slander by deed."}]'::jsonb, 2, 'medium', 'The intent to humiliate, shown by the circumstances, makes a slap slander by deed.', 'Revised Penal Code, Art. 359', 'Study module Criminal Law and Jurisprudence, Chapter 4: Criminal Law (Book 2) (CLJ-4.4).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-4.4', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-4.4_02', 'criminal_jurisprudence', 'Criminal Law (Book 2)', 'F secretly spread rumors among neighbors that a teacher was having an affair, without saying where the story came from, to ruin the teacher''s reputation. What crime did F commit?', '[{"text": "Slander by deed", "is_correct": false, "rationale": "Slander by deed requires an act, not the spreading of a story."}, {"text": "Intriguing against honor", "is_correct": true, "rationale": "Article 364 punishes any intrigue whose principal purpose is to blemish the honor or reputation of another, where the source of the defamatory story is hard to trace."}, {"text": "Libel by means of writings", "is_correct": false, "rationale": "Libel requires a public and malicious imputation made in writing or similar means."}, {"text": "Grave scandal", "is_correct": false, "rationale": "Grave scandal concerns highly scandalous conduct offensive to decency, not rumors about another."}]'::jsonb, 1, 'medium', 'Intriguing against honor typically involves gossip or rumor-mongering whose source cannot be determined.', 'Revised Penal Code, Art. 364', 'Study module Criminal Law and Jurisprudence, Chapter 4: Criminal Law (Book 2) (CLJ-4.4).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-4.4', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-4.4_03', 'criminal_jurisprudence', 'Criminal Law (Book 2)', 'A married man kept his mistress in the conjugal dwelling. What crime did he commit?', '[{"text": "Concubinage", "is_correct": true, "rationale": "Article 334 punishes a husband who keeps a mistress in the conjugal dwelling, has sexual intercourse under scandalous circumstances, or cohabits with her elsewhere."}, {"text": "Adultery", "is_correct": false, "rationale": "Adultery is committed by a married woman and the man who knows she is married."}, {"text": "Bigamy", "is_correct": false, "rationale": "Bigamy requires a second marriage while the first is subsisting."}, {"text": "Seduction", "is_correct": false, "rationale": "Seduction involves having sexual intercourse with a woman through abuse of confidence or deceit."}]'::jsonb, 0, 'medium', 'Concubinage and adultery may be prosecuted only upon complaint of the offended spouse.', 'Revised Penal Code, Arts. 333-334 and 344', 'Study module Criminal Law and Jurisprudence, Chapter 4: Criminal Law (Book 2) (CLJ-4.4).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-4.4', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-4.4_04', 'criminal_jurisprudence', 'Criminal Law (Book 2)', 'G, whose first marriage was never annulled or declared void, married H. What crime did G commit?', '[{"text": "Bigamy", "is_correct": true, "rationale": "Article 349 punishes contracting a second or subsequent marriage before the first marriage has been legally dissolved or the absent spouse has been declared presumptively dead."}, {"text": "Concubinage", "is_correct": false, "rationale": "Concubinage concerns a husband''s relations with a mistress, not a second marriage."}, {"text": "Illegal marriage", "is_correct": false, "rationale": "Bigamy is the specific crime for marrying while a prior marriage subsists."}, {"text": "Adultery", "is_correct": false, "rationale": "Adultery concerns sexual relations, not the contracting of marriage."}]'::jsonb, 0, 'medium', 'A judicial declaration of nullity of the first marriage must be obtained before remarrying; otherwise bigamy may be committed.', 'Revised Penal Code, Art. 349', 'Study module Criminal Law and Jurisprudence, Chapter 4: Criminal Law (Book 2) (CLJ-4.4).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-4.4', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-4.4_05', 'criminal_jurisprudence', 'Criminal Law (Book 2)', 'Against her will and with lewd designs, a man took a woman away from her home. What crime did he commit?', '[{"text": "Forcible abduction", "is_correct": true, "rationale": "Article 342 punishes taking away a woman against her will and with lewd designs."}, {"text": "Consented abduction", "is_correct": false, "rationale": "Consented abduction requires the woman''s consent, given within the age limits set by law."}, {"text": "Simple seduction", "is_correct": false, "rationale": "Seduction involves sexual intercourse obtained through deceit or abuse of authority, not a taking away against her will."}, {"text": "Slight illegal detention", "is_correct": false, "rationale": "Lewd designs make the act forcible abduction rather than illegal detention."}]'::jsonb, 0, 'medium', 'Lewd design is the element that makes the taking an abduction rather than another crime against liberty.', 'Revised Penal Code, Art. 342', 'Study module Criminal Law and Jurisprudence, Chapter 4: Criminal Law (Book 2) (CLJ-4.4).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-4.4', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-4.4_06', 'criminal_jurisprudence', 'Criminal Law (Book 2)', 'A married woman had sexual relations with a man who knew she was married. Who may be held liable for adultery?', '[{"text": "Only the married woman", "is_correct": false, "rationale": "The law punishes both participants."}, {"text": "Both the married woman and the man", "is_correct": true, "rationale": "Article 333 punishes both the married woman and the man who has carnal knowledge of her knowing her to be married."}, {"text": "Only the man, as the guilty party", "is_correct": false, "rationale": "Both are liable; the woman is the principal offender in adultery."}, {"text": "Neither, unless a public prosecutor files the complaint", "is_correct": false, "rationale": "Adultery cannot be prosecuted except upon complaint of the offended spouse, who must include both guilty parties."}]'::jsonb, 1, 'medium', 'Under Article 344, the offended spouse must file the complaint against both guilty parties, if both are alive.', 'Revised Penal Code, Arts. 333 and 344', 'Study module Criminal Law and Jurisprudence, Chapter 4: Criminal Law (Book 2) (CLJ-4.4).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-4.4', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-4.5_01', 'criminal_jurisprudence', 'Criminal Law (Book 2)', 'Which law is the Expanded Anti-Trafficking in Persons Act of 2012?', '[{"text": "R.A. 9208", "is_correct": false, "rationale": "R.A. 9208 is the original Anti-Trafficking in Persons Act of 2003."}, {"text": "R.A. 10364", "is_correct": true, "rationale": "R.A. 10364 amended R.A. 9208 and expanded the acts of trafficking in persons; it was later amended again by R.A. 11862."}, {"text": "R.A. 11313", "is_correct": false, "rationale": "R.A. 11313 is the Safe Spaces Act."}, {"text": "R.A. 11053", "is_correct": false, "rationale": "R.A. 11053 is the Anti-Hazing Act of 2018."}]'::jsonb, 1, 'easy', 'Trafficking involves recruitment, transport, harboring or receipt of persons by means such as force, fraud or abuse of power for exploitation.', 'R.A. 9208, as amended by R.A. 10364 and R.A. 11862', 'Study module Criminal Law and Jurisprudence, Chapter 4: Criminal Law (Book 2) (CLJ-4.5).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-4.5', 'Remembering') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-4.5_02', 'criminal_jurisprudence', 'Criminal Law (Book 2)', 'What law punishes catcalling, wolf-whistling and other gender-based sexual harassment in streets and public places?', '[{"text": "R.A. 11313, the Safe Spaces Act", "is_correct": true, "rationale": "R.A. 11313 penalizes gender-based sexual harassment in streets, public spaces, online, workplaces and educational institutions."}, {"text": "R.A. 7877, the Anti-Sexual Harassment Act of 1995", "is_correct": false, "rationale": "R.A. 7877 covers sexual harassment in work, education and training environments involving authority or influence."}, {"text": "R.A. 9262, the Anti-VAWC Act of 2004", "is_correct": false, "rationale": "R.A. 9262 covers violence against women and their children in intimate relationships."}, {"text": "R.A. 11053, the Anti-Hazing Act of 2018", "is_correct": false, "rationale": "R.A. 11053 covers hazing in organizations."}]'::jsonb, 0, 'easy', 'The Safe Spaces Act is also known as the Bawal Bastos Law.', 'R.A. 11313', 'Study module Criminal Law and Jurisprudence, Chapter 4: Criminal Law (Book 2) (CLJ-4.5).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-4.5', 'Remembering') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-4.5_03', 'criminal_jurisprudence', 'Criminal Law (Book 2)', 'Which law is the Anti-Terrorism Act of 2020?', '[{"text": "R.A. 9372", "is_correct": false, "rationale": "R.A. 9372, the Human Security Act of 2007, was repealed by R.A. 11479."}, {"text": "R.A. 11479", "is_correct": true, "rationale": "R.A. 11479 repealed the Human Security Act and is the current Anti-Terrorism Act."}, {"text": "R.A. 10168", "is_correct": false, "rationale": "R.A. 10168 is the Terrorism Financing Prevention and Suppression Act of 2012."}, {"text": "R.A. 10175", "is_correct": false, "rationale": "R.A. 10175 is the Cybercrime Prevention Act of 2012."}]'::jsonb, 1, 'easy', 'R.A. 11479 defines terrorism by its acts and its purposes, such as intimidating the public or seriously destabilizing the country.', 'R.A. 11479', 'Study module Criminal Law and Jurisprudence, Chapter 4: Criminal Law (Book 2) (CLJ-4.5).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-4.5', 'Remembering') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-4.5_04', 'criminal_jurisprudence', 'Criminal Law (Book 2)', 'Under the Anti-Hazing Act of 2018, what is hazing?', '[{"text": "Any initiation rite held by a fraternity without a faculty adviser", "is_correct": false, "rationale": "The presence or absence of a faculty adviser does not define hazing."}, {"text": "Any act of bullying committed against a classmate in school", "is_correct": false, "rationale": "Bullying among students is covered by the Anti-Bullying Act of 2013."}, {"text": "Any act causing physical or psychological harm to a recruit as a condition of admission", "is_correct": true, "rationale": "R.A. 11053 defines hazing as any physical or psychological suffering, harm or injury inflicted on a recruit, neophyte or applicant as a requirement for admission or continued membership."}, {"text": "Any public ridicule of a member of a sorority or fraternity", "is_correct": false, "rationale": "Hazing is defined by its connection to admission or membership, not by mere ridicule."}]'::jsonb, 2, 'easy', 'R.A. 11053 prohibits all forms of hazing and regulates initiation rites that involve no physical or psychological harm.', 'R.A. 11053, amending R.A. 8049', 'Study module Criminal Law and Jurisprudence, Chapter 4: Criminal Law (Book 2) (CLJ-4.5).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-4.5', 'Remembering') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-4.5_05', 'criminal_jurisprudence', 'Criminal Law (Book 2)', 'Under the anti-trafficking law, when is the recruitment of a child for exploitation considered trafficking even without force, fraud or coercion?', '[{"text": "Only when the child is below 12 years old", "is_correct": false, "rationale": "The law protects all persons below 18 years of age, not only those below 12."}, {"text": "Only when the child is taken outside the country", "is_correct": false, "rationale": "Trafficking may be domestic or across borders."}, {"text": "Only when the parents of the child did not consent", "is_correct": false, "rationale": "Consent of the child or the parents is not a defense in child trafficking."}, {"text": "Always; the means need not be proved when the victim is a child", "is_correct": true, "rationale": "R.A. 9208 as amended treats the recruitment, transport or harboring of a child for exploitation as trafficking even if none of the means is used."}]'::jsonb, 3, 'easy', 'A child is a person below 18, or over 18 but unable to fully protect himself because of a disability.', 'R.A. 9208, Secs. 3-4, as amended by R.A. 10364', 'Study module Criminal Law and Jurisprudence, Chapter 4: Criminal Law (Book 2) (CLJ-4.5).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-4.5', 'Remembering') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-5.1_01', 'criminal_jurisprudence', 'Criminal Evidence', 'What quantum of evidence is required to convict an accused in a criminal case?', '[{"text": "Preponderance of evidence", "is_correct": false, "rationale": "Preponderance of evidence is the standard in civil cases."}, {"text": "Substantial evidence", "is_correct": false, "rationale": "Substantial evidence is the standard in administrative and quasi-judicial cases."}, {"text": "Proof beyond reasonable doubt", "is_correct": true, "rationale": "Rule 133, Section 2 requires proof beyond reasonable doubt, or moral certainty, for conviction."}, {"text": "Clear and convincing evidence", "is_correct": false, "rationale": "Clear and convincing evidence is used in certain special matters, not for criminal conviction."}]'::jsonb, 2, 'easy', 'Proof beyond reasonable doubt does not mean absolute certainty; it means moral certainty that convinces an unprejudiced mind.', 'Rules of Court, Rule 133, Sec. 2', 'Study module Criminal Law and Jurisprudence, Chapter 5: Criminal Evidence (CLJ-5.1).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-5.1', 'Remembering') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-5.1_02', 'criminal_jurisprudence', 'Criminal Evidence', 'What is the equipoise rule?', '[{"text": "When the evidence is evenly balanced, the court must order a new trial", "is_correct": false, "rationale": "Balanced evidence leads to judgment against the party with the burden, not to a new trial."}, {"text": "When both parties present the same number of witnesses, the case is dismissed", "is_correct": false, "rationale": "Evidence is weighed, not counted by the number of witnesses."}, {"text": "When the evidence is balanced, the side with the older documents prevails", "is_correct": false, "rationale": "The age of documents does not decide balanced evidence."}, {"text": "When the evidence of both sides is evenly balanced, the party with the burden of proof loses", "is_correct": true, "rationale": "Under the equipoise (equiponderance) rule, evenly balanced evidence means the party with the burden fails; in criminal cases the accused is acquitted."}]'::jsonb, 3, 'easy', 'The rule follows from the presumption of innocence and the burden of proof resting on the prosecution.', 'Rules of Court, Rules 131 and 133', 'Study module Criminal Law and Jurisprudence, Chapter 5: Criminal Evidence (CLJ-5.1).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-5.1', 'Remembering') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-5.2_01', 'criminal_jurisprudence', 'Criminal Evidence', 'A knife recovered from the crime scene is shown to the court so the judge can see it. What form of evidence is it?', '[{"text": "Documentary evidence", "is_correct": false, "rationale": "Documentary evidence consists of writings or materials offered for their contents."}, {"text": "Testimonial evidence", "is_correct": false, "rationale": "Testimonial evidence is given by a witness under oath."}, {"text": "Object evidence", "is_correct": true, "rationale": "Object (real) evidence is addressed to the senses of the court and may be exhibited, examined or viewed."}, {"text": "Hearsay evidence", "is_correct": false, "rationale": "Hearsay concerns out-of-court statements offered for their truth."}]'::jsonb, 2, 'easy', 'The three forms of evidence are object, documentary and testimonial.', 'Rules of Court, Rule 130, Sec. 1 (2019 Revised Rules on Evidence)', 'Study module Criminal Law and Jurisprudence, Chapter 5: Criminal Evidence (CLJ-5.2).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-5.2', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-5.2_02', 'criminal_jurisprudence', 'Criminal Evidence', 'A letter is presented to prove what is written in it. What form of evidence is it?', '[{"text": "Object evidence", "is_correct": false, "rationale": "If the letter were offered to prove its existence or physical condition rather than its contents, it would be object evidence."}, {"text": "Documentary evidence", "is_correct": true, "rationale": "Documents are writings, recordings, photographs or other materials offered as proof of their contents."}, {"text": "Testimonial evidence", "is_correct": false, "rationale": "Testimonial evidence comes from a witness testifying in court."}, {"text": "Circumstantial evidence", "is_correct": false, "rationale": "Circumstantial evidence is a kind of evidence by its relation to the fact, not a form."}]'::jsonb, 1, 'easy', 'The purpose of the offer decides whether a writing is documentary or object evidence.', 'Rules of Court, Rule 130, Sec. 2 (2019 Revised Rules on Evidence)', 'Study module Criminal Law and Jurisprudence, Chapter 5: Criminal Evidence (CLJ-5.2).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-5.2', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-5.3_01', 'criminal_jurisprudence', 'Criminal Evidence', 'A witness testifies that he saw the accused running from the house with a bloody knife moments after a scream, but he did not see the stabbing. What kind of evidence is his testimony as to the killing?', '[{"text": "Direct evidence", "is_correct": false, "rationale": "Direct evidence proves the fact in issue without inference, such as an eyewitness to the stabbing."}, {"text": "Negative evidence", "is_correct": false, "rationale": "Negative evidence is testimony that a fact did not happen or was not observed."}, {"text": "Cumulative evidence", "is_correct": false, "rationale": "Cumulative evidence repeats the same kind of evidence on the same point."}, {"text": "Circumstantial evidence", "is_correct": true, "rationale": "The testimony proves facts from which the main fact, the killing, may be inferred, so it is circumstantial."}]'::jsonb, 3, 'medium', 'Circumstantial evidence may support a conviction if the requisites of Rule 133, Sec. 4 are met.', 'Rules of Court, Rule 133, Sec. 4', 'Study module Criminal Law and Jurisprudence, Chapter 5: Criminal Evidence (CLJ-5.3).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-5.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-5.3_02', 'criminal_jurisprudence', 'Criminal Evidence', 'Two witnesses describe the same robbery in the same way, and a third witness adds a detail that supports their account from a different angle. What is the third witness''s testimony?', '[{"text": "Corroborative evidence", "is_correct": true, "rationale": "Corroborative evidence is additional evidence of a different kind or source tending to prove the same point."}, {"text": "Cumulative evidence", "is_correct": false, "rationale": "Cumulative evidence is additional evidence of the same kind and character on the same point."}, {"text": "Primary evidence", "is_correct": false, "rationale": "Primary evidence refers to the original document under the original document rule."}, {"text": "Rebuttal evidence", "is_correct": false, "rationale": "Rebuttal evidence answers new matters raised by the adverse party."}]'::jsonb, 0, 'medium', 'Corroborative and cumulative evidence are both additional evidence; they differ in whether the new evidence is of a different kind.', 'Rules of Court, Rules 128-133', 'Study module Criminal Law and Jurisprudence, Chapter 5: Criminal Evidence (CLJ-5.3).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-5.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-5.4_01', 'criminal_jurisprudence', 'Criminal Evidence', 'When is evidence admissible?', '[{"text": "When it is relevant and not excluded by the Constitution, the law or the Rules", "is_correct": true, "rationale": "Rule 128, Section 3 makes evidence admissible when it is relevant and competent, meaning not excluded by law or the Rules."}, {"text": "When it is offered by the prosecution in a criminal case against the accused", "is_correct": false, "rationale": "Evidence from either party must meet the same tests of relevance and competence."}, {"text": "When it is notarized or certified by a public officer", "is_correct": false, "rationale": "Notarization affects how a document is authenticated, not the general test of admissibility."}, {"text": "When both parties agree that it is true", "is_correct": false, "rationale": "Admissibility is decided by the court under the Rules, not by agreement of the parties."}]'::jsonb, 0, 'easy', 'Admissibility (relevance and competence) is different from weight (credibility and persuasiveness).', 'Rules of Court, Rule 128, Sec. 3', 'Study module Criminal Law and Jurisprudence, Chapter 5: Criminal Evidence (CLJ-5.4).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-5.4', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-5.4_02', 'criminal_jurisprudence', 'Criminal Evidence', 'Which statement best describes the original document rule?', '[{"text": "Every document must be presented in its original form even if only its existence is in issue", "is_correct": false, "rationale": "The rule applies only when the contents of the document are the subject of inquiry."}, {"text": "When the contents of a document are in issue, the original must be presented, subject to exceptions", "is_correct": true, "rationale": "Rule 130, Section 3 requires the original document when the subject of inquiry is its contents, with listed exceptions such as loss or destruction without bad faith."}, {"text": "Copies are always admissible as long as they are certified by a lawyer", "is_correct": false, "rationale": "Certification by a lawyer does not satisfy the rule."}, {"text": "Oral testimony is preferred over the document when the contents are disputed", "is_correct": false, "rationale": "Oral testimony is not a substitute for the original when the contents are in issue, unless an exception applies."}]'::jsonb, 1, 'easy', 'The 2019 Revised Rules on Evidence renamed the best evidence rule as the original document rule.', 'Rules of Court, Rule 130, Sec. 3 (2019 Revised Rules on Evidence)', 'Study module Criminal Law and Jurisprudence, Chapter 5: Criminal Evidence (CLJ-5.4).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-5.4', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-5.4_03', 'criminal_jurisprudence', 'Criminal Evidence', 'A witness testifies, ''My neighbor told me that the accused stole the cellphone.'' The prosecution offers this to prove the theft. How should the court treat it?', '[{"text": "As direct evidence, because the witness heard it personally", "is_correct": false, "rationale": "The witness personally heard only the statement, not the theft itself."}, {"text": "As admissible, because the neighbor is a trustworthy person", "is_correct": false, "rationale": "Trustworthiness of the declarant does not cure the hearsay problem."}, {"text": "As hearsay, inadmissible to prove the theft unless an exception applies", "is_correct": true, "rationale": "A statement made out of court, offered to prove the truth of what it asserts, is hearsay and generally inadmissible."}, {"text": "As an admission, because it concerns the accused", "is_correct": false, "rationale": "An admission must be the statement of the party himself, not of a neighbor."}]'::jsonb, 2, 'medium', 'A witness may testify only to facts within personal knowledge, unless an exception to the hearsay rule applies.', 'Rules of Court, Rule 130 (hearsay rule, 2019 Revised Rules on Evidence)', 'Study module Criminal Law and Jurisprudence, Chapter 5: Criminal Evidence (CLJ-5.4).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-5.4', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-5.4_04', 'criminal_jurisprudence', 'Criminal Evidence', 'Shortly before dying of stab wounds and knowing he was about to die, the victim named his attacker to a police officer. Is the statement admissible?', '[{"text": "Yes, as a dying declaration, an exception to the hearsay rule", "is_correct": true, "rationale": "A statement about the cause and circumstances of death, made under the consciousness of impending death, is admissible as a dying declaration."}, {"text": "No, because the victim cannot be cross-examined", "is_correct": false, "rationale": "The lack of cross-examination is precisely why the law requires consciousness of impending death as a guarantee of truth."}, {"text": "No, because it was made to a police officer and not to a judge", "is_correct": false, "rationale": "A dying declaration may be made to anyone, not only to a judge."}, {"text": "Yes, but only as proof of the time of death", "is_correct": false, "rationale": "It is admissible to prove the identity of the attacker and the circumstances of death."}]'::jsonb, 0, 'medium', 'The requisites are: it concerns the cause and circumstances of death, made under consciousness of impending death, the declarant was competent, and it is offered in a case involving his death.', 'Rules of Court, Rule 130 (dying declaration, 2019 Revised Rules on Evidence)', 'Study module Criminal Law and Jurisprudence, Chapter 5: Criminal Evidence (CLJ-5.4).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-5.4', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-5.4_05', 'criminal_jurisprudence', 'Criminal Evidence', 'Why is an extrajudicial confession obtained without the assistance of counsel inadmissible even if it is true?', '[{"text": "Because written confessions are always hearsay and cannot be admitted at all", "is_correct": false, "rationale": "A confession of the accused is an admission, which is an exception to the hearsay rule."}, {"text": "Because a confession must always be made in open court", "is_correct": false, "rationale": "Extrajudicial confessions may be admissible if made with the required safeguards."}, {"text": "Because the Constitution excludes confessions taken in violation of custodial rights", "is_correct": true, "rationale": "Art. III, Sec. 12(3) makes any confession or admission obtained in violation of custodial rights inadmissible, whatever its truth."}, {"text": "Because the accused may change his mind before trial", "is_correct": false, "rationale": "A valid confession remains admissible even if the accused later recants."}]'::jsonb, 2, 'hard', 'Competence of evidence includes constitutional exclusions, which apply even to truthful evidence.', '1987 Constitution, Art. III, Sec. 12; R.A. 7438', 'Study module Criminal Law and Jurisprudence, Chapter 5: Criminal Evidence (CLJ-5.4).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-5.4', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-5.4_06', 'criminal_jurisprudence', 'Criminal Evidence', 'Which distinction between the admissibility and the weight of evidence is correct?', '[{"text": "Admissibility is decided by the prosecutor; weight is decided by the judge", "is_correct": false, "rationale": "Both admissibility and weight are decided by the court."}, {"text": "Admissibility depends on the number of witnesses; weight depends on their credibility", "is_correct": false, "rationale": "Neither test depends on the number of witnesses."}, {"text": "Admissibility and weight mean the same thing under the Rules", "is_correct": false, "rationale": "They are distinct concepts; admitted evidence may still carry little weight."}, {"text": "Admissibility concerns whether evidence may be considered; weight concerns how much it proves", "is_correct": true, "rationale": "Admissibility is about relevance and competence; weight is about the persuasiveness or credibility of evidence already admitted."}]'::jsonb, 3, 'hard', 'Evidence may be admitted yet be given little or no weight after the court evaluates it.', 'Rules of Court, Rules 128 and 133', 'Study module Criminal Law and Jurisprudence, Chapter 5: Criminal Evidence (CLJ-5.4).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-5.4', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-5.5_01', 'criminal_jurisprudence', 'Criminal Evidence', 'Under the 2019 Revised Rules on Evidence, when is the testimony of a witness formally offered?', '[{"text": "At the time the witness is called to testify", "is_correct": true, "rationale": "Rule 132, Section 35 requires the offer of testimonial evidence at the time the witness is called to testify, stating its purpose."}, {"text": "After all the documentary exhibits have been marked", "is_correct": false, "rationale": "Documentary and object evidence are offered after the presentation of a party''s testimonial evidence."}, {"text": "Only in the memorandum filed after trial", "is_correct": false, "rationale": "Evidence must be offered during trial, not only in a memorandum."}, {"text": "At the pre-trial conference before any witness testifies", "is_correct": false, "rationale": "Pre-trial is for marking and stipulations, not for the formal offer of testimony."}]'::jsonb, 0, 'easy', 'The court considers no evidence that has not been formally offered, and the purpose of the offer must be specified.', 'Rules of Court, Rule 132, Secs. 34-35', 'Study module Criminal Law and Jurisprudence, Chapter 5: Criminal Evidence (CLJ-5.5).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-5.5', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-5.5_02', 'criminal_jurisprudence', 'Criminal Evidence', 'During direct examination, the prosecutor asks a question that is clearly leading. When should defense counsel object?', '[{"text": "As soon as the ground for objection becomes reasonably apparent", "is_correct": true, "rationale": "Rule 132, Section 36 requires an objection to a question propounded during oral examination to be made as soon as its grounds become reasonably apparent."}, {"text": "Only after the witness has finished the entire testimony", "is_correct": false, "rationale": "Waiting until the end may result in waiver of the objection."}, {"text": "Only during the formal offer of documentary evidence", "is_correct": false, "rationale": "The formal offer of documents is a separate stage."}, {"text": "Within five days after receiving the transcript", "is_correct": false, "rationale": "Objections to questions must be made during the examination, not days later."}]'::jsonb, 0, 'medium', 'Failure to object at the proper time generally waives the objection.', 'Rules of Court, Rule 132, Sec. 36', 'Study module Criminal Law and Jurisprudence, Chapter 5: Criminal Evidence (CLJ-5.5).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-5.5', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-5.6_01', 'criminal_jurisprudence', 'Criminal Evidence', 'Before a private document is received in evidence as authentic, what must be proved?', '[{"text": "Its notarization by a lawyer", "is_correct": false, "rationale": "Notarized documents become public documents; private documents need proof of authenticity instead."}, {"text": "Its due execution and authenticity", "is_correct": true, "rationale": "Rule 132, Section 20 requires proof of due execution and authenticity of a private document, for example by a witness who saw it executed or by evidence of the genuineness of the signature."}, {"text": "Its acceptance by the adverse party", "is_correct": false, "rationale": "The adverse party''s acceptance is not required, although an admission may dispense with proof."}, {"text": "Its registration with a government office", "is_correct": false, "rationale": "Registration is not a general requirement for private documents."}]'::jsonb, 1, 'easy', 'Public documents are generally admissible without further proof of due execution; private documents must be authenticated.', 'Rules of Court, Rule 132, Sec. 20', 'Study module Criminal Law and Jurisprudence, Chapter 5: Criminal Evidence (CLJ-5.6).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-5.6', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-5.6_02', 'criminal_jurisprudence', 'Criminal Evidence', 'A party wants to present a photocopy of a contract to prove its terms, claiming the original was destroyed in a fire. What must the party first show?', '[{"text": "That the original was destroyed without bad faith on the offeror''s part", "is_correct": true, "rationale": "Under the original document rule, secondary evidence of the contents is allowed once the loss or destruction of the original, without bad faith, is shown."}, {"text": "That the photocopy was certified by the barangay captain", "is_correct": false, "rationale": "Certification by a barangay captain does not satisfy the rule."}, {"text": "That the adverse party has seen the photocopy before", "is_correct": false, "rationale": "Prior knowledge of the adverse party is not the test."}, {"text": "That the contract was signed in the presence of the judge", "is_correct": false, "rationale": "Signing in the presence of a judge is not required for contracts."}]'::jsonb, 0, 'medium', 'Secondary evidence may be a copy, a recital of its contents in an authentic document, or testimony, in that order.', 'Rules of Court, Rule 130, Secs. 3 and 5', 'Study module Criminal Law and Jurisprudence, Chapter 5: Criminal Evidence (CLJ-5.6).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-5.6', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-5.7_01', 'criminal_jurisprudence', 'Criminal Evidence', 'When is circumstantial evidence sufficient to convict?', '[{"text": "When at least one strong circumstance points to the accused", "is_correct": false, "rationale": "A single circumstance is not enough under the Rules."}, {"text": "When the accused fails to testify in his own defense", "is_correct": false, "rationale": "The silence of the accused cannot be used against him."}, {"text": "When the circumstances are supported by the sworn testimony of the arresting police officers", "is_correct": false, "rationale": "The source of the evidence does not replace the three requisites."}, {"text": "When there are several proven circumstances that together produce conviction beyond reasonable doubt", "is_correct": true, "rationale": "Rule 133, Section 4 lists these three requisites for conviction on circumstantial evidence."}]'::jsonb, 3, 'easy', 'The circumstances must form an unbroken chain leading to one fair and reasonable conclusion pointing to the accused.', 'Rules of Court, Rule 133, Sec. 4', 'Study module Criminal Law and Jurisprudence, Chapter 5: Criminal Evidence (CLJ-5.7).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-5.7', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-5.7_02', 'criminal_jurisprudence', 'Criminal Evidence', 'Is an extrajudicial confession alone sufficient to convict the accused?', '[{"text": "No, it must be corroborated by evidence of the corpus delicti", "is_correct": true, "rationale": "Rule 133, Section 3 provides that an extrajudicial confession is not sufficient ground for conviction unless corroborated by evidence of the corpus delicti."}, {"text": "Yes, if it was given voluntarily", "is_correct": false, "rationale": "Voluntariness makes it admissible but does not make it sufficient alone."}, {"text": "Yes, if it was written in the accused''s own handwriting", "is_correct": false, "rationale": "Handwriting does not replace proof of corpus delicti."}, {"text": "No, it can never be used as evidence", "is_correct": false, "rationale": "A valid extrajudicial confession is admissible; it simply needs corroboration."}]'::jsonb, 0, 'easy', 'Corpus delicti means that the crime was actually committed, for example the fact of death in a homicide.', 'Rules of Court, Rule 133, Sec. 3', 'Study module Criminal Law and Jurisprudence, Chapter 5: Criminal Evidence (CLJ-5.7).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-5.7', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-6.1_01', 'criminal_jurisprudence', 'Criminal Procedure and Court Testimony', 'A city mayor with salary grade 27 is charged with a graft offense related to his office. Which court has jurisdiction?', '[{"text": "Sandiganbayan", "is_correct": true, "rationale": "The Sandiganbayan has jurisdiction over graft and office-related offenses of officials with salary grade 27 or higher, including city mayors."}, {"text": "Regional Trial Court", "is_correct": false, "rationale": "Office-related cases of officials below salary grade 27 go to the regular trial courts."}, {"text": "Court of Appeals", "is_correct": false, "rationale": "The Court of Appeals is an appellate court."}, {"text": "Municipal Trial Court in Cities", "is_correct": false, "rationale": "First-level courts do not try graft cases of high-ranking officials."}]'::jsonb, 0, 'medium', 'P.D. 1606 as amended by R.A. 10660 defines the jurisdiction of the Sandiganbayan.', 'P.D. 1606, as amended by R.A. 10660', 'Study module Criminal Law and Jurisprudence, Chapter 6: Criminal Procedure and Court Testimony (CLJ-6.1).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-6.1', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-6.1_02', 'criminal_jurisprudence', 'Criminal Procedure and Court Testimony', 'A crime punishable by imprisonment of eight years was committed in Cebu City. Where must the case be filed?', '[{"text": "Municipal Trial Court in Cities of Cebu City", "is_correct": false, "rationale": "First-level courts try offenses punishable by not more than six years."}, {"text": "Regional Trial Court in Manila", "is_correct": false, "rationale": "Venue lies where the crime was committed, not in Manila."}, {"text": "Any court chosen by the offended party", "is_correct": false, "rationale": "The offended party cannot choose the venue; it is fixed by law."}, {"text": "Regional Trial Court in Cebu City", "is_correct": true, "rationale": "Offenses punishable by more than six years fall within the RTC, and venue in criminal cases is where the offense was committed."}]'::jsonb, 3, 'medium', 'In criminal cases venue is jurisdictional: the case must be filed where the offense or any of its essential elements occurred.', 'B.P. 129, as amended; Rules of Court, Rule 110, Sec. 15', 'Study module Criminal Law and Jurisprudence, Chapter 6: Criminal Procedure and Court Testimony (CLJ-6.1).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-6.1', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-6.1_03', 'criminal_jurisprudence', 'Criminal Procedure and Court Testimony', 'Why is venue considered jurisdictional in criminal cases but not in civil cases?', '[{"text": "Because criminal cases are always filed in the Supreme Court", "is_correct": false, "rationale": "Criminal cases are filed in trial courts, not in the Supreme Court."}, {"text": "Because the accused chooses the venue in criminal cases", "is_correct": false, "rationale": "Venue is fixed by law, not chosen by the accused."}, {"text": "Because a criminal court can try only offenses committed within its territory", "is_correct": true, "rationale": "The territorial jurisdiction of a criminal court is limited to offenses committed within it, so improper venue means lack of jurisdiction."}, {"text": "Because civil cases are not governed by the Rules of Court", "is_correct": false, "rationale": "Civil cases are governed by the Rules of Court; there, venue is procedural and may be waived."}]'::jsonb, 2, 'hard', 'Territorial jurisdiction in criminal cases cannot be waived by the parties.', 'Rules of Court, Rule 110, Sec. 15', 'Study module Criminal Law and Jurisprudence, Chapter 6: Criminal Procedure and Court Testimony (CLJ-6.1).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-6.1', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-6.2_01', 'criminal_jurisprudence', 'Criminal Procedure and Court Testimony', 'How does the court acquire jurisdiction over the person of the accused?', '[{"text": "By the filing of the complaint with the prosecutor", "is_correct": false, "rationale": "Filing with the prosecutor starts the preliminary investigation, not the court''s jurisdiction over the accused."}, {"text": "By the issuance of a subpoena to the accused", "is_correct": false, "rationale": "A subpoena is not the means by which the court acquires jurisdiction over an accused."}, {"text": "By his arrest or his voluntary surrender to the court", "is_correct": true, "rationale": "Jurisdiction over the person of the accused is acquired through arrest or voluntary appearance or surrender."}, {"text": "By the publication of the information in a newspaper", "is_correct": false, "rationale": "Publication is not a mode of acquiring jurisdiction over the accused in criminal cases."}]'::jsonb, 2, 'easy', 'Jurisdiction over the subject matter is conferred by law; over the person, by arrest or voluntary surrender.', 'Rules of Court, Rules 110 and 113', 'Study module Criminal Law and Jurisprudence, Chapter 6: Criminal Procedure and Court Testimony (CLJ-6.2).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-6.2', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-6.2_02', 'criminal_jurisprudence', 'Criminal Procedure and Court Testimony', 'What is the difference between a complaint and an information?', '[{"text": "A complaint is filed only in the RTC; an information only in the MTC", "is_correct": false, "rationale": "Both may be filed in any court with jurisdiction."}, {"text": "A complaint is oral; an information is written", "is_correct": false, "rationale": "Both must be in writing."}, {"text": "A complaint is signed by the offended party or a peace officer; an information is signed by the prosecutor", "is_correct": true, "rationale": "Rule 110 defines a complaint as a sworn statement subscribed by the offended party, a peace officer or another enforcement officer, and an information as an accusation subscribed by the prosecutor."}, {"text": "A complaint charges a crime; an information charges only a violation of an ordinance", "is_correct": false, "rationale": "Both may charge any offense within the court''s jurisdiction."}]'::jsonb, 2, 'easy', 'Every criminal action is commenced by a complaint or an information.', 'Rules of Court, Rule 110, Secs. 1-4', 'Study module Criminal Law and Jurisprudence, Chapter 6: Criminal Procedure and Court Testimony (CLJ-6.2).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-6.2', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-6.3_01', 'criminal_jurisprudence', 'Criminal Procedure and Court Testimony', 'The accused chose not to testify during trial. The judge remarked that his silence showed guilt. Was the judge correct?', '[{"text": "Yes, because an innocent person would always take the witness stand to deny the charge", "is_correct": false, "rationale": "The law does not presume guilt from silence."}, {"text": "Yes, because silence during trial is an implied admission of guilt by the accused", "is_correct": false, "rationale": "Silence during trial is not an implied admission."}, {"text": "No, unless the prosecution objected to his silence", "is_correct": false, "rationale": "The right does not depend on any objection by the prosecution."}, {"text": "No, because the accused may choose not to testify and his silence cannot prejudice him", "is_correct": true, "rationale": "Rule 115 and Art. III, Sec. 17 give the accused the right to testify or not, and his refusal shall not prejudice him."}]'::jsonb, 3, 'medium', 'The rights of the accused at trial include presumption of innocence, the right to be heard, the right to confront witnesses, and the right against self-incrimination.', 'Rules of Court, Rule 115; 1987 Constitution, Art. III, Secs. 14 and 17', 'Study module Criminal Law and Jurisprudence, Chapter 6: Criminal Procedure and Court Testimony (CLJ-6.3).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-6.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-6.3_02', 'criminal_jurisprudence', 'Criminal Procedure and Court Testimony', 'The prosecution wants to use the sworn statement of a witness who will not appear at trial, so the defense cannot cross-examine him. Which right of the accused is affected?', '[{"text": "The right to a speedy disposition of the case", "is_correct": false, "rationale": "Speedy disposition concerns delay, not the use of absent witnesses'' statements."}, {"text": "The right to bail", "is_correct": false, "rationale": "Bail concerns provisional liberty."}, {"text": "The right to confront and cross-examine witnesses", "is_correct": true, "rationale": "The accused has the right to meet the witnesses face to face and to cross-examine them; affidavits of absent witnesses are generally inadmissible against him."}, {"text": "The right to appeal", "is_correct": false, "rationale": "Appeal concerns review after judgment."}]'::jsonb, 2, 'medium', 'Confrontation allows the accused to test the credibility of the witnesses against him.', 'Rules of Court, Rule 115, Sec. 1(f); 1987 Constitution, Art. III, Sec. 14(2)', 'Study module Criminal Law and Jurisprudence, Chapter 6: Criminal Procedure and Court Testimony (CLJ-6.3).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-6.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-6.3_03', 'criminal_jurisprudence', 'Criminal Procedure and Court Testimony', 'An accused was charged with homicide, but the information did not allege any qualifying circumstance. After trial, the evidence showed treachery. Can he be convicted of murder?', '[{"text": "Yes, because the evidence presented at trial proved the qualifying circumstance", "is_correct": false, "rationale": "Proof of an unalleged qualifying circumstance does not justify conviction for the graver crime."}, {"text": "Yes, if the judge believes the evidence is strong", "is_correct": false, "rationale": "The judge''s belief cannot override the requirement of allegation."}, {"text": "No, because he has the right to be informed of the nature and cause of the accusation", "is_correct": true, "rationale": "Qualifying and aggravating circumstances must be alleged in the information; otherwise the accused cannot be convicted of the graver offense."}, {"text": "No, because treachery can never be proved by evidence", "is_correct": false, "rationale": "Treachery may be proved, but it must first be alleged."}]'::jsonb, 2, 'hard', 'Rule 110, Sections 8 and 9 require that qualifying and aggravating circumstances be stated in the information.', 'Rules of Court, Rule 110, Secs. 8-9; 1987 Constitution, Art. III, Sec. 14(2)', 'Study module Criminal Law and Jurisprudence, Chapter 6: Criminal Procedure and Court Testimony (CLJ-6.3).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-6.3', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-6.4_01', 'criminal_jurisprudence', 'Criminal Procedure and Court Testimony', 'Police officers saw a man stab another person on the street and arrested him on the spot without a warrant. Was the arrest valid?', '[{"text": "Yes, because it was an in flagrante delicto arrest", "is_correct": true, "rationale": "Rule 113, Section 5(a) allows a warrantless arrest when the person has committed, is committing or is attempting an offense in the presence of the arresting officer."}, {"text": "No, because a warrant is always needed to arrest a person", "is_correct": false, "rationale": "Warrantless arrests are allowed in the cases listed in Rule 113, Section 5."}, {"text": "Yes, but only if the victim filed a complaint first", "is_correct": false, "rationale": "No prior complaint is needed for an in flagrante arrest."}, {"text": "No, because only the barangay captain may arrest without a warrant", "is_correct": false, "rationale": "Any peace officer or private person may arrest in these cases."}]'::jsonb, 0, 'hard', 'The three valid warrantless arrests are in flagrante delicto, hot pursuit, and arrest of escaped prisoners.', 'Rules of Court, Rule 113, Sec. 5', 'Study module Criminal Law and Jurisprudence, Chapter 6: Criminal Procedure and Court Testimony (CLJ-6.4).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-6.4', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-6.4_02', 'criminal_jurisprudence', 'Criminal Procedure and Court Testimony', 'Officers arrived two days after a robbery and arrested a suspect without a warrant, based only on a description from witnesses. Why was this arrest likely invalid?', '[{"text": "The offense had not ''just been committed'' and the officers lacked personal knowledge", "is_correct": true, "rationale": "A hot pursuit arrest under Rule 113, Section 5(b) requires that the offense has just been committed and that the officers have probable cause based on personal knowledge of facts or circumstances."}, {"text": "Robbery is not one of the offenses for which a warrantless arrest is ever allowed", "is_correct": false, "rationale": "Robbery is an offense for which a person may be arrested."}, {"text": "The witnesses had no right to describe the suspect", "is_correct": false, "rationale": "Witness descriptions may support a warrant application but do not by themselves justify a warrantless arrest days later."}, {"text": "Warrantless arrests are allowed only at night", "is_correct": false, "rationale": "There is no rule limiting warrantless arrests to nighttime."}]'::jsonb, 0, 'hard', 'Immediacy and personal knowledge of the arresting officer are the requirements for hot pursuit arrests.', 'Rules of Court, Rule 113, Sec. 5(b)', 'Study module Criminal Law and Jurisprudence, Chapter 6: Criminal Procedure and Court Testimony (CLJ-6.4).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-6.4', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-6.4_03', 'criminal_jurisprudence', 'Criminal Procedure and Court Testimony', 'Officers have a search warrant for a house to look for unlicensed firearms. Which action best complies with the Rules?', '[{"text": "Search in the presence of the occupant or two witnesses of the locality, and issue a receipt for items seized", "is_correct": true, "rationale": "Rule 126 requires the search in the presence of the lawful occupant or a member of the family, or two witnesses of sufficient age residing in the same locality, and a detailed receipt for property seized."}, {"text": "Search the house next door as well, since the firearms might have been moved there", "is_correct": false, "rationale": "The warrant authorizes a search only of the place particularly described."}, {"text": "Keep the warrant for a month and search the house whenever convenient", "is_correct": false, "rationale": "A search warrant is valid for only ten days from its date."}, {"text": "Search at night without notice to avoid tipping off the occupants", "is_correct": false, "rationale": "A search warrant is served in the day unless the warrant itself allows service at any time."}]'::jsonb, 0, 'hard', 'Strict compliance with Rule 126 protects the admissibility of the evidence seized.', 'Rules of Court, Rule 126, Secs. 8-12', 'Study module Criminal Law and Jurisprudence, Chapter 6: Criminal Procedure and Court Testimony (CLJ-6.4).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-6.4', 'Evaluating') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-6.4_04', 'criminal_jurisprudence', 'Criminal Procedure and Court Testimony', 'At a checkpoint, an officer notices a firearm in plain view on the seat of a car. What is the most appropriate legal assessment?', '[{"text": "The firearm may not be seized because the officer has no search warrant", "is_correct": false, "rationale": "A warrant is not required for objects in plain view during a lawful intrusion."}, {"text": "The firearm may be seized because it is in plain view during a lawful checkpoint inspection", "is_correct": true, "rationale": "The plain view doctrine allows seizure when the officer is lawfully in position, the discovery is inadvertent, and the illegality of the item is immediately apparent."}, {"text": "The car may be searched thoroughly because all checkpoint searches are lawful", "is_correct": false, "rationale": "Routine checkpoints allow only a visual inspection; a full search needs probable cause."}, {"text": "The officer must first ask the barangay to issue a seizure order", "is_correct": false, "rationale": "Barangay officials do not issue seizure orders."}]'::jsonb, 1, 'hard', 'Checkpoints are valid if limited to visual inspection; the plain view doctrine is one exception to the warrant requirement.', '1987 Constitution, Art. III, Sec. 2; jurisprudence on plain view and checkpoints', 'Study module Criminal Law and Jurisprudence, Chapter 6: Criminal Procedure and Court Testimony (CLJ-6.4).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-6.4', 'Evaluating') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-6.5_01', 'criminal_jurisprudence', 'Criminal Procedure and Court Testimony', 'An offense is punishable by imprisonment of five years. Is a preliminary investigation required before the information is filed?', '[{"text": "Yes, because the penalty is at least four years, two months and one day", "is_correct": true, "rationale": "Rule 112, Section 1 requires preliminary investigation for offenses punishable by at least four years, two months and one day of imprisonment, regardless of the fine."}, {"text": "No, because preliminary investigation is required only for crimes punished by life imprisonment", "is_correct": false, "rationale": "Preliminary investigation covers much more than crimes punished by life imprisonment."}, {"text": "No, because the penalty is below six years", "is_correct": false, "rationale": "The six-year line concerns the jurisdiction of first-level courts, not preliminary investigation."}, {"text": "Yes, but only if the accused requests it in writing", "is_correct": false, "rationale": "Preliminary investigation is required by the Rules in these cases, not merely on request."}]'::jsonb, 0, 'medium', 'Preliminary investigation determines whether there is sufficient ground to believe a crime was committed and the respondent is probably guilty.', 'Rules of Court, Rule 112, Sec. 1', 'Study module Criminal Law and Jurisprudence, Chapter 6: Criminal Procedure and Court Testimony (CLJ-6.5).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-6.5', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-6.5_02', 'criminal_jurisprudence', 'Criminal Procedure and Court Testimony', 'Two residents of the same barangay quarrel, and one files a criminal complaint for slight physical injuries directly with the court. What procedural defect is present?', '[{"text": "The complaint should have been filed with the Sandiganbayan", "is_correct": false, "rationale": "The Sandiganbayan has nothing to do with this dispute."}, {"text": "The offended party should have filed a civil case instead", "is_correct": false, "rationale": "The offended party may file a criminal case, but only after conciliation and a certification to file action."}, {"text": "The dispute should first have gone through barangay conciliation", "is_correct": true, "rationale": "Under the Katarungang Pambarangay law, disputes between residents of the same city or municipality involving offenses punishable by imprisonment not exceeding one year or a fine not exceeding P5,000 must first undergo conciliation."}, {"text": "There is no defect, because criminal cases never need conciliation", "is_correct": false, "rationale": "Some criminal cases, those with light penalties, require conciliation first."}]'::jsonb, 2, 'hard', 'Barangay conciliation is a condition precedent; filing without it may lead to dismissal of the complaint.', 'R.A. 7160, Secs. 408-412', 'Study module Criminal Law and Jurisprudence, Chapter 6: Criminal Procedure and Court Testimony (CLJ-6.5).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-6.5', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-6.5_03', 'criminal_jurisprudence', 'Criminal Procedure and Court Testimony', 'Which distinction between preliminary investigation and inquest is correct?', '[{"text": "Preliminary investigation is conducted by trial judges; inquest is conducted by police investigators", "is_correct": false, "rationale": "Both are conducted by prosecutors."}, {"text": "Preliminary investigation is for respondents not under lawful arrest; inquest is for those arrested without a warrant", "is_correct": true, "rationale": "An inquest is a summary proceeding for persons lawfully arrested without a warrant; a preliminary investigation is a fuller inquiry where the respondent is not under detention."}, {"text": "Preliminary investigation decides guilt; inquest decides the penalty", "is_correct": false, "rationale": "Neither decides guilt or penalty; both concern probable cause."}, {"text": "Preliminary investigation is optional; inquest is never allowed", "is_correct": false, "rationale": "Both are recognized procedures under the Rules."}]'::jsonb, 1, 'hard', 'A person arrested without a warrant may ask for a preliminary investigation, but must sign a waiver of Article 125 with the assistance of counsel.', 'Rules of Court, Rule 112, Secs. 1 and 6', 'Study module Criminal Law and Jurisprudence, Chapter 6: Criminal Procedure and Court Testimony (CLJ-6.5).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-6.5', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-6.5_04', 'criminal_jurisprudence', 'Criminal Procedure and Court Testimony', 'A person was arrested without a warrant for a crime requiring preliminary investigation and wants one. What must he do?', '[{"text": "Wait for the case to be filed and ask the court to dismiss it", "is_correct": false, "rationale": "He may also ask for a preliminary investigation within five days after learning that the case was filed, but a waiver is needed if he wants it before filing."}, {"text": "Pay bail to the arresting officer at the station", "is_correct": false, "rationale": "Bail is posted with the court, not paid to the arresting officer."}, {"text": "Execute a waiver of Article 125 of the RPC with the assistance of counsel", "is_correct": true, "rationale": "Under Rule 112, Section 6, a person arrested without a warrant may ask for a preliminary investigation before the information is filed, but must sign a waiver of Article 125 in the presence of counsel."}, {"text": "Ask the barangay to conduct the preliminary investigation", "is_correct": false, "rationale": "Barangay officials do not conduct preliminary investigations."}]'::jsonb, 2, 'hard', 'Article 125 sets the periods within which a person arrested without a warrant must be delivered to judicial authorities.', 'Rules of Court, Rule 112, Sec. 6; Revised Penal Code, Art. 125', 'Study module Criminal Law and Jurisprudence, Chapter 6: Criminal Procedure and Court Testimony (CLJ-6.5).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-6.5', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-6.6_01', 'criminal_jurisprudence', 'Criminal Procedure and Court Testimony', 'Under Rule 114, in which situation is bail a matter of right?', '[{"text": "After conviction by the Regional Trial Court, for any offense charged in the information", "is_correct": false, "rationale": "After conviction by the RTC, bail becomes discretionary."}, {"text": "Before conviction, for offenses not punishable by death, reclusion perpetua or life imprisonment", "is_correct": true, "rationale": "Rule 114, Section 4 makes bail a matter of right before conviction by the RTC for offenses not punishable by death, reclusion perpetua or life imprisonment, and before or after conviction by first-level courts."}, {"text": "Only for offenses committed by first-time offenders", "is_correct": false, "rationale": "The right to bail does not depend on being a first-time offender."}, {"text": "Only when the accused can pay in cash", "is_correct": false, "rationale": "Bail may be given as corporate surety, property bond, cash deposit or recognizance."}]'::jsonb, 1, 'easy', 'For offenses punishable by reclusion perpetua or life imprisonment, bail is denied when evidence of guilt is strong, after a hearing.', 'Rules of Court, Rule 114, Secs. 4-7', 'Study module Criminal Law and Jurisprudence, Chapter 6: Criminal Procedure and Court Testimony (CLJ-6.6).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-6.6', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-6.6_02', 'criminal_jurisprudence', 'Criminal Procedure and Court Testimony', 'An accused charged with murder applies for bail. What must the judge do before ruling?', '[{"text": "Grant bail automatically because the accused is presumed innocent", "is_correct": false, "rationale": "The presumption of innocence does not make bail automatic for such offenses."}, {"text": "Conduct a hearing to determine whether the evidence of guilt is strong", "is_correct": true, "rationale": "For offenses punishable by reclusion perpetua, a bail hearing is required to determine whether the evidence of guilt is strong."}, {"text": "Deny bail automatically because murder is a heinous crime", "is_correct": false, "rationale": "Bail may be granted if the evidence of guilt is not strong."}, {"text": "Ask the prosecutor to fix the amount of bail without a hearing", "is_correct": false, "rationale": "The court, not the prosecutor, decides bail after a hearing."}]'::jsonb, 1, 'medium', 'Denying or granting bail in capital offenses without a hearing is grave abuse of discretion.', 'Rules of Court, Rule 114, Secs. 7-8', 'Study module Criminal Law and Jurisprudence, Chapter 6: Criminal Procedure and Court Testimony (CLJ-6.6).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-6.6', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-6.6_03', 'criminal_jurisprudence', 'Criminal Procedure and Court Testimony', 'At arraignment, the accused refuses to enter any plea. What should the court do?', '[{"text": "Enter a plea of not guilty for him", "is_correct": true, "rationale": "Rule 116, Section 1(c) provides that if the accused refuses to plead, a plea of not guilty shall be entered for him."}, {"text": "Enter a plea of guilty for him", "is_correct": false, "rationale": "A plea of guilty must come from the accused himself."}, {"text": "Dismiss the case for lack of a plea", "is_correct": false, "rationale": "Refusal to plead is not a ground for dismissal."}, {"text": "Postpone the case until the accused enters a plea", "is_correct": false, "rationale": "The Rules provide for a plea of not guilty instead of indefinite postponement."}]'::jsonb, 0, 'medium', 'A plea of not guilty is also entered when the accused makes a conditional plea or pleads guilty but presents exculpatory evidence.', 'Rules of Court, Rule 116, Sec. 1(c)-(d)', 'Study module Criminal Law and Jurisprudence, Chapter 6: Criminal Procedure and Court Testimony (CLJ-6.6).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-6.6', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-6.6_04', 'criminal_jurisprudence', 'Criminal Procedure and Court Testimony', 'After the prosecution rested its case, the defense believes the evidence is insufficient. What may the defense file?', '[{"text": "A motion to quash the information", "is_correct": false, "rationale": "A motion to quash is filed before arraignment, against defects in the information."}, {"text": "A demurrer to evidence", "is_correct": true, "rationale": "Rule 119, Section 23 allows the accused to file a demurrer to evidence after the prosecution rests, on the ground of insufficiency of evidence."}, {"text": "A petition for review with the DOJ", "is_correct": false, "rationale": "A petition for review challenges the prosecutor''s finding of probable cause, not the evidence at trial."}, {"text": "A motion for a bill of particulars", "is_correct": false, "rationale": "A bill of particulars is asked before arraignment to clarify vague allegations."}]'::jsonb, 1, 'medium', 'If a demurrer is filed without leave of court and is denied, the accused waives the right to present evidence.', 'Rules of Court, Rule 119, Sec. 23', 'Study module Criminal Law and Jurisprudence, Chapter 6: Criminal Procedure and Court Testimony (CLJ-6.6).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-6.6', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-6.7_01', 'criminal_jurisprudence', 'Criminal Procedure and Court Testimony', 'A ten-year-old witness becomes frightened in the courtroom while testifying against her abuser. Which measure may the court allow under the Rule on Examination of a Child Witness?', '[{"text": "Postponement of her testimony until she turns eighteen", "is_correct": false, "rationale": "Delaying testimony until adulthood is not a measure under the Rule."}, {"text": "Testimony through live-link television outside the courtroom", "is_correct": true, "rationale": "The Rule allows live-link television testimony, a support person, screens and other protective measures for child witnesses."}, {"text": "Replacing her testimony with the police report", "is_correct": false, "rationale": "A police report cannot replace the child''s testimony."}, {"text": "Requiring her to testify only in written form", "is_correct": false, "rationale": "The Rule provides for oral testimony with protective measures, not written testimony only."}]'::jsonb, 1, 'medium', 'The Rule on Examination of a Child Witness aims to create an environment that allows the child to give reliable testimony without further trauma.', 'Rule on Examination of a Child Witness, A.M. No. 004-07-SC', 'Study module Criminal Law and Jurisprudence, Chapter 6: Criminal Procedure and Court Testimony (CLJ-6.7).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-6.7', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CLJ-6.7_02', 'criminal_jurisprudence', 'Criminal Procedure and Court Testimony', 'During cross-examination, defense counsel asks the prosecution witness, ''You were drinking that night, weren''t you?'' The prosecutor objects that it is leading. How should the court rule?', '[{"text": "Overrule the objection, because leading questions are allowed on cross-examination", "is_correct": true, "rationale": "Leading questions are allowed on cross-examination, which tests the accuracy and truthfulness of the witness."}, {"text": "Sustain the objection, because leading questions are never allowed", "is_correct": false, "rationale": "Leading questions are generally not allowed on direct examination, but they are allowed on cross."}, {"text": "Sustain the objection, because cross-examination must be limited to new matters", "is_correct": false, "rationale": "Cross-examination may cover matters stated on direct and matters connected with them, including credibility."}, {"text": "Overrule the objection only if the witness is a child", "is_correct": false, "rationale": "The rule allowing leading questions on cross does not depend on the witness being a child."}]'::jsonb, 0, 'medium', 'The order of examination is direct, cross, re-direct and re-cross.', 'Rules of Court, Rule 132, Secs. 4-10', 'Study module Criminal Law and Jurisprudence, Chapter 6: Criminal Procedure and Court Testimony (CLJ-6.7).', 'generated', 'tos_2024', 1, FALSE, 'CLJ-6.7', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-1.1_01', 'law_enforcement', 'Law Enforcement Organization and Administration (Inter-Agency Approach)', 'Which principle of organization means that each member reports to only one immediate superior?', '[{"text": "Span of control", "is_correct": false, "rationale": "Span of control is the number of subordinates a superior can effectively supervise."}, {"text": "Unity of command", "is_correct": true, "rationale": "Unity of command requires that every member be under the direct command of only one superior, to avoid conflicting orders."}, {"text": "Delegation of authority", "is_correct": false, "rationale": "Delegation of authority is the act of assigning authority to subordinates to carry out tasks."}, {"text": "Scalar chain", "is_correct": false, "rationale": "The scalar chain (chain of command) is the unbroken line of authority from top to bottom."}]'::jsonb, 1, 'easy', 'Unity of command, span of control, delegation of authority and the chain of command are basic principles of police organization.', NULL, 'Study module Law Enforcement Administration, Chapter 1: Law Enforcement Organization and Administration (Inter-Agency Approach) (LEA-1.1).', 'generated', 'tos_2024', 1, FALSE, 'LEA-1.1', 'Remembering') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-1.1_02', 'law_enforcement', 'Law Enforcement Organization and Administration (Inter-Agency Approach)', 'A precinct commander finds that he cannot properly supervise twenty-five officers by himself. Which principle explains his problem?', '[{"text": "Unity of command", "is_correct": false, "rationale": "Unity of command concerns having one superior per member, not the number of members supervised."}, {"text": "Line and staff", "is_correct": false, "rationale": "Line and staff concerns the distinction between operating and support units."}, {"text": "Specialization", "is_correct": false, "rationale": "Specialization concerns assigning specific tasks to persons trained for them."}, {"text": "Span of control", "is_correct": true, "rationale": "Span of control holds that a superior can effectively supervise only a limited number of subordinates; too many weakens supervision."}]'::jsonb, 3, 'easy', 'When the span of control is exceeded, organizations add supervisors or create sub-units.', NULL, 'Study module Law Enforcement Administration, Chapter 1: Law Enforcement Organization and Administration (Inter-Agency Approach) (LEA-1.1).', 'generated', 'tos_2024', 1, FALSE, 'LEA-1.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-1.1_03', 'law_enforcement', 'Law Enforcement Organization and Administration (Inter-Agency Approach)', 'Which statement correctly distinguishes line functions from staff functions in a police organization?', '[{"text": "Line units carry out the main mission such as patrol; staff units support and advise them", "is_correct": true, "rationale": "Line functions directly accomplish the organization''s objectives (patrol, investigation, traffic); staff functions such as planning and personnel support the line."}, {"text": "Line units give policy advice to the chief; staff units patrol the streets", "is_correct": false, "rationale": "This reverses the two functions."}, {"text": "Line units are civilians; staff units are uniformed officers", "is_correct": false, "rationale": "Both line and staff positions may be held by uniformed personnel."}, {"text": "Line units exist only at headquarters; staff units exist only in the field", "is_correct": false, "rationale": "Line and staff units exist at every level of the organization."}]'::jsonb, 0, 'easy', 'The line and staff structure is common in police organizations: the line operates, the staff supports.', NULL, 'Study module Law Enforcement Administration, Chapter 1: Law Enforcement Organization and Administration (Inter-Agency Approach) (LEA-1.1).', 'generated', 'tos_2024', 1, FALSE, 'LEA-1.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-1.2_01', 'law_enforcement', 'Law Enforcement Organization and Administration (Inter-Agency Approach)', 'A foreign tourist has overstayed his visa for two years and is found working without a permit. Which agency has authority over his case?', '[{"text": "National Bureau of Investigation", "is_correct": false, "rationale": "The NBI investigates crimes, but immigration violations of aliens are under the Bureau of Immigration."}, {"text": "Department of Foreign Affairs", "is_correct": false, "rationale": "The DFA issues passports and handles foreign relations, not immigration enforcement inside the country."}, {"text": "Bureau of Immigration", "is_correct": true, "rationale": "The Bureau of Immigration enforces immigration laws, including the arrest, detention and deportation of aliens who violate them."}, {"text": "Philippine National Police", "is_correct": false, "rationale": "The PNP may assist, but the Bureau of Immigration has jurisdiction over violations of immigration laws."}]'::jsonb, 2, 'medium', 'The Bureau of Immigration (formerly the Bureau of Immigration and Deportation) administers and enforces the Philippine Immigration Act of 1940 (C.A. 613).', 'C.A. 613 (Philippine Immigration Act of 1940)', 'Study module Law Enforcement Administration, Chapter 1: Law Enforcement Organization and Administration (Inter-Agency Approach) (LEA-1.2).', 'generated', 'tos_2024', 1, FALSE, 'LEA-1.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-1.2_02', 'law_enforcement', 'Law Enforcement Organization and Administration (Inter-Agency Approach)', 'A ferry capsized in the Visayan Sea. Under R.A. 9993, which agency has the primary function of maritime search and rescue?', '[{"text": "Philippine Navy", "is_correct": false, "rationale": "The Navy is a branch of the AFP for national defense; it may assist but is not the primary SAR agency."}, {"text": "Philippine Coast Guard", "is_correct": true, "rationale": "R.A. 9993 gives the PCG the functions of maritime search and rescue, maritime safety, marine environmental protection, maritime law enforcement and maritime security."}, {"text": "PNP Maritime Group", "is_correct": false, "rationale": "The PNP Maritime Group enforces laws in coastal areas but is not the primary SAR agency."}, {"text": "Maritime Industry Authority", "is_correct": false, "rationale": "MARINA develops and regulates the maritime industry; it does not lead search and rescue."}]'::jsonb, 1, 'medium', 'R.A. 9993, the Philippine Coast Guard Law of 2009, made the PCG an armed and uniformed service attached to the Department of Transportation.', 'R.A. 9993, Sec. 3', 'Study module Law Enforcement Administration, Chapter 1: Law Enforcement Organization and Administration (Inter-Agency Approach) (LEA-1.2).', 'generated', 'tos_2024', 1, FALSE, 'LEA-1.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-1.2_03', 'law_enforcement', 'Law Enforcement Organization and Administration (Inter-Agency Approach)', 'A businessman wants to open a restaurant. Which agency must inspect the building and issue a Fire Safety Inspection Certificate?', '[{"text": "City Engineer''s Office", "is_correct": false, "rationale": "The City Engineer issues building permits, but the FSIC is issued by the BFP."}, {"text": "Bureau of Fire Protection", "is_correct": true, "rationale": "Under the Fire Code, the BFP conducts fire safety inspections and issues the FSIC, a prerequisite for business permits and occupancy."}, {"text": "Department of Trade and Industry", "is_correct": false, "rationale": "The DTI registers business names, but it does not certify fire safety."}, {"text": "Philippine National Police", "is_correct": false, "rationale": "The PNP does not inspect buildings for compliance with the Fire Code."}]'::jsonb, 1, 'medium', 'The BFP enforces R.A. 9514, the Fire Code of the Philippines of 2008.', 'R.A. 9514', 'Study module Law Enforcement Administration, Chapter 1: Law Enforcement Organization and Administration (Inter-Agency Approach) (LEA-1.2).', 'generated', 'tos_2024', 1, FALSE, 'LEA-1.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-1.2_04', 'law_enforcement', 'Law Enforcement Organization and Administration (Inter-Agency Approach)', 'The Secretary of Justice orders an investigation of a crime that spans several regions and uses sophisticated methods. Which agency under the DOJ carries out such investigations?', '[{"text": "PNP Criminal Investigation and Detection Group", "is_correct": false, "rationale": "The CIDG is a unit of the PNP, which is under the DILG, not the DOJ."}, {"text": "Philippine Drug Enforcement Agency", "is_correct": false, "rationale": "PDEA is the lead agency for illegal drugs only, under the Office of the President."}, {"text": "Office of the Ombudsman", "is_correct": false, "rationale": "The Ombudsman investigates public officers; it is a constitutional body, not part of the DOJ."}, {"text": "National Bureau of Investigation", "is_correct": true, "rationale": "R.A. 10867 authorizes the NBI, attached to the DOJ, to investigate crimes of national interest, including those that are transnational or use sophisticated means."}]'::jsonb, 3, 'medium', 'R.A. 10867, the NBI Reorganization and Modernization Act, lists the crimes the NBI may investigate.', 'R.A. 10867', 'Study module Law Enforcement Administration, Chapter 1: Law Enforcement Organization and Administration (Inter-Agency Approach) (LEA-1.2).', 'generated', 'tos_2024', 1, FALSE, 'LEA-1.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-1.3_01', 'law_enforcement', 'Law Enforcement Organization and Administration (Inter-Agency Approach)', 'A police station put up lights and assigned guards at a market with repeated thefts. It now compares theft reports before and after. Which step of the SARA model is this?', '[{"text": "Scanning", "is_correct": false, "rationale": "Scanning identifies and prioritizes recurring problems."}, {"text": "Analysis", "is_correct": false, "rationale": "Analysis studies the causes and conditions of the problem."}, {"text": "Assessment", "is_correct": true, "rationale": "Assessment evaluates whether the response worked, for example by comparing data before and after."}, {"text": "Response", "is_correct": false, "rationale": "Response is the carrying out of the measures, such as installing lights and posting guards."}]'::jsonb, 2, 'medium', 'SARA (Scanning, Analysis, Response, Assessment) is the problem-solving process of problem-oriented policing (POP).', NULL, 'Study module Law Enforcement Administration, Chapter 1: Law Enforcement Organization and Administration (Inter-Agency Approach) (LEA-1.3).', 'generated', 'tos_2024', 1, FALSE, 'LEA-1.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-2.1_01', 'law_enforcement', 'Comparative Models in Policing', 'How does the Home Rule theory of policing differ from the Continental theory?', '[{"text": "Home Rule sees police as soldiers of the state; Continental sees them as elected officials", "is_correct": false, "rationale": "Neither theory treats police as soldiers or as elected officials."}, {"text": "Home Rule applies only in Asia; Continental applies only in Europe", "is_correct": false, "rationale": "The theories describe philosophies of policing, not geographic rules."}, {"text": "Home Rule sees police as servants of the community; Continental sees them as servants of higher authority", "is_correct": true, "rationale": "Under the Home Rule theory, policemen are servants of the people; under the Continental theory, they are servants of the higher authorities, with the people having little say."}, {"text": "Home Rule bans police from arresting; Continental allows arrests only with a warrant", "is_correct": false, "rationale": "Both theories allow the police to arrest according to law."}]'::jsonb, 2, 'easy', 'Home Rule is associated with England and the United States; the Continental theory with countries such as France and Italy.', NULL, 'Study module Law Enforcement Administration, Chapter 2: Comparative Models in Policing (LEA-2.1).', 'generated', 'tos_2024', 1, FALSE, 'LEA-2.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-2.2_01', 'law_enforcement', 'Comparative Models in Policing', 'A Filipino suspect in a murder case fled abroad. Which INTERPOL notice asks member countries to locate and provisionally arrest him for extradition?', '[{"text": "Blue Notice", "is_correct": false, "rationale": "A Blue Notice collects additional information about a person''s identity, location or activities."}, {"text": "Yellow Notice", "is_correct": false, "rationale": "A Yellow Notice helps locate missing persons, often minors, or identify persons unable to identify themselves."}, {"text": "Red Notice", "is_correct": true, "rationale": "A Red Notice is a request to locate and provisionally arrest a person pending extradition or similar legal action."}, {"text": "Black Notice", "is_correct": false, "rationale": "A Black Notice seeks information on unidentified bodies."}]'::jsonb, 2, 'medium', 'The National Central Bureau of INTERPOL in the Philippines coordinates requests for notices.', NULL, 'Study module Law Enforcement Administration, Chapter 2: Comparative Models in Policing (LEA-2.2).', 'generated', 'tos_2024', 1, FALSE, 'LEA-2.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-2.2_02', 'law_enforcement', 'Comparative Models in Policing', 'The Philippines asks Country X, based on a treaty, to surrender a Filipino who is charged with estafa here. What process is being used?', '[{"text": "Deportation", "is_correct": false, "rationale": "Deportation is the removal of an alien by the state where he is, for violating its own laws."}, {"text": "Repatriation", "is_correct": false, "rationale": "Repatriation is the return of a person to his own country, usually voluntarily or in emergencies."}, {"text": "Political asylum", "is_correct": false, "rationale": "Political asylum is protection given by a state to a person fleeing persecution, the opposite of surrender."}, {"text": "Extradition", "is_correct": true, "rationale": "Extradition is the surrender of a person by one state to another, usually under a treaty, to stand trial or serve sentence."}]'::jsonb, 3, 'medium', 'P.D. 1069 prescribes the procedure for the extradition of persons who committed crimes in a foreign country.', 'P.D. 1069 (Philippine Extradition Law)', 'Study module Law Enforcement Administration, Chapter 2: Comparative Models in Policing (LEA-2.2).', 'generated', 'tos_2024', 1, FALSE, 'LEA-2.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-2.3_01', 'law_enforcement', 'Comparative Models in Policing', 'A police office uses intelligence on prolific offenders and crime analysis to decide where to focus its operations. Which policing model is it applying?', '[{"text": "Community-oriented policing", "is_correct": false, "rationale": "Community-oriented policing emphasizes partnership with residents to address crime and disorder."}, {"text": "Traditional reactive policing", "is_correct": false, "rationale": "Traditional policing reacts to calls for service after crimes happen."}, {"text": "Intelligence-led policing", "is_correct": true, "rationale": "Intelligence-led policing uses criminal intelligence and analysis to target prolific offenders and guide resources."}, {"text": "Problem-oriented policing", "is_correct": false, "rationale": "Problem-oriented policing focuses on recurring problems and their underlying conditions through SARA."}]'::jsonb, 2, 'medium', 'The common policing models are traditional, community-oriented, problem-oriented and intelligence-led policing.', NULL, 'Study module Law Enforcement Administration, Chapter 2: Comparative Models in Policing (LEA-2.3).', 'generated', 'tos_2024', 1, FALSE, 'LEA-2.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-2.4_01', 'law_enforcement', 'Comparative Models in Policing', 'A police unit is assigned to a community of indigenous people with their own customs. Which approach best upholds both the law and multicultural policing?', '[{"text": "Enforce every rule strictly without consulting anyone so that no one is favored", "is_correct": false, "rationale": "Enforcement without understanding the culture breeds distrust and weakens cooperation."}, {"text": "Engage the community''s elders and respect its customs while enforcing the law equally", "is_correct": true, "rationale": "Multicultural policing seeks cooperation by respecting cultural differences and involving community leaders, without exempting anyone from the law; R.A. 8371 recognizes customary laws."}, {"text": "Assign only officers who share the group''s ethnicity and let them decide everything", "is_correct": false, "rationale": "Officers of the same ethnicity may help, but the unit cannot surrender its duty to enforce the law equally."}, {"text": "Avoid the community unless a crime is reported, to prevent cultural conflicts", "is_correct": false, "rationale": "Avoiding the community leaves it underserved and defeats the preventive role of the police."}]'::jsonb, 1, 'hard', 'Police legitimacy in diverse communities depends on respect, communication and equal treatment.', 'R.A. 8371 (Indigenous Peoples'' Rights Act)', 'Study module Law Enforcement Administration, Chapter 2: Comparative Models in Policing (LEA-2.4).', 'generated', 'tos_2024', 1, FALSE, 'LEA-2.4', 'Evaluating') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-3.1_01', 'law_enforcement', 'Introduction to Industrial Security Concepts', 'Which law is the Private Security Services Industry Act?', '[{"text": "R.A. 5487", "is_correct": false, "rationale": "R.A. 5487 was the old Private Security Agency Law, now repealed."}, {"text": "R.A. 6975", "is_correct": false, "rationale": "R.A. 6975 is the DILG Act of 1990, which created the PNP, BFP and BJMP."}, {"text": "R.A. 11917", "is_correct": true, "rationale": "R.A. 11917, signed in 2022, is the Private Security Services Industry Act; it repealed R.A. 5487."}, {"text": "R.A. 11131", "is_correct": false, "rationale": "R.A. 11131 is the Philippine Criminology Profession Act of 2018."}]'::jsonb, 2, 'easy', 'R.A. 11917 regulates private security agencies, company guard forces and private security professionals.', 'R.A. 11917', 'Study module Law Enforcement Administration, Chapter 3: Introduction to Industrial Security Concepts (LEA-3.1).', 'generated', 'tos_2024', 1, FALSE, 'LEA-3.1', 'Remembering') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-3.1_02', 'law_enforcement', 'Introduction to Industrial Security Concepts', 'Why does R.A. 11917 require private security agencies and personnel to be licensed and regulated by the PNP?', '[{"text": "Because private security guards become regular members of the PNP once licensed", "is_correct": false, "rationale": "Licensed security personnel remain private persons; they do not become PNP members."}, {"text": "Because the State recognizes the industry''s role in public safety and must protect the public", "is_correct": true, "rationale": "The law declares the vital role of private security in peace and order, so the State regulates the industry to ensure competence and protect the public."}, {"text": "Because licensing allows security guards to arrest without warrant in all cases", "is_correct": false, "rationale": "Security guards may arrest without warrant only in the cases allowed for private persons under Rule 113."}, {"text": "Because licensed security guards are exempted from the Labor Code and its rules", "is_correct": false, "rationale": "Security guards remain covered by labor laws; R.A. 11917 adds protections for them."}]'::jsonb, 1, 'easy', 'Regulation covers licensing, training, firearms, and the standards of security services.', 'R.A. 11917, Declaration of Policy', 'Study module Law Enforcement Administration, Chapter 3: Introduction to Industrial Security Concepts (LEA-3.1).', 'generated', 'tos_2024', 1, FALSE, 'LEA-3.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-3.2_01', 'law_enforcement', 'Introduction to Industrial Security Concepts', 'At a mall entrance, an angry shopper complains loudly about the bag inspection. What should the security guard do?', '[{"text": "Let him pass without inspection to avoid a scene in front of other shoppers", "is_correct": false, "rationale": "Skipping the inspection defeats the security protocol and treats shoppers unequally."}, {"text": "Raise his voice to show authority and order the shopper to leave the mall", "is_correct": false, "rationale": "Shouting escalates the situation and is poor customer relations."}, {"text": "Calmly explain the purpose of the inspection and apply it to him as to everyone else", "is_correct": true, "rationale": "Good customer relations means staying courteous and calm, explaining the reason for the procedure, and applying it consistently."}, {"text": "Call the police at once and keep the shopper inside until they arrive", "is_correct": false, "rationale": "A complaint is not a crime; holding the shopper could amount to unlawful detention."}]'::jsonb, 2, 'medium', 'Security personnel serve both the client''s protection and the public, so courtesy and consistency go together.', NULL, 'Study module Law Enforcement Administration, Chapter 3: Introduction to Industrial Security Concepts (LEA-3.2).', 'generated', 'tos_2024', 1, FALSE, 'LEA-3.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-3.2_02', 'law_enforcement', 'Introduction to Industrial Security Concepts', 'A guard finds an unattended bag left in an office lobby for a long time. What is the proper first action?', '[{"text": "Open the bag carefully to check what is inside before reporting it", "is_correct": false, "rationale": "Opening or moving the bag may set off an explosive device."}, {"text": "Carry the bag outside the building so no one inside will be hurt", "is_correct": false, "rationale": "Moving the bag exposes the guard and others to danger."}, {"text": "Leave it there, since the owner will probably come back for it", "is_correct": false, "rationale": "Ignoring a suspicious item violates basic security protocol."}, {"text": "Do not touch it; keep people away from the area and report it to the supervisor", "is_correct": true, "rationale": "A suspicious item must not be handled; the guard isolates the area, keeps people away and reports so trained responders can assess it."}]'::jsonb, 3, 'medium', 'The usual protocol is: do not touch, isolate the area, evacuate if necessary, and report.', NULL, 'Study module Law Enforcement Administration, Chapter 3: Introduction to Industrial Security Concepts (LEA-3.2).', 'generated', 'tos_2024', 1, FALSE, 'LEA-3.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-3.3_01', 'law_enforcement', 'Introduction to Industrial Security Concepts', 'A company wants to know the security weaknesses of its warehouse before it prepares a security plan. What should be conducted first?', '[{"text": "Security inspection", "is_correct": false, "rationale": "A security inspection checks compliance with security measures that are already in place."}, {"text": "Background investigation", "is_correct": false, "rationale": "Background investigation concerns the character and history of persons, not of facilities."}, {"text": "Security survey", "is_correct": true, "rationale": "A security survey is a critical on-site examination of a facility to find its weaknesses and recommend measures; it comes before the plan."}, {"text": "Security education", "is_correct": false, "rationale": "Security education informs personnel about security policies after these are set."}]'::jsonb, 2, 'medium', 'The survey''s findings are the basis of the security plan and its risk treatments.', NULL, 'Study module Law Enforcement Administration, Chapter 3: Introduction to Industrial Security Concepts (LEA-3.3).', 'generated', 'tos_2024', 1, FALSE, 'LEA-3.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-3.3_02', 'law_enforcement', 'Introduction to Industrial Security Concepts', 'A firm checks the character, records and loyalty of job applicants before hiring them for sensitive posts. Which type of security is this?', '[{"text": "Personnel security", "is_correct": true, "rationale": "Personnel security covers measures to ensure that persons with access to sensitive matters are suitable, such as background checks."}, {"text": "Physical security", "is_correct": false, "rationale": "Physical security uses barriers, locks, lights and guards to protect places and property."}, {"text": "Document and information security", "is_correct": false, "rationale": "Document and information security protects classified documents and information."}, {"text": "Operational security", "is_correct": false, "rationale": "Operational security protects plans and activities from being disclosed."}]'::jsonb, 0, 'medium', 'The main types of industrial security are physical, personnel, and document and information security.', NULL, 'Study module Law Enforcement Administration, Chapter 3: Introduction to Industrial Security Concepts (LEA-3.3).', 'generated', 'tos_2024', 1, FALSE, 'LEA-3.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-3.4_01', 'law_enforcement', 'Introduction to Industrial Security Concepts', 'A city redesigns a park with clear sight lines, better lighting and fewer hiding places so that people can watch what goes on. Which concept is being applied?', '[{"text": "Natural surveillance (CPTED)", "is_correct": true, "rationale": "Natural surveillance arranges the physical environment so that legitimate users can easily see activity, which discourages offenders."}, {"text": "Natural access control (CPTED)", "is_correct": false, "rationale": "Natural access control guides people through entrances and exits to limit access to targets."}, {"text": "Territorial reinforcement (CPTED)", "is_correct": false, "rationale": "Territorial reinforcement uses fences, signs and design to show ownership of a space."}, {"text": "Target hardening", "is_correct": false, "rationale": "Target hardening makes a target physically harder to attack, such as with locks and grills."}]'::jsonb, 0, 'hard', 'Crime Prevention Through Environmental Design (CPTED) reduces opportunities for crime through the design of places.', NULL, 'Study module Law Enforcement Administration, Chapter 3: Introduction to Industrial Security Concepts (LEA-3.4).', 'generated', 'tos_2024', 1, FALSE, 'LEA-3.4', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-4.1_01', 'law_enforcement', 'Law Enforcement Operations and Planning with Crime Mapping', 'Which type of plan is prepared in advance for an event that may or may not happen, such as an earthquake or a hostage crisis?', '[{"text": "Strategic plan", "is_correct": false, "rationale": "A strategic plan sets long-range direction and goals."}, {"text": "Procedural plan", "is_correct": false, "rationale": "A procedural plan prescribes standard steps for routine tasks."}, {"text": "Management plan", "is_correct": false, "rationale": "A management plan covers the use of personnel, money and equipment of the organization."}, {"text": "Contingency plan", "is_correct": true, "rationale": "A contingency plan prepares responses to possible emergencies or unusual events."}]'::jsonb, 3, 'easy', 'Contingency plans let a unit respond quickly when an emergency happens, instead of planning in the middle of it.', NULL, 'Study module Law Enforcement Administration, Chapter 4: Law Enforcement Operations and Planning with Crime Mapping (LEA-4.1).', 'generated', 'tos_2024', 1, FALSE, 'LEA-4.1', 'Remembering') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-4.1_02', 'law_enforcement', 'Law Enforcement Operations and Planning with Crime Mapping', 'In the PNP''s strategic management, what does PGS stand for?', '[{"text": "Police General Strategy", "is_correct": false, "rationale": "There is no framework called the Police General Strategy."}, {"text": "Performance Governance System", "is_correct": true, "rationale": "The PNP adopted the Performance Governance System, a strategic management framework, to carry out its P.A.T.R.O.L. Plan 2030 roadmap."}, {"text": "Patrol Grid System", "is_correct": false, "rationale": "Patrol grids are a deployment tool, not the PNP''s governance framework."}, {"text": "Public Guidance Standard", "is_correct": false, "rationale": "There is no PNP framework called the Public Guidance Standard."}]'::jsonb, 1, 'easy', 'Under the PGS, units cascade the PNP strategy map and scorecard to their own plans and targets.', NULL, 'Study module Law Enforcement Administration, Chapter 4: Law Enforcement Operations and Planning with Crime Mapping (LEA-4.1).', 'generated', 'tos_2024', 1, FALSE, 'LEA-4.1', 'Remembering') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-4.1_03', 'law_enforcement', 'Law Enforcement Operations and Planning with Crime Mapping', 'Which type of police plan prescribes the standard steps for routine work, such as how the desk officer receives a complaint?', '[{"text": "Tactical plan", "is_correct": false, "rationale": "Tactical plans concern methods of action at a specific place or situation, such as a raid."}, {"text": "Strategic plan", "is_correct": false, "rationale": "Strategic plans set the long-range direction of the organization."}, {"text": "Procedural plan", "is_correct": true, "rationale": "Procedural plans are the standard operating procedures that guide routine work."}, {"text": "Contingency plan", "is_correct": false, "rationale": "Contingency plans prepare for possible emergencies."}]'::jsonb, 2, 'easy', 'Common types of police plans include procedural, tactical, operational, management and extra-office plans.', NULL, 'Study module Law Enforcement Administration, Chapter 4: Law Enforcement Operations and Planning with Crime Mapping (LEA-4.1).', 'generated', 'tos_2024', 1, FALSE, 'LEA-4.1', 'Remembering') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-4.1_04', 'law_enforcement', 'Law Enforcement Operations and Planning with Crime Mapping', 'Why should a police plan be flexible?', '[{"text": "So it can be adjusted when conditions change without abandoning its objectives", "is_correct": true, "rationale": "The principle of flexibility means a plan can adapt to changing conditions while still pursuing its objectives."}, {"text": "So that officers may ignore it whenever they disagree with its contents", "is_correct": false, "rationale": "Flexibility does not mean the plan is optional."}, {"text": "So it can be written quickly without gathering facts or data first", "is_correct": false, "rationale": "Good plans are based on facts and data, flexible or not."}, {"text": "So that no officer can be held responsible for carrying it out", "is_correct": false, "rationale": "Plans assign responsibility; flexibility does not remove it."}]'::jsonb, 0, 'easy', 'Other principles of planning include clear objectives, simplicity, and a basis in facts.', NULL, 'Study module Law Enforcement Administration, Chapter 4: Law Enforcement Operations and Planning with Crime Mapping (LEA-4.1).', 'generated', 'tos_2024', 1, FALSE, 'LEA-4.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-4.1_05', 'law_enforcement', 'Law Enforcement Operations and Planning with Crime Mapping', 'How does a strategic plan differ from an operational plan?', '[{"text": "A strategic plan covers one day; an operational plan covers ten or more years", "is_correct": false, "rationale": "This reverses the time frames."}, {"text": "A strategic plan is written by field officers; an operational plan by the President", "is_correct": false, "rationale": "Strategic plans are made by top management; operational plans by lower units."}, {"text": "A strategic plan sets long-range direction; an operational plan carries it out in the near term", "is_correct": true, "rationale": "Strategic plans set long-range goals for the whole organization; operational plans translate them into specific short-term actions."}, {"text": "A strategic plan applies only in wartime; an operational plan only in peacetime", "is_correct": false, "rationale": "Both kinds of plans are used in peacetime."}]'::jsonb, 2, 'easy', 'Strategic, intermediate and operational plans differ in time frame and level of detail.', NULL, 'Study module Law Enforcement Administration, Chapter 4: Law Enforcement Operations and Planning with Crime Mapping (LEA-4.1).', 'generated', 'tos_2024', 1, FALSE, 'LEA-4.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-4.1_06', 'law_enforcement', 'Law Enforcement Operations and Planning with Crime Mapping', 'Why does the PNP require its regional and provincial offices to align their plans with the P.A.T.R.O.L. Plan 2030?', '[{"text": "So that each unit may adopt its own strategy different from the national one", "is_correct": false, "rationale": "Alignment means the units share the same strategy, not separate ones."}, {"text": "So that every unit''s plans and targets contribute to the same national strategic goals", "is_correct": true, "rationale": "Cascading the roadmap aligns all units'' objectives and scorecards with the PNP''s strategy."}, {"text": "So that the plans of the units can be kept secret from PNP headquarters", "is_correct": false, "rationale": "Alignment requires the units to report their plans and results, not hide them."}, {"text": "So that the units can avoid being measured against performance targets", "is_correct": false, "rationale": "Under the PGS, units are measured through scorecards and targets."}]'::jsonb, 1, 'easy', 'Strategy alignment helps an organization of many units move in one direction.', NULL, 'Study module Law Enforcement Administration, Chapter 4: Law Enforcement Operations and Planning with Crime Mapping (LEA-4.1).', 'generated', 'tos_2024', 1, FALSE, 'LEA-4.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-4.2_01', 'law_enforcement', 'Law Enforcement Operations and Planning with Crime Mapping', 'What does geographic profiling try to estimate?', '[{"text": "The exact time when the next crime in the series will happen", "is_correct": false, "rationale": "It does not predict the exact time of the next crime."}, {"text": "The psychological disorder that the offender is suffering from", "is_correct": false, "rationale": "Psychological profiling, not geographic profiling, looks at the offender''s personality."}, {"text": "The number of officers needed to patrol every barangay", "is_correct": false, "rationale": "Staffing needs are estimated by workload analysis, not geographic profiling."}, {"text": "The area where a serial offender most likely lives or is based", "is_correct": true, "rationale": "Geographic profiling analyzes the locations of a connected series of crimes to estimate the offender''s likely anchor point."}]'::jsonb, 3, 'easy', 'Geographic profiling helps investigators prioritize suspects and areas to search.', NULL, 'Study module Law Enforcement Administration, Chapter 4: Law Enforcement Operations and Planning with Crime Mapping (LEA-4.2).', 'generated', 'tos_2024', 1, FALSE, 'LEA-4.2', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-4.2_02', 'law_enforcement', 'Law Enforcement Operations and Planning with Crime Mapping', 'In crime mapping, what is a hotspot?', '[{"text": "An area with a greater than average number of crime events", "is_correct": true, "rationale": "A hotspot is a place where crime concentrates, where people have a higher than average risk of victimization."}, {"text": "An area with no recorded crime during the past year", "is_correct": false, "rationale": "An area without crime is the opposite of a hotspot."}, {"text": "A location where the police station is situated", "is_correct": false, "rationale": "The location of the station does not make an area a hotspot."}, {"text": "A place reported by the media as dangerous, regardless of data", "is_correct": false, "rationale": "Hotspots are identified from crime data, not from media reports."}]'::jsonb, 0, 'easy', 'Hotspot analysis helps target patrol and prevention to the few places where crime clusters.', NULL, 'Study module Law Enforcement Administration, Chapter 4: Law Enforcement Operations and Planning with Crime Mapping (LEA-4.2).', 'generated', 'tos_2024', 1, FALSE, 'LEA-4.2', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-4.2_03', 'law_enforcement', 'Law Enforcement Operations and Planning with Crime Mapping', 'A map shades each barangay darker or lighter depending on its rate of theft. What type of map is this?', '[{"text": "Thematic (choropleth) map", "is_correct": true, "rationale": "A thematic choropleth map shades areas according to a value, such as the rate of crime per barangay."}, {"text": "Point (pin) map", "is_correct": false, "rationale": "A point map shows each incident as a separate dot or pin."}, {"text": "Geographic profile", "is_correct": false, "rationale": "A geographic profile estimates an offender''s likely base from a crime series."}, {"text": "Road network map", "is_correct": false, "rationale": "A road map shows streets, not crime values per area."}]'::jsonb, 0, 'easy', 'Thematic maps help compare areas at a glance, but rates rather than counts should be used for fair comparison.', NULL, 'Study module Law Enforcement Administration, Chapter 4: Law Enforcement Operations and Planning with Crime Mapping (LEA-4.2).', 'generated', 'tos_2024', 1, FALSE, 'LEA-4.2', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-4.3_01', 'law_enforcement', 'Law Enforcement Operations and Planning with Crime Mapping', 'Why must other law enforcement agencies coordinate with PDEA before conducting anti-drug operations?', '[{"text": "Because only PDEA agents may lawfully arrest persons for any crime", "is_correct": false, "rationale": "Other officers may arrest persons for crimes; the coordination rule concerns drug operations."}, {"text": "Because PDEA pays for the operations of all other agencies", "is_correct": false, "rationale": "Coordination is about authority and unity of effort, not funding."}, {"text": "Because other agencies are banned from handling drug cases at all", "is_correct": false, "rationale": "Other agencies may handle drug cases, under PDEA''s coordination."}, {"text": "Because PDEA is the lead agency in enforcing the Dangerous Drugs Act", "is_correct": true, "rationale": "R.A. 9165 makes PDEA the lead agency, and other agencies'' anti-drug units act in coordination with it."}]'::jsonb, 3, 'easy', 'Coordination prevents overlapping operations and protects the integrity of drug cases.', 'R.A. 9165, Secs. 82 and 86', 'Study module Law Enforcement Administration, Chapter 4: Law Enforcement Operations and Planning with Crime Mapping (LEA-4.3).', 'generated', 'tos_2024', 1, FALSE, 'LEA-4.3', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-4.3_02', 'law_enforcement', 'Law Enforcement Operations and Planning with Crime Mapping', 'In law enforcement planning, why must the objectives be set before the alternative courses of action are developed?', '[{"text": "Because the alternatives are judged by how well they achieve the objectives", "is_correct": true, "rationale": "Objectives are the standard for comparing and choosing among alternatives."}, {"text": "Because objectives can only be written after the plan has been carried out", "is_correct": false, "rationale": "Objectives guide the plan; they are not written after it is carried out."}, {"text": "Because alternatives are chosen by lottery once the objectives are known", "is_correct": false, "rationale": "Alternatives are chosen by analysis, not by chance."}, {"text": "Because the objectives replace the need to gather any data", "is_correct": false, "rationale": "Data gathering is still needed to understand the problem and the options."}]'::jsonb, 0, 'easy', 'The planning process moves from recognizing the problem, to setting objectives, to studying data and alternatives, to choosing and carrying out the plan, and finally evaluating it.', NULL, 'Study module Law Enforcement Administration, Chapter 4: Law Enforcement Operations and Planning with Crime Mapping (LEA-4.3).', 'generated', 'tos_2024', 1, FALSE, 'LEA-4.3', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-4.3_03', 'law_enforcement', 'Law Enforcement Operations and Planning with Crime Mapping', 'What is the purpose of the evaluation step at the end of a law enforcement plan?', '[{"text": "To decide which officers deserve promotion regardless of results", "is_correct": false, "rationale": "Evaluation concerns the plan''s results, not promotions."}, {"text": "To find out whether the plan achieved its objectives and what should change", "is_correct": true, "rationale": "Evaluation compares results with objectives and feeds lessons into the next cycle of planning."}, {"text": "To start writing the plan before the problem has been identified", "is_correct": false, "rationale": "Writing the plan comes much earlier in the process."}, {"text": "To end the plan without reviewing any of its results", "is_correct": false, "rationale": "Evaluation is a review of results, not a way to skip it."}]'::jsonb, 1, 'easy', 'Without evaluation, a unit cannot tell whether its plans actually work.', NULL, 'Study module Law Enforcement Administration, Chapter 4: Law Enforcement Operations and Planning with Crime Mapping (LEA-4.3).', 'generated', 'tos_2024', 1, FALSE, 'LEA-4.3', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-4.3_04', 'law_enforcement', 'Law Enforcement Operations and Planning with Crime Mapping', 'Officers will set up a checkpoint at night. Which arrangement follows the PNP''s operational procedures?', '[{"text": "A hidden site at a dark curve so that motorists will be surprised", "is_correct": false, "rationale": "Checkpoints must be visible and announced, not designed to surprise."}, {"text": "A site manned by plainclothes officers who order everyone out of their cars", "is_correct": false, "rationale": "Personnel must be in uniform, and occupants are not routinely ordered out of their vehicles."}, {"text": "A well-lit, clearly marked site manned by uniformed personnel under an officer", "is_correct": true, "rationale": "Checkpoints must be well-lit, properly identified with signs, and manned by uniformed personnel led by an officer; inspection is generally visual."}, {"text": "A site with no signs, so drivers will not have time to hide anything", "is_correct": false, "rationale": "Signs are required so motorists know they are at a legitimate checkpoint."}]'::jsonb, 2, 'medium', 'Routine checkpoints are valid when they intrude minimally; a full search needs probable cause.', 'PNP Operational Procedures (Revised)', 'Study module Law Enforcement Administration, Chapter 4: Law Enforcement Operations and Planning with Crime Mapping (LEA-4.3).', 'generated', 'tos_2024', 1, FALSE, 'LEA-4.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-4.3_05', 'law_enforcement', 'Law Enforcement Operations and Planning with Crime Mapping', 'The first fire crew to arrive at a burning house quickly evaluates the fire, exposures and persons trapped before deploying. What is this step called?', '[{"text": "Overhaul", "is_correct": false, "rationale": "Overhaul is searching for and extinguishing hidden fire after the main fire is controlled."}, {"text": "Salvage", "is_correct": false, "rationale": "Salvage protects property from smoke and water damage."}, {"text": "Size-up", "is_correct": true, "rationale": "Size-up is the initial evaluation of the fire situation that guides the deployment of resources."}, {"text": "Ventilation", "is_correct": false, "rationale": "Ventilation releases heat and smoke from a structure."}]'::jsonb, 2, 'medium', 'Size-up continues throughout the operation as conditions change.', NULL, 'Study module Law Enforcement Administration, Chapter 4: Law Enforcement Operations and Planning with Crime Mapping (LEA-4.3).', 'generated', 'tos_2024', 1, FALSE, 'LEA-4.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-4.3_06', 'law_enforcement', 'Law Enforcement Operations and Planning with Crime Mapping', 'After a buy-bust operation, where should the inventory and photographing of the seized drugs be done?', '[{"text": "At the crime laboratory only, a week after the seizure", "is_correct": false, "rationale": "The inventory must be made immediately after seizure, not a week later at the laboratory."}, {"text": "At the home of the team leader, for safekeeping", "is_correct": false, "rationale": "Evidence cannot be kept in an officer''s home."}, {"text": "At the court, during the arraignment of the accused", "is_correct": false, "rationale": "The inventory is done at the time of seizure, not in court."}, {"text": "At the place of seizure, or the nearest police station if impracticable", "is_correct": true, "rationale": "Section 21 of R.A. 9165, as amended, requires the inventory and photographing immediately after seizure, at the place of seizure or, if not practicable, the nearest police station or office of the apprehending team."}]'::jsonb, 3, 'medium', 'The inventory must be witnessed by the accused or his representative, an elected public official, and a representative of the National Prosecution Service or the media.', 'R.A. 9165, Sec. 21, as amended by R.A. 10640', 'Study module Law Enforcement Administration, Chapter 4: Law Enforcement Operations and Planning with Crime Mapping (LEA-4.3).', 'generated', 'tos_2024', 1, FALSE, 'LEA-4.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-4.3_07', 'law_enforcement', 'Law Enforcement Operations and Planning with Crime Mapping', 'A plan to reduce robberies has run for six months. The chief now compares the results with the objectives. Which step of planning is this?', '[{"text": "Recognizing the need for a plan", "is_correct": false, "rationale": "Recognizing the need is the first step, before any plan is made."}, {"text": "Evaluation", "is_correct": true, "rationale": "Comparing results with objectives is the evaluation step at the end of the planning process."}, {"text": "Formulating the objectives", "is_correct": false, "rationale": "Objectives are set early, before the plan is carried out."}, {"text": "Gathering and analyzing data", "is_correct": false, "rationale": "Data gathering supports the plan before it is chosen."}]'::jsonb, 1, 'medium', 'Evaluation tells the chief whether to continue, change or end the plan.', NULL, 'Study module Law Enforcement Administration, Chapter 4: Law Enforcement Operations and Planning with Crime Mapping (LEA-4.3).', 'generated', 'tos_2024', 1, FALSE, 'LEA-4.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-4.3_08', 'law_enforcement', 'Law Enforcement Operations and Planning with Crime Mapping', 'A police unit will serve a search warrant in a barangay outside its own area of responsibility. What should it do before serving it?', '[{"text": "Coordinate with the police unit that has territorial jurisdiction", "is_correct": true, "rationale": "Operational procedures require coordination with the territorial unit to avoid misencounters and ensure support."}, {"text": "Keep the operation secret from all other police units", "is_correct": false, "rationale": "Total secrecy from the territorial unit risks friendly-fire incidents."}, {"text": "Ask the barangay captain to serve the warrant instead", "is_correct": false, "rationale": "The warrant must be served by the officers named or authorized, not by the barangay captain."}, {"text": "Wait until the warrant has expired before entering the area", "is_correct": false, "rationale": "A search warrant may be served only while it is valid."}]'::jsonb, 0, 'medium', 'Coordination is a standard part of planning police operations in another unit''s area.', 'PNP Operational Procedures (Revised)', 'Study module Law Enforcement Administration, Chapter 4: Law Enforcement Operations and Planning with Crime Mapping (LEA-4.3).', 'generated', 'tos_2024', 1, FALSE, 'LEA-4.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-4.4_01', 'law_enforcement', 'Law Enforcement Operations and Planning with Crime Mapping', 'A GIS map shows that most robberies happen within 200 meters of a jeepney terminal between 6 and 9 p.m. What is the best use of this finding?', '[{"text": "Spread patrol equally across the whole city at all hours", "is_correct": false, "rationale": "Equal patrol ignores the data and wastes resources where crime is rare."}, {"text": "Close the jeepney terminal permanently to stop the robberies", "is_correct": false, "rationale": "Closing a terminal is an extreme measure that is not the role of the police."}, {"text": "Focus patrol and visibility on that area during those hours", "is_correct": true, "rationale": "Hotspot policing directs resources to the places and times where crime concentrates."}, {"text": "Ignore the map, since robberies can happen anywhere", "is_correct": false, "rationale": "Crime data show concentration, which is the reason for crime mapping."}]'::jsonb, 2, 'medium', 'Matching patrol to time and place patterns is a basic use of GIS in policing.', NULL, 'Study module Law Enforcement Administration, Chapter 4: Law Enforcement Operations and Planning with Crime Mapping (LEA-4.4).', 'generated', 'tos_2024', 1, FALSE, 'LEA-4.4', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-4.4_02', 'law_enforcement', 'Law Enforcement Operations and Planning with Crime Mapping', 'A dark alley with overgrown bushes has repeated snatching incidents. Which environmental measure fits the problem?', '[{"text": "Put up a sign telling people to avoid the alley at night", "is_correct": false, "rationale": "A sign shifts the burden to the public and does not change the conditions."}, {"text": "Post a guard there permanently while leaving the area dark", "is_correct": false, "rationale": "A permanent guard is costly and does not fix the conditions that make the alley risky."}, {"text": "Improve the lighting and trim the bushes to remove hiding spots", "is_correct": true, "rationale": "Lighting and clearing vegetation improve natural surveillance and remove places where offenders hide."}, {"text": "Paint the walls of the alley a darker color", "is_correct": false, "rationale": "Darker walls reduce visibility further."}]'::jsonb, 2, 'medium', 'CPTED changes the setting so that offenders feel more likely to be seen.', NULL, 'Study module Law Enforcement Administration, Chapter 4: Law Enforcement Operations and Planning with Crime Mapping (LEA-4.4).', 'generated', 'tos_2024', 1, FALSE, 'LEA-4.4', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-4.4_03', 'law_enforcement', 'Law Enforcement Operations and Planning with Crime Mapping', 'Residents of a subdivision put up a gate, a low fence and signs with the subdivision''s name to show that the area is theirs. Which CPTED principle is this?', '[{"text": "Natural surveillance", "is_correct": false, "rationale": "Natural surveillance concerns visibility of activity."}, {"text": "Maintenance", "is_correct": false, "rationale": "Maintenance concerns keeping the place in good repair."}, {"text": "Target hardening", "is_correct": false, "rationale": "Target hardening makes specific targets physically harder to attack."}, {"text": "Territorial reinforcement", "is_correct": true, "rationale": "Territorial reinforcement uses physical features to express ownership of a space and discourage intruders."}]'::jsonb, 3, 'medium', 'A space that looks cared for and owned signals to offenders that someone is watching.', NULL, 'Study module Law Enforcement Administration, Chapter 4: Law Enforcement Operations and Planning with Crime Mapping (LEA-4.4).', 'generated', 'tos_2024', 1, FALSE, 'LEA-4.4', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-4.4_04', 'law_enforcement', 'Law Enforcement Operations and Planning with Crime Mapping', 'Broken streetlights and graffiti have been left unrepaired in a plaza, and disorder is rising. Which action applies the CPTED principle of maintenance?', '[{"text": "Install more cameras but leave the damage as it is", "is_correct": false, "rationale": "Cameras alone do not address the signs of neglect."}, {"text": "Ban young people from the plaza after dark", "is_correct": false, "rationale": "A curfew-type ban punishes users instead of fixing the environment."}, {"text": "Repair the lights and clean up the graffiti promptly", "is_correct": true, "rationale": "Maintenance keeps a place in good condition so it signals that it is cared for and watched."}, {"text": "Wait for the barangay elections before acting", "is_correct": false, "rationale": "Delay allows the disorder to grow."}]'::jsonb, 2, 'medium', 'The broken windows idea holds that visible neglect invites more disorder and crime.', NULL, 'Study module Law Enforcement Administration, Chapter 4: Law Enforcement Operations and Planning with Crime Mapping (LEA-4.4).', 'generated', 'tos_2024', 1, FALSE, 'LEA-4.4', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-4.4_05', 'law_enforcement', 'Law Enforcement Operations and Planning with Crime Mapping', 'An analyst wants to count the incidents that happened within 100 meters of each bar in the city. Which GIS operation should be used?', '[{"text": "Choropleth mapping", "is_correct": false, "rationale": "A choropleth map shades areas by value; it does not create distance zones."}, {"text": "Geocoding", "is_correct": false, "rationale": "Geocoding converts addresses into map coordinates."}, {"text": "Georeferencing", "is_correct": false, "rationale": "Georeferencing aligns a scanned map or image to real-world coordinates."}, {"text": "Buffer analysis", "is_correct": true, "rationale": "A buffer draws a zone of a set distance around features so the incidents inside it can be counted."}]'::jsonb, 3, 'medium', 'Buffers help test whether crime clusters around certain places.', NULL, 'Study module Law Enforcement Administration, Chapter 4: Law Enforcement Operations and Planning with Crime Mapping (LEA-4.4).', 'generated', 'tos_2024', 1, FALSE, 'LEA-4.4', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-4.4_06', 'law_enforcement', 'Law Enforcement Operations and Planning with Crime Mapping', 'Incident reports list only street addresses. What must be done before the incidents can be plotted on a GIS map?', '[{"text": "Buffering", "is_correct": false, "rationale": "Buffering creates distance zones around features already on the map."}, {"text": "Overlaying", "is_correct": false, "rationale": "Overlaying combines layers that are already mapped."}, {"text": "Geocoding", "is_correct": true, "rationale": "Geocoding converts addresses or place names into geographic coordinates so they can be mapped."}, {"text": "Hotspot analysis", "is_correct": false, "rationale": "Hotspot analysis needs mapped points first."}]'::jsonb, 2, 'medium', 'Accurate addresses in reports are needed for accurate crime maps.', NULL, 'Study module Law Enforcement Administration, Chapter 4: Law Enforcement Operations and Planning with Crime Mapping (LEA-4.4).', 'generated', 'tos_2024', 1, FALSE, 'LEA-4.4', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-4.4_07', 'law_enforcement', 'Law Enforcement Operations and Planning with Crime Mapping', 'Barangay A has 50 thefts and 50,000 residents. Barangay B has 30 thefts and 10,000 residents. Which statement is correct?', '[{"text": "Barangay A has the higher theft rate, 50 per 1,000 residents", "is_correct": false, "rationale": "A''s rate is 1 per 1,000, not 50."}, {"text": "Barangay B has the higher theft rate, 3 per 1,000 residents", "is_correct": true, "rationale": "Barangay B''s rate is 30 / 10,000 x 1,000 = 3 per 1,000, while A''s is 50 / 50,000 x 1,000 = 1 per 1,000."}, {"text": "Both barangays have the same theft rate of 1 per 1,000", "is_correct": false, "rationale": "The rates differ: 1 and 3 per 1,000."}, {"text": "Barangay A has the higher rate because it has more thefts", "is_correct": false, "rationale": "Counts alone mislead; rates adjust for population."}]'::jsonb, 1, 'medium', 'Crime rates, not raw counts, should be used to compare areas with different populations.', NULL, 'Study module Law Enforcement Administration, Chapter 4: Law Enforcement Operations and Planning with Crime Mapping (LEA-4.4).', 'generated', 'tos_2024', 1, FALSE, 'LEA-4.4', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-4.5_01', 'law_enforcement', 'Law Enforcement Operations and Planning with Crime Mapping', 'A suspect is arrested for robbery. What must the arresting officer do at the time of arrest?', '[{"text": "Ask him to confess first, then tell him why he was arrested", "is_correct": false, "rationale": "Questioning before giving the warnings violates his rights."}, {"text": "Bring him to the media for a press presentation before booking", "is_correct": false, "rationale": "Parading a suspect before the media is contrary to his right to be presumed innocent."}, {"text": "Inform him of the reason for the arrest and of his rights to silence and counsel", "is_correct": true, "rationale": "R.A. 7438 and the Rules require the officer to tell the person the cause of the arrest and to inform him of his rights in a language he understands."}, {"text": "Keep the reason for the arrest secret until the trial begins", "is_correct": false, "rationale": "The person has a right to know why he is being arrested."}]'::jsonb, 2, 'medium', 'These duties protect the arrested person and the admissibility of the evidence.', 'R.A. 7438, Sec. 2; Rules of Court, Rule 113, Sec. 8', 'Study module Law Enforcement Administration, Chapter 4: Law Enforcement Operations and Planning with Crime Mapping (LEA-4.5).', 'generated', 'tos_2024', 1, FALSE, 'LEA-4.5', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-4.5_02', 'law_enforcement', 'Law Enforcement Operations and Planning with Crime Mapping', 'To make a detainee confess, an investigator threatens to harm his family. Under R.A. 9745, what is this act?', '[{"text": "A lawful method of interrogation", "is_correct": false, "rationale": "No form of torture is allowed in interrogation."}, {"text": "Simple coercion under the Revised Penal Code", "is_correct": false, "rationale": "R.A. 9745 specifically defines and punishes torture, including mental torture."}, {"text": "Grave threats, but not torture", "is_correct": false, "rationale": "The act is specifically torture when done by a person in authority to obtain a confession."}, {"text": "Mental or psychological torture", "is_correct": true, "rationale": "R.A. 9745 includes threats to harm the person or his family among acts of mental or psychological torture."}]'::jsonb, 3, 'medium', 'A confession obtained through torture is inadmissible, and torture is a non-derogable right violation.', 'R.A. 9745 (Anti-Torture Act of 2009), Sec. 4', 'Study module Law Enforcement Administration, Chapter 4: Law Enforcement Operations and Planning with Crime Mapping (LEA-4.5).', 'generated', 'tos_2024', 1, FALSE, 'LEA-4.5', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-4.5_03', 'law_enforcement', 'Law Enforcement Operations and Planning with Crime Mapping', 'A person was arrested without a warrant for an offense punishable by an afflictive penalty. Within what period must he be delivered to the proper judicial authorities?', '[{"text": "12 hours", "is_correct": false, "rationale": "Twelve hours applies to light penalties."}, {"text": "18 hours", "is_correct": false, "rationale": "Eighteen hours applies to correctional penalties."}, {"text": "72 hours", "is_correct": false, "rationale": "There is no 72-hour period under Article 125."}, {"text": "36 hours", "is_correct": true, "rationale": "Article 125 sets 36 hours for crimes punishable by afflictive or capital penalties."}]'::jsonb, 3, 'medium', 'Failure to deliver within the period is the crime of delay in the delivery of detained persons.', 'Revised Penal Code, Art. 125', 'Study module Law Enforcement Administration, Chapter 4: Law Enforcement Operations and Planning with Crime Mapping (LEA-4.5).', 'generated', 'tos_2024', 1, FALSE, 'LEA-4.5', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-4.5_04', 'law_enforcement', 'Law Enforcement Operations and Planning with Crime Mapping', 'Police ''invite'' a suspect to the station to answer questions about a robbery. Why are his custodial rights already in effect?', '[{"text": "Because R.A. 7438 treats such an invitation of a suspect as custodial investigation", "is_correct": true, "rationale": "R.A. 7438 states that custodial investigation includes the practice of issuing an invitation to a person investigated for an offense he is suspected to have committed."}, {"text": "Because any visit to a police station is an arrest under the Rules", "is_correct": false, "rationale": "Not every station visit is an arrest; the invitation of a suspect is what triggers the rights."}, {"text": "Because invited persons must always be detained for 36 hours", "is_correct": false, "rationale": "Invited persons are not required to be detained."}, {"text": "Because custodial rights apply only once a case is filed in court", "is_correct": false, "rationale": "Custodial rights apply during investigation, before any case is filed."}]'::jsonb, 0, 'hard', 'The law prevents officers from avoiding custodial rights by calling an interrogation an ''invitation''.', 'R.A. 7438, Sec. 2(f)', 'Study module Law Enforcement Administration, Chapter 4: Law Enforcement Operations and Planning with Crime Mapping (LEA-4.5).', 'generated', 'tos_2024', 1, FALSE, 'LEA-4.5', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-4.5_05', 'law_enforcement', 'Law Enforcement Operations and Planning with Crime Mapping', 'An officer frisked a man on the street only because he looked nervous. Was the stop-and-frisk valid?', '[{"text": "Yes, because looking nervous is enough to suspect a crime", "is_correct": false, "rationale": "Mere nervousness or suspicion does not justify a frisk."}, {"text": "Yes, because officers may frisk anyone in a public place", "is_correct": false, "rationale": "Public places do not remove the protection against unreasonable searches."}, {"text": "No, a frisk needs genuine reason from more than mere nervousness", "is_correct": true, "rationale": "Jurisprudence requires a genuine reason, based on the officer''s experience and the surrounding conditions, to believe the person is armed or committing a crime; nervousness alone is not enough."}, {"text": "No, because a frisk is never allowed without a warrant", "is_correct": false, "rationale": "A valid stop-and-frisk is a recognized exception to the warrant requirement."}]'::jsonb, 2, 'hard', 'Stop-and-frisk is limited to a protective pat-down of outer clothing for weapons.', '1987 Constitution, Art. III, Sec. 2; Manalili v. CA; Malacat v. CA', 'Study module Law Enforcement Administration, Chapter 4: Law Enforcement Operations and Planning with Crime Mapping (LEA-4.5).', 'generated', 'tos_2024', 1, FALSE, 'LEA-4.5', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-4.5_06', 'law_enforcement', 'Law Enforcement Operations and Planning with Crime Mapping', 'Police are assigned to a rally that has a permit. Which deployment best complies with B.P. 880?', '[{"text": "Uniformed, with nameplates, unarmed, at least 100 meters away, with maximum tolerance", "is_correct": true, "rationale": "B.P. 880 requires the law enforcement detail to be in full uniform with nameplates, without firearms though they may carry riot gear, to stay at least 100 meters away, and to observe maximum tolerance."}, {"text": "Plainclothes officers mixing with the crowd and carrying firearms", "is_correct": false, "rationale": "Plainclothes officers with firearms violate the rule on uniform and firearms."}, {"text": "Officers forming a line in front of the stage and blocking the speakers", "is_correct": false, "rationale": "Blocking the speakers interferes with a lawful assembly."}, {"text": "Officers ordering the crowd to leave once the speeches become critical", "is_correct": false, "rationale": "Criticism of the government is protected; it is not a ground for dispersal."}]'::jsonb, 0, 'hard', 'Dispersal of a permitted rally is allowed only under the conditions and steps set by the law.', 'B.P. 880 (Public Assembly Act of 1985), Secs. 9-11', 'Study module Law Enforcement Administration, Chapter 4: Law Enforcement Operations and Planning with Crime Mapping (LEA-4.5).', 'generated', 'tos_2024', 1, FALSE, 'LEA-4.5', 'Evaluating') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-5.1_01', 'law_enforcement', 'Character Formation 1 - Nationalism and Patriotism', 'How did the aim of the Propaganda Movement differ from that of the Katipunan?', '[{"text": "The Propaganda sought reforms under Spain; the Katipunan sought independence through revolution", "is_correct": true, "rationale": "The Propagandists, such as Rizal, del Pilar and Lopez Jaena, asked for reforms like representation in the Cortes; the Katipunan of Bonifacio worked for independence by armed revolt."}, {"text": "The Propaganda sought independence by war; the Katipunan sought reforms through writing", "is_correct": false, "rationale": "This reverses their aims."}, {"text": "Both sought only to replace the Spanish governor with a Filipino", "is_correct": false, "rationale": "Neither movement aimed merely at replacing the governor."}, {"text": "Both sought union with the United States through peaceful means", "is_correct": false, "rationale": "Neither movement sought union with the United States."}]'::jsonb, 0, 'easy', 'The failure of peaceful reforms led many Filipinos to support the revolution of 1896.', NULL, 'Study module Law Enforcement Administration, Chapter 5: Character Formation 1 - Nationalism and Patriotism (LEA-5.1).', 'generated', 'tos_2024', 1, FALSE, 'LEA-5.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-5.1_02', 'law_enforcement', 'Character Formation 1 - Nationalism and Patriotism', 'Which Filipino value is shown when neighbors work together to carry a family''s house to a new place?', '[{"text": "Utang na loob", "is_correct": false, "rationale": "Utang na loob is a debt of gratitude."}, {"text": "Bayanihan", "is_correct": true, "rationale": "Bayanihan is the spirit of communal unity and cooperation, traditionally pictured as neighbors moving a house."}, {"text": "Amor propio", "is_correct": false, "rationale": "Amor propio is self-esteem or sensitivity to criticism."}, {"text": "Ningas cogon", "is_correct": false, "rationale": "Ningas cogon is starting something with enthusiasm and quickly losing interest."}]'::jsonb, 1, 'easy', 'Bayanihan is often cited as a strength of the Filipino character.', NULL, 'Study module Law Enforcement Administration, Chapter 5: Character Formation 1 - Nationalism and Patriotism (LEA-5.1).', 'generated', 'tos_2024', 1, FALSE, 'LEA-5.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-5.1_03', 'law_enforcement', 'Character Formation 1 - Nationalism and Patriotism', 'What is the difference between patriotism and nationalism as commonly taught in character formation?', '[{"text": "Patriotism applies only to soldiers; nationalism applies only to civilians", "is_correct": false, "rationale": "Both apply to all citizens, not only to particular groups."}, {"text": "Patriotism means obeying foreign powers; nationalism means opposing all foreigners", "is_correct": false, "rationale": "Neither involves obeying foreign powers, and nationalism is not hostility to all foreigners."}, {"text": "Patriotism and nationalism mean exactly the same thing in every context", "is_correct": false, "rationale": "They are related but not identical ideas."}, {"text": "Patriotism is love of country; nationalism also asserts national identity and interests", "is_correct": true, "rationale": "Patriotism is love of and devotion to one''s country; nationalism includes consciousness of national identity and the promotion of national interests and sovereignty."}]'::jsonb, 3, 'easy', 'Both are values the State seeks to develop through education under Art. XIV of the Constitution.', '1987 Constitution, Art. XIV, Sec. 3(2)', 'Study module Law Enforcement Administration, Chapter 5: Character Formation 1 - Nationalism and Patriotism (LEA-5.1).', 'generated', 'tos_2024', 1, FALSE, 'LEA-5.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-5.1_04', 'law_enforcement', 'Character Formation 1 - Nationalism and Patriotism', 'Why can the Filipino value of ''pakikisama'' become a weakness inside a police organization?', '[{"text": "It makes officers too strict with fellow officers who make mistakes", "is_correct": false, "rationale": "Pakikisama tends toward leniency, not strictness."}, {"text": "It causes officers to refuse any teamwork with their colleagues", "is_correct": false, "rationale": "Pakikisama promotes teamwork, sometimes to excess."}, {"text": "It leads officers to report every small error to the media", "is_correct": false, "rationale": "Pakikisama discourages, rather than encourages, exposing colleagues."}, {"text": "The wish to get along may lead members to tolerate colleagues'' wrongdoing", "is_correct": true, "rationale": "Pakikisama, smooth interpersonal relations, becomes harmful when keeping harmony means covering up misconduct."}]'::jsonb, 3, 'hard', 'A value can be a strength or a weakness depending on how it is practiced.', NULL, 'Study module Law Enforcement Administration, Chapter 5: Character Formation 1 - Nationalism and Patriotism (LEA-5.1).', 'generated', 'tos_2024', 1, FALSE, 'LEA-5.1', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-5.1_05', 'law_enforcement', 'Character Formation 1 - Nationalism and Patriotism', 'A city starts a crime-prevention program with great enthusiasm, but within months the meetings stop and the project is forgotten. Which Filipino trait does this illustrate?', '[{"text": "Ningas cogon", "is_correct": true, "rationale": "Ningas cogon, like cogon grass that burns fast and dies out, describes starting with enthusiasm and quickly losing interest."}, {"text": "Bahala na", "is_correct": false, "rationale": "Bahala na is a fatalistic or trusting attitude of leaving things to fate or God."}, {"text": "Hiya", "is_correct": false, "rationale": "Hiya is a sense of shame or propriety."}, {"text": "Bayanihan", "is_correct": false, "rationale": "Bayanihan is communal cooperation, the opposite of abandoning a shared project."}]'::jsonb, 0, 'hard', 'Recognizing such traits helps leaders design programs with follow-through and monitoring.', NULL, 'Study module Law Enforcement Administration, Chapter 5: Character Formation 1 - Nationalism and Patriotism (LEA-5.1).', 'generated', 'tos_2024', 1, FALSE, 'LEA-5.1', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-5.1_06', 'law_enforcement', 'Character Formation 1 - Nationalism and Patriotism', 'Why is ''colonial mentality'' considered a hindrance to Philippine nationalism?', '[{"text": "It makes people too proud of local products and culture", "is_correct": false, "rationale": "Pride in local products is the opposite of colonial mentality."}, {"text": "It treats foreign products and ideas as better and undervalues Filipino ones", "is_correct": true, "rationale": "Colonial mentality is the attitude that what is foreign is superior, which weakens pride in and support for Filipino identity and products."}, {"text": "It forces citizens to learn several local languages", "is_correct": false, "rationale": "Language learning is not what colonial mentality means."}, {"text": "It requires the government to cut ties with all foreign countries", "is_correct": false, "rationale": "Nationalism does not require cutting ties with other countries."}]'::jsonb, 1, 'hard', 'Nationalism encourages valuing Filipino culture without rejecting good foreign influences.', NULL, 'Study module Law Enforcement Administration, Chapter 5: Character Formation 1 - Nationalism and Patriotism (LEA-5.1).', 'generated', 'tos_2024', 1, FALSE, 'LEA-5.1', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-5.2_01', 'law_enforcement', 'Character Formation 1 - Nationalism and Patriotism', 'What do the eight primary rays of the sun on the Philippine flag represent?', '[{"text": "The first eight provinces that rose in revolt against Spain", "is_correct": true, "rationale": "The rays stand for the first eight provinces that took up arms against Spain: Manila, Cavite, Bulacan, Pampanga, Nueva Ecija, Bataan, Laguna and Batangas."}, {"text": "The eight regions of the Philippines at independence", "is_correct": false, "rationale": "The rays do not represent regions."}, {"text": "The eight founders of the Katipunan in 1892", "is_correct": false, "rationale": "The rays do not represent the founders of the Katipunan."}, {"text": "The eight articles of the Malolos Constitution", "is_correct": false, "rationale": "The rays do not represent articles of any constitution."}]'::jsonb, 0, 'easy', 'These provinces were placed under martial law by the Spanish authorities in 1896.', 'R.A. 8491', 'Study module Law Enforcement Administration, Chapter 5: Character Formation 1 - Nationalism and Patriotism (LEA-5.2).', 'generated', 'tos_2024', 1, FALSE, 'LEA-5.2', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-5.2_02', 'law_enforcement', 'Character Formation 1 - Nationalism and Patriotism', 'What do the three five-pointed stars on the Philippine flag represent?', '[{"text": "Faith, hope and charity", "is_correct": false, "rationale": "These are religious virtues, not the meaning of the stars."}, {"text": "Luzon, Visayas and Mindanao", "is_correct": true, "rationale": "The three stars represent the three major island groups of the country."}, {"text": "Liberty, equality and fraternity", "is_correct": false, "rationale": "These are ideals, not the meaning of the stars."}, {"text": "The three branches of government", "is_correct": false, "rationale": "The branches of government are not represented by the stars."}]'::jsonb, 1, 'easy', 'The flag''s design and colors are set by R.A. 8491.', 'R.A. 8491', 'Study module Law Enforcement Administration, Chapter 5: Character Formation 1 - Nationalism and Patriotism (LEA-5.2).', 'generated', 'tos_2024', 1, FALSE, 'LEA-5.2', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-5.2_03', 'law_enforcement', 'Character Formation 1 - Nationalism and Patriotism', 'Which describes the proper way to fly the flag at half-mast as a sign of mourning?', '[{"text": "Raise it directly to half-mast without reaching the peak", "is_correct": false, "rationale": "The flag must reach the peak first."}, {"text": "Hoist it to the peak for a moment, then lower it to half-mast", "is_correct": true, "rationale": "The Code requires the flag to be hoisted to the peak for a moment before it is lowered to half-mast, and raised to the peak again before it is lowered for the day."}, {"text": "Fly it upside down at the peak of the pole", "is_correct": false, "rationale": "Flying the flag with the red field on top signals war, not mourning."}, {"text": "Tie a black ribbon to it and leave it at the bottom", "is_correct": false, "rationale": "The flag must be raised, not left at the bottom of the pole."}]'::jsonb, 1, 'easy', 'Half-mast is ordered for official periods of mourning.', 'R.A. 8491', 'Study module Law Enforcement Administration, Chapter 5: Character Formation 1 - Nationalism and Patriotism (LEA-5.2).', 'generated', 'tos_2024', 1, FALSE, 'LEA-5.2', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-5.2_04', 'law_enforcement', 'Character Formation 1 - Nationalism and Patriotism', 'The country is in a state of war. How should the flag be flown from a flagpole?', '[{"text": "With the blue field on top", "is_correct": false, "rationale": "The blue field is on top in time of peace."}, {"text": "At half-mast throughout the war", "is_correct": false, "rationale": "Half-mast is a sign of mourning, not of war."}, {"text": "With the red field on top", "is_correct": true, "rationale": "R.A. 8491 requires the red field on top in time of war."}, {"text": "With the white triangle at the bottom", "is_correct": false, "rationale": "The position of the triangle at the hoist does not change in wartime."}]'::jsonb, 2, 'medium', 'The Philippine flag is one of the few flags that signals a state of war by its position.', 'R.A. 8491', 'Study module Law Enforcement Administration, Chapter 5: Character Formation 1 - Nationalism and Patriotism (LEA-5.2).', 'generated', 'tos_2024', 1, FALSE, 'LEA-5.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-5.2_05', 'law_enforcement', 'Character Formation 1 - Nationalism and Patriotism', 'In peacetime, a large flag will be hung vertically on a wall. How should it be displayed?', '[{"text": "With the red field to the observer''s left", "is_correct": false, "rationale": "The red field goes to the observer''s left only in time of war."}, {"text": "With the blue field to the observer''s left", "is_correct": true, "rationale": "When hung vertically, the blue field is to the right of the flag, which is the observer''s left, in time of peace."}, {"text": "With the sun and stars at the bottom", "is_correct": false, "rationale": "The triangle with the sun and stars goes at the top when hung vertically."}, {"text": "With the blue field facing the wall", "is_correct": false, "rationale": "The flag must face the viewer, not the wall."}]'::jsonb, 1, 'medium', 'The same peace and war rule applies whether the flag is flown or hung.', 'R.A. 8491', 'Study module Law Enforcement Administration, Chapter 5: Character Formation 1 - Nationalism and Patriotism (LEA-5.2).', 'generated', 'tos_2024', 1, FALSE, 'LEA-5.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-5.2_06', 'law_enforcement', 'Character Formation 1 - Nationalism and Patriotism', 'The Philippine flag is displayed beside the flag of a visiting country. Where should the Philippine flag be placed?', '[{"text": "On its own left, which is the observer''s right", "is_correct": false, "rationale": "The flag''s left is not the position of honor."}, {"text": "Below the other flag on the same pole", "is_correct": false, "rationale": "Two national flags are not flown one below the other on the same pole."}, {"text": "Behind the other flag, out of view", "is_correct": false, "rationale": "The flag must not be hidden from view."}, {"text": "On its own right, which is the observer''s left", "is_correct": true, "rationale": "When displayed with another flag, the Philippine flag is placed on the right of the other flag, the position of honor."}]'::jsonb, 3, 'medium', 'If there is a line of other flags, the Philippine flag is placed in the middle of the line.', 'R.A. 8491', 'Study module Law Enforcement Administration, Chapter 5: Character Formation 1 - Nationalism and Patriotism (LEA-5.2).', 'generated', 'tos_2024', 1, FALSE, 'LEA-5.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-5.2_07', 'law_enforcement', 'Character Formation 1 - Nationalism and Patriotism', 'The flag will cover the casket of a deceased veteran. How must it be placed?', '[{"text": "Red field at the head, blue field covering the left side", "is_correct": false, "rationale": "The red field is not placed at the head."}, {"text": "Sun and stars at the foot, red field covering the right side", "is_correct": false, "rationale": "The triangle with the sun and stars goes at the head."}, {"text": "Folded neatly and placed on the casket''s lid", "is_correct": false, "rationale": "The flag covers the casket; it is folded only before interment and given to the heirs."}, {"text": "White triangle at the head, blue field covering the right side", "is_correct": true, "rationale": "R.A. 8491 requires the white triangle at the head and the blue portion covering the right side of the casket."}]'::jsonb, 3, 'medium', 'The flag must not be lowered into the grave.', 'R.A. 8491', 'Study module Law Enforcement Administration, Chapter 5: Character Formation 1 - Nationalism and Patriotism (LEA-5.2).', 'generated', 'tos_2024', 1, FALSE, 'LEA-5.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-5.2_08', 'law_enforcement', 'Character Formation 1 - Nationalism and Patriotism', 'A restaurant plans to use small Philippine flags as table covers for an Independence Day promotion. Is this allowed?', '[{"text": "Yes, because it is done to honor Independence Day", "is_correct": false, "rationale": "Good intentions do not make a prohibited use lawful."}, {"text": "No, using the flag as a tablecloth or covering is prohibited", "is_correct": true, "rationale": "R.A. 8491 prohibits using the flag as drapery, festoon, tablecloth or covering for objects."}, {"text": "Yes, as long as the flags are new and clean", "is_correct": false, "rationale": "The condition of the flags does not change the prohibition."}, {"text": "No, but only because restaurants may not display flags", "is_correct": false, "rationale": "Restaurants may display the flag properly; the problem is using it as a covering."}]'::jsonb, 1, 'medium', 'Other prohibited acts include dipping the flag as a salute and using it as a trademark.', 'R.A. 8491, Sec. 34', 'Study module Law Enforcement Administration, Chapter 5: Character Formation 1 - Nationalism and Patriotism (LEA-5.2).', 'generated', 'tos_2024', 1, FALSE, 'LEA-5.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-5.2_09', 'law_enforcement', 'Character Formation 1 - Nationalism and Patriotism', 'Under R.A. 8491, when must government offices hold the flag-raising and flag-lowering ceremonies?', '[{"text": "Raising and lowering only on national holidays", "is_correct": false, "rationale": "The ceremonies are weekly, not only on holidays."}, {"text": "Raising every Friday morning; lowering every Monday afternoon", "is_correct": false, "rationale": "This reverses the days."}, {"text": "Raising only on June 12 and lowering on December 30", "is_correct": false, "rationale": "The ceremonies are not limited to two days of the year."}, {"text": "Raising every Monday morning; lowering every Friday afternoon", "is_correct": true, "rationale": "The Code requires government offices and educational institutions to hold the flag-raising ceremony every Monday morning and the flag-lowering ceremony every Friday afternoon."}]'::jsonb, 3, 'medium', 'The flag is displayed in public buildings every day throughout the year.', 'R.A. 8491, Sec. 18', 'Study module Law Enforcement Administration, Chapter 5: Character Formation 1 - Nationalism and Patriotism (LEA-5.2).', 'generated', 'tos_2024', 1, FALSE, 'LEA-5.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-5.2_10', 'law_enforcement', 'Character Formation 1 - Nationalism and Patriotism', 'The National Anthem is played at a program, but no flag is present. What should the audience do?', '[{"text": "Stand at attention facing the source of the music, right palm over the left chest", "is_correct": true, "rationale": "When the anthem is played, people stand at attention facing the flag or, if there is none, the source of the music, with the right palm over the left chest."}, {"text": "Remain seated, since the anthem need not be honored without a flag", "is_correct": false, "rationale": "The anthem must be honored even without a flag."}, {"text": "Face the stage and sing only the first verse", "is_correct": false, "rationale": "The anthem should be sung in full with fervor."}, {"text": "Raise the right hand as when taking an oath", "is_correct": false, "rationale": "Raising the right hand is for oaths, not for the anthem."}]'::jsonb, 0, 'medium', 'Uniformed personnel salute as prescribed by their regulations.', 'R.A. 8491, Sec. 38', 'Study module Law Enforcement Administration, Chapter 5: Character Formation 1 - Nationalism and Patriotism (LEA-5.2).', 'generated', 'tos_2024', 1, FALSE, 'LEA-5.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-5.3_01', 'law_enforcement', 'Character Formation 1 - Nationalism and Patriotism', 'Article II, Section 3 of the Constitution declares civilian authority supreme over the military. What does this principle mean in practice?', '[{"text": "Military forces are under civilian leaders such as the President as commander-in-chief", "is_correct": true, "rationale": "Civilian supremacy places the armed forces under elected civilian authority, with the President as commander-in-chief."}, {"text": "Military officers may take over the government during any crisis", "is_correct": false, "rationale": "The military has no right to take over the government."}, {"text": "Civilians may command troops in battle without military training", "is_correct": false, "rationale": "The principle concerns control and authority, not tactical command in battle."}, {"text": "The military may disregard civilian laws during operations", "is_correct": false, "rationale": "The military is bound by civilian laws at all times."}]'::jsonb, 0, 'hard', 'The same section describes the AFP as the protector of the people and the State.', '1987 Constitution, Art. II, Sec. 3; Art. VII, Sec. 18', 'Study module Law Enforcement Administration, Chapter 5: Character Formation 1 - Nationalism and Patriotism (LEA-5.3).', 'generated', 'tos_2024', 1, FALSE, 'LEA-5.3', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-5.3_02', 'law_enforcement', 'Character Formation 1 - Nationalism and Patriotism', 'Article XVI, Section 6 requires one police force that is national in scope and civilian in character. Which feature of the PNP follows from this?', '[{"text": "It is separate from the AFP and administered by the National Police Commission", "is_correct": true, "rationale": "Being civilian in character, the PNP is separate from the military and is administered and controlled by NAPOLCOM under R.A. 6975."}, {"text": "It is a branch of the AFP under the Department of National Defense", "is_correct": false, "rationale": "The 1987 Constitution removed the police from military control."}, {"text": "It is divided into independent city police forces controlled by mayors", "is_correct": false, "rationale": "The police force must be national in scope, not separate city forces."}, {"text": "It is a private force hired by the local governments", "is_correct": false, "rationale": "The police force is a government institution, not a private one."}]'::jsonb, 0, 'hard', 'Mayors have operational supervision and control over local police, as deputies of NAPOLCOM.', '1987 Constitution, Art. XVI, Sec. 6; R.A. 6975', 'Study module Law Enforcement Administration, Chapter 5: Character Formation 1 - Nationalism and Patriotism (LEA-5.3).', 'generated', 'tos_2024', 1, FALSE, 'LEA-5.3', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-5.3_03', 'law_enforcement', 'Character Formation 1 - Nationalism and Patriotism', 'A school is planning its values program. Which activity best carries out Article XIV, Section 3(2) of the Constitution?', '[{"text": "A program that teaches only test-taking skills for board examinations", "is_correct": false, "rationale": "Test-taking skills alone do not address the values the provision names."}, {"text": "Lessons that build patriotism, respect for human rights and appreciation of national heroes", "is_correct": true, "rationale": "Article XIV, Sec. 3(2) directs schools to inculcate patriotism and nationalism, foster love of humanity and respect for human rights, and appreciate the role of national heroes."}, {"text": "A class that encourages students to prefer foreign culture over their own", "is_correct": false, "rationale": "The provision promotes national identity, not preference for foreign culture."}, {"text": "An activity that requires students to join a particular religion", "is_correct": false, "rationale": "Religious instruction is optional and needs written consent under Sec. 3(3)."}]'::jsonb, 1, 'hard', 'Article XIV covers education, science and technology, arts, culture and sports.', '1987 Constitution, Art. XIV, Sec. 3', 'Study module Law Enforcement Administration, Chapter 5: Character Formation 1 - Nationalism and Patriotism (LEA-5.3).', 'generated', 'tos_2024', 1, FALSE, 'LEA-5.3', 'Evaluating') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-5.3_04', 'law_enforcement', 'Character Formation 1 - Nationalism and Patriotism', 'A student says that the Preamble of the Constitution grants enforceable rights to citizens. How should this claim be evaluated?', '[{"text": "Correct; the Preamble is the source of all rights in the Bill of Rights", "is_correct": false, "rationale": "Rights are found in the Bill of Rights and other provisions, not in the Preamble."}, {"text": "Correct; courts enforce the Preamble as the main article of the Constitution", "is_correct": false, "rationale": "The Preamble is an introduction, not the main article."}, {"text": "Incorrect; the Preamble states aims and aspirations and may guide interpretation", "is_correct": true, "rationale": "The Preamble is not a source of rights or powers, but it shows the purposes of the Constitution and can aid its interpretation."}, {"text": "Incorrect; the Preamble has no use at all in understanding the Constitution", "is_correct": false, "rationale": "The Preamble is useful in understanding the intent of the Constitution."}]'::jsonb, 2, 'hard', 'The Preamble names the sovereign Filipino people as the authors of the Constitution.', '1987 Constitution, Preamble', 'Study module Law Enforcement Administration, Chapter 5: Character Formation 1 - Nationalism and Patriotism (LEA-5.3).', 'generated', 'tos_2024', 1, FALSE, 'LEA-5.3', 'Evaluating') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-6.1_01', 'law_enforcement', 'Character Formation 2 - Leadership, Decision Making, Management and Administration', 'Which statement best distinguishes leadership from management?', '[{"text": "Management plans and controls resources; leadership influences people toward goals", "is_correct": true, "rationale": "Management focuses on planning, organizing and controlling resources; leadership focuses on influencing and motivating people."}, {"text": "Management is only for private firms; leadership is only for the police", "is_correct": false, "rationale": "Both apply to public and private organizations."}, {"text": "Management needs no people; leadership needs no planning", "is_correct": false, "rationale": "Both involve people and planning, with different emphasis."}, {"text": "Management and leadership are the same and need not be distinguished", "is_correct": false, "rationale": "They overlap but are distinct; good commanders need both."}]'::jsonb, 0, 'easy', 'A police commander must both manage resources and lead personnel.', NULL, 'Study module Law Enforcement Administration, Chapter 6: Character Formation 2 - Leadership, Decision Making, Management and Administration (LEA-6.1).', 'generated', 'tos_2024', 1, FALSE, 'LEA-6.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-6.1_02', 'law_enforcement', 'Character Formation 2 - Leadership, Decision Making, Management and Administration', 'A new patrol officer is eager to learn but lacks skills. Under the situational leadership model, which style should the supervisor use?', '[{"text": "Delegating", "is_correct": false, "rationale": "Delegating fits a highly competent and committed subordinate."}, {"text": "Directing (telling)", "is_correct": true, "rationale": "An enthusiastic beginner with low competence needs clear instructions and close supervision, the directing style."}, {"text": "Supporting (participating)", "is_correct": false, "rationale": "Supporting fits a capable subordinate whose confidence varies."}, {"text": "Coaching (selling)", "is_correct": false, "rationale": "Coaching fits a subordinate with some skill who is losing enthusiasm."}]'::jsonb, 1, 'medium', 'Situational leadership matches the style to the subordinate''s competence and commitment.', NULL, 'Study module Law Enforcement Administration, Chapter 6: Character Formation 2 - Leadership, Decision Making, Management and Administration (LEA-6.1).', 'generated', 'tos_2024', 1, FALSE, 'LEA-6.1', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-6.1_03', 'law_enforcement', 'Character Formation 2 - Leadership, Decision Making, Management and Administration', 'An officer has secure pay and a stable job, but he feels isolated from his team. Under Maslow''s hierarchy, which need should his supervisor address?', '[{"text": "Physiological needs", "is_correct": false, "rationale": "Physiological needs, such as food and rest, are already met."}, {"text": "Safety and security needs", "is_correct": false, "rationale": "His pay and job security meet his safety needs."}, {"text": "Social or belongingness needs", "is_correct": true, "rationale": "With basic and security needs met, the next level is belongingness, met through acceptance and teamwork."}, {"text": "Self-actualization needs", "is_correct": false, "rationale": "Self-actualization comes after belongingness and esteem needs."}]'::jsonb, 2, 'medium', 'Maslow''s hierarchy runs from physiological, safety, belongingness and esteem to self-actualization.', NULL, 'Study module Law Enforcement Administration, Chapter 6: Character Formation 2 - Leadership, Decision Making, Management and Administration (LEA-6.1).', 'generated', 'tos_2024', 1, FALSE, 'LEA-6.1', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-6.1_04', 'law_enforcement', 'Character Formation 2 - Leadership, Decision Making, Management and Administration', 'A chief raised allowances, but morale stayed low. Based on Herzberg''s two-factor theory, what should he add?', '[{"text": "More hygiene factors such as better office furniture", "is_correct": false, "rationale": "Furniture is a hygiene factor, which does not motivate by itself."}, {"text": "Stricter supervision and more frequent inspections", "is_correct": false, "rationale": "Stricter supervision is not a motivator in Herzberg''s theory."}, {"text": "Longer duty hours to increase productivity", "is_correct": false, "rationale": "Longer hours do not address motivation and may lower morale."}, {"text": "Motivators such as recognition, responsibility and achievement", "is_correct": true, "rationale": "Herzberg held that hygiene factors like pay only prevent dissatisfaction; motivators like recognition and achievement increase motivation."}]'::jsonb, 3, 'medium', 'Herzberg separated hygiene factors (pay, conditions, policies) from motivators (achievement, recognition, the work itself).', NULL, 'Study module Law Enforcement Administration, Chapter 6: Character Formation 2 - Leadership, Decision Making, Management and Administration (LEA-6.1).', 'generated', 'tos_2024', 1, FALSE, 'LEA-6.1', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-6.1_05', 'law_enforcement', 'Character Formation 2 - Leadership, Decision Making, Management and Administration', 'A commander believes that his officers like responsibility and can direct themselves, so he lets them plan their own tasks. Which theory guides him?', '[{"text": "McGregor''s Theory X", "is_correct": false, "rationale": "Theory X assumes people dislike work and must be closely controlled."}, {"text": "Taylor''s scientific management", "is_correct": false, "rationale": "Scientific management focuses on the most efficient way to do each task."}, {"text": "Weber''s bureaucratic theory", "is_correct": false, "rationale": "Bureaucratic theory focuses on rules, hierarchy and impersonal authority."}, {"text": "McGregor''s Theory Y", "is_correct": true, "rationale": "Theory Y assumes that people find work natural, seek responsibility and can exercise self-direction."}]'::jsonb, 3, 'medium', 'A manager''s assumptions about people shape how much freedom subordinates are given.', NULL, 'Study module Law Enforcement Administration, Chapter 6: Character Formation 2 - Leadership, Decision Making, Management and Administration (LEA-6.1).', 'generated', 'tos_2024', 1, FALSE, 'LEA-6.1', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-6.2_01', 'law_enforcement', 'Character Formation 2 - Leadership, Decision Making, Management and Administration', 'A police sergeant directly supervises patrol officers in the field. Which level of management does he belong to?', '[{"text": "Middle management", "is_correct": false, "rationale": "Middle managers supervise other managers and carry out top management''s plans."}, {"text": "First-line management", "is_correct": true, "rationale": "First-line managers directly supervise the employees who do the operating work."}, {"text": "Top management", "is_correct": false, "rationale": "Top managers set the direction and policies of the whole organization."}, {"text": "Staff management", "is_correct": false, "rationale": "Staff is a type of function, not a level of management."}]'::jsonb, 1, 'easy', 'The three levels are top, middle and first-line management.', NULL, 'Study module Law Enforcement Administration, Chapter 6: Character Formation 2 - Leadership, Decision Making, Management and Administration (LEA-6.2).', 'generated', 'tos_2024', 1, FALSE, 'LEA-6.2', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-6.2_02', 'law_enforcement', 'Character Formation 2 - Leadership, Decision Making, Management and Administration', 'What is characteristic of the laissez-faire management style?', '[{"text": "The leader makes all decisions alone and expects strict obedience", "is_correct": false, "rationale": "Making all decisions alone is the autocratic style."}, {"text": "The leader gives subordinates almost complete freedom with little direction", "is_correct": true, "rationale": "Laissez-faire leaders leave decisions mostly to the group and give little direction."}, {"text": "The leader consults subordinates and decides with them", "is_correct": false, "rationale": "Consulting and deciding with subordinates is the democratic or participative style."}, {"text": "The leader rewards and punishes based only on targets met", "is_correct": false, "rationale": "Rewarding and punishing based on targets describes transactional leadership."}]'::jsonb, 1, 'easy', 'Laissez-faire can work with very capable teams but leads to drift without them.', NULL, 'Study module Law Enforcement Administration, Chapter 6: Character Formation 2 - Leadership, Decision Making, Management and Administration (LEA-6.2).', 'generated', 'tos_2024', 1, FALSE, 'LEA-6.2', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-6.2_03', 'law_enforcement', 'Character Formation 2 - Leadership, Decision Making, Management and Administration', 'During a hostage crisis, the commander makes decisions immediately without consulting his team. Why is the autocratic style suitable here?', '[{"text": "The autocratic style is always the most effective style in every situation", "is_correct": false, "rationale": "No style is best in every situation; the situation decides."}, {"text": "The emergency leaves no time for consultation and needs one clear command", "is_correct": true, "rationale": "In emergencies, quick and clear direction from one leader is more effective than group discussion."}, {"text": "The team members have no right to give their views at any time", "is_correct": false, "rationale": "Members may give their views in planning and debriefing; the crisis limits it."}, {"text": "Consultation is prohibited by law during police operations", "is_correct": false, "rationale": "No law prohibits consultation; it is a matter of time and effectiveness."}]'::jsonb, 1, 'hard', 'Contingency approaches hold that the best leadership style depends on the situation.', NULL, 'Study module Law Enforcement Administration, Chapter 6: Character Formation 2 - Leadership, Decision Making, Management and Administration (LEA-6.2).', 'generated', 'tos_2024', 1, FALSE, 'LEA-6.2', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-6.2_04', 'law_enforcement', 'Character Formation 2 - Leadership, Decision Making, Management and Administration', 'According to Katz, why do top managers need conceptual skills more than first-line supervisors do?', '[{"text": "They must personally perform the technical tasks of every unit", "is_correct": false, "rationale": "Technical skills matter most at the first-line level."}, {"text": "They deal only with machines and not with people", "is_correct": false, "rationale": "All managers need human skills to deal with people."}, {"text": "They must see the organization as a whole and plan its long-range direction", "is_correct": true, "rationale": "Conceptual skills, the ability to see the whole organization and its environment, matter most at the top where strategy is set."}, {"text": "They are not responsible for any decisions in the organization", "is_correct": false, "rationale": "Top managers make the most far-reaching decisions."}]'::jsonb, 2, 'hard', 'Katz named three managerial skills: technical, human and conceptual.', NULL, 'Study module Law Enforcement Administration, Chapter 6: Character Formation 2 - Leadership, Decision Making, Management and Administration (LEA-6.2).', 'generated', 'tos_2024', 1, FALSE, 'LEA-6.2', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-6.2_05', 'law_enforcement', 'Character Formation 2 - Leadership, Decision Making, Management and Administration', 'A commander learns that a popular officer extorted money from a motorist. Which action best shows the qualities of an effective leader?', '[{"text": "Ignore it to keep the morale of the unit high", "is_correct": false, "rationale": "Ignoring misconduct damages discipline and public trust."}, {"text": "Refer the matter for proper investigation and act fairly regardless of popularity", "is_correct": true, "rationale": "Integrity and fairness require that misconduct be addressed through due process, whatever the officer''s popularity."}, {"text": "Quietly transfer the officer to another unit without any investigation", "is_correct": false, "rationale": "Transferring without investigation passes the problem to another unit."}, {"text": "Punish the officer at once without hearing his side", "is_correct": false, "rationale": "Punishment without hearing violates due process."}]'::jsonb, 1, 'hard', 'Leaders model accountability; tolerating misconduct teaches others that it is acceptable.', NULL, 'Study module Law Enforcement Administration, Chapter 6: Character Formation 2 - Leadership, Decision Making, Management and Administration (LEA-6.2).', 'generated', 'tos_2024', 1, FALSE, 'LEA-6.2', 'Evaluating') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-6.2_06', 'law_enforcement', 'Character Formation 2 - Leadership, Decision Making, Management and Administration', 'A team of highly experienced investigators is handling a complex case, and the chief remains accountable for the results. Which management style is most appropriate?', '[{"text": "Strict autocratic style with every step dictated by the chief", "is_correct": false, "rationale": "Dictating every step wastes their expertise and lowers morale."}, {"text": "Complete laissez-faire with no reporting to the chief at all", "is_correct": false, "rationale": "No reporting removes the chief''s ability to answer for the results."}, {"text": "Participative style that draws on their expertise while the chief decides", "is_correct": true, "rationale": "Experienced investigators contribute best when consulted, while the chief keeps final responsibility."}, {"text": "Coercive style that relies on threats of punishment", "is_correct": false, "rationale": "Threats discourage initiative in skilled teams."}]'::jsonb, 2, 'hard', 'The best style fits the abilities of the team and the demands of the task.', NULL, 'Study module Law Enforcement Administration, Chapter 6: Character Formation 2 - Leadership, Decision Making, Management and Administration (LEA-6.2).', 'generated', 'tos_2024', 1, FALSE, 'LEA-6.2', 'Evaluating') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-6.2_07', 'law_enforcement', 'Character Formation 2 - Leadership, Decision Making, Management and Administration', 'A new regional director must change an organization that resists reform. Which leadership approach would be most effective?', '[{"text": "Transactional leadership based only on rewards for meeting quotas", "is_correct": false, "rationale": "Rewards for quotas maintain routines but rarely change culture."}, {"text": "Laissez-faire leadership that leaves everyone to decide for themselves", "is_correct": false, "rationale": "Leaving everyone alone does not create change."}, {"text": "Autocratic leadership that forbids any questions about the reforms", "is_correct": false, "rationale": "Forbidding questions breeds resentment and hidden resistance."}, {"text": "Transformational leadership that inspires a shared vision for change", "is_correct": true, "rationale": "Transformational leaders motivate people to commit to a vision, which helps overcome resistance to change."}]'::jsonb, 3, 'hard', 'Transformational leadership emphasizes vision, inspiration and the development of followers.', NULL, 'Study module Law Enforcement Administration, Chapter 6: Character Formation 2 - Leadership, Decision Making, Management and Administration (LEA-6.2).', 'generated', 'tos_2024', 1, FALSE, 'LEA-6.2', 'Evaluating') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-6.3_01', 'law_enforcement', 'Character Formation 2 - Leadership, Decision Making, Management and Administration', 'What is the controlling function of management?', '[{"text": "Setting the organization''s goals and choosing strategies", "is_correct": false, "rationale": "Setting goals and strategies is planning."}, {"text": "Grouping tasks and assigning authority to units", "is_correct": false, "rationale": "Grouping tasks and assigning authority is organizing."}, {"text": "Measuring performance against standards and correcting deviations", "is_correct": true, "rationale": "Controlling checks actual performance against the plan and takes corrective action."}, {"text": "Recruiting, selecting and training personnel", "is_correct": false, "rationale": "Recruiting, selecting and training is staffing."}]'::jsonb, 2, 'easy', 'The functions of management are planning, organizing, staffing, leading and controlling.', NULL, 'Study module Law Enforcement Administration, Chapter 6: Character Formation 2 - Leadership, Decision Making, Management and Administration (LEA-6.3).', 'generated', 'tos_2024', 1, FALSE, 'LEA-6.3', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-6.3_02', 'law_enforcement', 'Character Formation 2 - Leadership, Decision Making, Management and Administration', 'Which activity belongs to the staffing function of management?', '[{"text": "Inspiring officers to work toward the unit''s goals", "is_correct": false, "rationale": "Inspiring and motivating is leading."}, {"text": "Recruiting, selecting, training and placing personnel", "is_correct": true, "rationale": "Staffing fills the positions in the organization with qualified people and develops them."}, {"text": "Comparing crime data with the unit''s targets", "is_correct": false, "rationale": "Comparing results with targets is controlling."}, {"text": "Writing the unit''s annual operational plan", "is_correct": false, "rationale": "Writing plans is planning."}]'::jsonb, 1, 'easy', 'Staffing ensures that the right people are in the right positions.', NULL, 'Study module Law Enforcement Administration, Chapter 6: Character Formation 2 - Leadership, Decision Making, Management and Administration (LEA-6.3).', 'generated', 'tos_2024', 1, FALSE, 'LEA-6.3', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-6.3_03', 'law_enforcement', 'Character Formation 2 - Leadership, Decision Making, Management and Administration', 'A chief of police sets next year''s crime reduction targets and the strategies to reach them. Which management function is he performing?', '[{"text": "Organizing", "is_correct": false, "rationale": "Organizing arranges people and tasks into a structure."}, {"text": "Planning", "is_correct": true, "rationale": "Setting objectives and deciding how to achieve them is planning."}, {"text": "Leading", "is_correct": false, "rationale": "Leading influences and motivates people."}, {"text": "Controlling", "is_correct": false, "rationale": "Controlling measures results against the plan."}]'::jsonb, 1, 'medium', 'Planning is the first function because the others depend on it.', NULL, 'Study module Law Enforcement Administration, Chapter 6: Character Formation 2 - Leadership, Decision Making, Management and Administration (LEA-6.3).', 'generated', 'tos_2024', 1, FALSE, 'LEA-6.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-6.3_04', 'law_enforcement', 'Character Formation 2 - Leadership, Decision Making, Management and Administration', 'A chief groups his personnel into patrol, investigation and administrative sections and assigns each a head. Which function is this?', '[{"text": "Planning", "is_correct": false, "rationale": "Planning sets objectives and strategies."}, {"text": "Staffing", "is_correct": false, "rationale": "Staffing fills positions with qualified people."}, {"text": "Controlling", "is_correct": false, "rationale": "Controlling checks performance."}, {"text": "Organizing", "is_correct": true, "rationale": "Organizing divides work, groups activities into units and assigns authority."}]'::jsonb, 3, 'medium', 'Organizing produces the structure through which the plan is carried out.', NULL, 'Study module Law Enforcement Administration, Chapter 6: Character Formation 2 - Leadership, Decision Making, Management and Administration (LEA-6.3).', 'generated', 'tos_2024', 1, FALSE, 'LEA-6.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-6.3_05', 'law_enforcement', 'Character Formation 2 - Leadership, Decision Making, Management and Administration', 'Each month, a chief reviews crime statistics against his targets and orders changes in deployment when targets are missed. Which function is this?', '[{"text": "Planning", "is_correct": false, "rationale": "Planning sets the targets in the first place."}, {"text": "Organizing", "is_correct": false, "rationale": "Organizing sets up the structure."}, {"text": "Controlling", "is_correct": true, "rationale": "Measuring results and correcting deviations is controlling."}, {"text": "Leading", "is_correct": false, "rationale": "Leading motivates and directs people."}]'::jsonb, 2, 'medium', 'Controlling closes the loop between plans and results.', NULL, 'Study module Law Enforcement Administration, Chapter 6: Character Formation 2 - Leadership, Decision Making, Management and Administration (LEA-6.3).', 'generated', 'tos_2024', 1, FALSE, 'LEA-6.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-6.3_06', 'law_enforcement', 'Character Formation 2 - Leadership, Decision Making, Management and Administration', 'A police chief represents his station at the city''s founding anniversary ceremony. Which managerial role, according to Mintzberg, is he performing?', '[{"text": "Liaison", "is_correct": false, "rationale": "The liaison role involves building contacts outside the unit."}, {"text": "Spokesperson", "is_correct": false, "rationale": "The spokesperson role involves giving information to outsiders."}, {"text": "Figurehead", "is_correct": true, "rationale": "The figurehead role covers ceremonial and symbolic duties as head of the unit."}, {"text": "Negotiator", "is_correct": false, "rationale": "The negotiator role involves bargaining for the unit."}]'::jsonb, 2, 'medium', 'Mintzberg grouped managerial roles into interpersonal, informational and decisional roles.', NULL, 'Study module Law Enforcement Administration, Chapter 6: Character Formation 2 - Leadership, Decision Making, Management and Administration (LEA-6.3).', 'generated', 'tos_2024', 1, FALSE, 'LEA-6.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-6.3_07', 'law_enforcement', 'Character Formation 2 - Leadership, Decision Making, Management and Administration', 'A chief settles a sudden conflict between two section heads that is disrupting operations. Which of Mintzberg''s roles is this?', '[{"text": "Resource allocator", "is_correct": false, "rationale": "The resource allocator role divides money, people and time among units."}, {"text": "Monitor", "is_correct": false, "rationale": "The monitor role gathers information."}, {"text": "Figurehead", "is_correct": false, "rationale": "The figurehead role covers ceremonial duties."}, {"text": "Disturbance handler", "is_correct": true, "rationale": "The disturbance handler role responds to conflicts and unexpected problems."}]'::jsonb, 3, 'medium', 'Disturbance handling is one of the decisional roles.', NULL, 'Study module Law Enforcement Administration, Chapter 6: Character Formation 2 - Leadership, Decision Making, Management and Administration (LEA-6.3).', 'generated', 'tos_2024', 1, FALSE, 'LEA-6.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-6.3_08', 'law_enforcement', 'Character Formation 2 - Leadership, Decision Making, Management and Administration', 'After a major incident, the chief briefs the media on what happened and what the police are doing. Which of Mintzberg''s roles is this?', '[{"text": "Disseminator", "is_correct": false, "rationale": "The disseminator role passes information to people inside the unit."}, {"text": "Spokesperson", "is_correct": true, "rationale": "The spokesperson role transmits information to people outside the unit, such as the media."}, {"text": "Leader", "is_correct": false, "rationale": "The leader role motivates and directs subordinates."}, {"text": "Entrepreneur", "is_correct": false, "rationale": "The entrepreneur role starts improvements and changes."}]'::jsonb, 1, 'medium', 'Spokesperson, monitor and disseminator are the informational roles.', NULL, 'Study module Law Enforcement Administration, Chapter 6: Character Formation 2 - Leadership, Decision Making, Management and Administration (LEA-6.3).', 'generated', 'tos_2024', 1, FALSE, 'LEA-6.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-6.3_09', 'law_enforcement', 'Character Formation 2 - Leadership, Decision Making, Management and Administration', 'The chief must divide a limited fuel budget among patrol, investigation and traffic units. Which of Mintzberg''s roles is he performing?', '[{"text": "Disturbance handler", "is_correct": false, "rationale": "Disturbance handling concerns conflicts and crises."}, {"text": "Liaison", "is_correct": false, "rationale": "The liaison role builds contacts outside the unit."}, {"text": "Resource allocator", "is_correct": true, "rationale": "The resource allocator role decides who gets the organization''s limited resources."}, {"text": "Monitor", "is_correct": false, "rationale": "The monitor role gathers information."}]'::jsonb, 2, 'medium', 'Resource allocation is a decisional role tied to the unit''s priorities.', NULL, 'Study module Law Enforcement Administration, Chapter 6: Character Formation 2 - Leadership, Decision Making, Management and Administration (LEA-6.3).', 'generated', 'tos_2024', 1, FALSE, 'LEA-6.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-6.3_10', 'law_enforcement', 'Character Formation 2 - Leadership, Decision Making, Management and Administration', 'A chief meets regularly with barangay captains and heads of other agencies to build working relationships. Which of Mintzberg''s roles is this?', '[{"text": "Figurehead", "is_correct": false, "rationale": "The figurehead role is ceremonial."}, {"text": "Disseminator", "is_correct": false, "rationale": "The disseminator role shares information inside the unit."}, {"text": "Liaison", "is_correct": true, "rationale": "The liaison role develops and maintains a network of contacts outside the unit."}, {"text": "Negotiator", "is_correct": false, "rationale": "The negotiator role bargains on specific matters."}]'::jsonb, 2, 'medium', 'Liaison is an interpersonal role; good networks help in coordinated operations.', NULL, 'Study module Law Enforcement Administration, Chapter 6: Character Formation 2 - Leadership, Decision Making, Management and Administration (LEA-6.3).', 'generated', 'tos_2024', 1, FALSE, 'LEA-6.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-6.4_01', 'law_enforcement', 'Character Formation 2 - Leadership, Decision Making, Management and Administration', 'How does problem-solving differ from decision-making?', '[{"text": "Problem-solving is done only by top managers; decision-making only by subordinates", "is_correct": false, "rationale": "Both are done at every level."}, {"text": "Problem-solving needs no information; decision-making needs no alternatives", "is_correct": false, "rationale": "Both need information and alternatives."}, {"text": "Problem-solving finds causes and possible solutions; decision-making chooses among them", "is_correct": true, "rationale": "Problem-solving defines and analyzes a problem and develops options; decision-making is choosing among the options."}, {"text": "Problem-solving and decision-making are two names for the same act", "is_correct": false, "rationale": "They are linked but different steps."}]'::jsonb, 2, 'easy', 'Decision-making is usually part of the larger problem-solving process.', NULL, 'Study module Law Enforcement Administration, Chapter 6: Character Formation 2 - Leadership, Decision Making, Management and Administration (LEA-6.4).', 'generated', 'tos_2024', 1, FALSE, 'LEA-6.4', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-6.4_02', 'law_enforcement', 'Character Formation 2 - Leadership, Decision Making, Management and Administration', 'What is a programmed decision?', '[{"text": "A routine decision handled by existing rules or procedures", "is_correct": true, "rationale": "Programmed decisions deal with repetitive situations covered by standard procedures."}, {"text": "A unique decision made for a new and complex problem", "is_correct": false, "rationale": "New and unstructured problems call for non-programmed decisions."}, {"text": "A decision made by a computer without any human input", "is_correct": false, "rationale": "Programmed does not mean computerized."}, {"text": "A decision made only during emergencies", "is_correct": false, "rationale": "Emergencies often call for non-programmed decisions."}]'::jsonb, 0, 'easy', 'SOPs allow managers to handle routine matters quickly and spend more time on new problems.', NULL, 'Study module Law Enforcement Administration, Chapter 6: Character Formation 2 - Leadership, Decision Making, Management and Administration (LEA-6.4).', 'generated', 'tos_2024', 1, FALSE, 'LEA-6.4', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-6.4_03', 'law_enforcement', 'Character Formation 2 - Leadership, Decision Making, Management and Administration', 'Members of a planning team first write their ideas privately, then share them one by one, discuss them, and vote. Which group decision technique is this?', '[{"text": "Brainstorming session", "is_correct": false, "rationale": "Brainstorming is free and open idea generation without criticism."}, {"text": "Delphi technique", "is_correct": false, "rationale": "The Delphi technique uses anonymous questionnaires to experts in several rounds."}, {"text": "Groupthink", "is_correct": false, "rationale": "Groupthink is a fault in group decisions, not a technique."}, {"text": "Nominal group technique", "is_correct": true, "rationale": "The nominal group technique combines silent individual idea generation, round-robin sharing, discussion and voting."}]'::jsonb, 3, 'medium', 'The nominal group technique keeps dominant members from controlling the discussion.', NULL, 'Study module Law Enforcement Administration, Chapter 6: Character Formation 2 - Leadership, Decision Making, Management and Administration (LEA-6.4).', 'generated', 'tos_2024', 1, FALSE, 'LEA-6.4', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-6.4_04', 'law_enforcement', 'Character Formation 2 - Leadership, Decision Making, Management and Administration', 'Experts who never meet answer questionnaires anonymously in several rounds, with a summary of answers shared after each round. Which technique is this?', '[{"text": "Delphi technique", "is_correct": true, "rationale": "The Delphi technique gathers expert opinion anonymously in rounds until views converge."}, {"text": "Nominal group technique", "is_correct": false, "rationale": "The nominal group technique involves members meeting face to face."}, {"text": "Brainstorming", "is_correct": false, "rationale": "Brainstorming happens in a meeting with open discussion."}, {"text": "Consensus voting", "is_correct": false, "rationale": "Consensus voting is a simple group decision, not anonymous rounds of experts."}]'::jsonb, 0, 'medium', 'Delphi is useful for forecasting and when experts are far apart.', NULL, 'Study module Law Enforcement Administration, Chapter 6: Character Formation 2 - Leadership, Decision Making, Management and Administration (LEA-6.4).', 'generated', 'tos_2024', 1, FALSE, 'LEA-6.4', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-6.4_05', 'law_enforcement', 'Character Formation 2 - Leadership, Decision Making, Management and Administration', 'A patrol officer suddenly faces an armed suspect and must decide in seconds. What should guide his decision?', '[{"text": "A full written analysis of all alternatives before acting", "is_correct": false, "rationale": "There is no time for a full written analysis."}, {"text": "The opinion of a supervisor who will arrive in an hour", "is_correct": false, "rationale": "Waiting an hour is impossible in a split-second situation."}, {"text": "A group vote among the bystanders at the scene", "is_correct": false, "rationale": "Bystanders have no authority or training to decide police actions."}, {"text": "His training, the established procedures and the immediate facts", "is_correct": true, "rationale": "Fast decisions rely on training and procedures that prepare officers to act on the facts before them."}]'::jsonb, 3, 'medium', 'Realistic training builds the judgment needed for quick decisions under stress.', NULL, 'Study module Law Enforcement Administration, Chapter 6: Character Formation 2 - Leadership, Decision Making, Management and Administration (LEA-6.4).', 'generated', 'tos_2024', 1, FALSE, 'LEA-6.4', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-6.4_06', 'law_enforcement', 'Character Formation 2 - Leadership, Decision Making, Management and Administration', 'A close-knit command team quickly agrees on a risky plan, and no one raises doubts for fear of breaking harmony. What is the danger here?', '[{"text": "Nominal group technique, which slows decisions down", "is_correct": false, "rationale": "The nominal group technique is a method to avoid such pressure."}, {"text": "Groupthink, where pressure for agreement suppresses critical views", "is_correct": true, "rationale": "Groupthink happens when the wish for unity overrides realistic appraisal of alternatives."}, {"text": "Bounded rationality, which forces the team to vote", "is_correct": false, "rationale": "Bounded rationality concerns limits of information and time, not group pressure."}, {"text": "The Delphi effect, which makes members anonymous", "is_correct": false, "rationale": "There is no Delphi effect that makes members anonymous in a meeting."}]'::jsonb, 1, 'hard', 'Leaders can reduce groupthink by inviting dissent and assigning a devil''s advocate.', NULL, 'Study module Law Enforcement Administration, Chapter 6: Character Formation 2 - Leadership, Decision Making, Management and Administration (LEA-6.4).', 'generated', 'tos_2024', 1, FALSE, 'LEA-6.4', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-6.4_07', 'law_enforcement', 'Character Formation 2 - Leadership, Decision Making, Management and Administration', 'A public manager chooses the first option that is good enough instead of searching for the best one, because of limited time and information. Which idea explains this?', '[{"text": "Rational choice with complete information", "is_correct": false, "rationale": "Complete rationality assumes all options and outcomes are known, which is not the case here."}, {"text": "Groupthink in a cohesive team", "is_correct": false, "rationale": "Groupthink concerns group pressure, not individual limits."}, {"text": "Escalation of commitment", "is_correct": false, "rationale": "Escalation of commitment is continuing a failing course because of past investments."}, {"text": "Bounded rationality and satisficing", "is_correct": true, "rationale": "Herbert Simon described bounded rationality: with limited information and time, decision-makers satisfice."}]'::jsonb, 3, 'hard', 'Recognizing bounded rationality helps managers decide when more data are worth gathering.', NULL, 'Study module Law Enforcement Administration, Chapter 6: Character Formation 2 - Leadership, Decision Making, Management and Administration (LEA-6.4).', 'generated', 'tos_2024', 1, FALSE, 'LEA-6.4', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_LEA-6.4_08', 'law_enforcement', 'Character Formation 2 - Leadership, Decision Making, Management and Administration', 'A commander keeps funding a failing anti-crime program because a large amount has already been spent on it. Which decision-making error is this?', '[{"text": "Escalation of commitment (sunk cost error)", "is_correct": true, "rationale": "Continuing a failing course of action because of money already spent is escalation of commitment."}, {"text": "Satisficing under bounded rationality", "is_correct": false, "rationale": "Satisficing is choosing a good-enough option, not persisting in a failing one."}, {"text": "The nominal group technique", "is_correct": false, "rationale": "The nominal group technique is a method for group decisions."}, {"text": "Programmed decision-making", "is_correct": false, "rationale": "Programmed decisions are routine choices under existing rules."}]'::jsonb, 0, 'hard', 'Good decisions look at future costs and benefits, not at money already spent.', NULL, 'Study module Law Enforcement Administration, Chapter 6: Character Formation 2 - Leadership, Decision Making, Management and Administration (LEA-6.4).', 'generated', 'tos_2024', 1, FALSE, 'LEA-6.4', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-1.1_01', 'criminalistics', 'Personal Identification Techniques', 'In the Henry system of primary classification, what value is given to a whorl on the right thumb or the right index finger?', '[{"text": "16", "is_correct": true, "rationale": "Fingers 1 and 2 (right thumb and right index) carry a whorl value of 16."}, {"text": "8", "is_correct": false, "rationale": "A value of 8 is given to fingers 3 and 4."}, {"text": "4", "is_correct": false, "rationale": "A value of 4 is given to fingers 5 and 6."}, {"text": "32", "is_correct": false, "rationale": "No finger has a value of 32; 32 is the highest possible sum including the added 1."}]'::jsonb, 0, 'easy', 'Whorl values are 16 for fingers 1-2, 8 for 3-4, 4 for 5-6, 2 for 7-8 and 1 for 9-10.', NULL, 'Study module Forensic Science, Chapter 1: Personal Identification Techniques (FS-1.1).', 'generated', 'tos_2024', 1, FALSE, 'FS-1.1', 'Remembering') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-1.1_02', 'criminalistics', 'Personal Identification Techniques', 'Which branch of forensic science identifies persons through their teeth and bite marks?', '[{"text": "Forensic anthropology", "is_correct": false, "rationale": "Forensic anthropology studies skeletal remains."}, {"text": "Forensic odontology", "is_correct": true, "rationale": "Forensic odontology applies dental science to identification and bite mark analysis."}, {"text": "Forensic serology", "is_correct": false, "rationale": "Forensic serology studies blood and other body fluids."}, {"text": "Dactyloscopy", "is_correct": false, "rationale": "Dactyloscopy is the study of fingerprints."}]'::jsonb, 1, 'easy', 'Dental records are compared with the teeth of unidentified remains.', NULL, 'Study module Forensic Science, Chapter 1: Personal Identification Techniques (FS-1.1).', 'generated', 'tos_2024', 1, FALSE, 'FS-1.1', 'Remembering') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-1.1_03', 'criminalistics', 'Personal Identification Techniques', 'Why does the Henry primary classification have 1,024 possible combinations?', '[{"text": "Because each of the ten fingers can have one of 1,024 patterns", "is_correct": false, "rationale": "Fingers do not have 1,024 pattern types."}, {"text": "Because the FBI added 1,024 new pattern types to the system", "is_correct": false, "rationale": "The number comes from the formula, not from added pattern types."}, {"text": "Because every fingerprint card is given its own serial number", "is_correct": false, "rationale": "Serial numbers have nothing to do with the primary classification."}, {"text": "Because the numerator and denominator can each range from 1 to 32", "is_correct": true, "rationale": "Adding 1 to the sums of whorl values makes each part range from 1 to 32, so there are 32 x 32 = 1,024 combinations."}]'::jsonb, 3, 'easy', 'The 1 is added so that the formula never has a zero, and the primary is always at least 1 over 1.', NULL, 'Study module Forensic Science, Chapter 1: Personal Identification Techniques (FS-1.1).', 'generated', 'tos_2024', 1, FALSE, 'FS-1.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-1.1_04', 'criminalistics', 'Personal Identification Techniques', 'Why can DNA profiling not tell identical twins apart?', '[{"text": "Because identical twins develop from one zygote and share the same nuclear DNA", "is_correct": true, "rationale": "Identical twins come from a single fertilized egg, so their nuclear DNA profiles are the same; fingerprints, however, differ."}, {"text": "Because identical twins have no DNA in their blood cells", "is_correct": false, "rationale": "Twins have DNA in their nucleated cells like anyone else."}, {"text": "Because DNA can only be taken from adults, not from twins", "is_correct": false, "rationale": "DNA can be taken from persons of any age."}, {"text": "Because the DNA of twins changes after birth", "is_correct": false, "rationale": "DNA does not change after birth in a way that separates twins."}]'::jsonb, 0, 'easy', 'Fingerprints are one way to distinguish identical twins, because ridge details form differently in each.', NULL, 'Study module Forensic Science, Chapter 1: Personal Identification Techniques (FS-1.1).', 'generated', 'tos_2024', 1, FALSE, 'FS-1.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-1.1_05', 'criminalistics', 'Personal Identification Techniques', 'Why are fingerprint cards filed according to their classification formulas?', '[{"text": "So that only cards of persons with criminal records are kept", "is_correct": false, "rationale": "Filing method does not decide whose cards are kept."}, {"text": "So that a card can be found by its formula without searching all the cards", "is_correct": true, "rationale": "Filing by classification groups cards with the same formula, which allows a search to be narrowed quickly."}, {"text": "So that cards are arranged by the date the prints were taken", "is_correct": false, "rationale": "Date-based filing would force a search of every card."}, {"text": "So that the names of the persons can be kept secret", "is_correct": false, "rationale": "Filing by formula is about retrieval, not secrecy."}]'::jsonb, 1, 'easy', 'Name files are kept separately so that a card can also be found by name.', NULL, 'Study module Forensic Science, Chapter 1: Personal Identification Techniques (FS-1.1).', 'generated', 'tos_2024', 1, FALSE, 'FS-1.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-1.1_06', 'criminalistics', 'Personal Identification Techniques', 'Why are teeth especially useful for identifying victims of fires and mass disasters?', '[{"text": "They regrow after death and show the person''s recent meals", "is_correct": false, "rationale": "Teeth do not regrow after death."}, {"text": "They carry the person''s name and birth date inside the enamel", "is_correct": false, "rationale": "Teeth do not carry names or dates."}, {"text": "They resist heat and decay, and can be compared with dental records", "is_correct": true, "rationale": "Teeth are the hardest tissue of the body and survive fire and decomposition; their features can be matched with dental charts and X-rays."}, {"text": "They are identical in all members of the same family", "is_correct": false, "rationale": "Teeth differ between family members; that is why they help identify individuals."}]'::jsonb, 2, 'easy', 'Forensic odontology is a standard method in disaster victim identification.', NULL, 'Study module Forensic Science, Chapter 1: Personal Identification Techniques (FS-1.1).', 'generated', 'tos_2024', 1, FALSE, 'FS-1.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-1.2_01', 'criminalistics', 'Personal Identification Techniques', 'A fingerprint pattern has one delta, and its ridges enter, recurve and leave on the side toward the little finger. What is the pattern?', '[{"text": "Radial loop", "is_correct": false, "rationale": "A radial loop flows toward the thumb (radius side)."}, {"text": "Ulnar loop", "is_correct": true, "rationale": "A loop whose ridges flow toward the little finger (ulna side) is an ulnar loop."}, {"text": "Plain whorl", "is_correct": false, "rationale": "A whorl has at least two deltas."}, {"text": "Tented arch", "is_correct": false, "rationale": "A tented arch has no recurving ridge with a ridge count."}]'::jsonb, 1, 'medium', 'Loops are the most common fingerprint pattern.', NULL, 'Study module Forensic Science, Chapter 1: Personal Identification Techniques (FS-1.2).', 'generated', 'tos_2024', 1, FALSE, 'FS-1.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-1.2_02', 'criminalistics', 'Personal Identification Techniques', 'A pattern has two deltas, and a line drawn between the deltas cuts across the circular ridges of the inner area. What is the pattern?', '[{"text": "Central pocket loop whorl", "is_correct": false, "rationale": "In a central pocket loop whorl, the line between the deltas does not touch any recurving ridge in the inner area."}, {"text": "Plain whorl", "is_correct": true, "rationale": "A plain whorl has two deltas and at least one ridge making a complete circuit, and the line between the deltas touches or crosses a recurving ridge in the inner area."}, {"text": "Double loop whorl", "is_correct": false, "rationale": "A double loop whorl has two separate loop formations."}, {"text": "Accidental whorl", "is_correct": false, "rationale": "An accidental whorl combines two or more different patterns or fits no other type."}]'::jsonb, 1, 'medium', 'The imaginary line between the deltas separates the plain whorl from the central pocket loop.', NULL, 'Study module Forensic Science, Chapter 1: Personal Identification Techniques (FS-1.2).', 'generated', 'tos_2024', 1, FALSE, 'FS-1.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-1.2_03', 'criminalistics', 'Personal Identification Techniques', 'Ridges enter from one side, rise slightly in the middle, and flow out the other side, with no delta. What is the pattern?', '[{"text": "Tented arch", "is_correct": false, "rationale": "A tented arch has an angle, an upthrust, or an incomplete loop in the center."}, {"text": "Radial loop", "is_correct": false, "rationale": "A loop needs a delta and a recurving ridge."}, {"text": "Plain arch", "is_correct": true, "rationale": "A plain arch has ridges flowing from one side to the other with a gentle rise, and no delta."}, {"text": "Accidental whorl", "is_correct": false, "rationale": "A whorl needs at least two deltas."}]'::jsonb, 2, 'medium', 'Arches are the least common of the basic patterns.', NULL, 'Study module Forensic Science, Chapter 1: Personal Identification Techniques (FS-1.2).', 'generated', 'tos_2024', 1, FALSE, 'FS-1.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-1.2_04', 'criminalistics', 'Personal Identification Techniques', 'A latent print recorded years ago is matched to a suspect arrested today. Which principle of fingerprint identification makes this possible?', '[{"text": "Variation: ridge details change every few years", "is_correct": false, "rationale": "Ridge details do not change over time."}, {"text": "Permanence: ridge details do not change during a person''s life", "is_correct": true, "rationale": "Friction ridge details form before birth and stay the same until decomposition, barring permanent scars."}, {"text": "Classification: all fingerprints can be grouped into one pattern", "is_correct": false, "rationale": "Classification helps filing but does not explain identification over time."}, {"text": "Similarity: prints of relatives are always the same", "is_correct": false, "rationale": "Relatives do not have identical prints."}]'::jsonb, 1, 'hard', 'The principles are individuality, permanence, and classifiable general patterns.', NULL, 'Study module Forensic Science, Chapter 1: Personal Identification Techniques (FS-1.2).', 'generated', 'tos_2024', 1, FALSE, 'FS-1.2', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-1.2_05', 'criminalistics', 'Personal Identification Techniques', 'A latent print and a suspect''s inked print are both ulnar loops, but their ridge endings and bifurcations are in different positions. What should the examiner conclude?', '[{"text": "They are from the same finger, because the patterns match", "is_correct": false, "rationale": "A matching pattern type alone does not prove identity."}, {"text": "They are not from the same finger, because identity rests on ridge details", "is_correct": true, "rationale": "The pattern is only a class characteristic; identity depends on ridge characteristics agreeing in kind and relative position."}, {"text": "They are from the same person, but from different fingers", "is_correct": false, "rationale": "Different ridge details show the print did not come from that finger; nothing shows which finger it came from."}, {"text": "No conclusion is possible, because loops are too common", "is_correct": false, "rationale": "An examiner can exclude a source when the ridge details clearly disagree."}]'::jsonb, 1, 'hard', 'Ridge characteristics include ridge endings, bifurcations, dots, short ridges and enclosures.', NULL, 'Study module Forensic Science, Chapter 1: Personal Identification Techniques (FS-1.2).', 'generated', 'tos_2024', 1, FALSE, 'FS-1.2', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-1.2_06', 'criminalistics', 'Personal Identification Techniques', 'A pattern has a delta and a recurving ridge, but no ridge crosses the line between the delta and the core. How is it classified?', '[{"text": "Ulnar loop, because a recurving ridge is present", "is_correct": false, "rationale": "A recurve alone is not enough to make a loop."}, {"text": "Plain whorl, because there is a delta", "is_correct": false, "rationale": "A whorl needs two deltas."}, {"text": "Tented arch, because a loop needs a ridge count of at least one", "is_correct": true, "rationale": "A loop requires a sufficient recurve, a delta, and a ridge count of at least one across a looping ridge; without the ridge count it is a tented arch."}, {"text": "Plain arch, because it has a delta", "is_correct": false, "rationale": "A plain arch has no delta."}]'::jsonb, 2, 'hard', 'Patterns that lack one of the essentials of a loop are commonly classified as tented arches.', NULL, 'Study module Forensic Science, Chapter 1: Personal Identification Techniques (FS-1.2).', 'generated', 'tos_2024', 1, FALSE, 'FS-1.2', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-1.3_01', 'criminalistics', 'Personal Identification Techniques', 'When taking rolled fingerprint impressions, how should the fingers be rolled?', '[{"text": "All fingers toward the subject''s body", "is_correct": false, "rationale": "Rolling all fingers toward the body is awkward and tends to smudge."}, {"text": "Thumbs toward the subject''s body; other fingers away from it", "is_correct": true, "rationale": "Thumbs are rolled toward the body and the fingers away from it, which uses the natural movement of the hand and gives a clear nail-to-nail impression."}, {"text": "All fingers away from the subject''s body", "is_correct": false, "rationale": "Thumbs are rolled toward the body, not away from it."}, {"text": "Thumbs and fingers pressed flat without rolling", "is_correct": false, "rationale": "Flat impressions are taken separately; rolled impressions require rolling."}]'::jsonb, 1, 'medium', 'Rolled impressions record the full friction ridge area from nail edge to nail edge.', NULL, 'Study module Forensic Science, Chapter 1: Personal Identification Techniques (FS-1.3).', 'generated', 'tos_2024', 1, FALSE, 'FS-1.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-1.3_02', 'criminalistics', 'Personal Identification Techniques', 'After rolling each finger, the technician also presses the four fingers of each hand together on the card, then both thumbs. Why?', '[{"text": "To replace the rolled prints if they are clear", "is_correct": false, "rationale": "The plain impressions supplement, not replace, the rolled ones."}, {"text": "To check that the rolled prints are in the correct finger order", "is_correct": true, "rationale": "Plain (simultaneous) impressions let the examiner verify the sequence of the rolled impressions."}, {"text": "To record the palm prints of the subject", "is_correct": false, "rationale": "Palm prints are taken on a separate card."}, {"text": "To find out whether the subject is right- or left-handed", "is_correct": false, "rationale": "Handedness is not determined from plain impressions."}]'::jsonb, 1, 'medium', 'Errors in finger order would give a wrong classification formula.', NULL, 'Study module Forensic Science, Chapter 1: Personal Identification Techniques (FS-1.3).', 'generated', 'tos_2024', 1, FALSE, 'FS-1.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-1.3_03', 'criminalistics', 'Personal Identification Techniques', 'A threatening letter on ordinary paper is suspected to bear latent prints. Which method is most suitable?', '[{"text": "Black powder dusting", "is_correct": false, "rationale": "Powders work best on smooth, non-porous surfaces."}, {"text": "Ninhydrin", "is_correct": true, "rationale": "Ninhydrin reacts with amino acids absorbed in porous surfaces like paper, producing a purple color."}, {"text": "Cyanoacrylate fuming", "is_correct": false, "rationale": "Cyanoacrylate fuming is used mainly on non-porous surfaces such as plastic and glass."}, {"text": "Small particle reagent", "is_correct": false, "rationale": "Small particle reagent is used on wet, non-porous surfaces."}]'::jsonb, 1, 'medium', 'The method of development depends on the surface: porous, non-porous or semi-porous.', NULL, 'Study module Forensic Science, Chapter 1: Personal Identification Techniques (FS-1.3).', 'generated', 'tos_2024', 1, FALSE, 'FS-1.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-1.3_04', 'criminalistics', 'Personal Identification Techniques', 'A latent print is visible on a drinking glass from the crime scene. Which method is appropriate?', '[{"text": "Spraying with ninhydrin solution", "is_correct": false, "rationale": "Ninhydrin is for porous surfaces like paper."}, {"text": "Soaking in silver nitrate solution", "is_correct": false, "rationale": "Silver nitrate is for porous surfaces."}, {"text": "Dusting with powder, then lifting with tape", "is_correct": true, "rationale": "Fingerprint powders adhere to the oily residue on smooth, non-porous surfaces like glass; the print is photographed and lifted."}, {"text": "Treating with iodine fumes on paper", "is_correct": false, "rationale": "Iodine fuming is mainly for porous surfaces and gives temporary results."}]'::jsonb, 2, 'medium', 'Prints should be photographed before lifting.', NULL, 'Study module Forensic Science, Chapter 1: Personal Identification Techniques (FS-1.3).', 'generated', 'tos_2024', 1, FALSE, 'FS-1.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-1.3_05', 'criminalistics', 'Personal Identification Techniques', 'The fingers of a body recovered from the water are badly wrinkled. What should be done to obtain readable prints?', '[{"text": "Dust the fingers with black powder and lift with tape", "is_correct": false, "rationale": "Powder and tape do not restore wrinkled ridges."}, {"text": "Treat the fingers with ninhydrin and wait one day", "is_correct": false, "rationale": "Ninhydrin is for latent prints on porous surfaces, not for restoring skin."}, {"text": "Inject a tissue builder under the skin to restore the ridges", "is_correct": true, "rationale": "Injecting a tissue builder, such as glycerin, under the skin fills out wrinkled fingertips so ridges can be recorded."}, {"text": "Take only the palm prints and leave the fingers", "is_correct": false, "rationale": "The fingers can still be recorded after restoration; palms are not a substitute."}]'::jsonb, 2, 'medium', 'Other post-mortem techniques include boiling or peeling the skin for decomposed bodies, done by trained personnel.', NULL, 'Study module Forensic Science, Chapter 1: Personal Identification Techniques (FS-1.3).', 'generated', 'tos_2024', 1, FALSE, 'FS-1.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-1.3_06', 'criminalistics', 'Personal Identification Techniques', 'Why must a developed latent print be photographed before it is lifted?', '[{"text": "Photographing the print makes the lifting tape stick better", "is_correct": false, "rationale": "Photography does not affect the adhesion of the tape."}, {"text": "Lifting may damage it; the photo keeps its original look and location", "is_correct": true, "rationale": "A lift can fail or distort the print; a photograph with a scale preserves the print as found and documents where it was."}, {"text": "A photo is needed only when the print is on paper", "is_correct": false, "rationale": "Prints on any surface should be photographed."}, {"text": "Photographs replace the need to lift the print in all cases", "is_correct": false, "rationale": "The lift is often still taken; the photo is an added safeguard."}]'::jsonb, 1, 'hard', 'Documentation is a basic rule in preserving physical evidence.', NULL, 'Study module Forensic Science, Chapter 1: Personal Identification Techniques (FS-1.3).', 'generated', 'tos_2024', 1, FALSE, 'FS-1.3', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-1.4_01', 'criminalistics', 'Personal Identification Techniques', 'An examiner places a latent print and an inked print side by side and checks whether their ridge details agree. Which phase of ACE-V is this?', '[{"text": "Comparison", "is_correct": true, "rationale": "Comparison is the side-by-side examination of the latent and known prints."}, {"text": "Analysis", "is_correct": false, "rationale": "Analysis studies the latent print alone to judge its quality and features."}, {"text": "Evaluation", "is_correct": false, "rationale": "Evaluation is reaching a conclusion from the comparison."}, {"text": "Verification", "is_correct": false, "rationale": "Verification is an independent check by another examiner."}]'::jsonb, 0, 'medium', 'ACE-V stands for Analysis, Comparison, Evaluation and Verification.', NULL, 'Study module Forensic Science, Chapter 1: Personal Identification Techniques (FS-1.4).', 'generated', 'tos_2024', 1, FALSE, 'FS-1.4', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-1.4_02', 'criminalistics', 'Personal Identification Techniques', 'After an examiner identifies a latent print, a second qualified examiner independently repeats the examination. Which phase of ACE-V is this?', '[{"text": "Verification", "is_correct": true, "rationale": "Verification is the independent re-examination by another qualified examiner."}, {"text": "Analysis", "is_correct": false, "rationale": "Analysis is the first study of the latent print."}, {"text": "Comparison", "is_correct": false, "rationale": "Comparison is the side-by-side examination."}, {"text": "Evaluation", "is_correct": false, "rationale": "Evaluation is the first examiner''s conclusion."}]'::jsonb, 0, 'medium', 'Verification guards against errors by a single examiner.', NULL, 'Study module Forensic Science, Chapter 1: Personal Identification Techniques (FS-1.4).', 'generated', 'tos_2024', 1, FALSE, 'FS-1.4', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-2.1_01', 'criminalistics', 'Forensic Photography', 'What is the approximate speed of light in a vacuum?', '[{"text": "300,000 kilometers per second", "is_correct": true, "rationale": "Light travels at about 300,000 km (186,000 miles) per second in a vacuum."}, {"text": "30,000 kilometers per second", "is_correct": false, "rationale": "30,000 km/s is ten times too slow."}, {"text": "3,000 kilometers per second", "is_correct": false, "rationale": "3,000 km/s is a hundred times too slow."}, {"text": "3,000,000 kilometers per second", "is_correct": false, "rationale": "3,000,000 km/s is ten times too fast."}]'::jsonb, 0, 'easy', 'Light is a form of electromagnetic energy that travels in straight lines.', NULL, 'Study module Forensic Science, Chapter 2: Forensic Photography (FS-2.1).', 'generated', 'tos_2024', 1, FALSE, 'FS-2.1', 'Remembering') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-2.1_02', 'criminalistics', 'Forensic Photography', 'What range of wavelengths makes up the visible light that the human eye can see?', '[{"text": "About 10 to 100 nanometers", "is_correct": false, "rationale": "Below 400 nm is ultraviolet and beyond; 10-100 nm is far ultraviolet."}, {"text": "About 1 to 10 millimeters", "is_correct": false, "rationale": "Millimeter waves are microwaves."}, {"text": "About 1 to 10 kilometers", "is_correct": false, "rationale": "Kilometer waves are radio waves."}, {"text": "About 400 to 700 nanometers", "is_correct": true, "rationale": "Visible light ranges from about 400 nm (violet) to 700 nm (red)."}]'::jsonb, 3, 'easy', 'Ultraviolet and infrared light, just outside this range, are used in forensic photography.', NULL, 'Study module Forensic Science, Chapter 2: Forensic Photography (FS-2.1).', 'generated', 'tos_2024', 1, FALSE, 'FS-2.1', 'Remembering') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-2.1_03', 'criminalistics', 'Forensic Photography', 'If the distance between the flash and the subject is doubled, what happens to the light falling on the subject?', '[{"text": "It becomes one-half as strong", "is_correct": false, "rationale": "One-half would be true only if light fell off in direct proportion to distance."}, {"text": "It becomes one-fourth as strong", "is_correct": true, "rationale": "By the inverse square law, light intensity varies inversely with the square of the distance: 1 / 2 squared = 1/4."}, {"text": "It stays the same", "is_correct": false, "rationale": "Light weakens with distance."}, {"text": "It becomes twice as strong", "is_correct": false, "rationale": "Light does not get stronger with distance."}]'::jsonb, 1, 'easy', 'The inverse square law explains why subjects far from the flash look dark.', NULL, 'Study module Forensic Science, Chapter 2: Forensic Photography (FS-2.1).', 'generated', 'tos_2024', 1, FALSE, 'FS-2.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-2.1_04', 'criminalistics', 'Forensic Photography', 'Why does a photographer use bounce flash by aiming the flash at a white ceiling?', '[{"text": "To make the flash travel faster to the subject", "is_correct": false, "rationale": "The speed of light does not change."}, {"text": "To increase the depth of field of the lens", "is_correct": false, "rationale": "Depth of field depends on aperture, focal length and distance."}, {"text": "To spread softer light and reduce harsh shadows", "is_correct": true, "rationale": "Bouncing light off a large surface diffuses it, giving more even lighting with softer shadows."}, {"text": "To make the photograph appear in black and white", "is_correct": false, "rationale": "Bounce flash does not change color into black and white."}]'::jsonb, 2, 'easy', 'A colored ceiling can tint the light, so a white surface is preferred.', NULL, 'Study module Forensic Science, Chapter 2: Forensic Photography (FS-2.1).', 'generated', 'tos_2024', 1, FALSE, 'FS-2.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-2.1_05', 'criminalistics', 'Forensic Photography', 'Why is oblique lighting used to photograph a footwear impression in dust?', '[{"text": "The light from above removes all shadows from the impression", "is_correct": false, "rationale": "Light from directly above flattens the image and hides relief."}, {"text": "The light changes the color of the dust so it shows better", "is_correct": false, "rationale": "Oblique light does not change the dust''s color."}, {"text": "The low-angle light creates shadows that show the relief of the impression", "is_correct": true, "rationale": "Light from a low angle across the surface casts shadows in the depressions, revealing detail."}, {"text": "The light makes the impression larger in the photograph", "is_correct": false, "rationale": "Lighting does not change the size of the impression."}]'::jsonb, 2, 'easy', 'The light should be moved around the impression to find the angle that shows most detail.', NULL, 'Study module Forensic Science, Chapter 2: Forensic Photography (FS-2.1).', 'generated', 'tos_2024', 1, FALSE, 'FS-2.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-2.1_06', 'criminalistics', 'Forensic Photography', 'A light ray bends as it passes at an angle from air into a glass lens. What property of light is this?', '[{"text": "Reflection", "is_correct": false, "rationale": "Reflection is light bouncing off a surface."}, {"text": "Refraction", "is_correct": true, "rationale": "Refraction is the bending of light as it passes from one medium to another of different density; lenses work by refraction."}, {"text": "Absorption", "is_correct": false, "rationale": "Absorption is light being taken in by a material."}, {"text": "Diffusion", "is_correct": false, "rationale": "Diffusion is the scattering of light by a rough or translucent surface."}]'::jsonb, 1, 'easy', 'The ability of lenses to form images depends on refraction.', NULL, 'Study module Forensic Science, Chapter 2: Forensic Photography (FS-2.1).', 'generated', 'tos_2024', 1, FALSE, 'FS-2.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-2.2_01', 'criminalistics', 'Forensic Photography', 'A photographer needs the whole crime scene sharp, from the nearest to the farthest object. What setting should he use?', '[{"text": "A wide aperture, such as f/2", "is_correct": false, "rationale": "A wide aperture gives a shallow depth of field."}, {"text": "A faster shutter speed only", "is_correct": false, "rationale": "Shutter speed controls motion blur, not depth of field."}, {"text": "A higher ISO only", "is_correct": false, "rationale": "ISO controls sensitivity, not depth of field."}, {"text": "A small aperture, such as f/16", "is_correct": true, "rationale": "A small aperture (large f-number) gives a greater depth of field."}]'::jsonb, 3, 'medium', 'A small aperture lets in less light, so a slower shutter speed or tripod may be needed.', NULL, 'Study module Forensic Science, Chapter 2: Forensic Photography (FS-2.2).', 'generated', 'tos_2024', 1, FALSE, 'FS-2.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-2.2_02', 'criminalistics', 'Forensic Photography', 'A photographer must freeze the motion of a moving vehicle at a scene. What should he adjust?', '[{"text": "Use a slow shutter speed, such as 1 second", "is_correct": false, "rationale": "A slow shutter speed blurs moving subjects."}, {"text": "Use the smallest aperture available", "is_correct": false, "rationale": "A small aperture increases depth of field but reduces light, often forcing a slower shutter."}, {"text": "Use the lowest ISO available", "is_correct": false, "rationale": "A low ISO reduces sensitivity, which also tends to force a slower shutter."}, {"text": "Use a fast shutter speed, such as 1/500 second", "is_correct": true, "rationale": "A fast shutter speed stops motion."}]'::jsonb, 3, 'medium', 'The exposure triangle links aperture, shutter speed and ISO.', NULL, 'Study module Forensic Science, Chapter 2: Forensic Photography (FS-2.2).', 'generated', 'tos_2024', 1, FALSE, 'FS-2.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-2.2_03', 'criminalistics', 'Forensic Photography', 'The camera is on a tripod, the scene is still and dim, and the photographer wants low noise and great depth of field. What should he adjust?', '[{"text": "Use a much higher ISO", "is_correct": false, "rationale": "A high ISO adds noise."}, {"text": "Use a longer shutter speed", "is_correct": true, "rationale": "With a tripod and a still scene, a long exposure collects enough light while keeping a low ISO and a small aperture."}, {"text": "Use the widest aperture", "is_correct": false, "rationale": "A wide aperture reduces depth of field."}, {"text": "Hold the camera by hand instead", "is_correct": false, "rationale": "Holding the camera by hand during a long exposure causes blur."}]'::jsonb, 1, 'medium', 'Time exposures are useful for night scenes and low light.', NULL, 'Study module Forensic Science, Chapter 2: Forensic Photography (FS-2.2).', 'generated', 'tos_2024', 1, FALSE, 'FS-2.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-2.2_04', 'criminalistics', 'Forensic Photography', 'Upon arriving at a crime scene, which photographs should be taken first?', '[{"text": "Overall views that show the entire scene", "is_correct": true, "rationale": "Overall (establishing) views record the scene as a whole before anything is disturbed."}, {"text": "Close-ups of each item with a scale", "is_correct": false, "rationale": "Close-ups come after the overall and mid-range views."}, {"text": "Mid-range views of the most important evidence", "is_correct": false, "rationale": "Mid-range views follow the overall views."}, {"text": "Photographs of the suspects at the station", "is_correct": false, "rationale": "Suspects are photographed separately, not as part of the first scene photographs."}]'::jsonb, 0, 'medium', 'The usual sequence is overall, mid-range, then close-up photographs.', NULL, 'Study module Forensic Science, Chapter 2: Forensic Photography (FS-2.2).', 'generated', 'tos_2024', 1, FALSE, 'FS-2.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-2.2_05', 'criminalistics', 'Forensic Photography', 'A bullet hole in a wall must be photographed for later measurement. Which procedure is correct?', '[{"text": "Take one angled shot with a scale placed across the hole itself", "is_correct": false, "rationale": "An angled view distorts measurements, and the scale must not cover the evidence."}, {"text": "Take one shot without a scale so the hole is not covered", "is_correct": false, "rationale": "A photo with a scale is needed for measurement."}, {"text": "Keep the camera square to the wall; take one shot without and one with a scale", "is_correct": true, "rationale": "The camera back should be parallel to the surface to avoid distortion, and the evidence is photographed first without and then with a scale."}, {"text": "Take the shot from a distance with a wide-angle lens", "is_correct": false, "rationale": "A distant wide-angle shot does not show the hole in usable detail."}]'::jsonb, 2, 'medium', 'The photo without a scale shows that nothing was hidden by the scale.', NULL, 'Study module Forensic Science, Chapter 2: Forensic Photography (FS-2.2).', 'generated', 'tos_2024', 1, FALSE, 'FS-2.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-2.2_06', 'criminalistics', 'Forensic Photography', 'A correct exposure is f/8 at 1/125 second. The photographer changes to f/11. Which shutter speed keeps the same exposure?', '[{"text": "1/250 second", "is_correct": false, "rationale": "1/250 would halve the light again, underexposing by two stops."}, {"text": "1/500 second", "is_correct": false, "rationale": "1/500 would underexpose by three stops."}, {"text": "1/125 second", "is_correct": false, "rationale": "Keeping 1/125 would underexpose by one stop."}, {"text": "1/60 second", "is_correct": true, "rationale": "f/11 lets in half the light of f/8, so the shutter must stay open twice as long: 1/60."}]'::jsonb, 3, 'medium', 'Each full f-stop or shutter-speed step doubles or halves the light.', NULL, 'Study module Forensic Science, Chapter 2: Forensic Photography (FS-2.2).', 'generated', 'tos_2024', 1, FALSE, 'FS-2.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-2.2_07', 'criminalistics', 'Forensic Photography', 'Why must the crime scene be photographed before any evidence is moved?', '[{"text": "Moving evidence first makes the photos clearer", "is_correct": false, "rationale": "Moving evidence first destroys the record of its position."}, {"text": "Photos record the original condition, which cannot be restored once disturbed", "is_correct": true, "rationale": "Photographs are a permanent record of the scene as found; once items are moved, the original positions are lost."}, {"text": "Photos are needed only for evidence that will be destroyed", "is_correct": false, "rationale": "All evidence and the scene as a whole are photographed."}, {"text": "Evidence must be moved first so the scale can be placed", "is_correct": false, "rationale": "Scales are placed next to evidence without moving it, after photos without scale."}]'::jsonb, 1, 'hard', 'Courts rely on scene photographs to understand positions and relationships of evidence.', NULL, 'Study module Forensic Science, Chapter 2: Forensic Photography (FS-2.2).', 'generated', 'tos_2024', 1, FALSE, 'FS-2.2', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-2.2_08', 'criminalistics', 'Forensic Photography', 'A photographer raises the ISO from 100 to 3200 to avoid using flash in a dark room. What is the main trade-off?', '[{"text": "Less depth of field in the photograph", "is_correct": false, "rationale": "Depth of field depends on aperture, not ISO."}, {"text": "More motion blur in the photograph", "is_correct": false, "rationale": "Higher ISO allows faster shutter speeds, which reduces blur."}, {"text": "A permanent change in the lens focal length", "is_correct": false, "rationale": "ISO does not affect focal length."}, {"text": "More digital noise, which reduces fine detail", "is_correct": true, "rationale": "Higher ISO increases sensitivity but adds noise, which can hide fine detail in evidence."}]'::jsonb, 3, 'hard', 'Each setting in the exposure triangle has a trade-off.', NULL, 'Study module Forensic Science, Chapter 2: Forensic Photography (FS-2.2).', 'generated', 'tos_2024', 1, FALSE, 'FS-2.2', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-2.3_01', 'criminalistics', 'Forensic Photography', 'Which lens is best for photographing a small toolmark at life size?', '[{"text": "Wide-angle lens", "is_correct": false, "rationale": "A wide-angle lens covers a broad view and distorts close subjects."}, {"text": "Macro lens", "is_correct": true, "rationale": "A macro lens focuses very close and can reproduce small objects at 1:1."}, {"text": "Telephoto lens", "is_correct": false, "rationale": "A telephoto lens magnifies distant subjects."}, {"text": "Fisheye lens", "is_correct": false, "rationale": "A fisheye lens produces strong distortion."}]'::jsonb, 1, 'medium', 'Macro photography is used for fingerprints, toolmarks and small items.', NULL, 'Study module Forensic Science, Chapter 2: Forensic Photography (FS-2.3).', 'generated', 'tos_2024', 1, FALSE, 'FS-2.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-2.3_02', 'criminalistics', 'Forensic Photography', 'A photographer must capture an entire small room from the doorway. Which lens is most suitable?', '[{"text": "Telephoto lens", "is_correct": false, "rationale": "A telephoto lens has a narrow view."}, {"text": "Macro lens", "is_correct": false, "rationale": "A macro lens is for close-ups."}, {"text": "Wide-angle lens", "is_correct": true, "rationale": "A wide-angle lens has a short focal length and a wide angle of view."}, {"text": "Long zoom lens", "is_correct": false, "rationale": "A long zoom set at its long end gives a narrow view."}]'::jsonb, 2, 'medium', 'Wide-angle lenses can distort straight lines near the edges.', NULL, 'Study module Forensic Science, Chapter 2: Forensic Photography (FS-2.3).', 'generated', 'tos_2024', 1, FALSE, 'FS-2.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-2.3_03', 'criminalistics', 'Forensic Photography', 'Evidence lies across a river that the photographer cannot cross yet. Which lens is most suitable?', '[{"text": "Wide-angle lens", "is_correct": false, "rationale": "A wide-angle lens makes distant objects look smaller."}, {"text": "Telephoto lens", "is_correct": true, "rationale": "A telephoto lens magnifies distant subjects."}, {"text": "Macro lens", "is_correct": false, "rationale": "A macro lens is for very close subjects."}, {"text": "Normal lens", "is_correct": false, "rationale": "A normal lens does not magnify distant subjects enough."}]'::jsonb, 1, 'medium', 'Telephoto lenses have long focal lengths and a narrow angle of view.', NULL, 'Study module Forensic Science, Chapter 2: Forensic Photography (FS-2.3).', 'generated', 'tos_2024', 1, FALSE, 'FS-2.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-2.3_04', 'criminalistics', 'Forensic Photography', 'Photos of people walking at a scene come out blurred. Which camera setting should be changed first?', '[{"text": "Aperture", "is_correct": false, "rationale": "Aperture controls the amount of light and depth of field."}, {"text": "White balance", "is_correct": false, "rationale": "White balance controls color, not blur."}, {"text": "Focus mode", "is_correct": false, "rationale": "Focus mode affects sharpness of still subjects, not motion blur."}, {"text": "Shutter speed", "is_correct": true, "rationale": "The shutter controls how long the sensor is exposed; a faster speed freezes motion."}]'::jsonb, 3, 'medium', 'Motion blur comes from movement during the exposure.', NULL, 'Study module Forensic Science, Chapter 2: Forensic Photography (FS-2.3).', 'generated', 'tos_2024', 1, FALSE, 'FS-2.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-2.3_05', 'criminalistics', 'Forensic Photography', 'Why is a wide-angle lens not ideal for close-up photographs used to measure evidence?', '[{"text": "It cannot focus on any object closer than ten meters", "is_correct": false, "rationale": "Wide-angle lenses can focus at close distances."}, {"text": "It lets in no light unless a flash is used", "is_correct": false, "rationale": "Wide-angle lenses let in light like other lenses."}, {"text": "It distorts shapes, especially near the edges of the frame", "is_correct": true, "rationale": "Wide-angle lenses exaggerate perspective and bend lines near the edges, which affects measurements."}, {"text": "It records the image only in black and white", "is_correct": false, "rationale": "The lens does not decide color or black and white."}]'::jsonb, 2, 'hard', 'Normal or macro lenses with the camera square to the surface are used for measurements.', NULL, 'Study module Forensic Science, Chapter 2: Forensic Photography (FS-2.3).', 'generated', 'tos_2024', 1, FALSE, 'FS-2.3', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-2.3_06', 'criminalistics', 'Forensic Photography', 'Why is a lens with a focal length near the diagonal of the film or sensor called a normal lens?', '[{"text": "It is the only lens that can be used with a flash", "is_correct": false, "rationale": "Any lens can be used with a flash."}, {"text": "It has the widest view of all lenses", "is_correct": false, "rationale": "Wide-angle lenses have wider views."}, {"text": "It produces no light falloff at any aperture", "is_correct": false, "rationale": "All lenses show some falloff at certain apertures."}, {"text": "It gives a perspective close to what the human eye sees", "is_correct": true, "rationale": "A focal length close to the diagonal of the format, such as 50 mm on full frame, gives a natural perspective."}]'::jsonb, 3, 'hard', 'Normal lenses are useful for mid-range photographs that show evidence as people see it.', NULL, 'Study module Forensic Science, Chapter 2: Forensic Photography (FS-2.3).', 'generated', 'tos_2024', 1, FALSE, 'FS-2.3', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-3.1_01', 'criminalistics', 'Forensic Chemistry and Toxicology', 'In a suspected poisoning death, what is the main role of forensic toxicology?', '[{"text": "To identify the suspect by examining his fingerprints", "is_correct": false, "rationale": "Fingerprints are examined in dactyloscopy."}, {"text": "To identify and measure poisons or drugs in body samples", "is_correct": true, "rationale": "Toxicology analyzes blood, urine and tissues for drugs and poisons and interprets whether they caused or contributed to death."}, {"text": "To determine the time of death from the body temperature", "is_correct": false, "rationale": "Time of death is estimated by forensic medicine."}, {"text": "To examine the handwriting on any suicide note", "is_correct": false, "rationale": "Handwriting is examined in questioned document examination."}]'::jsonb, 1, 'easy', 'Toxicology results are interpreted together with autopsy findings.', NULL, 'Study module Forensic Science, Chapter 3: Forensic Chemistry and Toxicology (FS-3.1).', 'generated', 'tos_2024', 1, FALSE, 'FS-3.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-3.1_02', 'criminalistics', 'Forensic Chemistry and Toxicology', 'Why is an unbroken chain of custody important in forensic chemistry cases?', '[{"text": "It shows the item examined is the same item seized, unchanged", "is_correct": true, "rationale": "The chain of custody accounts for each person who handled the item, proving its identity and integrity."}, {"text": "It allows the chemist to skip the confirmatory test", "is_correct": false, "rationale": "The chain of custody does not replace testing."}, {"text": "It lets the police keep the evidence at home", "is_correct": false, "rationale": "Evidence must be kept in proper custody, not at home."}, {"text": "It makes the evidence admissible without a chemist''s report", "is_correct": false, "rationale": "The chemist''s findings are still needed to prove what the item is."}]'::jsonb, 0, 'easy', 'In drug cases, gaps in the chain of custody have led to acquittals.', 'R.A. 9165, Sec. 21, as amended by R.A. 10640', 'Study module Forensic Science, Chapter 3: Forensic Chemistry and Toxicology (FS-3.1).', 'generated', 'tos_2024', 1, FALSE, 'FS-3.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-3.2_01', 'criminalistics', 'Forensic Chemistry and Toxicology', 'How does a preliminary (presumptive) test differ from a confirmatory test?', '[{"text": "A presumptive test is done in court; a confirmatory test at the scene", "is_correct": false, "rationale": "Both are done in the field or laboratory, not in court."}, {"text": "A presumptive test is always more accurate than a confirmatory one", "is_correct": false, "rationale": "Confirmatory tests are more specific and reliable."}, {"text": "A presumptive test only suggests presence; a confirmatory test identifies it", "is_correct": true, "rationale": "Presumptive tests are quick screening tests that can give false positives; confirmatory tests specifically identify the substance."}, {"text": "A presumptive test needs no sample; a confirmatory test needs one", "is_correct": false, "rationale": "Both tests need a sample."}]'::jsonb, 2, 'easy', 'Examples: Kastle-Meyer (presumptive for blood); Takayama and Teichmann crystal tests (confirmatory for blood).', NULL, 'Study module Forensic Science, Chapter 3: Forensic Chemistry and Toxicology (FS-3.2).', 'generated', 'tos_2024', 1, FALSE, 'FS-3.2', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-3.2_02', 'criminalistics', 'Forensic Chemistry and Toxicology', 'A reddish stain on a shirt turns pink with the Kastle-Meyer (phenolphthalein) test. What is the proper next step?', '[{"text": "Report the stain as human blood based on the color change alone", "is_correct": false, "rationale": "A presumptive result does not prove blood, and it says nothing about human origin."}, {"text": "Do a confirmatory test, such as a crystal test, before calling it blood", "is_correct": true, "rationale": "Kastle-Meyer is presumptive; a confirmatory test such as Takayama or Teichmann, then a test for human origin, is needed."}, {"text": "Discard the shirt because the test has used up the stain", "is_correct": false, "rationale": "The rest of the stain must be preserved for further tests."}, {"text": "Report the stain as rust because it is reddish", "is_correct": false, "rationale": "The test result suggests blood, not rust."}]'::jsonb, 1, 'medium', 'The precipitin test determines whether blood is of human origin.', NULL, 'Study module Forensic Science, Chapter 3: Forensic Chemistry and Toxicology (FS-3.2).', 'generated', 'tos_2024', 1, FALSE, 'FS-3.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-3.3_01', 'criminalistics', 'Forensic Chemistry and Toxicology', 'A blood-soaked shirt is recovered from a crime scene. How should it be packaged?', '[{"text": "Seal it while wet in an airtight plastic bag", "is_correct": false, "rationale": "Sealing wet items in plastic traps moisture and promotes decay."}, {"text": "Wash it to remove dirt before sending it to the laboratory", "is_correct": false, "rationale": "Washing destroys the evidence."}, {"text": "Dry it under direct sunlight to speed up drying", "is_correct": false, "rationale": "Direct sunlight and heat can degrade DNA."}, {"text": "Air-dry it at room temperature, then pack it in a paper bag", "is_correct": true, "rationale": "Air-drying and paper packaging prevent mold and bacteria from destroying the biological evidence."}]'::jsonb, 3, 'medium', 'Each item is packaged separately to avoid cross-contamination.', NULL, 'Study module Forensic Science, Chapter 3: Forensic Chemistry and Toxicology (FS-3.3).', 'generated', 'tos_2024', 1, FALSE, 'FS-3.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-3.3_02', 'criminalistics', 'Forensic Chemistry and Toxicology', 'Known hair samples must be taken from a suspect for comparison. Which procedure is correct?', '[{"text": "Pull or comb hairs from different areas of the scalp, roots included", "is_correct": true, "rationale": "Known samples should represent the whole scalp, and pulled hairs with roots allow DNA testing."}, {"text": "Cut a few hairs from one spot near the neck using scissors", "is_correct": false, "rationale": "Cut hairs lack roots and represent only one area."}, {"text": "Pick one hair from the suspect''s comb at home", "is_correct": false, "rationale": "A single hair from a comb may not be the suspect''s and does not represent variation."}, {"text": "Ask the suspect to bring any hair he chooses", "is_correct": false, "rationale": "The suspect must not choose the samples."}]'::jsonb, 0, 'medium', 'Hairs vary across the head, so several areas are sampled.', NULL, 'Study module Forensic Science, Chapter 3: Forensic Chemistry and Toxicology (FS-3.3).', 'generated', 'tos_2024', 1, FALSE, 'FS-3.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-3.4_01', 'criminalistics', 'Forensic Chemistry and Toxicology', 'A farmer collapses after spraying pesticide. He has pinpoint pupils, heavy sweating and excessive salivation. Which antidote is used?', '[{"text": "Sodium thiosulfate", "is_correct": false, "rationale": "Sodium thiosulfate is used in cyanide poisoning."}, {"text": "Naloxone", "is_correct": false, "rationale": "Naloxone reverses opioid overdose."}, {"text": "Atropine", "is_correct": true, "rationale": "These are signs of organophosphate poisoning, treated with atropine, often with pralidoxime."}, {"text": "Vitamin K", "is_correct": false, "rationale": "Vitamin K reverses certain anticoagulant poisonings."}]'::jsonb, 2, 'medium', 'Organophosphates inhibit cholinesterase, causing a buildup of acetylcholine.', NULL, 'Study module Forensic Science, Chapter 3: Forensic Chemistry and Toxicology (FS-3.4).', 'generated', 'tos_2024', 1, FALSE, 'FS-3.4', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-3.4_02', 'criminalistics', 'Forensic Chemistry and Toxicology', 'A man is bitten by a cobra. What is the specific treatment for this biological poison?', '[{"text": "Atropine", "is_correct": false, "rationale": "Atropine treats organophosphate poisoning."}, {"text": "Activated charcoal", "is_correct": false, "rationale": "Activated charcoal binds ingested poisons in the gut, not injected venom."}, {"text": "Antivenin (antivenom)", "is_correct": true, "rationale": "Antivenin contains antibodies that neutralize the snake''s venom."}, {"text": "Sodium nitrite", "is_correct": false, "rationale": "Sodium nitrite is used in cyanide poisoning."}]'::jsonb, 2, 'medium', 'Biological poisons come from living things, such as venoms and bacterial toxins; chemical poisons are substances like cyanide and pesticides.', NULL, 'Study module Forensic Science, Chapter 3: Forensic Chemistry and Toxicology (FS-3.4).', 'generated', 'tos_2024', 1, FALSE, 'FS-3.4', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-4.1_01', 'criminalistics', 'Questioned Documents Examination', 'What is a document whose genuineness or authorship is disputed?', '[{"text": "Questioned document", "is_correct": true, "rationale": "A questioned document is any document whose source or authenticity is in question."}, {"text": "Standard document", "is_correct": false, "rationale": "A standard is a known writing used for comparison."}, {"text": "Official document", "is_correct": false, "rationale": "An official document is issued by a public office; it may or may not be questioned."}, {"text": "Holographic document", "is_correct": false, "rationale": "A holographic document is written entirely by the hand of its author, such as a holographic will."}]'::jsonb, 0, 'easy', 'Questioned document examination compares questioned writings with known standards.', NULL, 'Study module Forensic Science, Chapter 4: Questioned Documents Examination (FS-4.1).', 'generated', 'tos_2024', 1, FALSE, 'FS-4.1', 'Remembering') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-4.1_02', 'criminalistics', 'Questioned Documents Examination', 'What are the known writings of a person, used for comparison with a questioned writing, called?', '[{"text": "Standards or exemplars", "is_correct": true, "rationale": "Standards (exemplars) are writings whose authorship is known."}, {"text": "Questioned writings", "is_correct": false, "rationale": "Questioned writings are those under examination."}, {"text": "Disguised writings", "is_correct": false, "rationale": "Disguised writings are deliberately altered by the writer."}, {"text": "Simulated writings", "is_correct": false, "rationale": "Simulated writings are imitations of another person''s writing."}]'::jsonb, 0, 'easy', 'Standards may be collected or requested.', NULL, 'Study module Forensic Science, Chapter 4: Questioned Documents Examination (FS-4.1).', 'generated', 'tos_2024', 1, FALSE, 'FS-4.1', 'Remembering') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-4.1_03', 'criminalistics', 'Questioned Documents Examination', 'Why are collected standards often preferred over requested standards?', '[{"text": "They are always written with a ballpoint pen", "is_correct": false, "rationale": "The writing instrument varies."}, {"text": "They are written in front of the examiner", "is_correct": false, "rationale": "Requested standards, not collected ones, are written in front of an investigator."}, {"text": "They are always newer than the questioned document", "is_correct": false, "rationale": "Standards should be close in date to the questioned writing, older or newer."}, {"text": "They were written naturally, before any comparison was expected", "is_correct": true, "rationale": "Collected standards come from ordinary business and personal writing, so they show natural habits without disguise."}]'::jsonb, 3, 'easy', 'Requested standards help when collected ones are lacking, and allow the same text to be written.', NULL, 'Study module Forensic Science, Chapter 4: Questioned Documents Examination (FS-4.1).', 'generated', 'tos_2024', 1, FALSE, 'FS-4.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-4.1_04', 'criminalistics', 'Questioned Documents Examination', 'What makes a document a public document rather than a private one?', '[{"text": "It is written on expensive paper with a letterhead", "is_correct": false, "rationale": "Paper and letterhead do not make a document public."}, {"text": "It is an official act or record, or is acknowledged before a notary", "is_correct": true, "rationale": "Public documents include written official acts and records and notarized documents; others are private documents."}, {"text": "It has been shown to many people", "is_correct": false, "rationale": "Publicity does not change the legal character of a document."}, {"text": "It was written by a famous person", "is_correct": false, "rationale": "The fame of the writer is irrelevant."}]'::jsonb, 1, 'easy', 'The distinction matters for authentication under Rule 132.', 'Rules of Court, Rule 132, Sec. 19', 'Study module Forensic Science, Chapter 4: Questioned Documents Examination (FS-4.1).', 'generated', 'tos_2024', 1, FALSE, 'FS-4.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-4.1_05', 'criminalistics', 'Questioned Documents Examination', 'Why is a stereoscopic microscope used in examining a questioned signature?', '[{"text": "It reads the invisible serial number printed in the paper", "is_correct": false, "rationale": "Paper does not have invisible serial numbers to be read this way."}, {"text": "It gives a magnified 3-D view of strokes, pen lifts and retouching", "is_correct": true, "rationale": "The stereo microscope shows depth and detail of strokes, revealing hesitation, pen lifts and patching."}, {"text": "It measures the age of the ink in exact years", "is_correct": false, "rationale": "No microscope can give the exact age of ink in years."}, {"text": "It removes the ink so the paper can be examined", "is_correct": false, "rationale": "The microscope does not remove ink; examination is non-destructive."}]'::jsonb, 1, 'easy', 'Other equipment includes UV and IR light sources and the video spectral comparator.', NULL, 'Study module Forensic Science, Chapter 4: Questioned Documents Examination (FS-4.1).', 'generated', 'tos_2024', 1, FALSE, 'FS-4.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-4.2_01', 'criminalistics', 'Questioned Documents Examination', 'Two signatures on different checks superimpose perfectly over each other. What does this suggest?', '[{"text": "Both are genuine, since they match exactly", "is_correct": false, "rationale": "Exact identity is a warning sign, not proof of genuineness."}, {"text": "Both are forged, since signatures should never match at all", "is_correct": false, "rationale": "Genuine signatures are similar but not identical; one may still be genuine."}, {"text": "Nothing, because superimposition has no meaning", "is_correct": false, "rationale": "Exact superimposition is significant evidence of tracing."}, {"text": "One is likely traced, since genuine signatures always vary naturally", "is_correct": true, "rationale": "No one signs exactly the same way twice; an exact match suggests tracing from a model."}]'::jsonb, 3, 'medium', 'The model signature from which the tracing was made may be found among the genuine ones.', NULL, 'Study module Forensic Science, Chapter 4: Questioned Documents Examination (FS-4.2).', 'generated', 'tos_2024', 1, FALSE, 'FS-4.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-4.2_02', 'criminalistics', 'Questioned Documents Examination', 'A questioned signature has blunt starts and ends, tremor, and pen lifts in odd places, while the standards are fluent with tapered strokes. What is the likely finding?', '[{"text": "Simulated forgery", "is_correct": true, "rationale": "Slow, drawn strokes, tremor and unnatural pen lifts are signs of a careful freehand copy."}, {"text": "Genuine signature written in haste", "is_correct": false, "rationale": "Haste produces speed and fluency, not tremor and blunt strokes."}, {"text": "Disguised writing by the owner", "is_correct": false, "rationale": "Disguise is the owner altering his own writing; the signs here point to copying."}, {"text": "Simple forgery", "is_correct": false, "rationale": "Simple forgery makes no attempt to copy the genuine form."}]'::jsonb, 0, 'medium', 'Line quality is one of the most important indicators in signature examination.', NULL, 'Study module Forensic Science, Chapter 4: Questioned Documents Examination (FS-4.2).', 'generated', 'tos_2024', 1, FALSE, 'FS-4.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-4.2_03', 'criminalistics', 'Questioned Documents Examination', 'A forger signed the account holder''s name in his own ordinary handwriting without trying to copy the real signature. What type of forgery is this?', '[{"text": "Simple (spurious) forgery", "is_correct": true, "rationale": "Simple forgery writes the name with no attempt to imitate the genuine signature."}, {"text": "Simulated forgery", "is_correct": false, "rationale": "Simulated forgery is a freehand copy of the genuine signature."}, {"text": "Traced forgery", "is_correct": false, "rationale": "Traced forgery follows the outline of a genuine model."}, {"text": "Guided-hand signature", "is_correct": false, "rationale": "A guided-hand signature is made with another person helping the writer''s hand."}]'::jsonb, 0, 'medium', 'Simple forgeries are usually easy to detect when compared with standards.', NULL, 'Study module Forensic Science, Chapter 4: Questioned Documents Examination (FS-4.2).', 'generated', 'tos_2024', 1, FALSE, 'FS-4.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-4.2_04', 'criminalistics', 'Questioned Documents Examination', 'Under magnification, faint carbon lines appear beneath the ink strokes of a questioned signature. What method of forgery was likely used?', '[{"text": "Simple forgery written freehand", "is_correct": false, "rationale": "A freehand forgery leaves no carbon outline."}, {"text": "Cut-and-paste of a genuine signature", "is_correct": false, "rationale": "A cut-and-paste would show cut edges or a printed image, not carbon lines."}, {"text": "Traced forgery using carbon paper", "is_correct": true, "rationale": "Carbon outlines under the ink show that the forger traced a model through carbon paper and then inked over it."}, {"text": "Disguised writing by the owner", "is_correct": false, "rationale": "Disguised writing does not leave carbon outlines."}]'::jsonb, 2, 'medium', 'Indented-line tracing and transmitted-light tracing are other tracing methods.', NULL, 'Study module Forensic Science, Chapter 4: Questioned Documents Examination (FS-4.2).', 'generated', 'tos_2024', 1, FALSE, 'FS-4.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-4.2_05', 'criminalistics', 'Questioned Documents Examination', 'Requested standards must be taken from a suspect. Which procedure is correct?', '[{"text": "Let him copy the questioned document word for word", "is_correct": false, "rationale": "Copying the questioned document lets him imitate or avoid its features."}, {"text": "Take only one sample so he does not get tired", "is_correct": false, "rationale": "Several samples are needed to show natural variation."}, {"text": "Dictate the text and remove each sample from view once written", "is_correct": true, "rationale": "Dictation and removing each sample prevents the writer from copying or keeping his disguise consistent."}, {"text": "Allow him to choose the pen and paper he likes", "is_correct": false, "rationale": "Writing materials should be similar to those of the questioned document."}]'::jsonb, 2, 'medium', 'Samples should be taken under conditions similar to the questioned writing.', NULL, 'Study module Forensic Science, Chapter 4: Questioned Documents Examination (FS-4.2).', 'generated', 'tos_2024', 1, FALSE, 'FS-4.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-4.2_06', 'criminalistics', 'Questioned Documents Examination', 'A writer deliberately changed his slant and made his letters larger so he would not be identified. What kind of writing is this?', '[{"text": "Simulated forgery", "is_correct": false, "rationale": "Simulated forgery imitates another person''s writing."}, {"text": "Traced forgery", "is_correct": false, "rationale": "Traced forgery follows a model''s outline."}, {"text": "Natural variation", "is_correct": false, "rationale": "Natural variation is the normal, unintended differences in a person''s writing."}, {"text": "Disguised writing", "is_correct": true, "rationale": "Disguised writing is a deliberate change in one''s own writing to avoid identification."}]'::jsonb, 3, 'medium', 'Disguise is hard to keep up, so habitual features often still show.', NULL, 'Study module Forensic Science, Chapter 4: Questioned Documents Examination (FS-4.2).', 'generated', 'tos_2024', 1, FALSE, 'FS-4.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-4.2_07', 'criminalistics', 'Questioned Documents Examination', 'The amount on a check appears to have been changed from 100 to 700. Which examination is most appropriate?', '[{"text": "Ask the bank teller whether the check looks correct", "is_correct": false, "rationale": "A teller''s opinion is not a scientific examination."}, {"text": "Compare the paper''s weight with another check", "is_correct": false, "rationale": "Paper weight does not show an alteration of the figures."}, {"text": "Wet the check to see whether the ink runs", "is_correct": false, "rationale": "Wetting can damage the evidence."}, {"text": "Examine it under ultraviolet and infrared light", "is_correct": true, "rationale": "UV and IR examination can show inks that look the same but differ in composition, revealing alterations."}]'::jsonb, 3, 'medium', 'Non-destructive methods come first in document examination.', NULL, 'Study module Forensic Science, Chapter 4: Questioned Documents Examination (FS-4.2).', 'generated', 'tos_2024', 1, FALSE, 'FS-4.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-4.2_08', 'criminalistics', 'Questioned Documents Examination', 'A questioned and a standard signature look alike in general form, but differ in how strokes begin, in pen pressure and in letter connections. How should the examiner weigh this?', '[{"text": "Similarity in general form is enough to declare them the same", "is_correct": false, "rationale": "Pictorial similarity is what a forger aims for, so it proves little."}, {"text": "Differences in details should be ignored as normal", "is_correct": false, "rationale": "Fundamental differences in habits are significant, not normal variation."}, {"text": "Differences in habitual details matter more than similarity in general form", "is_correct": true, "rationale": "A forger can copy the general form, but habitual details like stroke beginnings, pressure and connections are hard to imitate."}, {"text": "Pen pressure is irrelevant in handwriting examination", "is_correct": false, "rationale": "Pressure patterns are among the habits examined."}]'::jsonb, 2, 'medium', 'Identification rests on significant writing habits, not on overall appearance.', NULL, 'Study module Forensic Science, Chapter 4: Questioned Documents Examination (FS-4.2).', 'generated', 'tos_2024', 1, FALSE, 'FS-4.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-4.2_09', 'criminalistics', 'Questioned Documents Examination', 'Why is natural variation important in signature identification?', '[{"text": "Natural variation proves that every signature is a forgery", "is_correct": false, "rationale": "Variation is expected in genuine writing."}, {"text": "Natural variation means no signature can ever be identified", "is_correct": false, "rationale": "Identification is possible by comparing questioned writing with the range shown by enough standards."}, {"text": "Genuine signatures vary slightly, so a lack of variation is suspicious", "is_correct": true, "rationale": "The examiner must know the range of a writer''s natural variation; differences within it are normal, and unnatural sameness is suspicious."}, {"text": "Natural variation applies only to typewritten documents", "is_correct": false, "rationale": "Variation is a feature of handwriting, not typewriting."}]'::jsonb, 2, 'hard', 'This is why several standards, not one, are needed for comparison.', NULL, 'Study module Forensic Science, Chapter 4: Questioned Documents Examination (FS-4.2).', 'generated', 'tos_2024', 1, FALSE, 'FS-4.2', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-4.3_01', 'criminalistics', 'Questioned Documents Examination', 'A suspected banknote feels flat and smooth, and no portrait watermark appears when it is held against the light. What does this suggest?', '[{"text": "It is genuine, because worn notes always lose their raised print", "is_correct": false, "rationale": "Wear can reduce texture, but a missing watermark cannot be explained by wear."}, {"text": "It is genuine, because watermarks are seen only under ultraviolet light", "is_correct": false, "rationale": "Watermarks are seen with transmitted light, not only under UV."}, {"text": "It is likely counterfeit, because genuine notes have raised print and a watermark", "is_correct": true, "rationale": "Genuine notes are printed by intaglio, which feels raised, and carry a watermark visible against light."}, {"text": "Nothing, because the feel and watermark are not security features", "is_correct": false, "rationale": "Both are important security features of genuine notes."}]'::jsonb, 2, 'hard', 'Suspected counterfeits are referred to the Bangko Sentral ng Pilipinas for examination.', NULL, 'Study module Forensic Science, Chapter 4: Questioned Documents Examination (FS-4.3).', 'generated', 'tos_2024', 1, FALSE, 'FS-4.3', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-4.3_02', 'criminalistics', 'Questioned Documents Examination', 'Why should a counterfeit examination check several security features instead of only one?', '[{"text": "One feature is always enough to prove a note is genuine", "is_correct": false, "rationale": "A single imitated feature can mislead."}, {"text": "Checking several features damages the banknote", "is_correct": false, "rationale": "Visual and tactile checks do not damage notes."}, {"text": "Counterfeiters may copy one feature, but copying all of them is far harder", "is_correct": true, "rationale": "Banknotes use layered features such as watermark, security thread, color-shifting ink and intaglio print; a fake rarely copies all of them well."}, {"text": "Only the serial number matters in counterfeit detection", "is_correct": false, "rationale": "Serial numbers are easy to print and are not the main test."}]'::jsonb, 2, 'hard', 'The feel-look-tilt method is commonly taught for checking banknotes.', NULL, 'Study module Forensic Science, Chapter 4: Questioned Documents Examination (FS-4.3).', 'generated', 'tos_2024', 1, FALSE, 'FS-4.3', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-5.1_01', 'criminalistics', 'Lie Detection Techniques', 'Who developed, in 1921, the instrument that continuously recorded blood pressure, pulse and breathing to detect deception?', '[{"text": "John A. Larson", "is_correct": true, "rationale": "John Larson, a police officer and physiologist in Berkeley, developed the first modern polygraph in 1921."}, {"text": "Leonarde Keeler", "is_correct": false, "rationale": "Leonarde Keeler later improved the polygraph and added the galvanograph."}, {"text": "Cesare Lombroso", "is_correct": false, "rationale": "Lombroso used a hydrosphygmograph to measure blood pressure changes in 1895."}, {"text": "William M. Marston", "is_correct": false, "rationale": "Marston developed the systolic blood pressure deception test."}]'::jsonb, 0, 'easy', 'Keeler''s improvements made the polygraph portable and more widely used.', NULL, 'Study module Forensic Science, Chapter 5: Lie Detection Techniques (FS-5.1).', 'generated', 'tos_2024', 1, FALSE, 'FS-5.1', 'Remembering') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-5.1_02', 'criminalistics', 'Lie Detection Techniques', 'What does the galvanograph component of the polygraph record?', '[{"text": "Changes in the skin''s electrical conductance", "is_correct": true, "rationale": "The galvanograph (electrodermal) component records changes in skin conductance linked to sweat gland activity."}, {"text": "Changes in breathing rate and depth", "is_correct": false, "rationale": "Breathing is recorded by the pneumograph."}, {"text": "Changes in blood pressure and pulse", "is_correct": false, "rationale": "Blood pressure and pulse are recorded by the cardiosphygmograph."}, {"text": "Movements of the subject''s body", "is_correct": false, "rationale": "Body movements are recorded by motion sensors."}]'::jsonb, 0, 'easy', 'Each component records a different physiological response.', NULL, 'Study module Forensic Science, Chapter 5: Lie Detection Techniques (FS-5.1).', 'generated', 'tos_2024', 1, FALSE, 'FS-5.1', 'Remembering') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-5.1_03', 'criminalistics', 'Lie Detection Techniques', 'Why can extreme nervousness in an innocent subject affect the accuracy of a polygraph test?', '[{"text": "It makes the polygraph instrument stop working", "is_correct": false, "rationale": "Nervousness does not stop the instrument."}, {"text": "It always makes a guilty person look innocent", "is_correct": false, "rationale": "Nervousness can affect both innocent and guilty subjects in various ways."}, {"text": "It may cause reactions that look like deception, giving a false result", "is_correct": true, "rationale": "Fear and nervousness produce physiological reactions that can be mistaken for deception; the pretest interview aims to reduce this."}, {"text": "It has no effect, because the polygraph measures only lies", "is_correct": false, "rationale": "The polygraph measures physiological responses, not lies directly."}]'::jsonb, 2, 'easy', 'Factors affecting accuracy include the subject''s condition, the examiner''s skill and the test environment.', NULL, 'Study module Forensic Science, Chapter 5: Lie Detection Techniques (FS-5.1).', 'generated', 'tos_2024', 1, FALSE, 'FS-5.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-5.1_04', 'criminalistics', 'Lie Detection Techniques', 'Why should a subject be rested, fed and free from drugs before a polygraph test?', '[{"text": "The subject''s appetite is part of the test questions", "is_correct": false, "rationale": "Appetite is not part of the questions."}, {"text": "Drugs make the subject tell the truth automatically", "is_correct": false, "rationale": "No drug forces truthfulness; drugs can suppress or exaggerate reactions."}, {"text": "Fatigue, hunger or drugs can alter physiological responses", "is_correct": true, "rationale": "The polygraph records physiological changes, so anything that alters them, like fatigue or drugs, can affect accuracy."}, {"text": "Resting is needed only for tests done at night", "is_correct": false, "rationale": "The subject''s condition matters at any time of day."}]'::jsonb, 2, 'easy', 'Examiners check the subject''s physical and mental fitness during the pretest.', NULL, 'Study module Forensic Science, Chapter 5: Lie Detection Techniques (FS-5.1).', 'generated', 'tos_2024', 1, FALSE, 'FS-5.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-5.2_01', 'criminalistics', 'Lie Detection Techniques', 'The examiner explains the instrument, discusses the case and reviews every question with the subject before attaching the sensors. Which phase is this?', '[{"text": "Pre-test interview", "is_correct": true, "rationale": "The pretest interview prepares the subject, reviews the questions and builds understanding before recording."}, {"text": "In-test (chart recording)", "is_correct": false, "rationale": "The in-test phase is the actual recording of charts."}, {"text": "Post-test interview", "is_correct": false, "rationale": "The post-test phase follows the recording."}, {"text": "Chart interpretation", "is_correct": false, "rationale": "Interpretation is the analysis of the charts."}]'::jsonb, 0, 'medium', 'Reviewing the questions avoids surprise reactions to unfamiliar wording.', NULL, 'Study module Forensic Science, Chapter 5: Lie Detection Techniques (FS-5.2).', 'generated', 'tos_2024', 1, FALSE, 'FS-5.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-5.2_02', 'criminalistics', 'Lie Detection Techniques', 'After the charts show significant reactions, the examiner discusses the results with the subject and invites an explanation. Which phase is this?', '[{"text": "Pre-test interview", "is_correct": false, "rationale": "The pretest comes before recording."}, {"text": "Post-test interview", "is_correct": true, "rationale": "The post-test interview follows the recording and gives the subject a chance to explain reactions."}, {"text": "In-test (chart recording)", "is_correct": false, "rationale": "The in-test phase is the recording itself."}, {"text": "Instrument calibration", "is_correct": false, "rationale": "Calibration is a technical check of the instrument."}]'::jsonb, 1, 'medium', 'Admissions made during the post-test must follow the subject''s constitutional rights.', NULL, 'Study module Forensic Science, Chapter 5: Lie Detection Techniques (FS-5.2).', 'generated', 'tos_2024', 1, FALSE, 'FS-5.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-5.2_03', 'criminalistics', 'Lie Detection Techniques', 'Which polygraph component uses rubber tubes placed around the chest and abdomen?', '[{"text": "Cardiosphygmograph", "is_correct": false, "rationale": "The cardiosphygmograph uses a cuff to record blood pressure and pulse."}, {"text": "Galvanograph", "is_correct": false, "rationale": "The galvanograph uses electrodes on the fingers."}, {"text": "Pneumograph", "is_correct": true, "rationale": "The pneumograph records breathing through tubes around the chest and abdomen."}, {"text": "Kymograph", "is_correct": false, "rationale": "The kymograph moves the chart paper in analog instruments."}]'::jsonb, 2, 'medium', 'Both thoracic and abdominal breathing are recorded.', NULL, 'Study module Forensic Science, Chapter 5: Lie Detection Techniques (FS-5.2).', 'generated', 'tos_2024', 1, FALSE, 'FS-5.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-5.2_04', 'criminalistics', 'Lie Detection Techniques', 'Which polygraph component uses a blood pressure cuff on the subject''s upper arm?', '[{"text": "Pneumograph", "is_correct": false, "rationale": "The pneumograph records breathing."}, {"text": "Galvanograph", "is_correct": false, "rationale": "The galvanograph records skin conductance."}, {"text": "Motion sensor", "is_correct": false, "rationale": "A motion sensor records body movements."}, {"text": "Cardiosphygmograph", "is_correct": true, "rationale": "The cardiosphygmograph records changes in relative blood pressure and pulse through the arm cuff."}]'::jsonb, 3, 'medium', 'The cuff is inflated to a moderate pressure during each chart.', NULL, 'Study module Forensic Science, Chapter 5: Lie Detection Techniques (FS-5.2).', 'generated', 'tos_2024', 1, FALSE, 'FS-5.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-5.2_05', 'criminalistics', 'Lie Detection Techniques', 'Which polygraph component uses electrodes attached to two of the subject''s fingers?', '[{"text": "Galvanograph", "is_correct": true, "rationale": "The galvanograph uses finger electrodes to measure skin conductance."}, {"text": "Pneumograph", "is_correct": false, "rationale": "The pneumograph uses chest and abdominal tubes."}, {"text": "Cardiosphygmograph", "is_correct": false, "rationale": "The cardiosphygmograph uses an arm cuff."}, {"text": "Kymograph", "is_correct": false, "rationale": "The kymograph is the chart drive."}]'::jsonb, 0, 'medium', 'Electrodermal responses are among the most sensitive polygraph measures.', NULL, 'Study module Forensic Science, Chapter 5: Lie Detection Techniques (FS-5.2).', 'generated', 'tos_2024', 1, FALSE, 'FS-5.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-5.2_06', 'criminalistics', 'Lie Detection Techniques', 'A reaction appears on a relevant question in only one of three charts. How should it be treated?', '[{"text": "As conclusive proof that the subject lied", "is_correct": false, "rationale": "One reaction is not proof of deception."}, {"text": "As a reason to stop the test and arrest the subject", "is_correct": false, "rationale": "No arrest can be based on a single chart reaction."}, {"text": "As a sign that the subject is telling the truth on all questions", "is_correct": false, "rationale": "An isolated reaction does not prove truthfulness either."}, {"text": "As unreliable, because meaningful reactions should be consistent across charts", "is_correct": true, "rationale": "Chart interpretation relies on consistent reactions across repeated charts, not a single reaction."}]'::jsonb, 3, 'medium', 'Repeating the questions in several charts helps separate real reactions from chance ones.', NULL, 'Study module Forensic Science, Chapter 5: Lie Detection Techniques (FS-5.2).', 'generated', 'tos_2024', 1, FALSE, 'FS-5.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-5.2_07', 'criminalistics', 'Lie Detection Techniques', 'The subject coughs just as a relevant question is asked. What should the examiner do?', '[{"text": "Mark the cough, disregard that reaction and repeat the question", "is_correct": true, "rationale": "Movements and coughs distort the tracings, so they are marked, the reaction is not scored, and the question is repeated."}, {"text": "Treat the reaction as a clear sign of deception", "is_correct": false, "rationale": "A cough is an artifact, not evidence of deception."}, {"text": "Stop the examination permanently", "is_correct": false, "rationale": "A cough does not require ending the test."}, {"text": "Erase the part of the chart that shows the cough", "is_correct": false, "rationale": "Charts must not be erased or altered."}]'::jsonb, 0, 'medium', 'Marking artifacts keeps the chart an accurate record.', NULL, 'Study module Forensic Science, Chapter 5: Lie Detection Techniques (FS-5.2).', 'generated', 'tos_2024', 1, FALSE, 'FS-5.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-5.2_08', 'criminalistics', 'Lie Detection Techniques', 'How should polygraph results be regarded in Philippine courts?', '[{"text": "As conclusive proof of guilt whenever deception is indicated", "is_correct": false, "rationale": "Courts do not treat polygraph results as conclusive."}, {"text": "As sufficient to convict without any other evidence", "is_correct": false, "rationale": "A conviction requires proof beyond reasonable doubt from competent evidence."}, {"text": "As investigative aids, not as conclusive evidence of guilt or innocence", "is_correct": true, "rationale": "The Supreme Court has treated polygraph results as lacking general scientific acceptance as proof of guilt or innocence; they guide investigation."}, {"text": "As evidence that must be accepted if the examiner is licensed", "is_correct": false, "rationale": "The examiner''s license does not make the results binding on the court."}]'::jsonb, 2, 'hard', 'The polygraph is useful in narrowing leads and obtaining admissions made with proper safeguards.', 'People v. Adoviso, G.R. Nos. 116196-97 (1999)', 'Study module Forensic Science, Chapter 5: Lie Detection Techniques (FS-5.2).', 'generated', 'tos_2024', 1, FALSE, 'FS-5.2', 'Evaluating') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-5.3_01', 'criminalistics', 'Lie Detection Techniques', 'A subject reacts consistently more to the relevant questions than to the comparison (control) questions. How is this interpreted?', '[{"text": "It indicates deception on the relevant issue", "is_correct": true, "rationale": "In comparison question tests, greater reactions to relevant than to comparison questions indicate deception."}, {"text": "It indicates truthfulness on the relevant issue", "is_correct": false, "rationale": "Truthful subjects tend to react more to the comparison questions."}, {"text": "It shows the comparison questions were badly worded", "is_correct": false, "rationale": "Consistent results do not by themselves show poor wording."}, {"text": "It shows that the instrument is broken", "is_correct": false, "rationale": "Consistent patterns show the instrument is recording."}]'::jsonb, 0, 'hard', 'Comparison questions are designed to concern truthful subjects more than the relevant questions do.', NULL, 'Study module Forensic Science, Chapter 5: Lie Detection Techniques (FS-5.3).', 'generated', 'tos_2024', 1, FALSE, 'FS-5.3', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-5.3_02', 'criminalistics', 'Lie Detection Techniques', 'What is the purpose of irrelevant questions such as ''Are you sitting down?'' in a polygraph test?', '[{"text": "To trap the subject into lying about the crime", "is_correct": false, "rationale": "Irrelevant questions are not traps."}, {"text": "To set a baseline of normal responses and allow recovery between questions", "is_correct": true, "rationale": "Irrelevant questions produce normal responses used as a baseline, and they give the subject time to return to normal."}, {"text": "To make the subject nervous before the relevant questions", "is_correct": false, "rationale": "They are meant to settle, not unsettle, the subject."}, {"text": "To test whether the subject understands the language", "is_correct": false, "rationale": "Language is checked in the pretest, not by irrelevant questions."}]'::jsonb, 1, 'hard', 'The three types of questions are relevant, irrelevant and comparison (control).', NULL, 'Study module Forensic Science, Chapter 5: Lie Detection Techniques (FS-5.3).', 'generated', 'tos_2024', 1, FALSE, 'FS-5.3', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-6.1_01', 'criminalistics', 'Forensic Ballistics', 'Which instrument lets an examiner view two bullets side by side in one field of view?', '[{"text": "Stereoscopic microscope", "is_correct": false, "rationale": "The stereo microscope gives a 3-D view of a single object."}, {"text": "Helixometer", "is_correct": false, "rationale": "The helixometer measures the pitch of rifling."}, {"text": "Comparison microscope", "is_correct": true, "rationale": "The comparison microscope joins two microscopes by an optical bridge so two objects are seen in one split view."}, {"text": "Bullet recovery box", "is_correct": false, "rationale": "The bullet recovery box catches test bullets."}]'::jsonb, 2, 'easy', 'The comparison microscope is the main instrument for identifying fired bullets and cartridge cases.', NULL, 'Study module Forensic Science, Chapter 6: Forensic Ballistics (FS-6.1).', 'generated', 'tos_2024', 1, FALSE, 'FS-6.1', 'Remembering') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-6.1_02', 'criminalistics', 'Forensic Ballistics', 'Why are test bullets fired into a water tank or cotton-filled box?', '[{"text": "To measure the loudness of the gunshot", "is_correct": false, "rationale": "These devices are not used to measure sound."}, {"text": "To clean the barrel of the suspect firearm", "is_correct": false, "rationale": "Test firing does not clean the barrel."}, {"text": "To recover them undamaged so their marks can be compared", "is_correct": true, "rationale": "Water tanks and cotton boxes slow the bullet gently, keeping its striations intact for comparison."}, {"text": "To find out the age of the ammunition", "is_correct": false, "rationale": "Recovery devices do not date ammunition."}]'::jsonb, 2, 'easy', 'Test bullets from the suspect firearm are compared with the evidence bullet.', NULL, 'Study module Forensic Science, Chapter 6: Forensic Ballistics (FS-6.1).', 'generated', 'tos_2024', 1, FALSE, 'FS-6.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-6.1_03', 'criminalistics', 'Forensic Ballistics', 'What does a firearms examiner measure with a helixometer?', '[{"text": "The pitch or twist of the rifling in the barrel", "is_correct": true, "rationale": "The helixometer measures the pitch of rifling, a class characteristic of the firearm."}, {"text": "The weight of a fired bullet", "is_correct": false, "rationale": "Bullet weight is measured with a balance."}, {"text": "The pressure of the gas inside the chamber", "is_correct": false, "rationale": "Chamber pressure is measured with special pressure gauges."}, {"text": "The distance of the shooter from the target", "is_correct": false, "rationale": "Firing distance is estimated from powder patterns."}]'::jsonb, 0, 'easy', 'Class characteristics such as twist help narrow the possible firearms.', NULL, 'Study module Forensic Science, Chapter 6: Forensic Ballistics (FS-6.1).', 'generated', 'tos_2024', 1, FALSE, 'FS-6.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-6.1_04', 'criminalistics', 'Forensic Ballistics', 'Why should a bullet embedded in a wall not be pried out with a knife?', '[{"text": "The bullet may explode if touched by metal", "is_correct": false, "rationale": "A fired bullet does not explode."}, {"text": "The knife may scratch it and destroy the marks needed for comparison", "is_correct": true, "rationale": "Prying can add marks that obscure the striations; the material around the bullet should be cut away instead."}, {"text": "The wall will become weaker and collapse", "is_correct": false, "rationale": "The concern is the evidence, not the wall''s strength."}, {"text": "The bullet must remain in the wall until the trial is over", "is_correct": false, "rationale": "The bullet is recovered for examination; photographs record its position."}]'::jsonb, 1, 'easy', 'Careful recovery protects the individual characteristics on the bullet.', NULL, 'Study module Forensic Science, Chapter 6: Forensic Ballistics (FS-6.1).', 'generated', 'tos_2024', 1, FALSE, 'FS-6.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-6.1_05', 'criminalistics', 'Forensic Ballistics', 'How should a firearms examiner support his conclusion when testifying in court?', '[{"text": "By explaining the comparison and showing photomicrographs of the matching marks", "is_correct": true, "rationale": "Expert testimony should explain the basis of the opinion; photomicrographs let the court see the agreement of marks."}, {"text": "By stating only that he is an expert and is certain", "is_correct": false, "rationale": "An expert''s opinion is weighed by its basis, not by the expert''s say-so."}, {"text": "By asking the judge to examine the bullets without explanation", "is_correct": false, "rationale": "The examiner must explain the findings to help the court."}, {"text": "By relying on the suspect''s admission instead of the examination", "is_correct": false, "rationale": "The examination stands on its own scientific basis."}]'::jsonb, 0, 'easy', 'Courts evaluate expert opinion by the reasons and methods given.', 'Rules of Court, Rule 130, Sec. 52 (opinion of expert witness)', 'Study module Forensic Science, Chapter 6: Forensic Ballistics (FS-6.1).', 'generated', 'tos_2024', 1, FALSE, 'FS-6.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-6.1_06', 'criminalistics', 'Forensic Ballistics', 'What is the role of the Integrated Ballistics Identification System (IBIS)?', '[{"text": "It replaces the examiner and gives the final identification", "is_correct": false, "rationale": "The system suggests candidates; the examiner makes the identification."}, {"text": "It test-fires guns automatically without ammunition", "is_correct": false, "rationale": "Test firing still requires ammunition."}, {"text": "It traces the owner of a gun through its serial number", "is_correct": false, "rationale": "Serial number tracing is done through firearms registration records."}, {"text": "It compares digital images of fired bullets and cases to suggest possible matches", "is_correct": true, "rationale": "IBIS correlates images in a database to find candidates, which an examiner then confirms with the comparison microscope."}]'::jsonb, 3, 'easy', 'Ballistic databases help link shootings across different cases.', NULL, 'Study module Forensic Science, Chapter 6: Forensic Ballistics (FS-6.1).', 'generated', 'tos_2024', 1, FALSE, 'FS-6.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-6.2_01', 'criminalistics', 'Forensic Ballistics', 'Which branch of ballistics studies a bullet''s flight from the muzzle to the target, including gravity and air resistance?', '[{"text": "Exterior ballistics", "is_correct": true, "rationale": "Exterior ballistics covers the projectile''s motion after it leaves the muzzle."}, {"text": "Interior ballistics", "is_correct": false, "rationale": "Interior ballistics covers events inside the firearm."}, {"text": "Terminal ballistics", "is_correct": false, "rationale": "Terminal ballistics covers the effect on the target."}, {"text": "Forensic ballistics", "is_correct": false, "rationale": "Forensic ballistics applies ballistics to legal questions."}]'::jsonb, 0, 'medium', 'The branches follow the stages of a bullet''s journey.', NULL, 'Study module Forensic Science, Chapter 6: Forensic Ballistics (FS-6.2).', 'generated', 'tos_2024', 1, FALSE, 'FS-6.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-6.2_02', 'criminalistics', 'Forensic Ballistics', 'A study examines how a bullet penetrates and wounds the body. Which branch of ballistics is this?', '[{"text": "Exterior ballistics", "is_correct": false, "rationale": "Exterior ballistics deals with flight."}, {"text": "Interior ballistics", "is_correct": false, "rationale": "Interior ballistics deals with events inside the firearm."}, {"text": "Terminal ballistics", "is_correct": true, "rationale": "Terminal ballistics deals with the bullet''s effect when it strikes its target."}, {"text": "Shot ballistics", "is_correct": false, "rationale": "There is no standard branch called shot ballistics."}]'::jsonb, 2, 'medium', 'Wound ballistics is a part of terminal ballistics.', NULL, 'Study module Forensic Science, Chapter 6: Forensic Ballistics (FS-6.2).', 'generated', 'tos_2024', 1, FALSE, 'FS-6.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-6.2_03', 'criminalistics', 'Forensic Ballistics', 'Which branch of ballistics covers events from the firing pin''s strike on the primer until the bullet leaves the muzzle?', '[{"text": "Exterior ballistics", "is_correct": false, "rationale": "Exterior ballistics begins at the muzzle."}, {"text": "Interior ballistics", "is_correct": true, "rationale": "Interior ballistics covers ignition, burning of the propellant and the bullet''s travel through the barrel."}, {"text": "Terminal ballistics", "is_correct": false, "rationale": "Terminal ballistics concerns the target."}, {"text": "Wound ballistics", "is_correct": false, "rationale": "Wound ballistics concerns injuries to the body."}]'::jsonb, 1, 'medium', 'Rifling marks are made on the bullet during the interior ballistic stage.', NULL, 'Study module Forensic Science, Chapter 6: Forensic Ballistics (FS-6.2).', 'generated', 'tos_2024', 1, FALSE, 'FS-6.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-6.2_04', 'criminalistics', 'Forensic Ballistics', 'A firearm with no rifling in its barrel fires many small pellets with each shot. How is it classified?', '[{"text": "Rifled long firearm (rifle)", "is_correct": false, "rationale": "Rifled firearms have lands and grooves."}, {"text": "Smoothbore firearm (shotgun)", "is_correct": true, "rationale": "Shotguns have smooth bores and usually fire multiple pellets."}, {"text": "Machine pistol", "is_correct": false, "rationale": "A machine pistol is a rifled automatic handgun."}, {"text": "Revolver", "is_correct": false, "rationale": "A revolver is a rifled handgun with a revolving cylinder."}]'::jsonb, 1, 'medium', 'Firearms are classified by bore as smoothbore or rifled.', NULL, 'Study module Forensic Science, Chapter 6: Forensic Ballistics (FS-6.2).', 'generated', 'tos_2024', 1, FALSE, 'FS-6.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-6.2_05', 'criminalistics', 'Forensic Ballistics', 'An evidence bullet shows six lands and grooves with a left twist. The suspect''s gun has five lands and grooves with a right twist. What should be concluded?', '[{"text": "The bullet was not fired from the suspect''s gun", "is_correct": true, "rationale": "Different class characteristics, the number of lands and direction of twist, exclude the firearm."}, {"text": "The bullet was fired from the suspect''s gun", "is_correct": false, "rationale": "A firearm cannot leave class characteristics different from its own barrel."}, {"text": "The comparison is inconclusive and must be repeated", "is_correct": false, "rationale": "Differences in class characteristics are clear enough to exclude."}, {"text": "The bullet was fired from a shotgun", "is_correct": false, "rationale": "Shotguns do not leave land and groove marks."}]'::jsonb, 0, 'medium', 'Class characteristics can exclude a firearm; individual characteristics are needed to identify one.', NULL, 'Study module Forensic Science, Chapter 6: Forensic Ballistics (FS-6.2).', 'generated', 'tos_2024', 1, FALSE, 'FS-6.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-6.2_06', 'criminalistics', 'Forensic Ballistics', 'Which part of a cartridge is struck by the firing pin to ignite the propellant?', '[{"text": "Bullet", "is_correct": false, "rationale": "The bullet is the projectile."}, {"text": "Primer", "is_correct": true, "rationale": "The primer contains a sensitive compound that explodes when struck, igniting the powder."}, {"text": "Cartridge case mouth", "is_correct": false, "rationale": "The mouth of the case holds the bullet."}, {"text": "Gunpowder", "is_correct": false, "rationale": "Gunpowder is ignited by the primer, not struck directly."}]'::jsonb, 1, 'medium', 'The parts of a cartridge are the bullet, cartridge case, propellant and primer.', NULL, 'Study module Forensic Science, Chapter 6: Forensic Ballistics (FS-6.2).', 'generated', 'tos_2024', 1, FALSE, 'FS-6.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-6.2_07', 'criminalistics', 'Forensic Ballistics', 'What does the gauge number of a 12-gauge shotgun mean?', '[{"text": "The bore is 12 millimeters in diameter", "is_correct": false, "rationale": "Gauge is not measured in millimeters."}, {"text": "The bore fits a lead ball weighing 1/12 of a pound", "is_correct": true, "rationale": "Gauge is the number of lead balls of the bore''s diameter that make one pound; 12 balls of a 12-gauge bore weigh one pound."}, {"text": "The barrel is 12 inches long", "is_correct": false, "rationale": "Gauge does not refer to barrel length."}, {"text": "The gun holds 12 shells", "is_correct": false, "rationale": "Gauge does not refer to magazine capacity."}]'::jsonb, 1, 'medium', 'The higher the gauge number, the smaller the bore, except the .410, which is a caliber.', NULL, 'Study module Forensic Science, Chapter 6: Forensic Ballistics (FS-6.2).', 'generated', 'tos_2024', 1, FALSE, 'FS-6.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-6.2_08', 'criminalistics', 'Forensic Ballistics', 'Two bullets have the same caliber, number of lands and twist, and their fine striations line up under the comparison microscope. What can be concluded?', '[{"text": "They were fired from two different firearms", "is_correct": false, "rationale": "Agreeing striations exclude different firearms."}, {"text": "They came from the same box of ammunition", "is_correct": false, "rationale": "Striations come from the barrel, not from the ammunition box."}, {"text": "They were fired from the same firearm", "is_correct": true, "rationale": "Agreement of individual characteristics, the striations, identifies a single firearm."}, {"text": "They were fired on the same day", "is_correct": false, "rationale": "The marks do not show the date of firing."}]'::jsonb, 2, 'medium', 'Individual characteristics come from tiny, random imperfections in the barrel.', NULL, 'Study module Forensic Science, Chapter 6: Forensic Ballistics (FS-6.2).', 'generated', 'tos_2024', 1, FALSE, 'FS-6.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-6.2_09', 'criminalistics', 'Forensic Ballistics', 'Only a fired cartridge case was found at the scene, and no bullet. Can it be linked to a particular firearm?', '[{"text": "Yes, through firing pin, breech face, extractor and ejector marks", "is_correct": true, "rationale": "The firearm''s parts leave individual marks on the case, which can be compared with test-fired cases."}, {"text": "No, because only bullets carry identifying marks", "is_correct": false, "rationale": "Cartridge cases also carry identifying marks."}, {"text": "No, because cartridge cases are never marked by the firearm", "is_correct": false, "rationale": "Firing pins, breech faces and extractors mark the case."}, {"text": "Yes, but only by reading its brand stamped on the head", "is_correct": false, "rationale": "The headstamp shows the maker, not the firearm."}]'::jsonb, 0, 'medium', 'Cartridge cases are often the only ballistic evidence left by semi-automatic firearms.', NULL, 'Study module Forensic Science, Chapter 6: Forensic Ballistics (FS-6.2).', 'generated', 'tos_2024', 1, FALSE, 'FS-6.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-6.2_10', 'criminalistics', 'Forensic Ballistics', 'An examiner finds that the class characteristics of the evidence bullet and the test bullets agree, but the striations are too damaged to compare. What is the best conclusion?', '[{"text": "Inconclusive: the gun can be neither identified nor excluded", "is_correct": true, "rationale": "Agreement in class characteristics without enough individual detail allows neither identification nor exclusion."}, {"text": "Identification: the bullet was fired from the suspect''s gun", "is_correct": false, "rationale": "An identification needs sufficient agreement of individual marks."}, {"text": "Exclusion: the bullet was not fired from the suspect''s gun", "is_correct": false, "rationale": "Agreeing class characteristics do not support exclusion."}, {"text": "Identification, because class characteristics are enough", "is_correct": false, "rationale": "Many firearms share the same class characteristics."}]'::jsonb, 0, 'hard', 'Reporting limits honestly is part of sound forensic practice.', NULL, 'Study module Forensic Science, Chapter 6: Forensic Ballistics (FS-6.2).', 'generated', 'tos_2024', 1, FALSE, 'FS-6.2', 'Evaluating') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-6.3_01', 'criminalistics', 'Forensic Ballistics', 'Where should an investigator put his identifying mark on a recovered bullet?', '[{"text": "On the sides, where the rifling marks are clearest", "is_correct": false, "rationale": "Marking the sides destroys the evidence needed for comparison."}, {"text": "On any part, since marks do not affect the examination", "is_correct": false, "rationale": "Marks on the wrong part can ruin the comparison."}, {"text": "On the sides, after first scraping them clean", "is_correct": false, "rationale": "Scraping destroys the striations."}, {"text": "On the base or nose, never on the sides with rifling marks", "is_correct": true, "rationale": "Marking the base or nose avoids damaging the striations on the bearing surface."}]'::jsonb, 3, 'medium', 'Some laboratories prefer marking the container instead of the bullet itself.', NULL, 'Study module Forensic Science, Chapter 6: Forensic Ballistics (FS-6.3).', 'generated', 'tos_2024', 1, FALSE, 'FS-6.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-6.3_02', 'criminalistics', 'Forensic Ballistics', 'Why should a firearm at a crime scene not be picked up by putting a pencil into its barrel?', '[{"text": "It may cause the firearm to be classified wrongly", "is_correct": false, "rationale": "Classification does not depend on how the gun is picked up."}, {"text": "It makes the serial number harder to read", "is_correct": false, "rationale": "Picking it up by the barrel does not affect the serial number."}, {"text": "It can damage the barrel and disturb trace evidence inside it", "is_correct": true, "rationale": "Inserting objects into the barrel can scratch it, alter marks and disturb residue or blood inside."}, {"text": "It is too slow when there are many firearms", "is_correct": false, "rationale": "The issue is preservation of evidence, not speed."}]'::jsonb, 2, 'hard', 'Firearms are handled by the edges of the grip or checkered areas, after making them safe.', NULL, 'Study module Forensic Science, Chapter 6: Forensic Ballistics (FS-6.3).', 'generated', 'tos_2024', 1, FALSE, 'FS-6.3', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-6.3_03', 'criminalistics', 'Forensic Ballistics', 'Why is a fired cartridge case marked inside its mouth rather than on its head?', '[{"text": "The mouth is the only part made of brass", "is_correct": false, "rationale": "The case is usually brass throughout."}, {"text": "The head bears the firing pin and breech face marks", "is_correct": true, "rationale": "Marks on the head could obliterate the firing pin, breech face, extractor and ejector marks."}, {"text": "Marks on the head make the case explode", "is_correct": false, "rationale": "A fired case does not explode."}, {"text": "The head must be kept clean for fingerprints only", "is_correct": false, "rationale": "The head carries ballistic marks, which is the main reason to keep it unmarked."}]'::jsonb, 1, 'hard', 'The mark is placed where it will not interfere with the examination.', NULL, 'Study module Forensic Science, Chapter 6: Forensic Ballistics (FS-6.3).', 'generated', 'tos_2024', 1, FALSE, 'FS-6.3', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-6.3_04', 'criminalistics', 'Forensic Ballistics', 'Why is each recovered bullet wrapped separately in soft tissue and placed in its own small box?', '[{"text": "To keep the bullets warm until examination", "is_correct": false, "rationale": "Temperature does not affect bullets."}, {"text": "To make them lighter to carry to the laboratory", "is_correct": false, "rationale": "Weight is not the reason for packaging."}, {"text": "To allow the bullets to dry in the open air", "is_correct": false, "rationale": "Bullets are protected in closed containers, not left in the open."}, {"text": "To keep the striations from rubbing and the items from mixing", "is_correct": true, "rationale": "Separate, padded packaging prevents damage to marks and keeps each item''s identity."}]'::jsonb, 3, 'hard', 'Each container is sealed and labeled for the chain of custody.', NULL, 'Study module Forensic Science, Chapter 6: Forensic Ballistics (FS-6.3).', 'generated', 'tos_2024', 1, FALSE, 'FS-6.3', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-7.1_01', 'criminalistics', 'Forensic Report Writing and Laboratory Safety', 'An examiner must write the conclusion of a bullet comparison report for court. Which formulation is best?', '[{"text": "''I am one hundred percent sure that no other gun in the world could have fired it.''", "is_correct": false, "rationale": "Claims of absolute certainty go beyond what the science supports."}, {"text": "''The suspect is guilty of the shooting because the bullet came from his gun.''", "is_correct": false, "rationale": "Guilt is for the court to decide, not the examiner."}, {"text": "''The bullets seem quite similar, and the gun might possibly be the one.''", "is_correct": false, "rationale": "Vague wording does not state a clear finding."}, {"text": "''Evidence bullet EB-1 and the test bullets were fired from the submitted pistol, based on agreeing striations.''", "is_correct": true, "rationale": "A good conclusion is clear and objective: it names the items, states the result and gives its basis."}]'::jsonb, 3, 'hard', 'A forensic report usually states the request, the items received, the examinations done, the findings and the conclusion.', NULL, 'Study module Forensic Science, Chapter 7: Forensic Report Writing and Laboratory Safety (FS-7.1).', 'generated', 'tos_2024', 1, FALSE, 'FS-7.1', 'Creating') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_FS-7.2_01', 'criminalistics', 'Forensic Report Writing and Laboratory Safety', 'A laboratory analyst spills a strong acid on her forearm. What is the correct first aid?', '[{"text": "Flush the area with plenty of running water for at least 15 minutes", "is_correct": true, "rationale": "Immediate, prolonged flushing with water removes and dilutes the chemical."}, {"text": "Cover the area with a dry cloth and wait for help", "is_correct": false, "rationale": "Waiting lets the acid keep burning."}, {"text": "Neutralize it at once by pouring a strong base on it", "is_correct": false, "rationale": "A strong base causes a heat-producing reaction and more injury."}, {"text": "Apply butter or oil to soothe the skin", "is_correct": false, "rationale": "Butter or oil traps the chemical and heat on the skin."}]'::jsonb, 0, 'medium', 'Laboratories must have safety showers, eyewash stations and safety data sheets for chemicals.', NULL, 'Study module Forensic Science, Chapter 7: Forensic Report Writing and Laboratory Safety (FS-7.2).', 'generated', 'tos_2024', 1, FALSE, 'FS-7.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-1.1_01', 'crime_detection', 'Fundamentals of Criminal Investigation and Intelligence', 'What is the main objective of criminal investigation?', '[{"text": "To identify, locate and prove the guilt of the offender", "is_correct": true, "rationale": "Criminal investigation aims to identify the offender, trace and locate him, and gather evidence to prove his guilt in court."}, {"text": "To punish the offender as quickly as possible", "is_correct": false, "rationale": "Punishment is imposed by the court after trial, not by investigators."}, {"text": "To obtain a confession from every suspect", "is_correct": false, "rationale": "A confession is not required and must never be the only aim."}, {"text": "To collect fines from persons who break the law", "is_correct": false, "rationale": "Fines are imposed by courts, not collected through investigation."}]'::jsonb, 0, 'easy', 'The three phases of investigation follow these objectives.', NULL, 'Study module Crime Detection and Investigation, Chapter 1: Fundamentals of Criminal Investigation and Intelligence (CDI-1.1).', 'generated', 'tos_2024', 1, FALSE, 'CDI-1.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-1.1_02', 'crime_detection', 'Fundamentals of Criminal Investigation and Intelligence', 'Which tool of investigation refers to the use of scientific instruments and forensic methods?', '[{"text": "Instrumentation", "is_correct": true, "rationale": "Instrumentation is the application of instruments and methods of the physical sciences to detect crime."}, {"text": "Information", "is_correct": false, "rationale": "Information is the knowledge gathered from persons and records."}, {"text": "Interrogation", "is_correct": false, "rationale": "Interrogation is the skillful questioning of suspects and witnesses."}, {"text": "Identification", "is_correct": false, "rationale": "Identification is an objective of investigation, not one of the three tools."}]'::jsonb, 0, 'easy', 'The three I''s of investigation are information, interrogation (with interview) and instrumentation.', NULL, 'Study module Crime Detection and Investigation, Chapter 1: Fundamentals of Criminal Investigation and Intelligence (CDI-1.1).', 'generated', 'tos_2024', 1, FALSE, 'CDI-1.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-1.1_03', 'crime_detection', 'Fundamentals of Criminal Investigation and Intelligence', 'Which cardinal point of investigation deals with the motive for the crime?', '[{"text": "Why", "is_correct": true, "rationale": "''Why'' asks for the reason or motive behind the crime."}, {"text": "How", "is_correct": false, "rationale": "''How'' asks for the manner in which the crime was committed."}, {"text": "When", "is_correct": false, "rationale": "''When'' asks for the time of the crime."}, {"text": "Where", "is_correct": false, "rationale": "''Where'' asks for the place of the crime."}]'::jsonb, 0, 'easy', 'The six cardinal points are what, where, when, how, who and why.', NULL, 'Study module Crime Detection and Investigation, Chapter 1: Fundamentals of Criminal Investigation and Intelligence (CDI-1.1).', 'generated', 'tos_2024', 1, FALSE, 'CDI-1.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-1.1_04', 'crime_detection', 'Fundamentals of Criminal Investigation and Intelligence', 'Why must intelligence be timely?', '[{"text": "Late intelligence is always more accurate than early intelligence", "is_correct": false, "rationale": "Delay does not make intelligence more accurate."}, {"text": "Timeliness matters only for military, not police, intelligence", "is_correct": false, "rationale": "Timeliness applies to all intelligence, including police intelligence."}, {"text": "Intelligence is useful only after the operation is over", "is_correct": false, "rationale": "Intelligence is meant to guide operations before and during them."}, {"text": "It loses its value if it reaches users after they must act", "is_correct": true, "rationale": "Intelligence exists to support decisions and operations; if it arrives late, it cannot influence them."}]'::jsonb, 3, 'easy', 'Other principles of intelligence include usefulness, security and continuity.', NULL, 'Study module Crime Detection and Investigation, Chapter 1: Fundamentals of Criminal Investigation and Intelligence (CDI-1.1).', 'generated', 'tos_2024', 1, FALSE, 'CDI-1.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-1.1_05', 'crime_detection', 'Fundamentals of Criminal Investigation and Intelligence', 'A suspect confessed during investigation. Why is the third phase of investigation, proving guilt, still not complete?', '[{"text": "A confession can never be used as evidence against anyone", "is_correct": false, "rationale": "A valid confession is admissible; it simply needs corroboration."}, {"text": "The third phase needs a second confession from the suspect", "is_correct": false, "rationale": "No rule requires a second confession."}, {"text": "A confession needs evidence of the corpus delicti to support a conviction", "is_correct": true, "rationale": "Under Rule 133, an extrajudicial confession is not enough to convict without evidence of the corpus delicti."}, {"text": "The third phase begins only after the suspect is convicted", "is_correct": false, "rationale": "Proof of guilt is gathered before trial, not after conviction."}]'::jsonb, 2, 'hard', 'Investigators should gather physical and testimonial evidence that stands on its own.', 'Rules of Court, Rule 133, Sec. 3', 'Study module Crime Detection and Investigation, Chapter 1: Fundamentals of Criminal Investigation and Intelligence (CDI-1.1).', 'generated', 'tos_2024', 1, FALSE, 'CDI-1.1', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-1.2_01', 'crime_detection', 'Fundamentals of Criminal Investigation and Intelligence', 'An agent watches a suspected drug den from a rented room across the street for several days. What type of surveillance is this?', '[{"text": "Tailing (moving surveillance)", "is_correct": false, "rationale": "Tailing follows a moving subject on foot or by vehicle."}, {"text": "Stakeout (fixed surveillance)", "is_correct": true, "rationale": "A stakeout is fixed surveillance of a place from a stationary position."}, {"text": "Roping (undercover work)", "is_correct": false, "rationale": "Roping is undercover work where the agent assumes a role to gain the subject''s confidence."}, {"text": "Casing of a target", "is_correct": false, "rationale": "Casing is the inspection of a place to plan an operation."}]'::jsonb, 1, 'medium', 'Surveillance is the covert observation of persons, places or things to obtain information.', NULL, 'Study module Crime Detection and Investigation, Chapter 1: Fundamentals of Criminal Investigation and Intelligence (CDI-1.2).', 'generated', 'tos_2024', 1, FALSE, 'CDI-1.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-1.2_02', 'crime_detection', 'Fundamentals of Criminal Investigation and Intelligence', 'Finished intelligence is delivered to the commander who requested it so he can plan an operation. Which phase of the intelligence cycle is this?', '[{"text": "Planning and direction", "is_correct": false, "rationale": "Planning and direction decides what intelligence is needed."}, {"text": "Collection", "is_correct": false, "rationale": "Collection gathers the raw information."}, {"text": "Processing", "is_correct": false, "rationale": "Processing records, evaluates and interprets the information."}, {"text": "Dissemination and use", "is_correct": true, "rationale": "Dissemination delivers the finished intelligence to the users who need it."}]'::jsonb, 3, 'medium', 'The cycle starts again as new needs arise.', NULL, 'Study module Crime Detection and Investigation, Chapter 1: Fundamentals of Criminal Investigation and Intelligence (CDI-1.2).', 'generated', 'tos_2024', 1, FALSE, 'CDI-1.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-1.2_03', 'crime_detection', 'Fundamentals of Criminal Investigation and Intelligence', 'A source has always been reliable, and his report is confirmed by other sources. How should the information be rated?', '[{"text": "A-1", "is_correct": true, "rationale": "A means completely reliable source; 1 means confirmed by other sources."}, {"text": "B-2", "is_correct": false, "rationale": "B-2 means usually reliable and probably true."}, {"text": "C-3", "is_correct": false, "rationale": "C-3 means fairly reliable and possibly true."}, {"text": "F-6", "is_correct": false, "rationale": "F-6 means the source''s reliability and the truth cannot be judged."}]'::jsonb, 0, 'medium', 'Letters rate the source (A to F); numbers rate the information (1 to 6).', NULL, 'Study module Crime Detection and Investigation, Chapter 1: Fundamentals of Criminal Investigation and Intelligence (CDI-1.2).', 'generated', 'tos_2024', 1, FALSE, 'CDI-1.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-1.2_04', 'crime_detection', 'Fundamentals of Criminal Investigation and Intelligence', 'A man regularly gives the police information about a gang in exchange for money. How is he classified?', '[{"text": "As an informer, because he gives information for a fee", "is_correct": true, "rationale": "An informer furnishes information regularly, usually for a fee or reward."}, {"text": "As an informant, because he gives information once and freely", "is_correct": false, "rationale": "An informant gives information freely, often once, without seeking reward."}, {"text": "As a witness, because he will surely testify in court", "is_correct": false, "rationale": "Informers usually do not testify, to protect their identity."}, {"text": "As an undercover agent, because he is a police officer", "is_correct": false, "rationale": "He is a private person, not a police officer."}]'::jsonb, 0, 'hard', 'Investigators must protect the identity of informers and weigh their motives.', NULL, 'Study module Crime Detection and Investigation, Chapter 1: Fundamentals of Criminal Investigation and Intelligence (CDI-1.2).', 'generated', 'tos_2024', 1, FALSE, 'CDI-1.2', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-1.2_05', 'crime_detection', 'Fundamentals of Criminal Investigation and Intelligence', 'Unauthorized disclosure of a document would cause grave, but not exceptionally grave, damage to the nation. How should it be classified?', '[{"text": "Top Secret", "is_correct": false, "rationale": "Top Secret covers exceptionally grave damage."}, {"text": "Secret", "is_correct": true, "rationale": "Secret covers information whose disclosure would cause grave damage."}, {"text": "Confidential", "is_correct": false, "rationale": "Confidential covers damage or prejudice to the interest of the nation."}, {"text": "Restricted", "is_correct": false, "rationale": "Restricted covers information for official use only."}]'::jsonb, 1, 'hard', 'Classification decides who may have access and how the document is handled.', NULL, 'Study module Crime Detection and Investigation, Chapter 1: Fundamentals of Criminal Investigation and Intelligence (CDI-1.2).', 'generated', 'tos_2024', 1, FALSE, 'CDI-1.2', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-1.3_01', 'crime_detection', 'Fundamentals of Criminal Investigation and Intelligence', 'A body was found in a large open field. Several officers will search the area. Which search method is most suitable?', '[{"text": "Spiral (circle) method", "is_correct": false, "rationale": "The spiral method is used by one searcher moving in or out in circles."}, {"text": "Wheel method", "is_correct": false, "rationale": "The wheel method has searchers move out from the center like spokes; it can leave gaps."}, {"text": "Strip (line) method", "is_correct": true, "rationale": "In the strip or line method, searchers walk side by side in straight lines, which covers large open areas well."}, {"text": "Zone method", "is_correct": false, "rationale": "The zone method divides a place, such as a house, into sections."}]'::jsonb, 2, 'medium', 'The choice of method depends on the size and nature of the scene and the number of searchers.', NULL, 'Study module Crime Detection and Investigation, Chapter 1: Fundamentals of Criminal Investigation and Intelligence (CDI-1.3).', 'generated', 'tos_2024', 1, FALSE, 'CDI-1.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-1.3_02', 'crime_detection', 'Fundamentals of Criminal Investigation and Intelligence', 'A house with several rooms is divided into sections, and each section is assigned to a searcher. Which search method is this?', '[{"text": "Zone (quadrant) method", "is_correct": true, "rationale": "The zone or quadrant method divides the scene into sections that are searched one at a time or by different searchers."}, {"text": "Strip (line) method", "is_correct": false, "rationale": "The strip method is for open areas searched in lines."}, {"text": "Spiral method", "is_correct": false, "rationale": "The spiral method is for one searcher moving in circles."}, {"text": "Wheel method", "is_correct": false, "rationale": "The wheel method moves out from a central point."}]'::jsonb, 0, 'medium', 'Each zone should be searched thoroughly and recorded before moving on.', NULL, 'Study module Crime Detection and Investigation, Chapter 1: Fundamentals of Criminal Investigation and Intelligence (CDI-1.3).', 'generated', 'tos_2024', 1, FALSE, 'CDI-1.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-1.3_03', 'crime_detection', 'Fundamentals of Criminal Investigation and Intelligence', 'An investigator wants one drawing to show the bloodstains on the floor and on the four walls of a room. Which sketch should he make?', '[{"text": "Locality (vicinity) sketch", "is_correct": false, "rationale": "A locality sketch shows the scene and its surroundings, such as nearby roads."}, {"text": "Cross-projection (exploded) sketch", "is_correct": true, "rationale": "A cross-projection sketch folds the walls down flat around the floor so marks on them can be shown together."}, {"text": "Perspective (3-D) sketch", "is_correct": false, "rationale": "A perspective sketch shows the scene in three dimensions."}, {"text": "Rough sketch only", "is_correct": false, "rationale": "A rough sketch is the first sketch made at the scene; it does not by itself solve the problem."}]'::jsonb, 1, 'medium', 'The finished sketch is drawn to scale from the rough sketch and measurements.', NULL, 'Study module Crime Detection and Investigation, Chapter 1: Fundamentals of Criminal Investigation and Intelligence (CDI-1.3).', 'generated', 'tos_2024', 1, FALSE, 'CDI-1.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-1.3_04', 'crime_detection', 'Fundamentals of Criminal Investigation and Intelligence', 'Why can a confession obtained through torture not be used as evidence, even if it is true?', '[{"text": "It is admissible if the suspect later repeats it in court", "is_correct": false, "rationale": "Repeating it in court does not cure the original illegality of the extrajudicial confession."}, {"text": "It is admissible if the torture left no visible injuries", "is_correct": false, "rationale": "Mental torture leaves no visible marks and is still torture."}, {"text": "It is admissible if the crime is a heinous one", "is_correct": false, "rationale": "No crime, however grave, allows the use of torture."}, {"text": "R.A. 9745 makes it inadmissible, except against the torturer", "is_correct": true, "rationale": "Section 8 of R.A. 9745 excludes any statement obtained through torture, except when used against the person accused of torture."}]'::jsonb, 3, 'hard', 'The exclusion removes any incentive to torture suspects.', 'R.A. 9745 (Anti-Torture Act of 2009), Sec. 8', 'Study module Crime Detection and Investigation, Chapter 1: Fundamentals of Criminal Investigation and Intelligence (CDI-1.3).', 'generated', 'tos_2024', 1, FALSE, 'CDI-1.3', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-1.3_05', 'crime_detection', 'Fundamentals of Criminal Investigation and Intelligence', 'A store owner catches a man in the act of stealing and holds him. Was the arrest lawful, and what must the owner do next?', '[{"text": "Lawful; he must hand the man to the nearest police station without delay", "is_correct": true, "rationale": "A private person may arrest an offender caught in the act and must deliver him to the nearest police station or jail without unnecessary delay."}, {"text": "Unlawful, because only police officers may arrest anyone", "is_correct": false, "rationale": "Private persons may arrest in the cases under Rule 113, Sec. 5."}, {"text": "Lawful; he may keep the man in the store until the next day", "is_correct": false, "rationale": "Keeping the person longer than necessary may be illegal detention."}, {"text": "Unlawful, unless the owner first obtains a warrant", "is_correct": false, "rationale": "No warrant is needed for an in flagrante delicto arrest."}]'::jsonb, 0, 'hard', 'A citizen''s arrest is subject to the same rules on warrantless arrest.', 'Rules of Court, Rule 113, Secs. 5 and 9', 'Study module Crime Detection and Investigation, Chapter 1: Fundamentals of Criminal Investigation and Intelligence (CDI-1.3).', 'generated', 'tos_2024', 1, FALSE, 'CDI-1.3', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-2.1_01', 'crime_detection', 'Specialized Crime Investigation 1 with Legal Medicine', 'A woman reports that she was raped an hour ago. What should the investigator advise her before the medico-legal examination?', '[{"text": "Do not bathe or change clothes, so physical evidence is preserved", "is_correct": true, "rationale": "Bathing or changing clothes can destroy semen, hair, fibers and other evidence."}, {"text": "Bathe first so she will feel comfortable during the examination", "is_correct": false, "rationale": "Comfort matters, but evidence must be preserved first."}, {"text": "Wash the clothes she wore before bringing them to the police", "is_correct": false, "rationale": "Washing the clothes destroys evidence."}, {"text": "Wait a week before the examination so she can rest", "is_correct": false, "rationale": "Delay lets injuries heal and evidence disappear."}]'::jsonb, 0, 'medium', 'Rape victims are referred to the Women and Children Protection Desk and handled with sensitivity.', 'R.A. 8505 (Rape Victim Assistance and Protection Act)', 'Study module Crime Detection and Investigation, Chapter 2: Specialized Crime Investigation 1 with Legal Medicine (CDI-2.1).', 'generated', 'tos_2024', 1, FALSE, 'CDI-2.1', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-2.1_02', 'crime_detection', 'Specialized Crime Investigation 1 with Legal Medicine', 'The first officer at a stabbing scene finds the victim still breathing. What should he do first?', '[{"text": "Search the victim''s pockets for evidence", "is_correct": false, "rationale": "Searching the victim delays aid and may disturb evidence."}, {"text": "Give or call for medical aid, then secure the scene", "is_correct": true, "rationale": "Saving life comes first; the officer then protects the scene and the evidence."}, {"text": "Take photographs before anything else", "is_correct": false, "rationale": "Photographs are important, but not before life-saving aid."}, {"text": "Look for the suspect in the nearby streets", "is_correct": false, "rationale": "Leaving the victim to chase a suspect abandons the first duty."}]'::jsonb, 1, 'medium', 'If the victim is moved for treatment, the officer notes his original position.', NULL, 'Study module Crime Detection and Investigation, Chapter 2: Specialized Crime Investigation 1 with Legal Medicine (CDI-2.1).', 'generated', 'tos_2024', 1, FALSE, 'CDI-2.1', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-2.1_03', 'crime_detection', 'Specialized Crime Investigation 1 with Legal Medicine', 'A fraternity member was present during a hazing in which a neophyte died, but did nothing to stop it. How does R.A. 11053 treat his presence?', '[{"text": "As proof that he was only a witness and is not liable", "is_correct": false, "rationale": "Presence is not treated as merely being a witness."}, {"text": "As prima facie evidence that he took part as a principal", "is_correct": true, "rationale": "R.A. 11053 makes presence during hazing prima facie evidence of participation as a principal, unless he tried to prevent it or promptly reported it."}, {"text": "As a mitigating circumstance in favor of the member", "is_correct": false, "rationale": "Presence is not a mitigating circumstance under the law."}, {"text": "As irrelevant unless he struck the neophyte himself", "is_correct": false, "rationale": "The law punishes participation, and presence raises a presumption of it."}]'::jsonb, 1, 'medium', 'Officers and members who planned or took part in hazing face heavy penalties, especially if death results.', 'R.A. 8049, as amended by R.A. 11053', 'Study module Crime Detection and Investigation, Chapter 2: Specialized Crime Investigation 1 with Legal Medicine (CDI-2.1).', 'generated', 'tos_2024', 1, FALSE, 'CDI-2.1', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-2.1_04', 'crime_detection', 'Specialized Crime Investigation 1 with Legal Medicine', 'Co-workers of equal rank keep making sexual remarks about a colleague at the office. Which law most directly applies?', '[{"text": "R.A. 7877, which requires authority over the victim", "is_correct": false, "rationale": "R.A. 7877 applies when the offender has authority, influence or moral ascendancy over the victim."}, {"text": "R.A. 11313, which covers peer harassment at work", "is_correct": true, "rationale": "The Safe Spaces Act covers gender-based sexual harassment in workplaces, including between peers."}, {"text": "R.A. 9262, which covers intimate partners only", "is_correct": false, "rationale": "R.A. 9262 concerns violence against women in intimate relationships."}, {"text": "R.A. 11053, which covers initiation rites", "is_correct": false, "rationale": "R.A. 11053 concerns hazing."}]'::jsonb, 1, 'hard', 'R.A. 11313 extended protection to streets, public spaces, online spaces, workplaces and schools.', 'R.A. 11313; R.A. 7877', 'Study module Crime Detection and Investigation, Chapter 2: Specialized Crime Investigation 1 with Legal Medicine (CDI-2.1).', 'generated', 'tos_2024', 1, FALSE, 'CDI-2.1', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-2.1_05', 'crime_detection', 'Specialized Crime Investigation 1 with Legal Medicine', 'A wife is suspected of killing her husband. Beyond the evidence needed for homicide, what must investigators also obtain?', '[{"text": "Proof that the husband had no life insurance", "is_correct": false, "rationale": "Insurance is not an element of parricide."}, {"text": "Proof of their marriage, such as the marriage certificate", "is_correct": true, "rationale": "Parricide requires the relationship; the marriage certificate is the best evidence of it."}, {"text": "Proof that the wife had a previous criminal record", "is_correct": false, "rationale": "A prior record is not an element of the crime."}, {"text": "Proof that the killing happened at their home", "is_correct": false, "rationale": "The place of the killing is not an element of parricide."}]'::jsonb, 1, 'hard', 'The relationship must also be alleged in the information.', 'Revised Penal Code, Art. 246', 'Study module Crime Detection and Investigation, Chapter 2: Specialized Crime Investigation 1 with Legal Medicine (CDI-2.1).', 'generated', 'tos_2024', 1, FALSE, 'CDI-2.1', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-2.2_01', 'crime_detection', 'Specialized Crime Investigation 1 with Legal Medicine', 'How does somatic death differ from molecular death?', '[{"text": "Somatic is the death of cells; molecular is the stop of breathing", "is_correct": false, "rationale": "This reverses the two kinds of death."}, {"text": "Somatic is the stop of vital functions; molecular is the later death of cells", "is_correct": true, "rationale": "Somatic (clinical) death is the complete and continuous stop of brain, heart and lung functions; molecular (cellular) death follows hours later."}, {"text": "Somatic happens days after molecular death", "is_correct": false, "rationale": "Somatic death comes first, then molecular death."}, {"text": "Somatic applies to animals; molecular applies to humans", "is_correct": false, "rationale": "Both apply to humans."}]'::jsonb, 1, 'easy', 'The gap between somatic and molecular death explains why organs can be harvested for transplant.', NULL, 'Study module Crime Detection and Investigation, Chapter 2: Specialized Crime Investigation 1 with Legal Medicine (CDI-2.2).', 'generated', 'tos_2024', 1, FALSE, 'CDI-2.2', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-2.2_02', 'crime_detection', 'Specialized Crime Investigation 1 with Legal Medicine', 'A body found lying face down has fixed lividity on its back. What does this suggest?', '[{"text": "The victim died lying face down where he was found", "is_correct": false, "rationale": "Death face down would put the lividity on the front."}, {"text": "The victim died less than an hour ago", "is_correct": false, "rationale": "Fixed lividity takes several hours to develop."}, {"text": "The lividity was caused by blows before death", "is_correct": false, "rationale": "Lividity is a post-mortem change, not a bruise from blows."}, {"text": "The body was moved after the lividity had become fixed", "is_correct": true, "rationale": "Lividity settles in the lowest parts; if it is fixed on the back while the body faces down, the body was turned or moved."}]'::jsonb, 3, 'medium', 'Livor mortis helps estimate the time of death and detect movement of the body.', NULL, 'Study module Crime Detection and Investigation, Chapter 2: Specialized Crime Investigation 1 with Legal Medicine (CDI-2.2).', 'generated', 'tos_2024', 1, FALSE, 'CDI-2.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-2.2_03', 'crime_detection', 'Specialized Crime Investigation 1 with Legal Medicine', 'A wound has clean, sharp edges and is longer than it is deep. What kind of wound is it?', '[{"text": "Incised wound", "is_correct": true, "rationale": "An incised wound is made by a sharp edge drawn across the skin; it is longer than deep."}, {"text": "Stab wound", "is_correct": false, "rationale": "A stab wound is deeper than it is long."}, {"text": "Lacerated wound", "is_correct": false, "rationale": "A lacerated wound has irregular, torn edges from blunt force."}, {"text": "Punctured wound", "is_correct": false, "rationale": "A punctured wound is made by a pointed instrument without a cutting edge."}]'::jsonb, 0, 'medium', 'The type of wound suggests the kind of weapon used.', NULL, 'Study module Crime Detection and Investigation, Chapter 2: Specialized Crime Investigation 1 with Legal Medicine (CDI-2.2).', 'generated', 'tos_2024', 1, FALSE, 'CDI-2.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-2.2_04', 'crime_detection', 'Specialized Crime Investigation 1 with Legal Medicine', 'A body has two gunshot wounds. Which features point to the wound of entrance?', '[{"text": "Larger size, everted edges and no contusion collar", "is_correct": false, "rationale": "These describe an exit wound."}, {"text": "Ragged edges with tissue pushed outward", "is_correct": false, "rationale": "Outward-pushed tissue describes an exit wound."}, {"text": "Smaller size, inverted edges and a contusion collar", "is_correct": true, "rationale": "Entrance wounds are usually smaller, with edges pushed inward and a ring of abrasion or contusion."}, {"text": "No difference between entrance and exit", "is_correct": false, "rationale": "Entrance and exit wounds usually show clear differences."}]'::jsonb, 2, 'medium', 'Close-range wounds may also show burning, smudging or tattooing from powder.', NULL, 'Study module Crime Detection and Investigation, Chapter 2: Specialized Crime Investigation 1 with Legal Medicine (CDI-2.2).', 'generated', 'tos_2024', 1, FALSE, 'CDI-2.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-2.2_05', 'crime_detection', 'Specialized Crime Investigation 1 with Legal Medicine', 'Under magnification, strands of tissue bridge the depth of a wound with irregular edges. What does this indicate?', '[{"text": "An incised wound from a very sharp knife", "is_correct": false, "rationale": "Sharp weapons leave no tissue bridges."}, {"text": "A gunshot wound from a long distance", "is_correct": false, "rationale": "Gunshot wounds have distinct features such as a contusion collar."}, {"text": "A laceration from blunt force, not a sharp cut", "is_correct": true, "rationale": "Tissue bridges remain when blunt force tears the skin; sharp instruments cut through everything cleanly."}, {"text": "A burn from a hot object", "is_correct": false, "rationale": "Burns do not form tissue bridges."}]'::jsonb, 2, 'hard', 'Telling lacerations from cuts helps identify the weapon.', NULL, 'Study module Crime Detection and Investigation, Chapter 2: Specialized Crime Investigation 1 with Legal Medicine (CDI-2.2).', 'generated', 'tos_2024', 1, FALSE, 'CDI-2.2', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-3.1_01', 'crime_detection', 'Specialized Crime Investigation 2 with Interview and Interrogation', 'How does an interview differ from an interrogation?', '[{"text": "An interview is only for suspects; an interrogation only for victims", "is_correct": false, "rationale": "Both may involve various persons, but interviews usually involve witnesses and victims."}, {"text": "An interview questions willing persons; an interrogation questions reluctant suspects", "is_correct": true, "rationale": "Interviews gather information from those willing to share it, such as witnesses; interrogations question suspects or reluctant persons."}, {"text": "An interview is always recorded; an interrogation never is", "is_correct": false, "rationale": "Both may be recorded."}, {"text": "An interview is done in court; an interrogation at the scene", "is_correct": false, "rationale": "Neither is done in court; both are investigative."}]'::jsonb, 1, 'easy', 'Rights of persons under custodial investigation apply during interrogation of suspects.', 'R.A. 7438', 'Study module Crime Detection and Investigation, Chapter 3: Specialized Crime Investigation 2 with Interview and Interrogation (CDI-3.1).', 'generated', 'tos_2024', 1, FALSE, 'CDI-3.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-3.1_02', 'crime_detection', 'Specialized Crime Investigation 2 with Interview and Interrogation', 'One investigator acts harsh toward the suspect while another acts kind and offers to help him. Which technique is this?', '[{"text": "Mutt and Jeff", "is_correct": true, "rationale": "Mutt and Jeff uses one hostile and one friendly investigator so the suspect turns to the friendly one."}, {"text": "Bluff on a split pair", "is_correct": false, "rationale": "Bluff on a split pair tells one suspect that his partner has already confessed."}, {"text": "Stern approach", "is_correct": false, "rationale": "The stern approach uses a firm, businesslike manner by one investigator."}, {"text": "Extenuation", "is_correct": false, "rationale": "Extenuation reduces the moral seriousness of the act to encourage a confession."}]'::jsonb, 0, 'medium', 'All techniques must respect the suspect''s rights; threats and torture are unlawful.', NULL, 'Study module Crime Detection and Investigation, Chapter 3: Specialized Crime Investigation 2 with Interview and Interrogation (CDI-3.1).', 'generated', 'tos_2024', 1, FALSE, 'CDI-3.1', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-3.1_03', 'crime_detection', 'Specialized Crime Investigation 2 with Interview and Interrogation', 'A suspect says he was at the scene and owns the knife found there, but denies killing the victim. What is his statement?', '[{"text": "A confession", "is_correct": false, "rationale": "A confession acknowledges guilt of the offense."}, {"text": "A dying declaration", "is_correct": false, "rationale": "A dying declaration is made by a victim conscious of impending death."}, {"text": "An admission", "is_correct": true, "rationale": "An admission acknowledges facts that tend to prove guilt, without admitting the crime itself."}, {"text": "A res gestae statement", "is_correct": false, "rationale": "A res gestae statement is made spontaneously during or right after a startling event."}]'::jsonb, 2, 'medium', 'Admissions and confessions under custodial investigation must follow the rules of R.A. 7438.', 'Rules of Court, Rule 130, Secs. 27 and 34', 'Study module Crime Detection and Investigation, Chapter 3: Specialized Crime Investigation 2 with Interview and Interrogation (CDI-3.1).', 'generated', 'tos_2024', 1, FALSE, 'CDI-3.1', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-3.1_04', 'crime_detection', 'Specialized Crime Investigation 2 with Interview and Interrogation', 'A witness testifies that she heard the accused shout threats at the victim, offered only to prove that the words were spoken. How is this testimony treated?', '[{"text": "As hearsay that must be excluded", "is_correct": false, "rationale": "Hearsay applies only when the statement is offered to prove its truth."}, {"text": "As an independent relevant statement, not hearsay", "is_correct": true, "rationale": "When the fact that words were said is itself relevant, not their truth, the statement is an independent relevant statement."}, {"text": "As a dying declaration of the victim", "is_correct": false, "rationale": "A dying declaration is made by the victim about his own death."}, {"text": "As an extrajudicial confession of the accused", "is_correct": false, "rationale": "Threats are not a confession of a crime."}]'::jsonb, 1, 'medium', 'The witness heard the words personally, so she can testify that they were said.', 'Rules of Court, Rule 130, Sec. 38', 'Study module Crime Detection and Investigation, Chapter 3: Specialized Crime Investigation 2 with Interview and Interrogation (CDI-3.1).', 'generated', 'tos_2024', 1, FALSE, 'CDI-3.1', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-3.1_05', 'crime_detection', 'Specialized Crime Investigation 2 with Interview and Interrogation', 'Without counsel, a suspect confessed orally to an officer during custodial investigation. The officer later testifies about it. Is the confession admissible?', '[{"text": "Yes, because the officer heard it personally", "is_correct": false, "rationale": "Personal knowledge of the officer does not cure the violation of the suspect''s rights."}, {"text": "No, because it was made without counsel and not in writing", "is_correct": true, "rationale": "R.A. 7438 requires an extrajudicial confession in custody to be in writing and signed with counsel, or with a valid waiver before the persons the law names."}, {"text": "Yes, because oral confessions need no counsel", "is_correct": false, "rationale": "Custodial confessions, oral or written, require the assistance of counsel."}, {"text": "No, unless the suspect repeats it in a newspaper interview", "is_correct": false, "rationale": "A media interview does not make the custodial confession admissible."}]'::jsonb, 1, 'hard', 'Spontaneous statements to the media, not made during custodial investigation, are treated differently.', 'R.A. 7438, Sec. 2(d); 1987 Constitution, Art. III, Sec. 12', 'Study module Crime Detection and Investigation, Chapter 3: Specialized Crime Investigation 2 with Interview and Interrogation (CDI-3.1).', 'generated', 'tos_2024', 1, FALSE, 'CDI-3.1', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-3.2_01', 'crime_detection', 'Specialized Crime Investigation 2 with Interview and Interrogation', 'In money laundering, which stage moves dirty money through many transactions to hide its source?', '[{"text": "Layering", "is_correct": true, "rationale": "Layering separates the money from its source through complex transfers and transactions."}, {"text": "Placement", "is_correct": false, "rationale": "Placement is putting the cash into the financial system."}, {"text": "Integration", "is_correct": false, "rationale": "Integration returns the money to the economy as apparently legitimate funds."}, {"text": "Structuring", "is_correct": false, "rationale": "Structuring is splitting deposits to avoid reporting thresholds, a placement method."}]'::jsonb, 0, 'easy', 'R.A. 9160, as amended, created the Anti-Money Laundering Council.', 'R.A. 9160, as amended', 'Study module Crime Detection and Investigation, Chapter 3: Specialized Crime Investigation 2 with Interview and Interrogation (CDI-3.2).', 'generated', 'tos_2024', 1, FALSE, 'CDI-3.2', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-3.2_02', 'crime_detection', 'Specialized Crime Investigation 2 with Interview and Interrogation', 'A man drove away a parked car without the owner''s consent, intending to sell it. What crime did he commit?', '[{"text": "Simple theft under the Revised Penal Code", "is_correct": false, "rationale": "The special law on carnapping applies to motor vehicles."}, {"text": "Robbery with force upon things", "is_correct": false, "rationale": "Carnapping covers the taking of motor vehicles whatever the means."}, {"text": "Carnapping under R.A. 10883", "is_correct": true, "rationale": "R.A. 10883 defines carnapping as taking a motor vehicle of another, with intent to gain, without consent or by violence, intimidation or force."}, {"text": "Estafa through abuse of confidence", "is_correct": false, "rationale": "There was no abuse of confidence."}]'::jsonb, 2, 'medium', 'R.A. 10883 repealed R.A. 6539 and increased the penalties.', 'R.A. 10883 (New Anti-Carnapping Act of 2016)', 'Study module Crime Detection and Investigation, Chapter 3: Specialized Crime Investigation 2 with Interview and Interrogation (CDI-3.2).', 'generated', 'tos_2024', 1, FALSE, 'CDI-3.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-3.2_03', 'crime_detection', 'Specialized Crime Investigation 2 with Interview and Interrogation', 'A shop owner bought a cellphone from a stranger at a very low price without a receipt and resold it. The phone was stolen. What is the owner''s liability?', '[{"text": "Theft, because he had the stolen item in his store", "is_correct": false, "rationale": "The fence is a different offender from the thief."}, {"text": "None, because he paid for the cellphone", "is_correct": false, "rationale": "Paying for stolen goods is the very act of fencing."}, {"text": "Estafa, because he resold the cellphone", "is_correct": false, "rationale": "Reselling stolen goods is fencing, not estafa."}, {"text": "Fencing, with possession of the stolen item as prima facie evidence", "is_correct": true, "rationale": "P.D. 1612 punishes dealing in items one knows or should know were stolen; possession of stolen goods is prima facie evidence of fencing."}]'::jsonb, 3, 'medium', 'A very low price and lack of receipt should alert a buyer that goods may be stolen.', 'P.D. 1612 (Anti-Fencing Law of 1979), Secs. 2 and 5', 'Study module Crime Detection and Investigation, Chapter 3: Specialized Crime Investigation 2 with Interview and Interrogation (CDI-3.2).', 'generated', 'tos_2024', 1, FALSE, 'CDI-3.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-3.2_04', 'crime_detection', 'Specialized Crime Investigation 2 with Interview and Interrogation', 'A recruiter takes the passports of workers and forces them to work without pay. Which law applies?', '[{"text": "The anti-carnapping law, R.A. 10883", "is_correct": false, "rationale": "R.A. 10883 concerns motor vehicles."}, {"text": "The anti-fencing law, P.D. 1612", "is_correct": false, "rationale": "P.D. 1612 concerns stolen goods."}, {"text": "The anti-money laundering law, R.A. 9160", "is_correct": false, "rationale": "R.A. 9160 concerns laundering of proceeds of crime."}, {"text": "The anti-trafficking law, R.A. 9208 as amended", "is_correct": true, "rationale": "Recruiting and keeping persons for forced labor through coercion is trafficking in persons; confiscating passports is a punishable act."}]'::jsonb, 3, 'medium', 'R.A. 9208 was expanded by R.A. 10364 and R.A. 11862.', 'R.A. 9208, as amended by R.A. 10364 and R.A. 11862', 'Study module Crime Detection and Investigation, Chapter 3: Specialized Crime Investigation 2 with Interview and Interrogation (CDI-3.2).', 'generated', 'tos_2024', 1, FALSE, 'CDI-3.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-3.2_05', 'crime_detection', 'Specialized Crime Investigation 2 with Interview and Interrogation', 'A company collector received payments from customers for his employer but kept the money. Why is he usually liable for qualified theft, not estafa?', '[{"text": "He used violence against the customers", "is_correct": false, "rationale": "No violence was used."}, {"text": "He deceived the customers before they paid", "is_correct": false, "rationale": "Deceit of the customers is not shown."}, {"text": "He was not an employee of the company", "is_correct": false, "rationale": "He was an employee, which is why the abuse of confidence qualifies the theft."}, {"text": "He held the money only materially, not juridically", "is_correct": true, "rationale": "An employee who receives money for the employer holds it only materially; taking it with grave abuse of confidence is qualified theft."}]'::jsonb, 3, 'hard', 'Estafa by misappropriation requires juridical possession, as by an agent or trustee.', 'Revised Penal Code, Arts. 308, 310 and 315', 'Study module Crime Detection and Investigation, Chapter 3: Specialized Crime Investigation 2 with Interview and Interrogation (CDI-3.2).', 'generated', 'tos_2024', 1, FALSE, 'CDI-3.2', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-4.1_01', 'crime_detection', 'Traffic Management and Accident Investigation with Driving', 'Which pillar of traffic management covers the design of roads and traffic control devices?', '[{"text": "Traffic education", "is_correct": false, "rationale": "Education teaches road users safe behavior."}, {"text": "Traffic engineering", "is_correct": true, "rationale": "Engineering deals with road design, signs, signals and markings."}, {"text": "Traffic enforcement", "is_correct": false, "rationale": "Enforcement applies traffic laws through apprehension."}, {"text": "Traffic economy", "is_correct": false, "rationale": "Economy concerns the costs and benefits of the traffic system."}]'::jsonb, 1, 'easy', 'The five pillars are engineering, education, enforcement, environment and economy.', NULL, 'Study module Crime Detection and Investigation, Chapter 4: Traffic Management and Accident Investigation with Driving (CDI-4.1).', 'generated', 'tos_2024', 1, FALSE, 'CDI-4.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-4.1_02', 'crime_detection', 'Traffic Management and Accident Investigation with Driving', 'Why does the LTFRB, rather than the LTO, grant franchises to jeepneys and buses?', '[{"text": "The LTFRB registers all private cars and issues driver''s licenses", "is_correct": false, "rationale": "Registration and licensing belong to the LTO."}, {"text": "The LTFRB regulates public land transport services and their routes", "is_correct": true, "rationale": "The LTFRB issues franchises and regulates fares and routes of public utility vehicles."}, {"text": "The LTFRB designs and builds national highways", "is_correct": false, "rationale": "Road design and construction belong to the DPWH."}, {"text": "The LTFRB arrests drivers who violate traffic laws", "is_correct": false, "rationale": "Enforcement belongs to the PNP, MMDA and deputized officers."}]'::jsonb, 1, 'easy', 'Several agencies share traffic responsibilities, which calls for coordination.', 'E.O. 202 (1987); R.A. 4136', 'Study module Crime Detection and Investigation, Chapter 4: Traffic Management and Accident Investigation with Driving (CDI-4.1).', 'generated', 'tos_2024', 1, FALSE, 'CDI-4.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-4.1_03', 'crime_detection', 'Traffic Management and Accident Investigation with Driving', 'An intersection has many accidents because drivers cannot see the cross traffic. Which response is most effective?', '[{"text": "Posting more traffic enforcers there to issue tickets to drivers", "is_correct": false, "rationale": "Tickets do not remove the visibility problem."}, {"text": "An engineering fix, such as clearing the view or adding signals", "is_correct": true, "rationale": "The cause is a physical hazard, so changing the road environment addresses it directly."}, {"text": "A slogan contest on road safety in schools", "is_correct": false, "rationale": "Education helps but does not fix the hazard at that site."}, {"text": "Raising the fines for all traffic violations", "is_correct": false, "rationale": "Higher fines do not improve visibility."}]'::jsonb, 1, 'hard', 'Matching the pillar to the cause makes traffic management effective.', NULL, 'Study module Crime Detection and Investigation, Chapter 4: Traffic Management and Accident Investigation with Driving (CDI-4.1).', 'generated', 'tos_2024', 1, FALSE, 'CDI-4.1', 'Evaluating') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-4.2_01', 'crime_detection', 'Traffic Management and Accident Investigation with Driving', 'Which type of traffic sign warns drivers of a hazard ahead, such as a sharp curve?', '[{"text": "Regulatory sign", "is_correct": false, "rationale": "Regulatory signs state rules that must be obeyed, such as stop or no parking."}, {"text": "Guide sign", "is_correct": false, "rationale": "Guide signs show routes, directions and distances."}, {"text": "Warning sign", "is_correct": true, "rationale": "Warning signs alert drivers to hazards or changes in road conditions ahead."}, {"text": "Informative sign", "is_correct": false, "rationale": "Informative signs give information about services and places."}]'::jsonb, 2, 'easy', 'Each category of sign has its own shape and color to be recognized quickly.', NULL, 'Study module Crime Detection and Investigation, Chapter 4: Traffic Management and Accident Investigation with Driving (CDI-4.2).', 'generated', 'tos_2024', 1, FALSE, 'CDI-4.2', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-4.2_02', 'crime_detection', 'Traffic Management and Accident Investigation with Driving', 'What does a broken white line between two lanes going the same way mean?', '[{"text": "Drivers may never cross it for any reason", "is_correct": false, "rationale": "Solid lines discourage or prohibit crossing."}, {"text": "It marks the edge of the road", "is_correct": false, "rationale": "Edge lines are usually solid lines at the side of the road."}, {"text": "Lanes may be changed across it when safe", "is_correct": true, "rationale": "Broken lines allow crossing when it is safe."}, {"text": "It marks a pedestrian crossing", "is_correct": false, "rationale": "Pedestrian crossings are marked with wide stripes."}]'::jsonb, 2, 'easy', 'Road markings guide and regulate traffic together with signs and signals.', NULL, 'Study module Crime Detection and Investigation, Chapter 4: Traffic Management and Accident Investigation with Driving (CDI-4.2).', 'generated', 'tos_2024', 1, FALSE, 'CDI-4.2', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-4.2_03', 'crime_detection', 'Traffic Management and Accident Investigation with Driving', 'A driver is very close to the stop line when the light turns yellow, and stopping suddenly would be unsafe. What is the best action?', '[{"text": "Proceed through with caution, since he cannot stop safely", "is_correct": true, "rationale": "Yellow warns that the light is about to turn red; a driver who cannot stop safely may proceed with caution."}, {"text": "Brake hard at once, whatever the cars behind him", "is_correct": false, "rationale": "Sudden hard braking may cause a rear-end collision."}, {"text": "Speed up to beat the red light at any cost", "is_correct": false, "rationale": "Speeding up to beat the light is dangerous."}, {"text": "Stop in the middle of the intersection", "is_correct": false, "rationale": "Stopping in the intersection blocks cross traffic."}]'::jsonb, 0, 'hard', 'Drivers approaching at a safe speed can usually stop when the light turns yellow.', NULL, 'Study module Crime Detection and Investigation, Chapter 4: Traffic Management and Accident Investigation with Driving (CDI-4.2).', 'generated', 'tos_2024', 1, FALSE, 'CDI-4.2', 'Evaluating') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-4.3_01', 'crime_detection', 'Traffic Management and Accident Investigation with Driving', 'Two cars reach an intersection without signals at about the same time. Under R.A. 4136, which car must yield?', '[{"text": "The car on the left yields to the car on the right", "is_correct": true, "rationale": "R.A. 4136 provides that the vehicle on the left shall yield the right of way to the vehicle on the right."}, {"text": "The car on the right yields to the car on the left", "is_correct": false, "rationale": "This reverses the rule."}, {"text": "The smaller car yields to the bigger one", "is_correct": false, "rationale": "Size does not decide the right of way."}, {"text": "The slower car yields to the faster one", "is_correct": false, "rationale": "Speed does not decide the right of way."}]'::jsonb, 0, 'medium', 'Drivers on a through highway and emergency vehicles have special rules.', 'R.A. 4136, Sec. 42', 'Study module Crime Detection and Investigation, Chapter 4: Traffic Management and Accident Investigation with Driving (CDI-4.3).', 'generated', 'tos_2024', 1, FALSE, 'CDI-4.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-4.3_02', 'crime_detection', 'Traffic Management and Accident Investigation with Driving', 'Where is a driver prohibited from parking under R.A. 4136?', '[{"text": "On a pedestrian crosswalk", "is_correct": true, "rationale": "R.A. 4136 prohibits parking on a crosswalk, within an intersection, and in other listed places."}, {"text": "On a marked parking slot", "is_correct": false, "rationale": "Marked parking slots are meant for parking."}, {"text": "In a private parking building", "is_correct": false, "rationale": "Private parking buildings are designed for parking."}, {"text": "On a road shoulder where signs allow", "is_correct": false, "rationale": "Parking where signs allow is lawful."}]'::jsonb, 0, 'medium', 'Other prohibited places include within six meters of an intersection and in front of a private driveway.', 'R.A. 4136, Sec. 47', 'Study module Crime Detection and Investigation, Chapter 4: Traffic Management and Accident Investigation with Driving (CDI-4.3).', 'generated', 'tos_2024', 1, FALSE, 'CDI-4.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-4.4_01', 'crime_detection', 'Traffic Management and Accident Investigation with Driving', 'A driver stopped at a red light reads and types a text message on his hand-held phone. Is this a violation of R.A. 10913?', '[{"text": "Yes, the law also covers stops at a traffic light", "is_correct": true, "rationale": "R.A. 10913 covers using a hand-held device while in motion or temporarily stopped at a traffic light or intersection."}, {"text": "No, because the vehicle was not moving", "is_correct": false, "rationale": "Being stopped at a light is expressly covered."}, {"text": "No, because texting is allowed at intersections", "is_correct": false, "rationale": "Intersections are expressly covered."}, {"text": "Yes, but only if the driver hits someone", "is_correct": false, "rationale": "The violation is the act itself, without any accident."}]'::jsonb, 0, 'medium', 'Hands-free use is allowed if the device does not block the driver''s view.', 'R.A. 10913 (Anti-Distracted Driving Act), Sec. 4', 'Study module Crime Detection and Investigation, Chapter 4: Traffic Management and Accident Investigation with Driving (CDI-4.4).', 'generated', 'tos_2024', 1, FALSE, 'CDI-4.4', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-4.4_02', 'crime_detection', 'Traffic Management and Accident Investigation with Driving', 'A father rides a motorcycle on a busy highway with his small child, whose feet cannot reach the foot pegs. Which law did he violate?', '[{"text": "R.A. 10586, the Anti-Drunk and Drugged Driving Act", "is_correct": false, "rationale": "R.A. 10586 concerns driving under the influence."}, {"text": "R.A. 10913, the Anti-Distracted Driving Act", "is_correct": false, "rationale": "R.A. 10913 concerns distracted driving."}, {"text": "R.A. 4136, the rules on parking", "is_correct": false, "rationale": "Parking rules do not apply to this situation."}, {"text": "R.A. 10666, the Children''s Safety on Motorcycles Act", "is_correct": true, "rationale": "R.A. 10666 bars a child from riding on public roads with heavy traffic unless the child can reach the foot pegs, wrap his arms around the driver, and wears a standard helmet."}]'::jsonb, 3, 'medium', 'There is an exception for medical emergencies.', 'R.A. 10666, Sec. 4', 'Study module Crime Detection and Investigation, Chapter 4: Traffic Management and Accident Investigation with Driving (CDI-4.4).', 'generated', 'tos_2024', 1, FALSE, 'CDI-4.4', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-4.4_03', 'crime_detection', 'Traffic Management and Accident Investigation with Driving', 'An officer flags down a driver who was weaving between lanes and smells of liquor. What procedure should he follow?', '[{"text": "Arrest him at once and take a blood sample by force", "is_correct": false, "rationale": "The law sets the testing steps; force is not the procedure."}, {"text": "Let him go with a warning because no one was hurt", "is_correct": false, "rationale": "Driving under the influence is a violation even without an accident."}, {"text": "Ask the driver whether he is drunk and accept his answer", "is_correct": false, "rationale": "The driver''s own answer is not a test."}, {"text": "Give field sobriety tests; if the driver fails, use a breath analyzer", "is_correct": true, "rationale": "R.A. 10586 provides for field sobriety tests when there is probable cause, followed by a breath analyzer test if the driver fails."}]'::jsonb, 3, 'medium', 'Drivers in accidents causing death or serious injury undergo mandatory alcohol and drug tests.', 'R.A. 10586 (Anti-Drunk and Drugged Driving Act of 2013), Secs. 6-7', 'Study module Crime Detection and Investigation, Chapter 4: Traffic Management and Accident Investigation with Driving (CDI-4.4).', 'generated', 'tos_2024', 1, FALSE, 'CDI-4.4', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-4.5_01', 'crime_detection', 'Traffic Management and Accident Investigation with Driving', 'In traffic accident investigation, what is the point of no escape?', '[{"text": "The point where the vehicle comes to rest after the crash", "is_correct": false, "rationale": "The final position is where the vehicle stops after the crash."}, {"text": "The point where the driver first sees the hazard", "is_correct": false, "rationale": "The point of perception is when the driver first sees the hazard."}, {"text": "The point where the police first arrive at the scene", "is_correct": false, "rationale": "Police arrival is not part of the chain of key events."}, {"text": "The point after which the accident can no longer be avoided", "is_correct": true, "rationale": "The point of no escape is the place and time after which nothing the driver does can prevent the accident."}]'::jsonb, 3, 'easy', 'Key events include perception, start of evasive action, point of no escape, maximum engagement and final position.', NULL, 'Study module Crime Detection and Investigation, Chapter 4: Traffic Management and Accident Investigation with Driving (CDI-4.5).', 'generated', 'tos_2024', 1, FALSE, 'CDI-4.5', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-4.5_02', 'crime_detection', 'Traffic Management and Accident Investigation with Driving', 'A collision injured two persons but killed no one. How is it classified?', '[{"text": "Fatal accident", "is_correct": false, "rationale": "A fatal accident involves at least one death."}, {"text": "Non-fatal injury accident", "is_correct": true, "rationale": "An accident with injuries but no deaths is a non-fatal injury accident."}, {"text": "Property damage only", "is_correct": false, "rationale": "Property damage only means no injuries or deaths."}, {"text": "Non-motor vehicle accident", "is_correct": false, "rationale": "This was a motor vehicle collision."}]'::jsonb, 1, 'easy', 'Accident classification affects reporting and investigation priorities.', NULL, 'Study module Crime Detection and Investigation, Chapter 4: Traffic Management and Accident Investigation with Driving (CDI-4.5).', 'generated', 'tos_2024', 1, FALSE, 'CDI-4.5', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-4.5_03', 'crime_detection', 'Traffic Management and Accident Investigation with Driving', 'A pedestrian crossed carelessly, but the driver saw him in time and could have stopped, yet did not. Who is liable under the last clear chance doctrine?', '[{"text": "The pedestrian, because he was careless first", "is_correct": false, "rationale": "The pedestrian''s earlier carelessness does not excuse the driver''s later failure."}, {"text": "Neither, because both were negligent", "is_correct": false, "rationale": "The doctrine decides liability when both were negligent."}, {"text": "The owner of the road, for poor lighting", "is_correct": false, "rationale": "Nothing shows the road''s condition caused the accident."}, {"text": "The driver, who had the last chance to avoid the accident", "is_correct": true, "rationale": "Under the last clear chance doctrine, the party who had the last fair opportunity to avoid the harm and failed is liable."}]'::jsonb, 3, 'medium', 'The doctrine is applied in Philippine jurisprudence on vehicular accidents.', NULL, 'Study module Crime Detection and Investigation, Chapter 4: Traffic Management and Accident Investigation with Driving (CDI-4.5).', 'generated', 'tos_2024', 1, FALSE, 'CDI-4.5', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-4.5_04', 'crime_detection', 'Traffic Management and Accident Investigation with Driving', 'Curved, striated tire marks show that a car slid sideways while turning at high speed. What are these marks called?', '[{"text": "Skid marks", "is_correct": false, "rationale": "Skid marks are usually straight, made by locked wheels during braking."}, {"text": "Scuff marks from a flat tire", "is_correct": false, "rationale": "Flat-tire marks are made by an underinflated tire, not by sliding sideways."}, {"text": "Yaw marks", "is_correct": true, "rationale": "Yaw marks are curved marks left by tires sliding sideways while still rotating, as in a sharp turn at speed."}, {"text": "Gouge marks", "is_correct": false, "rationale": "Gouges are made by metal parts digging into the road."}]'::jsonb, 2, 'medium', 'Yaw marks can be used to estimate the speed of the vehicle.', NULL, 'Study module Crime Detection and Investigation, Chapter 4: Traffic Management and Accident Investigation with Driving (CDI-4.5).', 'generated', 'tos_2024', 1, FALSE, 'CDI-4.5', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-5.1_01', 'crime_detection', 'Fire Protection and Arson Investigation', 'What does the fire tetrahedron add to the fire triangle?', '[{"text": "A source of ignition such as a spark", "is_correct": false, "rationale": "Heat is already one side of the triangle."}, {"text": "A supply of oxygen from the air", "is_correct": false, "rationale": "Oxygen is already one side of the triangle."}, {"text": "An uninhibited chemical chain reaction", "is_correct": true, "rationale": "The tetrahedron adds the chain reaction that keeps the fire burning; breaking it extinguishes the fire."}, {"text": "A fuel such as wood or gasoline", "is_correct": false, "rationale": "Fuel is already one side of the triangle."}]'::jsonb, 2, 'easy', 'Some extinguishing agents, like dry chemicals, work by interrupting the chain reaction.', NULL, 'Study module Crime Detection and Investigation, Chapter 5: Fire Protection and Arson Investigation (CDI-5.1).', 'generated', 'tos_2024', 1, FALSE, 'CDI-5.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-5.1_02', 'crime_detection', 'Fire Protection and Arson Investigation', 'Why is carbon monoxide the deadliest product of combustion for people in a burning building?', '[{"text": "It is the hottest gas produced by the fire", "is_correct": false, "rationale": "Its danger is chemical, not its temperature."}, {"text": "It produces a strong smell that causes panic", "is_correct": false, "rationale": "CO is colorless and odorless."}, {"text": "It is heavier than the smoke and stays on the floor", "is_correct": false, "rationale": "CO''s density is close to air; its danger is its effect on blood."}, {"text": "It binds with hemoglobin more readily than oxygen does", "is_correct": true, "rationale": "CO combines with hemoglobin far more readily than oxygen, starving the body of oxygen."}]'::jsonb, 3, 'easy', 'Many fire deaths are caused by smoke inhalation rather than burns.', NULL, 'Study module Crime Detection and Investigation, Chapter 5: Fire Protection and Arson Investigation (CDI-5.1).', 'generated', 'tos_2024', 1, FALSE, 'CDI-5.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-5.1_03', 'crime_detection', 'Fire Protection and Arson Investigation', 'A burning house sets fire to another house across the street, though nothing touched it. How was the heat transferred?', '[{"text": "Radiation", "is_correct": true, "rationale": "Radiation transfers heat through electromagnetic waves across space without contact."}, {"text": "Conduction", "is_correct": false, "rationale": "Conduction needs direct contact through a material."}, {"text": "Convection", "is_correct": false, "rationale": "Convection moves heat through moving gases or liquids, mainly upward."}, {"text": "Direct flame contact", "is_correct": false, "rationale": "The houses did not touch, so there was no flame contact."}]'::jsonb, 0, 'medium', 'Firefighters protect exposures by cooling them with water.', NULL, 'Study module Crime Detection and Investigation, Chapter 5: Fire Protection and Arson Investigation (CDI-5.1).', 'generated', 'tos_2024', 1, FALSE, 'CDI-5.1', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-5.1_04', 'crime_detection', 'Fire Protection and Arson Investigation', 'In a burning room, all the combustible contents suddenly ignite at almost the same time. What stage has been reached?', '[{"text": "Incipient stage", "is_correct": false, "rationale": "The incipient stage is the early stage of a small fire."}, {"text": "Flashover", "is_correct": true, "rationale": "Flashover is the sudden, near-simultaneous ignition of a room''s contents, marking the change to a fully developed fire."}, {"text": "Decay stage", "is_correct": false, "rationale": "The decay stage is when the fire dies down."}, {"text": "Smoldering ignition", "is_correct": false, "rationale": "Smoldering is slow combustion without flame."}]'::jsonb, 1, 'medium', 'Flashover is extremely dangerous to occupants and firefighters.', NULL, 'Study module Crime Detection and Investigation, Chapter 5: Fire Protection and Arson Investigation (CDI-5.1).', 'generated', 'tos_2024', 1, FALSE, 'CDI-5.1', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-5.2_01', 'crime_detection', 'Fire Protection and Arson Investigation', 'Why should water not be used on a fire involving live electrical equipment?', '[{"text": "Water conducts electricity and can electrocute the firefighter", "is_correct": true, "rationale": "Energized electrical fires (Class C) need non-conductive agents such as CO2 or dry chemical."}, {"text": "Water makes electrical fires spread to metals", "is_correct": false, "rationale": "Water does not cause electrical fires to spread to metals."}, {"text": "Water reacts with plastic to form explosives", "is_correct": false, "rationale": "Water does not form explosives with plastic."}, {"text": "Water evaporates before it reaches the fire", "is_correct": false, "rationale": "Water reaches the fire; the danger is electric shock."}]'::jsonb, 0, 'easy', 'Once the power is cut, the fire may be fought according to the burning material.', NULL, 'Study module Crime Detection and Investigation, Chapter 5: Fire Protection and Arson Investigation (CDI-5.2).', 'generated', 'tos_2024', 1, FALSE, 'CDI-5.2', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-5.2_02', 'crime_detection', 'Fire Protection and Arson Investigation', 'A deep fryer of cooking oil catches fire in a restaurant kitchen. Which class of fire is it and what should be used?', '[{"text": "Class A; a water extinguisher", "is_correct": false, "rationale": "Water on burning oil causes violent splattering."}, {"text": "Class K; a wet chemical extinguisher", "is_correct": true, "rationale": "Fires in cooking oils and fats are Class K, best fought with wet chemical agents that cool and seal the oil."}, {"text": "Class C; a carbon dioxide extinguisher", "is_correct": false, "rationale": "Class C is for energized electrical fires."}, {"text": "Class D; a dry powder agent", "is_correct": false, "rationale": "Class D is for combustible metals."}]'::jsonb, 1, 'medium', 'Many commercial kitchens have built-in wet chemical suppression systems.', NULL, 'Study module Crime Detection and Investigation, Chapter 5: Fire Protection and Arson Investigation (CDI-5.2).', 'generated', 'tos_2024', 1, FALSE, 'CDI-5.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-5.2_03', 'crime_detection', 'Fire Protection and Arson Investigation', 'Magnesium shavings catch fire in a machine shop. Which class of fire is it and what agent should be used?', '[{"text": "Class D; a dry powder agent", "is_correct": true, "rationale": "Burning combustible metals are Class D fires, fought with special dry powders."}, {"text": "Class B; foam", "is_correct": false, "rationale": "Foam is for flammable liquids."}, {"text": "Class A; water", "is_correct": false, "rationale": "Water can react violently with burning metals."}, {"text": "Class K; a wet chemical", "is_correct": false, "rationale": "Wet chemical agents are for cooking oils."}]'::jsonb, 0, 'medium', 'Class D agents smother the fire and absorb heat.', NULL, 'Study module Crime Detection and Investigation, Chapter 5: Fire Protection and Arson Investigation (CDI-5.2).', 'generated', 'tos_2024', 1, FALSE, 'CDI-5.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-5.3_01', 'crime_detection', 'Fire Protection and Arson Investigation', 'A building uses fire-rated walls and self-closing fire doors to keep a fire in one area. What kind of fire protection is this?', '[{"text": "Active fire protection", "is_correct": false, "rationale": "Active protection needs action, such as sprinklers or alarms."}, {"text": "Manual fire suppression", "is_correct": false, "rationale": "Manual suppression is firefighting by people."}, {"text": "Passive fire protection", "is_correct": true, "rationale": "Passive protection uses building features that contain fire and smoke without needing activation."}, {"text": "Automatic fire detection", "is_correct": false, "rationale": "Detection systems sense fire; they do not contain it."}]'::jsonb, 2, 'medium', 'Compartmentation slows fire spread and protects escape routes.', 'R.A. 9514 (Fire Code of the Philippines) and its IRR', 'Study module Crime Detection and Investigation, Chapter 5: Fire Protection and Arson Investigation (CDI-5.3).', 'generated', 'tos_2024', 1, FALSE, 'CDI-5.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-5.3_02', 'crime_detection', 'Fire Protection and Arson Investigation', 'Smoke from cooking keeps setting off the smoke detector in a canteen kitchen. Which detector is more suitable there?', '[{"text": "Ionization smoke detector", "is_correct": false, "rationale": "Ionization detectors respond strongly to fine smoke particles."}, {"text": "Photoelectric smoke detector", "is_correct": false, "rationale": "Photoelectric detectors still respond to smoke."}, {"text": "Beam smoke detector", "is_correct": false, "rationale": "Beam detectors also sense smoke."}, {"text": "Heat detector", "is_correct": true, "rationale": "Heat detectors respond to temperature, so cooking smoke does not set them off."}]'::jsonb, 3, 'medium', 'The detector should fit the normal conditions of the area.', NULL, 'Study module Crime Detection and Investigation, Chapter 5: Fire Protection and Arson Investigation (CDI-5.3).', 'generated', 'tos_2024', 1, FALSE, 'CDI-5.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-5.4_01', 'crime_detection', 'Fire Protection and Arson Investigation', 'A man set fire to his own house, which stood close to his neighbors'' houses, exposing them to danger. Is he liable for arson?', '[{"text": "No, because a person may do as he wishes with his own property", "is_correct": false, "rationale": "Ownership does not allow endangering others."}, {"text": "No, unless one of the neighbors'' houses actually burned", "is_correct": false, "rationale": "The crime is complete when the danger is created."}, {"text": "Yes, burning one''s own property is arson if it endangers others", "is_correct": true, "rationale": "P.D. 1613 punishes burning one''s own property under circumstances that expose another to danger."}, {"text": "Yes, but only for malicious mischief", "is_correct": false, "rationale": "The act is arson under the special law, not malicious mischief."}]'::jsonb, 2, 'medium', 'If he burned it to collect insurance, that is a special aggravating circumstance.', 'P.D. 1613 (New Arson Law), Secs. 1 and 4', 'Study module Crime Detection and Investigation, Chapter 5: Fire Protection and Arson Investigation (CDI-5.4).', 'generated', 'tos_2024', 1, FALSE, 'CDI-5.4', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-5.4_02', 'crime_detection', 'Fire Protection and Arson Investigation', 'A store fire started at several points at the same time, and cans of gasoline were found inside. What do these facts establish under P.D. 1613?', '[{"text": "Conclusive proof that the owner is guilty", "is_correct": false, "rationale": "Prima facie evidence may be rebutted; it is not conclusive."}, {"text": "Prima facie evidence of arson", "is_correct": true, "rationale": "Section 6 of P.D. 1613 lists multiple points of origin and the presence of flammable substances not normally found there as prima facie evidence of arson."}, {"text": "Proof that the fire was accidental", "is_correct": false, "rationale": "These facts point away from an accident."}, {"text": "Nothing, unless the owner confesses", "is_correct": false, "rationale": "Prima facie evidence stands without a confession."}]'::jsonb, 1, 'hard', 'The investigator must still identify the person responsible.', 'P.D. 1613, Sec. 6', 'Study module Crime Detection and Investigation, Chapter 5: Fire Protection and Arson Investigation (CDI-5.4).', 'generated', 'tos_2024', 1, FALSE, 'CDI-5.4', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-5.4_03', 'crime_detection', 'Fire Protection and Arson Investigation', 'A man set fire to a house to kill the person inside, and the person died. What crime was committed?', '[{"text": "Arson only, because the house was burned", "is_correct": false, "rationale": "When the main objective is to burn and death results, the crime is arson; here the aim was to kill."}, {"text": "Murder, because fire was the means to kill", "is_correct": true, "rationale": "When the main objective is to kill and fire is the means, the crime is murder qualified by the use of fire."}, {"text": "Arson with homicide, a special complex crime", "is_correct": false, "rationale": "Jurisprudence does not treat this as a special complex crime of arson with homicide."}, {"text": "Homicide, because fire is not a qualifying circumstance", "is_correct": false, "rationale": "Fire is a qualifying circumstance of murder under Article 248."}]'::jsonb, 1, 'hard', 'The offender''s main objective decides between arson and murder (People v. Malngan).', 'Revised Penal Code, Art. 248; People v. Malngan, G.R. No. 170470 (2006)', 'Study module Crime Detection and Investigation, Chapter 5: Fire Protection and Arson Investigation (CDI-5.4).', 'generated', 'tos_2024', 1, FALSE, 'CDI-5.4', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-5.5_01', 'crime_detection', 'Fire Protection and Arson Investigation', 'A V-shaped burn pattern appears on a wall at a fire scene. What does its lowest point usually indicate?', '[{"text": "The area where the fire probably started", "is_correct": true, "rationale": "Fire rises and spreads outward, so the bottom of the V often points toward the origin."}, {"text": "The point where the fire was finally put out", "is_correct": false, "rationale": "Extinguishment does not create V patterns."}, {"text": "The place where the fire was coolest", "is_correct": false, "rationale": "The base of the V is often where the fire burned longest."}, {"text": "The spot where firefighters entered", "is_correct": false, "rationale": "Entry points do not make V patterns."}]'::jsonb, 0, 'medium', 'Patterns must be read together with other evidence, since ventilation can alter them.', NULL, 'Study module Crime Detection and Investigation, Chapter 5: Fire Protection and Arson Investigation (CDI-5.5).', 'generated', 'tos_2024', 1, FALSE, 'CDI-5.5', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-5.5_02', 'crime_detection', 'Fire Protection and Arson Investigation', 'An investigator sees an irregular burn on a floor shaped like spilled liquid. What should he do?', '[{"text": "Conclude at once that gasoline was used", "is_correct": false, "rationale": "A pattern alone is not proof of an accelerant."}, {"text": "Wash the floor to see the pattern better", "is_correct": false, "rationale": "Washing destroys the evidence."}, {"text": "Collect debris in an airtight metal can for laboratory analysis", "is_correct": true, "rationale": "Such patterns may suggest a flammable liquid, but only laboratory analysis of sealed samples can confirm it."}, {"text": "Ignore it, because floors always burn this way", "is_correct": false, "rationale": "The pattern is worth investigating, not ignoring."}]'::jsonb, 2, 'medium', 'Airtight containers keep volatile residues from evaporating.', NULL, 'Study module Crime Detection and Investigation, Chapter 5: Fire Protection and Arson Investigation (CDI-5.5).', 'generated', 'tos_2024', 1, FALSE, 'CDI-5.5', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-5.5_03', 'crime_detection', 'Fire Protection and Arson Investigation', 'Why is the area of deepest and lowest charring often taken as a sign of the fire''s origin?', '[{"text": "Fire always starts at the ceiling and burns downward", "is_correct": false, "rationale": "Fire usually spreads upward and outward."}, {"text": "The fire usually burned longest where it started", "is_correct": true, "rationale": "The origin has often been exposed to fire the longest, so damage there tends to be deepest and lowest."}, {"text": "Charring is deepest where water was sprayed", "is_correct": false, "rationale": "Water reduces charring rather than deepening it."}, {"text": "The deepest char always marks where the accelerant was poured", "is_correct": false, "rationale": "Deep char does not by itself prove an accelerant."}]'::jsonb, 1, 'hard', 'Ventilation and fuel load can create misleading patterns, so investigators test their hypotheses.', NULL, 'Study module Crime Detection and Investigation, Chapter 5: Fire Protection and Arson Investigation (CDI-5.5).', 'generated', 'tos_2024', 1, FALSE, 'CDI-5.5', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-6.1_01', 'crime_detection', 'Vice and Drug Education and Control', 'Why is alcoholism regarded as a disease and not merely a bad habit?', '[{"text": "It affects only persons who drink once a year", "is_correct": false, "rationale": "Occasional drinking is not alcoholism."}, {"text": "It can be cured simply by willpower in one day", "is_correct": false, "rationale": "Recovery usually requires treatment and support over time."}, {"text": "It involves loss of control, physical dependence and withdrawal", "is_correct": true, "rationale": "Alcoholism is marked by compulsive drinking, loss of control, tolerance and withdrawal symptoms."}, {"text": "It has no effect on the drinker''s health or family", "is_correct": false, "rationale": "Alcoholism harms health, work and family life."}]'::jsonb, 2, 'easy', 'Treatment and rehabilitation are part of the response to alcoholism.', NULL, 'Study module Crime Detection and Investigation, Chapter 6: Vice and Drug Education and Control (CDI-6.1).', 'generated', 'tos_2024', 1, FALSE, 'CDI-6.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-6.1_02', 'crime_detection', 'Vice and Drug Education and Control', 'A man collects bets for a jueteng operator in his barangay. Which law punishes him?', '[{"text": "R.A. 9165, the Comprehensive Dangerous Drugs Act", "is_correct": false, "rationale": "R.A. 9165 concerns dangerous drugs."}, {"text": "R.A. 10586, the Anti-Drunk Driving Act", "is_correct": false, "rationale": "R.A. 10586 concerns driving under the influence."}, {"text": "R.A. 9287, which raised penalties for illegal numbers games", "is_correct": true, "rationale": "R.A. 9287 amended P.D. 1602 and punishes collectors, agents and others in illegal numbers games such as jueteng."}, {"text": "R.A. 11313, the Safe Spaces Act", "is_correct": false, "rationale": "R.A. 11313 concerns gender-based sexual harassment."}]'::jsonb, 2, 'medium', 'Penalties are higher for financiers, maintainers and protectors, including public officials.', 'R.A. 9287, amending P.D. 1602', 'Study module Crime Detection and Investigation, Chapter 6: Vice and Drug Education and Control (CDI-6.1).', 'generated', 'tos_2024', 1, FALSE, 'CDI-6.1', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-6.1_03', 'crime_detection', 'Vice and Drug Education and Control', 'Police rescue women whom a pimp forced into prostitution while keeping their earnings. How should the women be treated?', '[{"text": "As offenders to be charged for prostitution", "is_correct": false, "rationale": "Trafficked persons are not penalized for acts done as a result of being trafficked."}, {"text": "As witnesses only, then released without assistance", "is_correct": false, "rationale": "Victims are entitled to support, not just release."}, {"text": "As victims of trafficking entitled to protection and services", "is_correct": true, "rationale": "The anti-trafficking law treats trafficked persons as victims, not offenders, and provides them with protection and services."}, {"text": "As accomplices of the pimp", "is_correct": false, "rationale": "Victims are not accomplices of their trafficker."}]'::jsonb, 2, 'medium', 'The pimp may be prosecuted for trafficking in persons.', 'R.A. 9208, as amended by R.A. 10364 and R.A. 11862', 'Study module Crime Detection and Investigation, Chapter 6: Vice and Drug Education and Control (CDI-6.1).', 'generated', 'tos_2024', 1, FALSE, 'CDI-6.1', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-6.2_01', 'crime_detection', 'Vice and Drug Education and Control', 'Why is shabu (methamphetamine hydrochloride) classified as a stimulant?', '[{"text": "It slows down breathing and causes deep sleep", "is_correct": false, "rationale": "Slowing breathing and causing sleep describe depressants such as opioids."}, {"text": "It causes users to see things that are not there only", "is_correct": false, "rationale": "Hallucinations can occur, but the main effect is stimulation."}, {"text": "It speeds up the central nervous system", "is_correct": true, "rationale": "Methamphetamine excites the central nervous system, causing wakefulness, energy and loss of appetite."}, {"text": "It has no effect on the nervous system", "is_correct": false, "rationale": "Shabu strongly affects the nervous system."}]'::jsonb, 2, 'easy', 'Shabu is the most commonly abused dangerous drug in the Philippines.', 'R.A. 9165', 'Study module Crime Detection and Investigation, Chapter 6: Vice and Drug Education and Control (CDI-6.2).', 'generated', 'tos_2024', 1, FALSE, 'CDI-6.2', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-6.2_02', 'crime_detection', 'Vice and Drug Education and Control', 'A suspect has not slept for days, talks very fast, has dilated pupils and has lost much weight. Which drug use do these signs suggest?', '[{"text": "Methamphetamine (shabu)", "is_correct": true, "rationale": "Sleeplessness, rapid speech, dilated pupils and weight loss are signs of stimulant use such as shabu."}, {"text": "Heroin (opioid)", "is_correct": false, "rationale": "Heroin causes drowsiness and pinpoint pupils."}, {"text": "Marijuana (cannabis)", "is_correct": false, "rationale": "Marijuana causes red eyes, increased appetite and relaxation."}, {"text": "Morphine (opiate)", "is_correct": false, "rationale": "Morphine causes drowsiness and constricted pupils."}]'::jsonb, 0, 'medium', 'Signs and symptoms help officers decide whether a drug test is warranted.', NULL, 'Study module Crime Detection and Investigation, Chapter 6: Vice and Drug Education and Control (CDI-6.2).', 'generated', 'tos_2024', 1, FALSE, 'CDI-6.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-6.2_03', 'crime_detection', 'Vice and Drug Education and Control', 'A person has pinpoint pupils, is very drowsy, and has needle marks on his arms. Which drug use do these signs suggest?', '[{"text": "Cocaine", "is_correct": false, "rationale": "Cocaine is a stimulant that dilates the pupils."}, {"text": "Heroin", "is_correct": true, "rationale": "Opioids such as heroin cause constricted pupils and drowsiness; injection leaves needle marks."}, {"text": "Shabu", "is_correct": false, "rationale": "Shabu is a stimulant that dilates the pupils."}, {"text": "Ecstasy", "is_correct": false, "rationale": "Ecstasy is a stimulant that dilates the pupils."}]'::jsonb, 1, 'medium', 'Opioid overdose can stop breathing and is treated with naloxone.', NULL, 'Study module Crime Detection and Investigation, Chapter 6: Vice and Drug Education and Control (CDI-6.2).', 'generated', 'tos_2024', 1, FALSE, 'CDI-6.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-6.2_04', 'crime_detection', 'Vice and Drug Education and Control', 'A student has red eyes, a big appetite, a distorted sense of time, and a smell of burnt leaves on his clothes. Which drug use do these signs suggest?', '[{"text": "Heroin", "is_correct": false, "rationale": "Heroin causes drowsiness and pinpoint pupils."}, {"text": "Cocaine", "is_correct": false, "rationale": "Cocaine causes excitement and dilated pupils."}, {"text": "Inhalants", "is_correct": false, "rationale": "Inhalants leave a chemical smell, such as solvent or glue."}, {"text": "Marijuana", "is_correct": true, "rationale": "Red eyes, increased appetite, altered time perception and the smell of burnt plant matter are signs of marijuana use."}]'::jsonb, 3, 'medium', 'Marijuana and marijuana resin are dangerous drugs under R.A. 9165.', NULL, 'Study module Crime Detection and Investigation, Chapter 6: Vice and Drug Education and Control (CDI-6.2).', 'generated', 'tos_2024', 1, FALSE, 'CDI-6.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-6.2_05', 'crime_detection', 'Vice and Drug Education and Control', 'A teenager inhales the vapors of a contact cement from a plastic bag. How is this drug use classified?', '[{"text": "Narcotic injection into a vein", "is_correct": false, "rationale": "No injection is involved."}, {"text": "Stimulant ingestion", "is_correct": false, "rationale": "The method is inhalation, and solvents are mainly depressants."}, {"text": "Inhalant (volatile solvent) abuse", "is_correct": true, "rationale": "Sniffing glue or solvents from a bag is inhalant abuse."}, {"text": "Hallucinogen smoking", "is_correct": false, "rationale": "Smoking is not the method used here."}]'::jsonb, 2, 'medium', 'Inhalants can cause sudden death and brain damage.', 'R.A. 9165', 'Study module Crime Detection and Investigation, Chapter 6: Vice and Drug Education and Control (CDI-6.2).', 'generated', 'tos_2024', 1, FALSE, 'CDI-6.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-6.3_01', 'crime_detection', 'Vice and Drug Education and Control', 'What does the chain of custody of seized drugs cover?', '[{"text": "Only the transfer from the arresting officer to the prosecutor", "is_correct": false, "rationale": "The chain covers more than one transfer."}, {"text": "Every recorded movement of the drugs from seizure to court and destruction", "is_correct": true, "rationale": "Chain of custody covers the duly recorded custody of the drugs from seizure, to the laboratory, to safekeeping, to court presentation and destruction."}, {"text": "Only the time the drugs spend inside the laboratory", "is_correct": false, "rationale": "The laboratory is only one link."}, {"text": "Only the moment of arrest of the accused", "is_correct": false, "rationale": "The arrest is only the start."}]'::jsonb, 1, 'easy', 'Each person who handled the item should be able to account for it.', 'Dangerous Drugs Board Regulation No. 1, s. 2002', 'Study module Crime Detection and Investigation, Chapter 6: Vice and Drug Education and Control (CDI-6.3).', 'generated', 'tos_2024', 1, FALSE, 'CDI-6.3', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-6.3_02', 'crime_detection', 'Vice and Drug Education and Control', 'Who should mark the seized sachets of drugs in a buy-bust operation, and when?', '[{"text": "The laboratory chemist, a week after receiving them", "is_correct": false, "rationale": "Marking must happen at the time of seizure, not later at the laboratory."}, {"text": "The prosecutor, when the case is filed in court", "is_correct": false, "rationale": "The prosecutor does not mark evidence."}, {"text": "Any bystander, at the police station", "is_correct": false, "rationale": "Only the officers handling the evidence mark it."}, {"text": "The seizing officer, immediately upon seizure, before the accused", "is_correct": true, "rationale": "Marking by the apprehending officer right after seizure, in the presence of the accused, starts the chain of custody."}]'::jsonb, 3, 'medium', 'Marking separates the seized items from other similar items.', 'R.A. 9165, Sec. 21, as amended by R.A. 10640', 'Study module Crime Detection and Investigation, Chapter 6: Vice and Drug Education and Control (CDI-6.3).', 'generated', 'tos_2024', 1, FALSE, 'CDI-6.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-6.3_03', 'crime_detection', 'Vice and Drug Education and Control', 'During the inventory of seized drugs, which persons must witness it under R.A. 9165 as amended?', '[{"text": "Only the arresting officers and the team leader", "is_correct": false, "rationale": "Officers alone do not satisfy the witness requirement."}, {"text": "Only the barangay tanods of the area", "is_correct": false, "rationale": "Tanods are not among the required witnesses."}, {"text": "The accused or counsel, an elected official, and the NPS or media", "is_correct": true, "rationale": "As amended by R.A. 10640, the inventory is done with the accused or his representative or counsel, an elected public official, and a representative of the National Prosecution Service or the media."}, {"text": "The accused''s relatives and his employer", "is_correct": false, "rationale": "Relatives and employers are not required witnesses."}]'::jsonb, 2, 'medium', 'The witnesses must sign the inventory and be given a copy.', 'R.A. 9165, Sec. 21(1), as amended by R.A. 10640', 'Study module Crime Detection and Investigation, Chapter 6: Vice and Drug Education and Control (CDI-6.3).', 'generated', 'tos_2024', 1, FALSE, 'CDI-6.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-6.3_04', 'crime_detection', 'Vice and Drug Education and Control', 'Within what period after seizure must the drugs be submitted to the PDEA forensic laboratory?', '[{"text": "48 hours", "is_correct": false, "rationale": "48 hours is longer than the law allows."}, {"text": "72 hours", "is_correct": false, "rationale": "72 hours is longer than the law allows."}, {"text": "7 days", "is_correct": false, "rationale": "Seven days is far longer than the law allows."}, {"text": "24 hours", "is_correct": true, "rationale": "Section 21(2) requires submission within 24 hours from seizure for qualitative and quantitative examination."}]'::jsonb, 3, 'medium', 'Prompt submission protects the integrity of the evidence.', 'R.A. 9165, Sec. 21(2)', 'Study module Crime Detection and Investigation, Chapter 6: Vice and Drug Education and Control (CDI-6.3).', 'generated', 'tos_2024', 1, FALSE, 'CDI-6.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-6.3_05', 'crime_detection', 'Vice and Drug Education and Control', 'No elected official witnessed the inventory because none could be found despite real efforts. What is the effect on the seizure?', '[{"text": "It is always void, whatever the reason", "is_correct": false, "rationale": "The law allows justified departures from the procedure."}, {"text": "It is valid even without any reason", "is_correct": false, "rationale": "The prosecution must prove the justifiable ground and the earnest efforts made."}, {"text": "It makes the drugs inadmissible but the arrest valid", "is_correct": false, "rationale": "Admissibility follows from whether the saving clause is satisfied."}, {"text": "It is not void if the reason is proven and integrity is kept", "is_correct": true, "rationale": "The saving clause excuses non-compliance on justifiable grounds, as long as the integrity and evidentiary value of the items were preserved."}]'::jsonb, 3, 'hard', 'The Supreme Court requires proof of earnest efforts to secure the witnesses (People v. Lim).', 'R.A. 9165, Sec. 21(1), as amended by R.A. 10640; People v. Lim, G.R. No. 231989 (2018)', 'Study module Crime Detection and Investigation, Chapter 6: Vice and Drug Education and Control (CDI-6.3).', 'generated', 'tos_2024', 1, FALSE, 'CDI-6.3', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-6.4_01', 'crime_detection', 'Vice and Drug Education and Control', 'In a buy-bust, the suspect handed a sachet of shabu to the poseur-buyer in exchange for marked money. What offense was committed?', '[{"text": "Illegal possession of dangerous drugs (Section 11)", "is_correct": false, "rationale": "Possession is a separate offense; the sale is proven by the transaction."}, {"text": "Illegal sale of dangerous drugs (Section 5)", "is_correct": true, "rationale": "Delivering the drug for payment completes the illegal sale."}, {"text": "Use of dangerous drugs (Section 15)", "is_correct": false, "rationale": "Use requires a positive drug test."}, {"text": "Maintenance of a drug den (Section 6)", "is_correct": false, "rationale": "A drug den is a place where drugs are used or sold."}]'::jsonb, 1, 'medium', 'The elements of sale are the identity of buyer and seller, the object, the consideration, and the delivery and payment.', 'R.A. 9165, Sec. 5', 'Study module Crime Detection and Investigation, Chapter 6: Vice and Drug Education and Control (CDI-6.4).', 'generated', 'tos_2024', 1, FALSE, 'CDI-6.4', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-6.4_02', 'crime_detection', 'Vice and Drug Education and Control', 'During a lawful search incident to arrest, police find sachets of shabu in the suspect''s pocket. No sale took place. What offense applies?', '[{"text": "Illegal sale of dangerous drugs (Section 5)", "is_correct": false, "rationale": "There was no sale."}, {"text": "Importation of dangerous drugs (Section 4)", "is_correct": false, "rationale": "There was no bringing of drugs into the country."}, {"text": "Illegal possession of dangerous drugs (Section 11)", "is_correct": true, "rationale": "Possession without authority of a dangerous drug, knowingly and freely, is illegal possession."}, {"text": "Possession of drug paraphernalia (Section 12)", "is_correct": false, "rationale": "Paraphernalia are instruments for using drugs, not the drugs themselves."}]'::jsonb, 2, 'medium', 'The penalty depends on the quantity of the drug.', 'R.A. 9165, Sec. 11', 'Study module Crime Detection and Investigation, Chapter 6: Vice and Drug Education and Control (CDI-6.4).', 'generated', 'tos_2024', 1, FALSE, 'CDI-6.4', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-7.1_01', 'crime_detection', 'Technical Writing 1 and 2 (Legal forms and Police Report writing)', 'What is the jurat of an affidavit?', '[{"text": "The first paragraph stating the affiant''s name and address", "is_correct": false, "rationale": "The opening paragraph is the preliminary or introductory statement."}, {"text": "The list of evidence attached to the affidavit", "is_correct": false, "rationale": "Attachments are annexes, not the jurat."}, {"text": "The signature of the investigator who typed it", "is_correct": false, "rationale": "The typist''s signature is not the jurat."}, {"text": "The certificate that the affiant personally swore to it before the officer", "is_correct": true, "rationale": "The jurat certifies that the affidavit was subscribed and sworn to before the administering officer."}]'::jsonb, 3, 'easy', 'An affidavit is a written statement of facts made under oath.', '2004 Rules on Notarial Practice', 'Study module Crime Detection and Investigation, Chapter 7: Technical Writing 1 and 2 (Legal forms and Police Report writing) (CDI-7.1).', 'generated', 'tos_2024', 1, FALSE, 'CDI-7.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-7.1_02', 'crime_detection', 'Technical Writing 1 and 2 (Legal forms and Police Report writing)', 'Why must police blotter entries be made promptly and never erased?', '[{"text": "Erasures make the blotter easier to read", "is_correct": false, "rationale": "Erasures reduce, not increase, reliability."}, {"text": "Entries can be changed freely before the case reaches court", "is_correct": false, "rationale": "Changes must be made by proper correction, not freely."}, {"text": "The blotter is a private notebook of the desk officer", "is_correct": false, "rationale": "The blotter is an official record, not a private notebook."}, {"text": "The blotter is an official record whose integrity must be protected", "is_correct": true, "rationale": "The blotter is the official daily record of incidents, and late entries or erasures cast doubt on it."}]'::jsonb, 3, 'easy', 'Corrections are made by a single line through the error, with the officer''s initials.', NULL, 'Study module Crime Detection and Investigation, Chapter 7: Technical Writing 1 and 2 (Legal forms and Police Report writing) (CDI-7.1).', 'generated', 'tos_2024', 1, FALSE, 'CDI-7.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-7.1_03', 'crime_detection', 'Technical Writing 1 and 2 (Legal forms and Police Report writing)', 'An investigator is drafting a witness''s sworn statement. In which part should the facts the witness personally saw be written?', '[{"text": "Body", "is_correct": true, "rationale": "The body states the facts known to the affiant, often in question-and-answer form."}, {"text": "Jurat", "is_correct": false, "rationale": "The jurat is the officer''s certification of the oath."}, {"text": "Title", "is_correct": false, "rationale": "The title identifies the document."}, {"text": "Signature block", "is_correct": false, "rationale": "The signature block holds the affiant''s signature."}]'::jsonb, 0, 'medium', 'The body should state facts, not opinions or hearsay.', NULL, 'Study module Crime Detection and Investigation, Chapter 7: Technical Writing 1 and 2 (Legal forms and Police Report writing) (CDI-7.1).', 'generated', 'tos_2024', 1, FALSE, 'CDI-7.1', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-7.1_04', 'crime_detection', 'Technical Writing 1 and 2 (Legal forms and Police Report writing)', 'A party wants the court to postpone a scheduled hearing. Which pleading or paper should be filed?', '[{"text": "Motion", "is_correct": true, "rationale": "A motion is an application for relief, such as postponement, other than by a pleading."}, {"text": "Manifestation", "is_correct": false, "rationale": "A manifestation informs the court of a fact without asking for relief."}, {"text": "Petition", "is_correct": false, "rationale": "A petition starts a special civil action or proceeding."}, {"text": "Affidavit", "is_correct": false, "rationale": "An affidavit is a sworn statement of facts."}]'::jsonb, 0, 'medium', 'A motion should state the relief sought and the grounds.', 'Rules of Court, Rule 15', 'Study module Crime Detection and Investigation, Chapter 7: Technical Writing 1 and 2 (Legal forms and Police Report writing) (CDI-7.1).', 'generated', 'tos_2024', 1, FALSE, 'CDI-7.1', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-7.2_01', 'crime_detection', 'Technical Writing 1 and 2 (Legal forms and Police Report writing)', 'A shooting occurred an hour ago, and the chief needs a first written account of it today. Which report should the investigator submit?', '[{"text": "Progress report", "is_correct": false, "rationale": "A progress report updates the case later."}, {"text": "Final report", "is_correct": false, "rationale": "A final report closes the investigation."}, {"text": "Spot report", "is_correct": true, "rationale": "A spot report is the immediate first report of an incident, usually within 24 hours."}, {"text": "After-operations report", "is_correct": false, "rationale": "An after-operations report covers a planned police operation."}]'::jsonb, 2, 'medium', 'Spot reports give the chain of command early information.', NULL, 'Study module Crime Detection and Investigation, Chapter 7: Technical Writing 1 and 2 (Legal forms and Police Report writing) (CDI-7.2).', 'generated', 'tos_2024', 1, FALSE, 'CDI-7.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-7.2_02', 'crime_detection', 'Technical Writing 1 and 2 (Legal forms and Police Report writing)', 'Two weeks after a robbery, the investigator reports newly identified witnesses and a recovered vehicle. Which report is this?', '[{"text": "Spot report", "is_correct": false, "rationale": "The spot report was the first report."}, {"text": "Final report", "is_correct": false, "rationale": "The final report is made when the case is closed or filed."}, {"text": "Progress report", "is_correct": true, "rationale": "A progress report gives developments in an ongoing case."}, {"text": "Incident record form", "is_correct": false, "rationale": "The incident record form is the initial record of the complaint."}]'::jsonb, 2, 'medium', 'Progress reports are submitted at intervals until the case is resolved.', NULL, 'Study module Crime Detection and Investigation, Chapter 7: Technical Writing 1 and 2 (Legal forms and Police Report writing) (CDI-7.2).', 'generated', 'tos_2024', 1, FALSE, 'CDI-7.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-7.2_03', 'crime_detection', 'Technical Writing 1 and 2 (Legal forms and Police Report writing)', 'Why should a spot report avoid conclusions about a suspect''s guilt?', '[{"text": "Spot reports are always kept secret from the chief", "is_correct": false, "rationale": "Spot reports go to the chain of command."}, {"text": "The early facts may be incomplete, and guilt is for the court", "is_correct": true, "rationale": "A spot report records known facts early; unverified conclusions can mislead and prejudice the case."}, {"text": "Conclusions are allowed only in traffic accident reports", "is_correct": false, "rationale": "Conclusions about guilt are not proper in any police report."}, {"text": "The suspect must first approve the report", "is_correct": false, "rationale": "Suspects do not approve police reports."}]'::jsonb, 1, 'hard', 'Reports should be accurate, brief, complete and objective.', NULL, 'Study module Crime Detection and Investigation, Chapter 7: Technical Writing 1 and 2 (Legal forms and Police Report writing) (CDI-7.2).', 'generated', 'tos_2024', 1, FALSE, 'CDI-7.2', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-7.2_04', 'crime_detection', 'Technical Writing 1 and 2 (Legal forms and Police Report writing)', 'A case has been filed in court. Which report summarizes the whole investigation, the evidence and the disposition?', '[{"text": "Spot (initial) report", "is_correct": false, "rationale": "The spot report is the early first report."}, {"text": "Final investigation report", "is_correct": true, "rationale": "The final investigation report pulls together the facts, evidence, findings and action taken."}, {"text": "Progress report", "is_correct": false, "rationale": "Progress reports cover interim developments."}, {"text": "Blotter entry", "is_correct": false, "rationale": "A blotter entry is a brief record of an incident."}]'::jsonb, 1, 'hard', 'The case folder holds the final report with the affidavits and other documents.', NULL, 'Study module Crime Detection and Investigation, Chapter 7: Technical Writing 1 and 2 (Legal forms and Police Report writing) (CDI-7.2).', 'generated', 'tos_2024', 1, FALSE, 'CDI-7.2', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-7.3_01', 'crime_detection', 'Technical Writing 1 and 2 (Legal forms and Police Report writing)', 'A regional director wants to issue a policy that all units must follow until it is revoked. Which issuance is most appropriate?', '[{"text": "Memorandum circular", "is_correct": true, "rationale": "A memorandum circular states policies or rules of general and continuing application."}, {"text": "Special order (SO)", "is_correct": false, "rationale": "A special order covers specific personnel actions such as assignments and details."}, {"text": "Travel order", "is_correct": false, "rationale": "A travel order authorizes official travel."}, {"text": "Spot report", "is_correct": false, "rationale": "A spot report is an incident report, not an issuance."}]'::jsonb, 0, 'hard', 'Choosing the right issuance makes its scope and authority clear.', NULL, 'Study module Crime Detection and Investigation, Chapter 7: Technical Writing 1 and 2 (Legal forms and Police Report writing) (CDI-7.3).', 'generated', 'tos_2024', 1, FALSE, 'CDI-7.3', 'Evaluating') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-7.3_02', 'crime_detection', 'Technical Writing 1 and 2 (Legal forms and Police Report writing)', 'Which is the best opening paragraph for a memorandum order directing all station commanders to intensify checkpoints during the holidays?', '[{"text": "''All station commanders shall intensify checkpoints from Dec. 15 to Jan. 5 to prevent crime.''", "is_correct": true, "rationale": "A good directive states who must act, what to do, when and why, in clear terms."}, {"text": "''It has come to our attention that checkpoints are sometimes held and may be useful.''", "is_correct": false, "rationale": "This wording is vague and gives no directive."}, {"text": "''Checkpoints are important, and everyone should think about doing more of them.''", "is_correct": false, "rationale": "This wording gives no clear instruction or period."}, {"text": "''The director feels that the holidays are very busy and requests suggestions.''", "is_correct": false, "rationale": "This asks for suggestions instead of giving the order."}]'::jsonb, 0, 'hard', 'Administrative issuances should be clear, specific and enforceable.', NULL, 'Study module Crime Detection and Investigation, Chapter 7: Technical Writing 1 and 2 (Legal forms and Police Report writing) (CDI-7.3).', 'generated', 'tos_2024', 1, FALSE, 'CDI-7.3', 'Creating') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-8.1_01', 'crime_detection', 'Introduction to Cybercrime and Environmental Laws', 'Under R.A. 10175, what is illegal access?', '[{"text": "Accessing all or part of a computer system without right", "is_correct": true, "rationale": "Illegal access is accessing all or part of a computer system without right."}, {"text": "Selling a computer with an expired warranty", "is_correct": false, "rationale": "Selling equipment is not a cybercrime."}, {"text": "Posting a true story about oneself online", "is_correct": false, "rationale": "Posting true facts about oneself is not illegal access."}, {"text": "Using public Wi-Fi in a mall", "is_correct": false, "rationale": "Using a public network with permission is not illegal access."}]'::jsonb, 0, 'easy', 'Other offenses against confidentiality include illegal interception and data interference.', 'R.A. 10175 (Cybercrime Prevention Act of 2012), Sec. 4(a)(1)', 'Study module Crime Detection and Investigation, Chapter 8: Introduction to Cybercrime and Environmental Laws (CDI-8.1).', 'generated', 'tos_2024', 1, FALSE, 'CDI-8.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-8.1_02', 'crime_detection', 'Introduction to Cybercrime and Environmental Laws', 'Under R.A. 9003, which act involving solid waste is prohibited?', '[{"text": "Open burning of solid waste", "is_correct": true, "rationale": "R.A. 9003 prohibits the open burning of solid waste."}, {"text": "Segregating waste at the source", "is_correct": false, "rationale": "Segregation at the source is required, not prohibited."}, {"text": "Composting biodegradable waste", "is_correct": false, "rationale": "Composting is encouraged."}, {"text": "Bringing recyclables to a materials recovery facility", "is_correct": false, "rationale": "Materials recovery facilities are part of the law''s system."}]'::jsonb, 0, 'easy', 'R.A. 9003 is the Ecological Solid Waste Management Act of 2000.', 'R.A. 9003, Sec. 48', 'Study module Crime Detection and Investigation, Chapter 8: Introduction to Cybercrime and Environmental Laws (CDI-8.1).', 'generated', 'tos_2024', 1, FALSE, 'CDI-8.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-8.1_03', 'crime_detection', 'Introduction to Cybercrime and Environmental Laws', 'Why does the Fisheries Code punish fishing with explosives?', '[{"text": "It destroys coral reefs and kills marine life without discrimination", "is_correct": true, "rationale": "Blast fishing destroys habitats and kills fish of all sizes, harming fisheries for years."}, {"text": "It is noisy and disturbs nearby coastal residents", "is_correct": false, "rationale": "The harm punished is ecological, not noise."}, {"text": "It uses more fuel than ordinary fishing methods", "is_correct": false, "rationale": "Fuel use is not the reason for the prohibition."}, {"text": "It catches too few fish to be worth the cost", "is_correct": false, "rationale": "Blast fishing kills many fish; the problem is the destruction."}]'::jsonb, 0, 'easy', 'The Fisheries Code (R.A. 8550, as amended by R.A. 10654) also punishes fishing with noxious substances.', 'R.A. 8550, as amended by R.A. 10654', 'Study module Crime Detection and Investigation, Chapter 8: Introduction to Cybercrime and Environmental Laws (CDI-8.1).', 'generated', 'tos_2024', 1, FALSE, 'CDI-8.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-8.2_01', 'crime_detection', 'Introduction to Cybercrime and Environmental Laws', 'Police lawfully seized a suspect''s phone during his arrest. Under the Rule on Cybercrime Warrants, what is needed to examine its data?', '[{"text": "A Warrant to Examine Computer Data (WECD)", "is_correct": true, "rationale": "When a device was lawfully obtained by other means, a WECD is needed before its data are examined."}, {"text": "A Warrant to Intercept Computer Data (WICD)", "is_correct": false, "rationale": "Interception concerns data in transmission."}, {"text": "A Warrant to Disclose Computer Data (WDCD)", "is_correct": false, "rationale": "Disclosure orders a person or provider to hand over data."}, {"text": "No warrant, since the phone was lawfully seized", "is_correct": false, "rationale": "Lawful seizure of the device does not authorize examining its data."}]'::jsonb, 0, 'easy', 'The Rule on Cybercrime Warrants is A.M. No. 17-11-03-SC.', 'Rule on Cybercrime Warrants, A.M. No. 17-11-03-SC, Rule 6', 'Study module Crime Detection and Investigation, Chapter 8: Introduction to Cybercrime and Environmental Laws (CDI-8.2).', 'generated', 'tos_2024', 1, FALSE, 'CDI-8.2', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-8.2_02', 'crime_detection', 'Introduction to Cybercrime and Environmental Laws', 'Why should a running computer at a crime scene not simply be switched off?', '[{"text": "The computer would lock the police out forever", "is_correct": false, "rationale": "Switching off does not always cause a lockout, though encryption may be a concern."}, {"text": "Switching it off deletes the hard disk at once", "is_correct": false, "rationale": "Turning off does not erase the disk."}, {"text": "The computer would send an alarm to the suspect", "is_correct": false, "rationale": "Switching off does not send alarms."}, {"text": "Volatile data in memory would be lost", "is_correct": true, "rationale": "Data held in memory, such as running processes and open sessions, disappear when power is cut; trained responders decide how to capture them."}]'::jsonb, 3, 'easy', 'Basic incident response includes documenting the screen and calling digital forensic specialists.', NULL, 'Study module Crime Detection and Investigation, Chapter 8: Introduction to Cybercrime and Environmental Laws (CDI-8.2).', 'generated', 'tos_2024', 1, FALSE, 'CDI-8.2', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-8.2_03', 'crime_detection', 'Introduction to Cybercrime and Environmental Laws', 'Why do examiners compute a hash value of a forensic image of a hard disk?', '[{"text": "To prove the copy is identical to the original", "is_correct": true, "rationale": "A matching hash shows the image is an exact, unchanged copy, which supports authentication in court."}, {"text": "To make the image file smaller for storage", "is_correct": false, "rationale": "Hashing does not compress files."}, {"text": "To hide the image from the defense lawyers", "is_correct": false, "rationale": "Evidence is disclosed according to the rules, not hidden."}, {"text": "To recover deleted files automatically", "is_correct": false, "rationale": "Hashing does not recover files."}]'::jsonb, 0, 'easy', 'Examinations are done on the image, not on the original device.', 'Rules on Electronic Evidence, A.M. No. 01-7-01-SC', 'Study module Crime Detection and Investigation, Chapter 8: Introduction to Cybercrime and Environmental Laws (CDI-8.2).', 'generated', 'tos_2024', 1, FALSE, 'CDI-8.2', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-8.2_04', 'crime_detection', 'Introduction to Cybercrime and Environmental Laws', 'Police need a service provider to disclose the subscriber details and traffic data of an account used in online scams. Which warrant should they apply for?', '[{"text": "Warrant to Disclose Computer Data (WDCD)", "is_correct": true, "rationale": "A WDCD orders a person or provider to disclose subscriber information, traffic data or relevant data in its control."}, {"text": "Warrant to Intercept Computer Data (WICD)", "is_correct": false, "rationale": "Interception is for data in transmission."}, {"text": "Warrant to Examine Computer Data (WECD)", "is_correct": false, "rationale": "A WECD is for examining data in a lawfully seized device."}, {"text": "Ordinary search warrant under Rule 126", "is_correct": false, "rationale": "Computer data are covered by the special warrants of the Rule."}]'::jsonb, 0, 'medium', 'R.A. 10175 also allows orders to preserve data while a warrant is sought.', 'Rule on Cybercrime Warrants, A.M. No. 17-11-03-SC, Rule 4', 'Study module Crime Detection and Investigation, Chapter 8: Introduction to Cybercrime and Environmental Laws (CDI-8.2).', 'generated', 'tos_2024', 1, FALSE, 'CDI-8.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-8.3_01', 'crime_detection', 'Introduction to Cybercrime and Environmental Laws', 'Under the Rules of Procedure for Environmental Cases, who may file a criminal complaint for violation of an environmental law?', '[{"text": "Only the Secretary of Environment and Natural Resources", "is_correct": false, "rationale": "The DENR Secretary is not the only one allowed."}, {"text": "An offended party, a peace officer, or an officer enforcing that law", "is_correct": true, "rationale": "The Rules allow any offended party, peace officer, or public officer charged with enforcing an environmental law to file a criminal complaint."}, {"text": "Only persons who own land near the polluted area", "is_correct": false, "rationale": "Ownership of nearby land is not required."}, {"text": "Only lawyers accredited by the Supreme Court", "is_correct": false, "rationale": "No accreditation of lawyers is required."}]'::jsonb, 1, 'easy', 'The Rules are A.M. No. 09-6-8-SC.', 'Rules of Procedure for Environmental Cases, A.M. No. 09-6-8-SC, Rule 9', 'Study module Crime Detection and Investigation, Chapter 8: Introduction to Cybercrime and Environmental Laws (CDI-8.3).', 'generated', 'tos_2024', 1, FALSE, 'CDI-8.3', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-8.3_02', 'crime_detection', 'Introduction to Cybercrime and Environmental Laws', 'What is a citizen suit under the Rules of Procedure for Environmental Cases?', '[{"text": "A suit that only government agencies may file", "is_correct": false, "rationale": "Citizen suits are filed by citizens, not only by agencies."}, {"text": "A suit by any Filipino, even for future generations", "is_correct": true, "rationale": "Any Filipino citizen, in representation of others including minors and generations yet unborn, may file an action to enforce environmental laws."}, {"text": "A suit filed only to collect taxes from polluters", "is_correct": false, "rationale": "Citizen suits enforce environmental rights, not taxes."}, {"text": "A suit that may be filed only by foreign residents", "is_correct": false, "rationale": "Citizen suits are for Filipino citizens."}]'::jsonb, 1, 'easy', 'This reflects the principle of intergenerational responsibility (Oposa v. Factoran).', 'Rules of Procedure for Environmental Cases, A.M. No. 09-6-8-SC, Rule 2, Sec. 5', 'Study module Crime Detection and Investigation, Chapter 8: Introduction to Cybercrime and Environmental Laws (CDI-8.3).', 'generated', 'tos_2024', 1, FALSE, 'CDI-8.3', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CDI-8.3_03', 'crime_detection', 'Introduction to Cybercrime and Environmental Laws', 'In environmental cases, what is a SLAPP?', '[{"text": "A lawsuit meant to harass those who protect the environment", "is_correct": true, "rationale": "A Strategic Lawsuit Against Public Participation is meant to harass or silence those enforcing environmental laws; the Rules allow it to be raised as a defense."}, {"text": "A permit to build a landfill near a river", "is_correct": false, "rationale": "SLAPP is not a permit."}, {"text": "A warrant to search a factory suspected of polluting", "is_correct": false, "rationale": "SLAPP is not a warrant."}, {"text": "A fine imposed on smoke-belching vehicles", "is_correct": false, "rationale": "SLAPP is not a fine."}]'::jsonb, 0, 'easy', 'A SLAPP defense may lead to dismissal and damages.', 'Rules of Procedure for Environmental Cases, A.M. No. 09-6-8-SC, Rule 6', 'Study module Crime Detection and Investigation, Chapter 8: Introduction to Cybercrime and Environmental Laws (CDI-8.3).', 'generated', 'tos_2024', 1, FALSE, 'CDI-8.3', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-1.1_01', 'criminology', 'Introduction to Criminology', 'How did the Neo-Classical school modify the ideas of the Classical school?', '[{"text": "It rejected free will and said crime is caused only by biology", "is_correct": false, "rationale": "Rejecting free will in favor of biological causes is associated with the Positivist school."}, {"text": "It demanded the same penalty for adults and children alike", "is_correct": false, "rationale": "Equal penalties for all, regardless of age, was the strict Classical position that the Neo-Classicals softened."}, {"text": "It held that punishment should be as severe as possible", "is_correct": false, "rationale": "Neither school favored the most severe punishment possible; both stressed proportion."}, {"text": "It accepted that age, insanity and other conditions can reduce responsibility", "is_correct": true, "rationale": "The Neo-Classical school kept free will but recognized that some persons, such as children and the insane, are less responsible, which led to mitigating circumstances."}]'::jsonb, 3, 'easy', 'The Revised Penal Code reflects both: it is basically Classical, with Neo-Classical mitigating and exempting circumstances.', NULL, 'Study module Criminology, Chapter 1: Introduction to Criminology (CRIM-1.1).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-1.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-1.1_02', 'criminology', 'Introduction to Criminology', 'What is the main contrast between the Classical and the Positivist schools of criminology?', '[{"text": "Classical uses scientific methods; Positivist relies only on philosophy", "is_correct": false, "rationale": "It was the Positivists who introduced scientific study of offenders."}, {"text": "Classical blames society; Positivist blames only the individual''s choice", "is_correct": false, "rationale": "Positivists looked at biological, psychological and social causes rather than free choice."}, {"text": "Classical: free will and fitting penalties; Positivist: causes and treatment", "is_correct": true, "rationale": "Beccaria and Bentham saw crime as a free choice to be deterred by proportionate punishment; Lombroso, Ferri and Garofalo looked for causes and favored individualized treatment."}, {"text": "Classical favors rehabilitation; Positivist favors only revenge", "is_correct": false, "rationale": "Classical thinkers favored deterrence, and Positivists favored treatment."}]'::jsonb, 2, 'easy', 'The Positivist school is said to have shifted attention from the crime to the criminal.', NULL, 'Study module Criminology, Chapter 1: Introduction to Criminology (CRIM-1.1).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-1.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-1.2_01', 'criminology', 'Introduction to Criminology', 'How do crimes mala in se differ from crimes mala prohibita?', '[{"text": "Mala in se are found only in special laws; mala prohibita only in the Revised Penal Code", "is_correct": false, "rationale": "Many special laws punish mala prohibita, but some special-law crimes are mala in se."}, {"text": "Mala in se are wrong in themselves and intent matters; mala prohibita are wrong because the law forbids them", "is_correct": true, "rationale": "Mala in se, like murder, are inherently wrong, so good faith and lack of intent are defenses; in mala prohibita, the act alone is punished regardless of intent."}, {"text": "Mala in se need no intent; mala prohibita always require criminal intent", "is_correct": false, "rationale": "It is the reverse: intent is generally irrelevant in mala prohibita."}, {"text": "Mala in se are minor offenses; mala prohibita are always grave offenses", "is_correct": false, "rationale": "Gravity does not depend on this classification."}]'::jsonb, 1, 'easy', 'Illegal possession of firearms and many traffic offenses are examples of mala prohibita.', NULL, 'Study module Criminology, Chapter 1: Introduction to Criminology (CRIM-1.2).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-1.2', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-1.2_02', 'criminology', 'Introduction to Criminology', 'Under the conflict model of crime, what do criminal laws mainly reflect?', '[{"text": "The shared values of all members of society", "is_correct": false, "rationale": "Shared values describe the consensus model."}, {"text": "The interests of the groups that hold power in society", "is_correct": true, "rationale": "The conflict model holds that those with economic and political power shape the law to protect their interests."}, {"text": "The natural law that is the same in every country", "is_correct": false, "rationale": "Natural law is a philosophical idea, not the conflict model."}, {"text": "The personal opinions of individual police officers", "is_correct": false, "rationale": "Police officers enforce laws but do not define them."}]'::jsonb, 1, 'easy', 'The interactionist model adds that those with power define which acts are labeled deviant.', NULL, 'Study module Criminology, Chapter 1: Introduction to Criminology (CRIM-1.2).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-1.2', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-1.3_01', 'criminology', 'Introduction to Criminology', 'An offender killed several victims over many months, with cooling-off periods between the killings. How is he classified?', '[{"text": "Mass murderer", "is_correct": false, "rationale": "Mass murderers kill several victims at one place in a single event."}, {"text": "Spree killer", "is_correct": false, "rationale": "Spree killers kill at two or more places without a cooling-off period."}, {"text": "Contract killer", "is_correct": false, "rationale": "Contract killers kill for payment, which is not shown here."}, {"text": "Serial killer", "is_correct": true, "rationale": "Serial killers commit separate killings over time with emotional cooling-off periods in between."}]'::jsonb, 3, 'easy', 'The timing and location of the killings separate serial, mass and spree murder.', NULL, 'Study module Criminology, Chapter 1: Introduction to Criminology (CRIM-1.3).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-1.3', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-1.3_02', 'criminology', 'Introduction to Criminology', 'In Groth''s typology of rapists, which type uses far more force than needed and expresses rage at the victim?', '[{"text": "Anger rapist", "is_correct": true, "rationale": "The anger rapist uses excessive brutality to express hostility and rage."}, {"text": "Power rapist", "is_correct": false, "rationale": "The power rapist uses only the force needed to control the victim and asserts dominance."}, {"text": "Sadistic rapist", "is_correct": false, "rationale": "The sadistic rapist finds sexual gratification in the victim''s suffering, often with ritual."}, {"text": "Opportunistic rapist", "is_correct": false, "rationale": "Opportunistic is not one of Groth''s three basic types."}]'::jsonb, 0, 'easy', 'Groth held that rape is motivated mainly by power and anger, not by sexual desire alone.', NULL, 'Study module Criminology, Chapter 1: Introduction to Criminology (CRIM-1.3).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-1.3', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-1.3_03', 'criminology', 'Introduction to Criminology', 'In Conklin''s typology of robbers, which type plans carefully and treats robbery as a career?', '[{"text": "Opportunist robber", "is_correct": false, "rationale": "Opportunist robbers pick easy targets for small amounts with little planning."}, {"text": "Addict robber", "is_correct": false, "rationale": "Addict robbers rob to support a drug habit."}, {"text": "Alcoholic robber", "is_correct": false, "rationale": "Alcoholic robbers rob while drunk, with little planning."}, {"text": "Professional robber", "is_correct": true, "rationale": "Professional robbers commit robbery as their main source of income, plan their crimes and seek large amounts."}]'::jsonb, 3, 'easy', 'Conklin''s typology is based on robbers'' motives and commitment to crime.', NULL, 'Study module Criminology, Chapter 1: Introduction to Criminology (CRIM-1.3).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-1.3', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-1.4_01', 'criminology', 'Introduction to Criminology', 'Under R.A. 11131, which body regulates and supervises the practice of criminology?', '[{"text": "The National Police Commission under the DILG", "is_correct": false, "rationale": "NAPOLCOM administers the PNP, not the criminology profession."}, {"text": "The Commission on Higher Education", "is_correct": false, "rationale": "CHED regulates criminology education programs, not professional practice."}, {"text": "The Philippine National Police Directorate for Personnel", "is_correct": false, "rationale": "The PNP''s directorates manage police personnel, not the profession."}, {"text": "The Professional Regulatory Board of Criminology under the PRC", "is_correct": true, "rationale": "R.A. 11131 vests regulation of the profession in the Professional Regulatory Board of Criminology, under the Professional Regulation Commission."}]'::jsonb, 3, 'easy', 'The Board prepares the licensure examination, issues certificates and enforces professional standards.', 'R.A. 11131 (Philippine Criminology Profession Act of 2018)', 'Study module Criminology, Chapter 1: Introduction to Criminology (CRIM-1.4).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-1.4', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-1.4_02', 'criminology', 'Introduction to Criminology', 'Why must a criminology graduate pass the licensure examination before practicing as a criminologist?', '[{"text": "Passing gives an automatic rank of police officer in the PNP", "is_correct": false, "rationale": "Passing the board does not give police rank; PNP appointment has its own requirements."}, {"text": "R.A. 11131 allows only registered criminologists with a valid COR and PIC to practice", "is_correct": true, "rationale": "Practice of criminology requires registration with a Certificate of Registration and a valid Professional Identification Card."}, {"text": "Graduates may practice freely until they reach the age of thirty", "is_correct": false, "rationale": "No age-based exemption exists."}, {"text": "The examination is only a requirement for teaching abroad", "is_correct": false, "rationale": "The license is required for practice in the Philippines."}]'::jsonb, 1, 'easy', 'Practicing without registration is a prohibited act under R.A. 11131.', 'R.A. 11131', 'Study module Criminology, Chapter 1: Introduction to Criminology (CRIM-1.4).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-1.4', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-1.4_03', 'criminology', 'Introduction to Criminology', 'Why is the teaching of professional criminology subjects counted as part of the practice of criminology?', '[{"text": "Because teachers of any subject automatically become criminologists", "is_correct": false, "rationale": "Teaching other subjects does not make one a criminologist."}, {"text": "Because only police officers are allowed to teach in colleges", "is_correct": false, "rationale": "Teaching is not limited to police officers."}, {"text": "Because teaching is a private hobby not covered by any law", "is_correct": false, "rationale": "Teaching professional subjects is regulated practice under the law."}, {"text": "Because R.A. 11131 includes teaching those subjects in the scope of practice", "is_correct": true, "rationale": "R.A. 11131 lists the teaching of criminology professional subjects as part of the practice, so faculty for those subjects must be registered criminologists."}]'::jsonb, 3, 'easy', 'Other areas of practice include law enforcement administration, forensic science, correctional administration and industrial security.', 'R.A. 11131', 'Study module Criminology, Chapter 1: Introduction to Criminology (CRIM-1.4).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-1.4', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-2.1_01', 'criminology', 'Theories of Crime Causation', 'Why was Lombroso''s theory of the ''born criminal'' later rejected?', '[{"text": "He studied only women offenders and ignored men", "is_correct": false, "rationale": "Lombroso studied mostly male offenders, and he also wrote on female offenders."}, {"text": "He proved that crime is caused only by poverty", "is_correct": false, "rationale": "Lombroso emphasized biological atavism, not poverty."}, {"text": "He used modern DNA tests that were later found to be faulty", "is_correct": false, "rationale": "DNA testing did not exist in Lombroso''s time."}, {"text": "He lacked control groups, and later studies found no criminal type", "is_correct": true, "rationale": "Charles Goring compared convicts with non-convicts and found no distinct criminal physical type; Lombroso''s methods lacked controls."}]'::jsonb, 3, 'hard', 'Lombroso is still called the father of modern criminology for applying scientific study to offenders.', NULL, 'Study module Criminology, Chapter 2: Theories of Crime Causation (CRIM-2.1).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-2.1', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-2.1_02', 'criminology', 'Theories of Crime Causation', 'A study finds that delinquents are more often muscular (mesomorphic). Why does this not prove that body type causes crime?', '[{"text": "Body type is always caused by the crimes a person commits", "is_correct": false, "rationale": "Body type is not caused by committing crimes."}, {"text": "The link may come from social factors, since correlation is not causation", "is_correct": true, "rationale": "Muscular youths may be recruited into fights or treated differently; a correlation does not show that body type causes delinquency."}, {"text": "Mesomorphs are never found among non-delinquents", "is_correct": false, "rationale": "Mesomorphs are common among non-delinquents too."}, {"text": "Sheldon''s theory says that thin people commit most crimes", "is_correct": false, "rationale": "Sheldon linked mesomorphy, not ectomorphy, to delinquency."}]'::jsonb, 1, 'hard', 'Sheldon''s somatotypes are endomorph, mesomorph and ectomorph.', NULL, 'Study module Criminology, Chapter 2: Theories of Crime Causation (CRIM-2.1).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-2.1', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-2.1_03', 'criminology', 'Theories of Crime Causation', 'Why are family studies like those of the Jukes and the Kallikaks weak evidence for inherited criminality?', '[{"text": "They studied too many families across many countries", "is_correct": false, "rationale": "These studies focused on a few families, not many."}, {"text": "Family members share environments as well as genes", "is_correct": true, "rationale": "Crime running in families may come from shared upbringing, poverty and learning, not just heredity."}, {"text": "They showed no criminal members in any of the families", "is_correct": false, "rationale": "They reported many criminal members, which was their point."}, {"text": "They relied on modern brain scans that proved inaccurate", "is_correct": false, "rationale": "Brain scans were not used in these early studies."}]'::jsonb, 1, 'hard', 'Twin and adoption studies were later used to separate genetic from environmental influences.', NULL, 'Study module Criminology, Chapter 2: Theories of Crime Causation (CRIM-2.1).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-2.1', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-2.2_01', 'criminology', 'Theories of Crime Causation', 'Burglaries rise in a subdivision where most residents work during the day and houses are left empty. Which theory best explains this?', '[{"text": "Strain theory", "is_correct": false, "rationale": "Strain theory explains crime as a response to blocked goals."}, {"text": "Routine activities theory", "is_correct": true, "rationale": "Routine activities theory says crime occurs when a motivated offender meets a suitable target without a capable guardian; empty houses lack guardians."}, {"text": "Labeling theory", "is_correct": false, "rationale": "Labeling theory concerns the effects of being labeled deviant."}, {"text": "Psychoanalytic theory", "is_correct": false, "rationale": "Psychoanalytic theory looks at unconscious conflicts."}]'::jsonb, 1, 'medium', 'Neighborhood watch and visible patrols add capable guardians.', NULL, 'Study module Criminology, Chapter 2: Theories of Crime Causation (CRIM-2.2).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-2.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-2.2_02', 'criminology', 'Theories of Crime Causation', 'According to the broken windows theory, why would fixing minor disorder help reduce serious crime?', '[{"text": "Minor disorder is the same thing as serious crime under the law", "is_correct": false, "rationale": "Disorder and serious crime are different, but the theory links them."}, {"text": "Fixing windows makes buildings too strong to break into", "is_correct": false, "rationale": "The idea is about signals of control, not stronger buildings."}, {"text": "Serious offenders are afraid of newly painted walls", "is_correct": false, "rationale": "The theory is about the message of order, not fear of paint."}, {"text": "Visible disorder signals that no one is in control, which invites more crime", "is_correct": true, "rationale": "Wilson and Kelling argued that unchecked disorder signals weak social control, encouraging more serious offending."}]'::jsonb, 3, 'hard', 'Order-maintenance policing draws on this theory, but it must respect people''s rights.', NULL, 'Study module Criminology, Chapter 2: Theories of Crime Causation (CRIM-2.2).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-2.2', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-2.2_03', 'criminology', 'Theories of Crime Causation', 'Crime pattern theory finds that crimes cluster near offenders'' homes, workplaces and the roads between them. Why?', '[{"text": "Offenders choose places they have never visited before", "is_correct": false, "rationale": "Unknown places carry more risk for offenders."}, {"text": "Crimes are evenly spread across all areas of a city", "is_correct": false, "rationale": "Crime is concentrated, not evenly spread."}, {"text": "Offenders commit crimes in areas they know from their daily routines", "is_correct": true, "rationale": "The Brantinghams showed that crimes occur within offenders'' awareness space, along their routine nodes and paths."}, {"text": "Offenders avoid all places near their daily routes", "is_correct": false, "rationale": "Offenders tend to offend near, not away from, their routines."}]'::jsonb, 2, 'hard', 'Geographic profiling builds on crime pattern theory.', NULL, 'Study module Criminology, Chapter 2: Theories of Crime Causation (CRIM-2.2).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-2.2', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-2.3_01', 'criminology', 'Theories of Crime Causation', 'A teenager whose friends belong to a gang begins skipping school and joining them in petty thefts. Which risk factor is most evident?', '[{"text": "Religious influence from his parish", "is_correct": false, "rationale": "Nothing in the facts concerns religious influence, which is usually protective."}, {"text": "Social responsibility from volunteering", "is_correct": false, "rationale": "Volunteering and social responsibility are protective factors."}, {"text": "High income of his family", "is_correct": false, "rationale": "Family income is not mentioned and is not the key factor here."}, {"text": "Peer pressure from delinquent friends", "is_correct": true, "rationale": "Association with delinquent peers is one of the strongest predictors of delinquency."}]'::jsonb, 3, 'medium', 'Prevention programs try to replace delinquent peer groups with prosocial ones.', NULL, 'Study module Criminology, Chapter 2: Theories of Crime Causation (CRIM-2.3).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-2.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-2.3_02', 'criminology', 'Theories of Crime Causation', 'A child grows up with parents who neglect him and use violence at home. Which risk factor is most evident?', '[{"text": "Unemployment of the child himself", "is_correct": false, "rationale": "The child is not employed; unemployment refers to adults in the household."}, {"text": "Family dynamics such as neglect and violence", "is_correct": true, "rationale": "Neglect, harsh discipline and violence in the home are family risk factors for delinquency."}, {"text": "Peer pressure from his classmates at school", "is_correct": false, "rationale": "Classmates are not mentioned."}, {"text": "Drug involvement of the child", "is_correct": false, "rationale": "Drug use by the child is not mentioned."}]'::jsonb, 1, 'medium', 'Children exposed to violence may learn it as a way of dealing with conflict.', NULL, 'Study module Criminology, Chapter 2: Theories of Crime Causation (CRIM-2.3).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-2.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-2.4_01', 'criminology', 'Theories of Crime Causation', 'A neighborhood has high resident turnover, weak community organizations and persistent crime even as its population changes. Which response follows social disorganization theory?', '[{"text": "Increase prison sentences for all offenders in the area", "is_correct": false, "rationale": "Longer sentences do not rebuild community controls."}, {"text": "Test the residents for genetic risk factors", "is_correct": false, "rationale": "Social disorganization theory does not look at genes."}, {"text": "Strengthen community organizations and ties among residents", "is_correct": true, "rationale": "Shaw and McKay linked crime to weak community controls; rebuilding community ties addresses this."}, {"text": "Label the area''s youth as future offenders", "is_correct": false, "rationale": "Labeling would make matters worse."}]'::jsonb, 2, 'medium', 'Shaw and McKay found that high delinquency stayed in certain zones regardless of who lived there.', NULL, 'Study module Criminology, Chapter 2: Theories of Crime Causation (CRIM-2.4).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-2.4', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-2.4_02', 'criminology', 'Theories of Crime Causation', 'A youth labeled a ''criminal'' after a minor offense begins to see himself that way and commits more offenses. What does this illustrate?', '[{"text": "Primary deviance under strain theory", "is_correct": false, "rationale": "Primary deviance is the initial act before any label."}, {"text": "Secondary deviance under labeling theory", "is_correct": true, "rationale": "Lemert described secondary deviance as deviance that follows the acceptance of a deviant label."}, {"text": "Differential association with law-abiding peers", "is_correct": false, "rationale": "Differential association concerns learning from delinquent associates."}, {"text": "Anomie caused by economic success", "is_correct": false, "rationale": "Anomie concerns a gap between goals and means, not labeling."}]'::jsonb, 1, 'hard', 'This reasoning supports diversion programs that avoid stigmatizing young offenders.', NULL, 'Study module Criminology, Chapter 2: Theories of Crime Causation (CRIM-2.4).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-2.4', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-3.1_01', 'criminology', 'Human Behavior and Victimology', 'According to Erikson, which psychosocial crisis do adolescents face?', '[{"text": "Trust versus mistrust", "is_correct": false, "rationale": "Trust versus mistrust is the crisis of infancy."}, {"text": "Industry versus inferiority", "is_correct": false, "rationale": "Industry versus inferiority belongs to the school years."}, {"text": "Integrity versus despair", "is_correct": false, "rationale": "Integrity versus despair belongs to old age."}, {"text": "Identity versus role confusion", "is_correct": true, "rationale": "Adolescents work to build a stable sense of self and their roles; failure leads to role confusion."}]'::jsonb, 3, 'easy', 'Erikson described eight stages of psychosocial development across the lifespan.', NULL, 'Study module Criminology, Chapter 3: Human Behavior and Victimology (CRIM-3.1).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-3.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-3.1_02', 'criminology', 'Human Behavior and Victimology', 'A boy who often watched his father beat his mother later becomes violent toward others. Which theory best explains this?', '[{"text": "Piaget''s cognitive development theory", "is_correct": false, "rationale": "Piaget''s theory concerns stages of thinking, not imitation of aggression."}, {"text": "Maslow''s hierarchy of needs", "is_correct": false, "rationale": "Maslow''s theory concerns the order of human needs."}, {"text": "Bandura''s social learning theory", "is_correct": true, "rationale": "Bandura showed that people learn aggression by observing and imitating models, especially when the behavior seems rewarded."}, {"text": "Erikson''s psychosocial theory", "is_correct": false, "rationale": "Erikson''s theory concerns psychosocial crises across life stages."}]'::jsonb, 2, 'hard', 'Bandura''s Bobo doll experiments showed children copying aggressive models.', NULL, 'Study module Criminology, Chapter 3: Human Behavior and Victimology (CRIM-3.1).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-3.1', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-3.2_01', 'criminology', 'Human Behavior and Victimology', 'Which statement about schizophrenia is correct?', '[{"text": "It means the person has two or more separate personalities", "is_correct": false, "rationale": "Multiple personalities describe dissociative identity disorder, a different condition."}, {"text": "It involves symptoms such as hallucinations, delusions and disorganized thinking", "is_correct": true, "rationale": "Schizophrenia is a psychotic disorder marked by hallucinations, delusions and disorganized thought."}, {"text": "It is a mild mood that always passes within a day", "is_correct": false, "rationale": "Schizophrenia is a serious, often long-term disorder."}, {"text": "It affects only persons who use illegal drugs", "is_correct": false, "rationale": "Schizophrenia occurs with or without drug use."}]'::jsonb, 1, 'easy', 'Most persons with schizophrenia are not violent, and treatment helps manage symptoms.', NULL, 'Study module Criminology, Chapter 3: Human Behavior and Victimology (CRIM-3.2).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-3.2', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-3.2_02', 'criminology', 'Human Behavior and Victimology', 'An officer meets a man in a psychotic episode who believes people are trying to kill him. How should the officer respond?', '[{"text": "Argue firmly that his beliefs are false until he admits it", "is_correct": false, "rationale": "Arguing with delusions usually increases agitation."}, {"text": "Handcuff him at once, since mental illness is a crime", "is_correct": false, "rationale": "Mental illness is not a crime; restraint is used only when necessary for safety."}, {"text": "Leave him alone, since mental illness is not a police matter", "is_correct": false, "rationale": "Officers still have a duty to protect the person and the public."}, {"text": "Stay calm, speak simply, don''t argue, and call mental health help", "is_correct": true, "rationale": "De-escalation, a safe distance, simple communication and referral to mental health services reduce risk to everyone."}]'::jsonb, 3, 'medium', 'R.A. 11036, the Mental Health Act, promotes the rights and humane treatment of persons with mental health conditions.', 'R.A. 11036 (Mental Health Act)', 'Study module Criminology, Chapter 3: Human Behavior and Victimology (CRIM-3.2).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-3.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-3.2_03', 'criminology', 'Human Behavior and Victimology', 'A detainee says he wants to die and has given away his belongings. What should the jail officer do?', '[{"text": "Ignore it, since detainees often say such things for attention", "is_correct": false, "rationale": "Every suicide threat must be treated as real."}, {"text": "Keep him under watch, remove dangerous items, and refer him", "is_correct": true, "rationale": "Talk of suicide and giving away belongings are warning signs; close watch, removal of means and referral can save a life."}, {"text": "Place him in isolation without any supervision", "is_correct": false, "rationale": "Isolation without supervision increases the risk."}, {"text": "Tell him to stop being dramatic and return to his cell", "is_correct": false, "rationale": "Dismissing his feelings can push him toward acting on them."}]'::jsonb, 1, 'medium', 'Depression is treatable, and early help prevents suicide.', NULL, 'Study module Criminology, Chapter 3: Human Behavior and Victimology (CRIM-3.2).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-3.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-3.3_01', 'criminology', 'Human Behavior and Victimology', 'What does the concept of victim precipitation mean?', '[{"text": "The victim''s own actions started or provoked the incident", "is_correct": true, "rationale": "Victim precipitation, studied by Wolfgang in homicides, refers to victims who first used force or provoked the offender."}, {"text": "The victim was chosen completely at random", "is_correct": false, "rationale": "Random selection is the opposite of precipitation."}, {"text": "The victim was punished by the court for the crime", "is_correct": false, "rationale": "Victims are not punished for crimes against them."}, {"text": "The victim reported the crime too late", "is_correct": false, "rationale": "Late reporting is not what the term means."}]'::jsonb, 0, 'easy', 'The concept explains interactions but does not excuse offenders.', NULL, 'Study module Criminology, Chapter 3: Human Behavior and Victimology (CRIM-3.3).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-3.3', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-3.3_02', 'criminology', 'Human Behavior and Victimology', 'A person who often goes out late to bars and walks home alone is robbed more than her neighbors. Which theory best explains this?', '[{"text": "Victim precipitation theory", "is_correct": false, "rationale": "Victim precipitation requires that the victim provoked the offender."}, {"text": "Labeling theory", "is_correct": false, "rationale": "Labeling theory concerns offenders, not victims."}, {"text": "Lifestyle theory of victimization", "is_correct": true, "rationale": "Lifestyle theory holds that certain lifestyles increase exposure to offenders and risky places."}, {"text": "Strain theory", "is_correct": false, "rationale": "Strain theory concerns offenders'' blocked goals."}]'::jsonb, 2, 'medium', 'Hindelang and colleagues developed the lifestyle exposure model.', NULL, 'Study module Criminology, Chapter 3: Human Behavior and Victimology (CRIM-3.3).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-3.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-3.3_03', 'criminology', 'Human Behavior and Victimology', 'A man attacked another with a knife and was killed by him in lawful self-defense. In Mendelsohn''s typology, what kind of victim is he?', '[{"text": "The most guilty victim", "is_correct": true, "rationale": "Mendelsohn''s ''most guilty victim'' is one who attacks and is killed by the person defending himself."}, {"text": "The completely innocent victim", "is_correct": false, "rationale": "The completely innocent victim did nothing to bring about the crime."}, {"text": "The victim with minor guilt", "is_correct": false, "rationale": "The victim with minor guilt contributed through ignorance or carelessness."}, {"text": "The imaginary victim", "is_correct": false, "rationale": "The imaginary victim pretends to be a victim."}]'::jsonb, 0, 'medium', 'Mendelsohn classified victims by their degree of responsibility for the crime.', NULL, 'Study module Criminology, Chapter 3: Human Behavior and Victimology (CRIM-3.3).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-3.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-3.3_04', 'criminology', 'Human Behavior and Victimology', 'Why are victims of online scams often targeted again soon after the first scam?', '[{"text": "Their details may be shared, and they are seen as likely to respond", "is_correct": true, "rationale": "Repeat victimization happens because offenders share lists of responsive victims and run follow-up ''recovery'' scams."}, {"text": "The law requires scammers to contact the same victims twice", "is_correct": false, "rationale": "No law requires such contact."}, {"text": "Victims of scams are protected from all future contact", "is_correct": false, "rationale": "No such protection exists automatically."}, {"text": "Online scams can only be committed once per person", "is_correct": false, "rationale": "Scams can be repeated against the same person."}]'::jsonb, 0, 'hard', 'Prevention advice to cyber victims includes warnings about follow-up scams.', 'R.A. 10175', 'Study module Criminology, Chapter 3: Human Behavior and Victimology (CRIM-3.3).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-3.3', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-3.3_05', 'criminology', 'Human Behavior and Victimology', 'How does victim profiling help a criminal investigation?', '[{"text": "It allows the court to blame the victim for the crime", "is_correct": false, "rationale": "Victim profiling does not shift guilt to the victim."}, {"text": "It proves the offender''s guilt without other evidence", "is_correct": false, "rationale": "It generates leads; it is not proof of guilt."}, {"text": "The victim''s routines and contacts can point to the offender", "is_correct": true, "rationale": "Victimology studies the victim''s lifestyle, contacts and movements, which can reveal how and why the offender chose the victim."}, {"text": "It replaces the need for any crime scene examination", "is_correct": false, "rationale": "It supplements, not replaces, scene examination."}]'::jsonb, 2, 'hard', 'Investigators combine victim profiling with physical evidence.', NULL, 'Study module Criminology, Chapter 3: Human Behavior and Victimology (CRIM-3.3).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-3.3', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-3.4_01', 'criminology', 'Human Behavior and Victimology', 'Under R.A. 9262, who issues a Barangay Protection Order, and how long is it effective?', '[{"text": "The Regional Trial Court judge; effective for 30 days", "is_correct": false, "rationale": "Courts issue Temporary Protection Orders (30 days) and Permanent Protection Orders."}, {"text": "The Chief of Police; effective until revoked", "is_correct": false, "rationale": "Police enforce protection orders but do not issue BPOs."}, {"text": "The Punong Barangay or a kagawad; effective for 15 days", "is_correct": true, "rationale": "R.A. 9262 lets the Punong Barangay, or a kagawad if he is unavailable, issue a BPO effective for 15 days."}, {"text": "The Mayor; effective for one year", "is_correct": false, "rationale": "Mayors do not issue protection orders."}]'::jsonb, 2, 'easy', 'The BPO orders the respondent to stop causing or threatening physical harm.', 'R.A. 9262, Secs. 14-16', 'Study module Criminology, Chapter 3: Human Behavior and Victimology (CRIM-3.4).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-3.4', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-3.4_02', 'criminology', 'Human Behavior and Victimology', 'A wife whose husband threatens to hurt her tonight needs protection at once, and the nearest office is the barangay hall. What should she ask for?', '[{"text": "A Barangay Protection Order from the Punong Barangay", "is_correct": true, "rationale": "The BPO is the quickest protection order available, issued on the same day by the Punong Barangay."}, {"text": "A Permanent Protection Order from the barangay", "is_correct": false, "rationale": "Permanent Protection Orders are issued only by courts."}, {"text": "A writ of habeas corpus from the barangay", "is_correct": false, "rationale": "Habeas corpus is a court remedy for illegal detention."}, {"text": "A search warrant from the barangay captain", "is_correct": false, "rationale": "Barangay officials do not issue search warrants."}]'::jsonb, 0, 'medium', 'She may also apply to the court for a TPO and a PPO.', 'R.A. 9262, Sec. 14', 'Study module Criminology, Chapter 3: Human Behavior and Victimology (CRIM-3.4).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-3.4', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-3.4_03', 'criminology', 'Human Behavior and Victimology', 'A witness to a murder fears for his life, and his testimony is essential to the case. Which program may protect him?', '[{"text": "The Barangay Protection Order under R.A. 9262", "is_correct": false, "rationale": "BPOs protect women and children from abuse by partners or family members."}, {"text": "The Probation program of the PPA", "is_correct": false, "rationale": "Probation applies to convicted offenders."}, {"text": "The DOJ Witness Protection, Security and Benefit Program", "is_correct": true, "rationale": "R.A. 6981 provides protection, security and benefits to qualified witnesses in grave felonies."}, {"text": "The Bureau of Immigration''s watchlist", "is_correct": false, "rationale": "An immigration watchlist does not protect witnesses."}]'::jsonb, 2, 'medium', 'Qualified witnesses may receive secure housing, livelihood aid and security.', 'R.A. 6981 (Witness Protection, Security and Benefit Act)', 'Study module Criminology, Chapter 3: Human Behavior and Victimology (CRIM-3.4).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-3.4', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-3.4_04', 'criminology', 'Human Behavior and Victimology', 'A police officer who will testify against fellow officers asks to enter the Witness Protection Program. How should his request be evaluated?', '[{"text": "He must be admitted because he testifies against other officers", "is_correct": false, "rationale": "Testifying against officers does not lift the disqualification."}, {"text": "He may be admitted only after he resigns from the police", "is_correct": false, "rationale": "The law provides no exception upon resignation."}, {"text": "He cannot be admitted, but members of his immediate family may be", "is_correct": true, "rationale": "R.A. 6981 disqualifies law enforcement officers even if they testify against other officers; only their immediate family may be covered."}, {"text": "He may be admitted together with all of his relatives", "is_correct": false, "rationale": "Coverage is limited to the immediate family."}]'::jsonb, 2, 'hard', 'Law enforcement officers are expected to be protected by their own agencies.', 'R.A. 6981, Sec. 3(d)', 'Study module Criminology, Chapter 3: Human Behavior and Victimology (CRIM-3.4).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-3.4', 'Evaluating') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-3.4_05', 'criminology', 'Human Behavior and Victimology', 'Someone claims that R.A. 9262 covers only physical violence. How should this claim be evaluated?', '[{"text": "Correct; only physical injuries are punishable under the law", "is_correct": false, "rationale": "The law expressly goes beyond physical violence."}, {"text": "Correct; other forms are covered only by the Revised Penal Code", "is_correct": false, "rationale": "These forms are covered by R.A. 9262 itself."}, {"text": "Incorrect; it covers only economic abuse", "is_correct": false, "rationale": "It covers all four forms, not only economic abuse."}, {"text": "Incorrect; it also covers sexual, psychological and economic abuse", "is_correct": true, "rationale": "R.A. 9262 defines violence against women and their children to include physical, sexual, psychological and economic abuse."}]'::jsonb, 3, 'hard', 'Denying financial support and repeated public humiliation may be forms of abuse under the law.', 'R.A. 9262, Sec. 3', 'Study module Criminology, Chapter 3: Human Behavior and Victimology (CRIM-3.4).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-3.4', 'Evaluating') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-4.1_01', 'criminology', 'Professional Conduct and Ethical Standards for Criminologists', 'A criminologist lists a master''s degree he never earned in his application for a job. Which duty in the Code of Ethics does he violate?', '[{"text": "Demeanor toward professional colleagues", "is_correct": false, "rationale": "Demeanor toward colleagues concerns how he treats fellow criminologists."}, {"text": "Commitment to life-long learning", "is_correct": false, "rationale": "Life-long learning concerns continuing professional development."}, {"text": "Personal integrity and honesty", "is_correct": true, "rationale": "Chapter II, Section 3 requires integrity in all facets of life and prohibits misrepresenting one''s qualifications."}, {"text": "Respect for the laws on traffic", "is_correct": false, "rationale": "Traffic laws are unrelated to the facts."}]'::jsonb, 2, 'medium', 'Misrepresentation may also be a ground for administrative action under R.A. 11131.', 'Code of Ethical and Professional Conduct of Philippine Registered Criminologists (PRB Crim. Res. No. 07 s. 2024), Ch. II, Sec. 3', 'Study module Criminology, Chapter 4: Professional Conduct and Ethical Standards for Criminologists (CRIM-4.1).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-4.1', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-4.1_02', 'criminology', 'Professional Conduct and Ethical Standards for Criminologists', 'A criminologist working as a jail officer serves a friend''s relatives ahead of other visitors who were waiting. Which duty does he violate?', '[{"text": "Commitment to life-long learning", "is_correct": false, "rationale": "Life-long learning concerns professional development."}, {"text": "Public service without discrimination", "is_correct": true, "rationale": "Chapter II, Section 2 requires putting the public interest above personal interest and serving everyone promptly and without discrimination."}, {"text": "Demeanor toward professional colleagues", "is_correct": false, "rationale": "Demeanor concerns conduct toward fellow criminologists."}, {"text": "Advocacy for the criminology profession", "is_correct": false, "rationale": "Advocacy concerns protecting and promoting the profession."}]'::jsonb, 1, 'medium', 'Criminologists are expected to be role models in public service.', 'Code of Ethical and Professional Conduct of Philippine Registered Criminologists, Ch. II, Sec. 2', 'Study module Criminology, Chapter 4: Professional Conduct and Ethical Standards for Criminologists (CRIM-4.1).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-4.1', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-4.2_01', 'criminology', 'Professional Conduct and Ethical Standards for Criminologists', 'A criminologist posts insulting comments online about a fellow criminologist''s competence. Which duty does he violate?', '[{"text": "Personal integrity in handling clients'' money", "is_correct": false, "rationale": "Clients'' money is not involved."}, {"text": "Proper demeanor toward professional colleagues", "is_correct": true, "rationale": "Chapter III, Section 2 requires courtesy, fairness and candor toward colleagues, and prohibits abusive language and maligning them."}, {"text": "Respect for the Constitution and the laws", "is_correct": false, "rationale": "The act concerns conduct toward colleagues, not obedience to the Constitution."}, {"text": "Commitment to research and extension", "is_correct": false, "rationale": "Research and extension are not involved."}]'::jsonb, 1, 'medium', 'Disagreements should be raised through proper channels, not public insults.', 'Code of Ethical and Professional Conduct of Philippine Registered Criminologists, Ch. III, Sec. 2', 'Study module Criminology, Chapter 4: Professional Conduct and Ethical Standards for Criminologists (CRIM-4.2).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-4.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-4.2_02', 'criminology', 'Professional Conduct and Ethical Standards for Criminologists', 'Which act best shows a criminologist''s commitment to life-long learning under the Code?', '[{"text": "Repeating the same lectures for years without any update", "is_correct": false, "rationale": "Never updating ignores changes in laws and science."}, {"text": "Avoiding seminars once the board examination is passed", "is_correct": false, "rationale": "Learning continues after licensure."}, {"text": "Relying only on what was learned in college", "is_correct": false, "rationale": "College learning alone does not keep a professional current."}, {"text": "Completing CPD programs and earning specialized certifications", "is_correct": true, "rationale": "Chapter III, Section 3 calls for continuing professional development, re-skilling, up-skilling and specialized certification."}]'::jsonb, 3, 'medium', 'CPD is also tied to renewal of the professional license.', 'Code of Ethical and Professional Conduct of Philippine Registered Criminologists, Ch. III, Sec. 3; R.A. 10912 (CPD Act)', 'Study module Criminology, Chapter 4: Professional Conduct and Ethical Standards for Criminologists (CRIM-4.2).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-4.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-4.2_03', 'criminology', 'Professional Conduct and Ethical Standards for Criminologists', 'A criminologist learns that an unlicensed person is teaching professional criminology subjects while claiming to be licensed. What does the duty of advocacy require?', '[{"text": "Ignore it, since the person is not his student", "is_correct": false, "rationale": "Ignoring it lets illegal practice continue."}, {"text": "Report it to the proper authorities, such as the Board", "is_correct": true, "rationale": "Chapter III, Section 1 calls on criminologists to protect the profession from unqualified persons, through proper channels."}, {"text": "Join the person in teaching to share the workload", "is_correct": false, "rationale": "Joining would abet illegal practice."}, {"text": "Confront the person publicly on social media", "is_correct": false, "rationale": "Public confrontation is not the proper channel and may malign the person."}]'::jsonb, 1, 'hard', 'Illegal practice may be reported to the Board of Criminology and the PRC.', 'Code of Ethical and Professional Conduct of Philippine Registered Criminologists, Ch. III, Sec. 1; R.A. 11131', 'Study module Criminology, Chapter 4: Professional Conduct and Ethical Standards for Criminologists (CRIM-4.2).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-4.2', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-4.3_01', 'criminology', 'Professional Conduct and Ethical Standards for Criminologists', 'Under Chapter V of the Code, how are violations of Chapter IV (duties to clients) treated?', '[{"text": "As light offenses, punished by a warning only", "is_correct": false, "rationale": "They are not light offenses."}, {"text": "As criminal cases tried only by the Sandiganbayan", "is_correct": false, "rationale": "These are administrative offenses, without prejudice to other liabilities."}, {"text": "As grave offenses, punished by two years'' suspension or revocation", "is_correct": true, "rationale": "Chapter V, Section 1 makes violations of Chapter IV grave offenses, punishable by suspension for two years or revocation of the license."}, {"text": "As matters that are never punished", "is_correct": false, "rationale": "The Code provides penalties for them."}]'::jsonb, 2, 'easy', 'Other violations may be grave or less grave depending on their gravity.', 'Code of Ethical and Professional Conduct of Philippine Registered Criminologists, Ch. V, Sec. 1', 'Study module Criminology, Chapter 4: Professional Conduct and Ethical Standards for Criminologists (CRIM-4.3).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-4.3', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-4.3_02', 'criminology', 'Professional Conduct and Ethical Standards for Criminologists', 'A friend asks a criminologist in private practice for details of a client''s case. What should the criminologist do?', '[{"text": "Refuse, because client information must be kept in utmost confidence", "is_correct": true, "rationale": "Chapter IV, Section 1 requires utmost confidentiality in dealings with clients."}, {"text": "Share the details, since the friend promises to keep them secret", "is_correct": false, "rationale": "A promise of secrecy does not permit disclosure."}, {"text": "Share only the client''s name and address", "is_correct": false, "rationale": "Even partial details violate confidentiality."}, {"text": "Post a summary of the case online without names", "is_correct": false, "rationale": "Public posts risk identifying the client and breach confidence."}]'::jsonb, 0, 'medium', 'Confidentiality builds trust between the professional and the client.', 'Code of Ethical and Professional Conduct of Philippine Registered Criminologists, Ch. IV, Sec. 1', 'Study module Criminology, Chapter 4: Professional Conduct and Ethical Standards for Criminologists (CRIM-4.3).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-4.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-4.3_03', 'criminology', 'Professional Conduct and Ethical Standards for Criminologists', 'A criminologist works as a correctional officer. How does the Code require him to treat persons deprived of liberty?', '[{"text": "Harshly, so that they will not commit crimes again", "is_correct": false, "rationale": "Harsh treatment is contrary to the Code and to human rights."}, {"text": "Only as well as their families can pay for", "is_correct": false, "rationale": "Treatment cannot depend on payment."}, {"text": "According to the warden''s personal preferences", "is_correct": false, "rationale": "Treatment is governed by law and the Code, not personal preference."}, {"text": "Humanely, respecting their rights and dignity", "is_correct": true, "rationale": "Chapter IV, Section 1 calls for humane treatment of persons deprived of liberty in correctional institutions."}]'::jsonb, 3, 'medium', 'This duty matches the UN Standard Minimum Rules for the Treatment of Prisoners.', 'Code of Ethical and Professional Conduct of Philippine Registered Criminologists, Ch. IV, Sec. 1', 'Study module Criminology, Chapter 4: Professional Conduct and Ethical Standards for Criminologists (CRIM-4.3).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-4.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-4.3_04', 'criminology', 'Professional Conduct and Ethical Standards for Criminologists', 'A criminologist submits a research report that copies another author''s work without citation. Which provision does he violate?', '[{"text": "The duty to charge reasonable fees", "is_correct": false, "rationale": "Fees are not involved."}, {"text": "The rule on using another''s seal or badge", "is_correct": false, "rationale": "No seal or badge was used."}, {"text": "The prohibition against plagiarism", "is_correct": true, "rationale": "Chapter IV, Section 2 prohibits plagiarism, and Chapter III also bars researchers from plagiarizing."}, {"text": "The duty of respect for the Constitution", "is_correct": false, "rationale": "The act is plagiarism, not a constitutional violation."}]'::jsonb, 2, 'medium', 'Proper citation gives credit and lets readers verify sources.', 'Code of Ethical and Professional Conduct of Philippine Registered Criminologists, Ch. IV, Sec. 2', 'Study module Criminology, Chapter 4: Professional Conduct and Ethical Standards for Criminologists (CRIM-4.3).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-4.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-4.3_05', 'criminology', 'Professional Conduct and Ethical Standards for Criminologists', 'A criminologist keeps signing forensic reports even though his PIC expired months ago. What is wrong with this?', '[{"text": "Nothing, because his COR is still valid", "is_correct": false, "rationale": "A valid COR does not cure an expired PIC."}, {"text": "Nothing, as long as his reports are accurate", "is_correct": false, "rationale": "Accuracy does not cure unauthorized practice."}, {"text": "Practicing with an expired PIC is prohibited by the Code", "is_correct": true, "rationale": "Chapter IV, Section 2 prohibits practicing with an expired, suspended or revoked COR, PIC or permit."}, {"text": "It is wrong only if a client complains", "is_correct": false, "rationale": "The violation exists without any complaint."}]'::jsonb, 2, 'medium', 'The PIC is renewed with CPD compliance and a Certificate of Good Standing from the AIPO.', 'Code of Ethical and Professional Conduct of Philippine Registered Criminologists, Ch. IV, Sec. 2', 'Study module Criminology, Chapter 4: Professional Conduct and Ethical Standards for Criminologists (CRIM-4.3).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-4.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-4.3_06', 'criminology', 'Professional Conduct and Ethical Standards for Criminologists', 'A criminologist lets his assistant, who is not a criminologist, conduct examinations reserved for criminologists under his name. Which rule does this violate?', '[{"text": "The duty to join professional organizations", "is_correct": false, "rationale": "Organizational membership is not the issue."}, {"text": "The duty to report to the Board every month", "is_correct": false, "rationale": "There is no monthly reporting duty involved."}, {"text": "The bar on delegating tasks to non-criminologists", "is_correct": true, "rationale": "Chapter IV, Section 2 prohibits delegating exclusively criminological tasks to non-criminologists."}, {"text": "The rule on reasonable fees for clients", "is_correct": false, "rationale": "Fees are not involved."}]'::jsonb, 2, 'medium', 'This also amounts to abetting illegal practice of the profession.', 'Code of Ethical and Professional Conduct of Philippine Registered Criminologists, Ch. IV, Sec. 2', 'Study module Criminology, Chapter 4: Professional Conduct and Ethical Standards for Criminologists (CRIM-4.3).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-4.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-4.3_07', 'criminology', 'Professional Conduct and Ethical Standards for Criminologists', 'A criminologist is asked to act as private investigator for both the complainant and the accused in the same case. Why should he decline one of them?', '[{"text": "He may serve both if each pays the full fee", "is_correct": false, "rationale": "Fees do not cure a conflict of interest."}, {"text": "He must serve both, since refusing clients is unethical", "is_correct": false, "rationale": "Declining a client is proper where a conflict exists."}, {"text": "Serving both sides creates a conflict of interest", "is_correct": true, "rationale": "The Code prohibits conflicts of interest; loyalty to one client would compromise duties to the other."}, {"text": "He may serve both if he keeps their reports separate", "is_correct": false, "rationale": "Separate reports do not remove the conflict."}]'::jsonb, 2, 'hard', 'Avoiding even the appearance of impropriety is part of personal integrity.', 'Code of Ethical and Professional Conduct of Philippine Registered Criminologists, Chs. II-IV', 'Study module Criminology, Chapter 4: Professional Conduct and Ethical Standards for Criminologists (CRIM-4.3).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-4.3', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-4.4_01', 'criminology', 'Professional Conduct and Ethical Standards for Criminologists', 'Why are human rights described as inherent?', '[{"text": "They are granted only to citizens who obey the law", "is_correct": false, "rationale": "Rights belong to everyone, including those accused of crimes."}, {"text": "They can be bought and sold like property", "is_correct": false, "rationale": "Inalienable rights cannot be bought or sold."}, {"text": "They belong to every person simply by being human", "is_correct": true, "rationale": "Human rights are inherent, universal and inalienable; the State recognizes and protects them."}, {"text": "They exist only when written in a contract", "is_correct": false, "rationale": "They exist independently of contracts."}]'::jsonb, 2, 'easy', 'The Universal Declaration of Human Rights (1948) states these principles.', '1987 Constitution, Art. II, Sec. 11; Art. III', 'Study module Criminology, Chapter 4: Professional Conduct and Ethical Standards for Criminologists (CRIM-4.4).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-4.4', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-4.4_02', 'criminology', 'Professional Conduct and Ethical Standards for Criminologists', 'During a state of emergency, a commander suggests torturing terrorism suspects to get information. How should this be assessed?', '[{"text": "Allowed, because emergencies suspend all rights", "is_correct": false, "rationale": "Some rights may be limited in emergencies, but freedom from torture is not one of them."}, {"text": "Allowed, if the President approves it in writing", "is_correct": false, "rationale": "No approval makes torture lawful."}, {"text": "Not allowed; freedom from torture is non-derogable", "is_correct": true, "rationale": "The right to be free from torture can never be suspended; R.A. 9745 makes it absolute."}, {"text": "Allowed, but only against foreign suspects", "is_correct": false, "rationale": "The right protects everyone, regardless of nationality."}]'::jsonb, 2, 'medium', 'No exceptional circumstance, such as war or emergency, justifies torture.', 'R.A. 9745, Sec. 6; UN Convention against Torture', 'Study module Criminology, Chapter 4: Professional Conduct and Ethical Standards for Criminologists (CRIM-4.4).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-4.4', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-4.4_03', 'criminology', 'Professional Conduct and Ethical Standards for Criminologists', 'An unarmed shoplifter runs away from an officer. May the officer shoot him to stop the escape?', '[{"text": "Yes; any fleeing suspect may be shot", "is_correct": false, "rationale": "Fleeing alone does not justify deadly force."}, {"text": "Yes; if the stolen item is expensive", "is_correct": false, "rationale": "Property value does not justify taking a life."}, {"text": "No; force must be necessary and proportionate to the threat", "is_correct": true, "rationale": "The UN Code of Conduct for Law Enforcement Officials allows force only when strictly necessary and to the extent required; firearms are for threats to life."}, {"text": "No; officers may never use any force at all", "is_correct": false, "rationale": "Reasonable force may be used when necessary; deadly force is the issue here."}]'::jsonb, 2, 'medium', 'The PNP Operational Procedures follow the same principles of necessity and proportionality.', 'UN Code of Conduct for Law Enforcement Officials (1979), Art. 3', 'Study module Criminology, Chapter 4: Professional Conduct and Ethical Standards for Criminologists (CRIM-4.4).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-4.4', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-5.1_01', 'criminology', 'Juvenile Delinquency and Juvenile Justice', 'Why is adolescence a high-risk period for delinquency?', '[{"text": "Teens are forming identities, value peer approval and take more risks", "is_correct": true, "rationale": "Identity formation, strong peer influence and risk-taking make adolescence the peak period of offending."}, {"text": "Teens are no longer influenced by their friends", "is_correct": false, "rationale": "Peer influence is strongest in adolescence."}, {"text": "Teens have the most money and fewest needs", "is_correct": false, "rationale": "Adolescents usually have limited resources."}, {"text": "The law punishes adolescents more severely than adults", "is_correct": false, "rationale": "Juvenile justice law treats adolescents more leniently than adults."}]'::jsonb, 0, 'easy', 'Most adolescents who offend stop as they mature, which supports diversion.', NULL, 'Study module Criminology, Chapter 5: Juvenile Delinquency and Juvenile Justice (CRIM-5.1).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-5.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-5.1_02', 'criminology', 'Juvenile Delinquency and Juvenile Justice', 'Why do boys commit more delinquent acts than girls in most studies?', '[{"text": "Girls are never punished for any offense they commit", "is_correct": false, "rationale": "Girls are held accountable for offenses."}, {"text": "Differences in socialization and parental control of boys and girls", "is_correct": true, "rationale": "Theories such as Hagan''s power-control theory explain the gap by how boys and girls are raised and supervised."}, {"text": "Boys are born with criminal genes that girls lack", "is_correct": false, "rationale": "There is no ''criminal gene'' that only boys have."}, {"text": "Girls do not experience peer pressure at all", "is_correct": false, "rationale": "Girls experience peer pressure too."}]'::jsonb, 1, 'easy', 'Female delinquency has its own patterns and needs gender-responsive programs.', NULL, 'Study module Criminology, Chapter 5: Juvenile Delinquency and Juvenile Justice (CRIM-5.1).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-5.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-5.1_03', 'criminology', 'Juvenile Delinquency and Juvenile Justice', 'Two poor families live in the same area. One child is closely supervised by consistent parents, while the other is left alone most of the day. Which child is at lower risk, and why?', '[{"text": "The unsupervised child, because independence builds discipline", "is_correct": false, "rationale": "Lack of supervision increases opportunities for delinquency."}, {"text": "The supervised child, because parental monitoring protects against delinquency", "is_correct": true, "rationale": "Research consistently finds parental supervision and consistent discipline to be protective factors."}, {"text": "Both equally, because poverty alone decides delinquency", "is_correct": false, "rationale": "Poverty is a risk factor, but family factors change its effect."}, {"text": "Neither, because family has no effect on delinquency", "is_correct": false, "rationale": "Family is among the strongest influences on delinquency."}]'::jsonb, 1, 'hard', 'Family support programs aim to strengthen parenting.', NULL, 'Study module Criminology, Chapter 5: Juvenile Delinquency and Juvenile Justice (CRIM-5.1).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-5.1', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-5.1_04', 'criminology', 'Juvenile Delinquency and Juvenile Justice', 'A student keeps failing and is often suspended from school. Why does this raise his risk of delinquency?', '[{"text": "Suspension always makes students study harder at home", "is_correct": false, "rationale": "Suspension often reduces engagement rather than increasing study."}, {"text": "It weakens his bond to school and leaves him unsupervised with risky peers", "is_correct": true, "rationale": "Hirschi''s social bond theory links weak attachment and commitment to school with delinquency; suspension adds unsupervised time."}, {"text": "School failure has no link with behavior outside school", "is_correct": false, "rationale": "School problems and delinquency are strongly linked."}, {"text": "Suspended students are legally required to work", "is_correct": false, "rationale": "No such legal requirement exists."}]'::jsonb, 1, 'hard', 'Schools can reduce risk with support programs instead of exclusion alone.', NULL, 'Study module Criminology, Chapter 5: Juvenile Delinquency and Juvenile Justice (CRIM-5.1).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-5.1', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-5.2_01', 'criminology', 'Juvenile Delinquency and Juvenile Justice', 'Under P.D. 603, who have the primary right and duty to rear and care for the child?', '[{"text": "The barangay officials", "is_correct": false, "rationale": "Barangays support child welfare but are not primarily responsible."}, {"text": "The child''s teachers", "is_correct": false, "rationale": "Teachers share in education but are not primarily responsible."}, {"text": "The police in the child''s area", "is_correct": false, "rationale": "Police protect children but do not rear them."}, {"text": "The child''s parents", "is_correct": true, "rationale": "P.D. 603 recognizes that parents have the natural right and duty to care for and rear their children."}]'::jsonb, 3, 'easy', 'The State steps in when parents fail in their duties.', 'P.D. 603 (Child and Youth Welfare Code)', 'Study module Criminology, Chapter 5: Juvenile Delinquency and Juvenile Justice (CRIM-5.2).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-5.2', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-5.2_02', 'criminology', 'Juvenile Delinquency and Juvenile Justice', 'A factory hires a 13-year-old as a full-time helper, keeping her out of school. Is this allowed?', '[{"text": "Yes, if her parents consent to the employment", "is_correct": false, "rationale": "Parental consent does not make factory work lawful."}, {"text": "Yes, if she is paid the minimum wage", "is_correct": false, "rationale": "Paying wages does not cure the prohibition."}, {"text": "No; children below 15 may work only in narrow exceptions", "is_correct": true, "rationale": "R.A. 7610, as amended by R.A. 7658 and R.A. 9231, prohibits employing children below 15, except in specific cases that do not harm their schooling and development."}, {"text": "No, but only because she is a girl", "is_correct": false, "rationale": "The rule applies to all children, boys and girls."}]'::jsonb, 2, 'medium', 'The exceptions include work under the sole responsibility of parents with only family members employed, and certain public entertainment with permits.', 'R.A. 7610, Sec. 12, as amended by R.A. 7658 and R.A. 9231', 'Study module Criminology, Chapter 5: Juvenile Delinquency and Juvenile Justice (CRIM-5.2).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-5.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-5.2_03', 'criminology', 'Juvenile Delinquency and Juvenile Justice', 'A teacher repeatedly beats and humiliates a student in front of the class. Which law applies?', '[{"text": "R.A. 9344, which covers children in conflict with the law", "is_correct": false, "rationale": "R.A. 9344 deals with children who commit offenses."}, {"text": "R.A. 7610, which punishes child abuse and cruelty", "is_correct": true, "rationale": "R.A. 7610 punishes physical and psychological abuse and cruelty that debase a child''s dignity."}, {"text": "R.A. 7658, which covers child labor", "is_correct": false, "rationale": "R.A. 7658 deals with employment of children."}, {"text": "P.D. 1612, which covers stolen goods", "is_correct": false, "rationale": "P.D. 1612 deals with fencing."}]'::jsonb, 1, 'medium', 'Corporal punishment in schools is also contrary to school rules and child protection policies.', 'R.A. 7610, Secs. 3 and 10', 'Study module Criminology, Chapter 5: Juvenile Delinquency and Juvenile Justice (CRIM-5.2).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-5.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-5.3_01', 'criminology', 'Juvenile Delinquency and Juvenile Justice', 'Why is a child aged 15 or below exempt from criminal liability under R.A. 9344?', '[{"text": "Children of that age cannot commit any harmful act", "is_correct": false, "rationale": "Children can cause harm; the law addresses them through intervention."}, {"text": "The law requires such children to be tried as adults", "is_correct": false, "rationale": "Children are not tried as adults under the law."}, {"text": "The law sets 15 as the minimum age of responsibility", "is_correct": true, "rationale": "R.A. 9344 sets the minimum age of criminal responsibility at 15; children at or below it are exempt but go through intervention programs, and civil liability remains."}, {"text": "Children of that age are exempt only from fines", "is_correct": false, "rationale": "The exemption covers criminal liability, not just fines."}]'::jsonb, 2, 'easy', 'Children above 15 but below 18 are exempt unless they acted with discernment.', 'R.A. 9344, Sec. 6, as amended by R.A. 10630', 'Study module Criminology, Chapter 5: Juvenile Delinquency and Juvenile Justice (CRIM-5.3).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-5.3', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-5.3_02', 'criminology', 'Juvenile Delinquency and Juvenile Justice', 'Police apprehend a 14-year-old for theft. What must they do?', '[{"text": "Detain him in the city jail with adult detainees", "is_correct": false, "rationale": "Children must never be held with adults."}, {"text": "File a criminal case against him in the RTC", "is_correct": false, "rationale": "A child aged 15 or below is exempt from criminal liability."}, {"text": "Release him without informing his parents", "is_correct": false, "rationale": "Parents and the social worker must be notified."}, {"text": "Turn him over to the social welfare office within 8 hours", "is_correct": true, "rationale": "R.A. 9344 requires the officer to turn over custody to the local social welfare and development office or an accredited NGO within 8 hours, and to notify his parents."}]'::jsonb, 3, 'medium', 'At initial contact, officers must also explain the reason for custody in simple language and avoid handcuffs unless absolutely necessary.', 'R.A. 9344, Sec. 21, as amended by R.A. 10630', 'Study module Criminology, Chapter 5: Juvenile Delinquency and Juvenile Justice (CRIM-5.3).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-5.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-5.4_01', 'criminology', 'Juvenile Delinquency and Juvenile Justice', 'A 16-year-old who acted with discernment committed theft punishable by less than six years, and the victim is known. Who may handle diversion?', '[{"text": "Only the Regional Trial Court after a full trial", "is_correct": false, "rationale": "Court diversion is required only for offenses punishable by more than six years."}, {"text": "The Punong Barangay or police, with the social worker", "is_correct": true, "rationale": "For offenses punishable by not more than six years, diversion may be done at the barangay or police level, with the social welfare officer, through mediation, family conferencing and conciliation."}, {"text": "Only the Bureau of Corrections", "is_correct": false, "rationale": "BuCor handles adult prisoners."}, {"text": "No one, because diversion is not allowed for theft", "is_correct": false, "rationale": "Theft is a diversionable offense."}]'::jsonb, 1, 'medium', 'Diversion keeps the child out of the formal justice system while ensuring accountability.', 'R.A. 9344, Sec. 23, as amended by R.A. 10630', 'Study module Criminology, Chapter 5: Juvenile Delinquency and Juvenile Justice (CRIM-5.4).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-5.4', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-5.4_02', 'criminology', 'Juvenile Delinquency and Juvenile Justice', 'A 17-year-old who acted with discernment committed an offense punishable by more than six years. Where may diversion take place?', '[{"text": "At the barangay hall", "is_correct": false, "rationale": "Barangay-level diversion is for lighter offenses."}, {"text": "At the police station", "is_correct": false, "rationale": "Police-level diversion is for lighter offenses."}, {"text": "At the child''s school", "is_correct": false, "rationale": "Schools do not conduct legal diversion."}, {"text": "Only in court", "is_correct": true, "rationale": "Where the imposable penalty exceeds six years, diversion measures may be resorted to only by the court."}]'::jsonb, 3, 'medium', 'The court may still order a diversion program instead of trial.', 'R.A. 9344, Sec. 23(c), as amended by R.A. 10630', 'Study module Criminology, Chapter 5: Juvenile Delinquency and Juvenile Justice (CRIM-5.4).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-5.4', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-5.4_03', 'criminology', 'Juvenile Delinquency and Juvenile Justice', 'A 14-year-old is found outside after the city curfew. How should he be handled?', '[{"text": "Fined and detained overnight at the police station", "is_correct": false, "rationale": "Fining and detaining the child would be a punishment."}, {"text": "Charged in court for violating the ordinance", "is_correct": false, "rationale": "Status offenses by children are not prosecuted."}, {"text": "Placed in jail with adult curfew violators", "is_correct": false, "rationale": "Children must never be jailed with adults."}, {"text": "Brought home or referred to social welfare, unpunished", "is_correct": true, "rationale": "R.A. 9344 bars punishing children for status offenses such as curfew violations; ordinances may provide only for intervention."}]'::jsonb, 3, 'medium', 'Curfew enforcement for children focuses on their safety and on involving parents.', 'R.A. 9344, Secs. 57 and 57-A, as amended by R.A. 10630', 'Study module Criminology, Chapter 5: Juvenile Delinquency and Juvenile Justice (CRIM-5.4).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-5.4', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-5.5_01', 'criminology', 'Juvenile Delinquency and Juvenile Justice', 'What is a Bahay Pag-asa?', '[{"text": "A national penitentiary for young adult offenders", "is_correct": false, "rationale": "Children are not placed in penitentiaries."}, {"text": "A school for children who want to become police officers", "is_correct": false, "rationale": "It is not a training school for police."}, {"text": "A shelter for adult victims of domestic violence", "is_correct": false, "rationale": "Shelters for adult victims are separate facilities."}, {"text": "A 24-hour child-caring facility for children in conflict with the law", "is_correct": true, "rationale": "R.A. 10630 requires provinces and highly urbanized cities to establish Bahay Pag-asa, run by the LGU, for CICL who need care and rehabilitation."}]'::jsonb, 3, 'easy', 'Each Bahay Pag-asa has an Intensive Juvenile Intervention and Support Center for children who need intensive care.', 'R.A. 9344, Sec. 4(b), as amended by R.A. 10630', 'Study module Criminology, Chapter 5: Juvenile Delinquency and Juvenile Justice (CRIM-5.5).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-5.5', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-5.5_02', 'criminology', 'Juvenile Delinquency and Juvenile Justice', 'A 14-year-old committed rape. How does R.A. 9344, as amended, require him to be handled?', '[{"text": "As a neglected child placed in the IJISC of a Bahay Pag-asa", "is_correct": true, "rationale": "R.A. 10630 deems a child above 12 up to 15 who commits serious crimes such as rape a neglected child, mandatorily placed in the Intensive Juvenile Intervention and Support Center."}, {"text": "As an adult offender detained in the city jail", "is_correct": false, "rationale": "Children are never treated as adult offenders under the law."}, {"text": "As a free child released to his parents without conditions", "is_correct": false, "rationale": "The law requires intensive intervention for such serious offenses."}, {"text": "As a convict sent to the Bureau of Corrections", "is_correct": false, "rationale": "Children are not sent to BuCor."}]'::jsonb, 0, 'medium', 'Other serious crimes covered include parricide, murder, infanticide and destructive arson.', 'R.A. 9344, Sec. 20-A, as amended by R.A. 10630', 'Study module Criminology, Chapter 5: Juvenile Delinquency and Juvenile Justice (CRIM-5.5).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-5.5', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-5.5_03', 'criminology', 'Juvenile Delinquency and Juvenile Justice', 'A 17-year-old is found guilty of robbery. What happens to his sentence under R.A. 9344?', '[{"text": "He is sent at once to the national penitentiary", "is_correct": false, "rationale": "CICL are not sent to penitentiaries."}, {"text": "He is fined and released with no further program", "is_correct": false, "rationale": "The law requires a rehabilitation program."}, {"text": "His case is dismissed as if it never happened", "is_correct": false, "rationale": "The finding of guilt remains; the sentence is suspended."}, {"text": "It is automatically suspended, and he undergoes rehabilitation", "is_correct": true, "rationale": "The court automatically suspends the sentence of a CICL found guilty and places him in a rehabilitation program, even if he is 18 or older at pronouncement."}]'::jsonb, 3, 'medium', 'Suspension may continue until the child turns 21, after which the court decides on discharge or execution.', 'R.A. 9344, Secs. 38 and 40', 'Study module Criminology, Chapter 5: Juvenile Delinquency and Juvenile Justice (CRIM-5.5).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-5.5', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-6.1_01', 'criminology', 'Dispute Resolution and Crisis/Incident Management', 'How does mediation differ from arbitration?', '[{"text": "A mediator makes a binding award; an arbitrator only gives advice", "is_correct": false, "rationale": "This reverses their roles."}, {"text": "A mediator helps the parties settle; an arbitrator makes a binding award", "is_correct": true, "rationale": "In mediation the parties make their own agreement with the mediator''s help; in arbitration a neutral decides the dispute with a binding award."}, {"text": "Mediation happens only in court; arbitration only in barangays", "is_correct": false, "rationale": "Both can happen outside court, and courts also use mediation."}, {"text": "Mediation needs lawyers; arbitration forbids them", "is_correct": false, "rationale": "Lawyers may take part in both."}]'::jsonb, 1, 'easy', 'R.A. 9285 institutionalized alternative dispute resolution in the Philippines.', 'R.A. 9285 (Alternative Dispute Resolution Act of 2004)', 'Study module Criminology, Chapter 6: Dispute Resolution and Crisis/Incident Management (CRIM-6.1).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-6.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-6.1_02', 'criminology', 'Dispute Resolution and Crisis/Incident Management', 'What is early neutral evaluation?', '[{"text": "A judge decides the case right after it is filed", "is_correct": false, "rationale": "No judgment is rendered in ENE."}, {"text": "A neutral person gives a non-binding view of each side''s case", "is_correct": true, "rationale": "In early neutral evaluation, a neutral third person assesses the strengths and weaknesses of each side to help them settle."}, {"text": "A police officer evaluates the suspect''s guilt", "is_correct": false, "rationale": "Police do not evaluate guilt for settlement."}, {"text": "A jury votes on the case before trial", "is_correct": false, "rationale": "There are no juries in Philippine courts."}]'::jsonb, 1, 'easy', 'ENE helps parties see their case realistically.', 'R.A. 9285, Sec. 3', 'Study module Criminology, Chapter 6: Dispute Resolution and Crisis/Incident Management (CRIM-6.1).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-6.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-6.1_03', 'criminology', 'Dispute Resolution and Crisis/Incident Management', 'Two residents of the same barangay fail to settle their dispute through the Lupon chairman''s mediation within 15 days. What happens next?', '[{"text": "A Pangkat ng Tagapagkasundo is formed to conciliate", "is_correct": true, "rationale": "Under R.A. 7160, if mediation by the Lupon chairman fails, a Pangkat ng Tagapagkasundo is constituted to conciliate the dispute."}, {"text": "The case goes straight to the Supreme Court", "is_correct": false, "rationale": "Disputes go through conciliation before any court."}, {"text": "The dispute is automatically dismissed", "is_correct": false, "rationale": "Failure of mediation leads to conciliation, not dismissal."}, {"text": "The Punong Barangay renders a final judgment", "is_correct": false, "rationale": "The Punong Barangay mediates; he does not render judgment."}]'::jsonb, 0, 'medium', 'If conciliation fails, a certification to file action is issued.', 'R.A. 7160, Secs. 410-412', 'Study module Criminology, Chapter 6: Dispute Resolution and Crisis/Incident Management (CRIM-6.1).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-6.1', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-6.1_04', 'criminology', 'Dispute Resolution and Crisis/Incident Management', 'A land dispute arises between members of an indigenous cultural community. How may it be settled?', '[{"text": "Only through a full trial in the Regional Trial Court", "is_correct": false, "rationale": "Courts are not the only forum for such disputes."}, {"text": "Only by the Philippine National Police", "is_correct": false, "rationale": "Police do not decide land disputes."}, {"text": "Only through arbitration abroad", "is_correct": false, "rationale": "Foreign arbitration is not required."}, {"text": "Through their customary laws and practices of dispute resolution", "is_correct": true, "rationale": "The law recognizes indigenous modes of settling disputes among members of indigenous communities."}]'::jsonb, 3, 'medium', 'The Local Government Code and R.A. 8371 recognize customary dispute resolution.', 'R.A. 7160, Sec. 399(f); R.A. 8371', 'Study module Criminology, Chapter 6: Dispute Resolution and Crisis/Incident Management (CRIM-6.1).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-6.1', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-6.1_05', 'criminology', 'Dispute Resolution and Crisis/Incident Management', 'Two companies want an expert they both choose to decide their dispute privately with a binding award. Which mode of ADR fits?', '[{"text": "Mediation", "is_correct": false, "rationale": "Mediation does not produce a binding decision by the mediator."}, {"text": "Arbitration", "is_correct": true, "rationale": "Arbitration gives a binding award by a chosen neutral."}, {"text": "Early neutral evaluation", "is_correct": false, "rationale": "Early neutral evaluation gives a non-binding assessment."}, {"text": "Mini-trial", "is_correct": false, "rationale": "A mini-trial presents the case to party representatives for settlement, not a binding award."}]'::jsonb, 1, 'medium', 'Arbitral awards may be confirmed and enforced by courts.', 'R.A. 9285', 'Study module Criminology, Chapter 6: Dispute Resolution and Crisis/Incident Management (CRIM-6.1).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-6.1', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-6.2_01', 'criminology', 'Dispute Resolution and Crisis/Incident Management', 'Police first responders arrive at a hostage-taking in a house. What should they do first?', '[{"text": "Storm the house at once to rescue the hostages", "is_correct": false, "rationale": "An immediate assault endangers the hostages."}, {"text": "Give the hostage-taker whatever he demands", "is_correct": false, "rationale": "Demands are handled by trained negotiators, and some are never granted."}, {"text": "Let the media interview the hostage-taker", "is_correct": false, "rationale": "Media access can inflame the situation and reveal police positions."}, {"text": "Contain and isolate the area for trained negotiators", "is_correct": true, "rationale": "First responders contain the scene, isolate it, evacuate bystanders and gather information until the crisis team arrives."}]'::jsonb, 3, 'medium', 'Time usually favors the negotiators in hostage situations.', 'PNP Critical Incident Management Operational Procedures', 'Study module Criminology, Chapter 6: Dispute Resolution and Crisis/Incident Management (CRIM-6.2).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-6.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-6.2_02', 'criminology', 'Dispute Resolution and Crisis/Incident Management', 'A hostage-taker demands a firearm in exchange for releasing one hostage. How should the negotiator respond?', '[{"text": "Refuse, since weapons are never negotiable", "is_correct": true, "rationale": "Weapons and ammunition are non-negotiable items, since they increase danger."}, {"text": "Agree, since one hostage would be freed", "is_correct": false, "rationale": "Giving a weapon can endanger the remaining hostages and responders."}, {"text": "Agree, but give an unloaded firearm", "is_correct": false, "rationale": "Any firearm is dangerous and still non-negotiable."}, {"text": "Refuse and end all negotiations", "is_correct": false, "rationale": "Negotiations continue on other matters."}]'::jsonb, 0, 'medium', 'Food, water and communication are commonly negotiable; weapons, release of prisoners and exchange of hostages are not.', NULL, 'Study module Criminology, Chapter 6: Dispute Resolution and Crisis/Incident Management (CRIM-6.2).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-6.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-6.2_03', 'criminology', 'Dispute Resolution and Crisis/Incident Management', 'A desk officer receives a phone call saying a bomb will explode in a mall. What should he do while on the line?', '[{"text": "Hang up at once to keep the line free", "is_correct": false, "rationale": "Hanging up loses valuable information."}, {"text": "Keep the caller talking and note the voice, words and background sounds", "is_correct": true, "rationale": "A bomb threat checklist guides officers to gather details on the bomb, the caller and the background while keeping the caller talking."}, {"text": "Argue with the caller that bomb threats are illegal", "is_correct": false, "rationale": "Arguing does not help and may end the call."}, {"text": "Wait until the call ends before writing anything", "is_correct": false, "rationale": "Details should be noted during the call while they are fresh."}]'::jsonb, 1, 'medium', 'The information is passed to the bomb disposal unit and the mall security.', NULL, 'Study module Criminology, Chapter 6: Dispute Resolution and Crisis/Incident Management (CRIM-6.2).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-6.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-6.2_04', 'criminology', 'Dispute Resolution and Crisis/Incident Management', 'Officers respond to a loud domestic quarrel. How should they handle the parties?', '[{"text": "Interview both together in the same room", "is_correct": false, "rationale": "Joint interviews often escalate the conflict."}, {"text": "Leave once the shouting stops", "is_correct": false, "rationale": "Leaving without assessing the situation may leave a victim in danger."}, {"text": "Separate them and talk with each one apart", "is_correct": true, "rationale": "Separating the parties reduces tension and allows each to speak freely, while officers check for injuries and weapons."}, {"text": "Take the side of the party who called the police", "is_correct": false, "rationale": "Officers must remain impartial and gather facts."}]'::jsonb, 2, 'medium', 'Where there is violence against women or children, R.A. 9262 applies.', 'R.A. 9262', 'Study module Criminology, Chapter 6: Dispute Resolution and Crisis/Incident Management (CRIM-6.2).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-6.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-6.2_05', 'criminology', 'Dispute Resolution and Crisis/Incident Management', 'Why are responders told not to use radios or cellphones near a suspected bomb?', '[{"text": "Radios make the bomb disposal team''s work slower", "is_correct": false, "rationale": "The danger is detonation, not delay."}, {"text": "Cellphones record evidence that can be used against the police", "is_correct": false, "rationale": "Recording evidence is not the reason for the rule."}, {"text": "Radio use near bombs is only a matter of courtesy", "is_correct": false, "rationale": "The rule concerns safety, not courtesy."}, {"text": "Radio signals may set off an electrically initiated device", "is_correct": true, "rationale": "Some devices are triggered by radio frequencies, so transmitting nearby can cause detonation."}]'::jsonb, 3, 'hard', 'A safe distance is kept, and communications are made from outside the danger area.', NULL, 'Study module Criminology, Chapter 6: Dispute Resolution and Crisis/Incident Management (CRIM-6.2).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-6.2', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-6.3_01', 'criminology', 'Dispute Resolution and Crisis/Incident Management', 'In PNP critical incident management, which phases belong to the proactive stage?', '[{"text": "Prediction, prevention and preparation", "is_correct": true, "rationale": "The proactive stage covers prediction, prevention and preparation before an incident."}, {"text": "Initial action, action and post-action", "is_correct": false, "rationale": "Initial action, action and post-action are the reactive stage."}, {"text": "Arrest, booking and filing of the case", "is_correct": false, "rationale": "Arrest and booking are police procedures, not stages of crisis management."}, {"text": "Negotiation, assault and debriefing", "is_correct": false, "rationale": "These are activities that may happen during a response, not the proactive stage."}]'::jsonb, 0, 'easy', 'Critical incident management has a proactive and a reactive stage.', 'PNP Critical Incident Management Operational Procedures', 'Study module Criminology, Chapter 6: Dispute Resolution and Crisis/Incident Management (CRIM-6.3).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-6.3', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-6.3_02', 'criminology', 'Dispute Resolution and Crisis/Incident Management', 'Before a big festival, police gather intelligence and assess the risk of a terrorist attack. Which phase of critical incident management is this?', '[{"text": "Prediction", "is_correct": true, "rationale": "Prediction anticipates possible incidents through intelligence and risk assessment."}, {"text": "Prevention", "is_correct": false, "rationale": "Prevention takes steps to stop incidents, based on the prediction."}, {"text": "Initial action", "is_correct": false, "rationale": "Initial action is the first response after an incident happens."}, {"text": "Post-action", "is_correct": false, "rationale": "Post-action follows the resolution of an incident."}]'::jsonb, 0, 'medium', 'Good prediction guides prevention and preparation.', NULL, 'Study module Criminology, Chapter 6: Dispute Resolution and Crisis/Incident Management (CRIM-6.3).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-6.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-6.3_03', 'criminology', 'Dispute Resolution and Crisis/Incident Management', 'Police organize a crisis management committee, train responders and hold simulation exercises. Which phase is this?', '[{"text": "Prediction", "is_correct": false, "rationale": "Prediction is the assessment of possible incidents."}, {"text": "Action", "is_correct": false, "rationale": "The action phase is the actual response to an incident."}, {"text": "Preparation", "is_correct": true, "rationale": "Preparation builds the organization, plans and skills needed to respond."}, {"text": "Post-action", "is_correct": false, "rationale": "Post-action follows the incident."}]'::jsonb, 2, 'medium', 'Simulation exercises test plans before a real incident.', NULL, 'Study module Criminology, Chapter 6: Dispute Resolution and Crisis/Incident Management (CRIM-6.3).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-6.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-6.3_04', 'criminology', 'Dispute Resolution and Crisis/Incident Management', 'Patrol officers arrive first at a bombing site; they report, cordon the area and help the injured. Which phase is this?', '[{"text": "Initial action", "is_correct": true, "rationale": "Initial action is the first response to contain the situation and report it."}, {"text": "Preparation", "is_correct": false, "rationale": "Preparation happens before incidents."}, {"text": "Prediction", "is_correct": false, "rationale": "Prediction happens before incidents."}, {"text": "Post-action", "is_correct": false, "rationale": "Post-action follows resolution."}]'::jsonb, 0, 'medium', 'The crisis management committee takes over during the action phase.', NULL, 'Study module Criminology, Chapter 6: Dispute Resolution and Crisis/Incident Management (CRIM-6.3).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-6.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-6.3_05', 'criminology', 'Dispute Resolution and Crisis/Incident Management', 'After a hostage incident is resolved, the team holds debriefings, documents the incident and critiques its response. Which phase is this?', '[{"text": "Initial action", "is_correct": false, "rationale": "Initial action is the first response."}, {"text": "Post-action", "is_correct": true, "rationale": "Post-action covers debriefing, documentation, evaluation and lessons learned."}, {"text": "Prevention", "is_correct": false, "rationale": "Prevention takes place before incidents."}, {"text": "Preparation", "is_correct": false, "rationale": "Preparation takes place before incidents."}]'::jsonb, 1, 'medium', 'Lessons learned feed back into future preparation.', NULL, 'Study module Criminology, Chapter 6: Dispute Resolution and Crisis/Incident Management (CRIM-6.3).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-6.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-7.1_01', 'criminology', 'Criminological Research 1 and 2', 'What does a descriptive study aim to do?', '[{"text": "Describe the characteristics of a group or situation as it is", "is_correct": true, "rationale": "Descriptive research describes ''what is'', such as the profile of offenders in a jail."}, {"text": "Prove that one variable causes another", "is_correct": false, "rationale": "Proving causation requires experimental designs."}, {"text": "Explore the lived experiences of a few persons in depth", "is_correct": false, "rationale": "Exploring lived experiences is phenomenology."}, {"text": "Test a treatment by randomly assigning participants", "is_correct": false, "rationale": "Random assignment of treatments is an experiment."}]'::jsonb, 0, 'easy', 'Surveys are a common method in descriptive studies.', NULL, 'Study module Criminology, Chapter 7: Criminological Research 1 and 2 (CRIM-7.1).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-7.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-7.1_02', 'criminology', 'Criminological Research 1 and 2', 'What does a correlational study measure?', '[{"text": "The cause of a crime, by controlling all other factors", "is_correct": false, "rationale": "Controlling factors to show cause is experimental research."}, {"text": "The life story of a single offender", "is_correct": false, "rationale": "One person''s life story is a case study."}, {"text": "The relationship between variables, without manipulating them", "is_correct": true, "rationale": "Correlational research measures how strongly variables move together."}, {"text": "The meaning that participants give to their experiences", "is_correct": false, "rationale": "Meanings of experiences are the focus of phenomenology."}]'::jsonb, 2, 'easy', 'Correlation coefficients range from -1 to +1.', NULL, 'Study module Criminology, Chapter 7: Criminological Research 1 and 2 (CRIM-7.1).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-7.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-7.1_03', 'criminology', 'Criminological Research 1 and 2', 'What is the focus of a phenomenological study?', '[{"text": "The lived experiences of participants and the meanings they give them", "is_correct": true, "rationale": "Phenomenology explores how people experience a phenomenon, such as life inside a jail."}, {"text": "The number of crimes recorded in a city each year", "is_correct": false, "rationale": "Counting crimes is descriptive research."}, {"text": "The statistical relationship between two variables", "is_correct": false, "rationale": "Statistical relationships are correlational research."}, {"text": "The effect of a program tested by random assignment", "is_correct": false, "rationale": "Random assignment is experimental research."}]'::jsonb, 0, 'easy', 'In-depth interviews are the usual method of phenomenological research.', NULL, 'Study module Criminology, Chapter 7: Criminological Research 1 and 2 (CRIM-7.1).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-7.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-7.1_04', 'criminology', 'Criminological Research 1 and 2', 'A researcher wants to study in depth how one police station runs its community policing program. Which method fits best?', '[{"text": "Correlational study", "is_correct": false, "rationale": "A correlational study measures relationships between variables across many cases."}, {"text": "Experimental study", "is_correct": false, "rationale": "An experiment manipulates variables under controlled conditions."}, {"text": "Cross-national survey", "is_correct": false, "rationale": "A cross-national survey covers many countries."}, {"text": "Case study", "is_correct": true, "rationale": "A case study examines a single unit, like one station, in depth."}]'::jsonb, 3, 'medium', 'Case studies use several data sources, such as interviews, documents and observation.', NULL, 'Study module Criminology, Chapter 7: Criminological Research 1 and 2 (CRIM-7.1).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-7.1', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-7.1_05', 'criminology', 'Criminological Research 1 and 2', 'A study finds that ice cream sales and street crimes rise together. Why can it not conclude that ice cream causes crime?', '[{"text": "Ice cream sales cannot be measured accurately", "is_correct": false, "rationale": "The sales can be measured; the issue is causation."}, {"text": "Street crimes are never related to any other factor", "is_correct": false, "rationale": "Crime is related to many factors."}, {"text": "A third factor, such as hot weather, may cause both", "is_correct": true, "rationale": "Hot weather increases both ice cream sales and outdoor activity, which raises opportunities for crime."}, {"text": "Correlation always proves causation in research", "is_correct": false, "rationale": "Correlation alone never proves causation."}]'::jsonb, 2, 'hard', 'Spurious relationships are a common trap in interpreting correlations.', NULL, 'Study module Criminology, Chapter 7: Criminological Research 1 and 2 (CRIM-7.1).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-7.1', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-7.2_01', 'criminology', 'Criminological Research 1 and 2', 'How does the validity of a research instrument differ from its reliability?', '[{"text": "Validity is giving consistent results; reliability is measuring the right thing", "is_correct": false, "rationale": "This reverses the two concepts."}, {"text": "Validity is measuring what it intends; reliability is giving consistent results", "is_correct": true, "rationale": "A valid instrument measures the intended concept; a reliable one gives consistent results over time or items."}, {"text": "Validity applies only to interviews; reliability only to surveys", "is_correct": false, "rationale": "Both apply to all kinds of instruments."}, {"text": "Validity and reliability mean the same thing", "is_correct": false, "rationale": "They are distinct qualities."}]'::jsonb, 1, 'easy', 'An instrument can be reliable but not valid; a valid instrument must be reliable.', NULL, 'Study module Criminology, Chapter 7: Criminological Research 1 and 2 (CRIM-7.2).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-7.2', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-7.2_02', 'criminology', 'Criminological Research 1 and 2', 'A researcher divides police officers by rank, then randomly selects from each rank in proportion to its size. Which sampling technique is this?', '[{"text": "Simple random sampling", "is_correct": false, "rationale": "Simple random sampling selects from the whole population without grouping."}, {"text": "Purposive sampling", "is_correct": false, "rationale": "Purposive sampling selects based on the researcher''s judgment."}, {"text": "Snowball sampling", "is_correct": false, "rationale": "Snowball sampling relies on participants referring others."}, {"text": "Stratified random sampling", "is_correct": true, "rationale": "Stratified random sampling divides the population into groups (strata) and samples randomly within each."}]'::jsonb, 3, 'medium', 'Stratifying ensures each subgroup is fairly represented.', NULL, 'Study module Criminology, Chapter 7: Criminological Research 1 and 2 (CRIM-7.2).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-7.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-7.2_03', 'criminology', 'Criminological Research 1 and 2', 'The ages of five respondents are 20, 22, 22, 25 and 61. Which measure best represents their typical age?', '[{"text": "The median, 22", "is_correct": true, "rationale": "The median is not pulled by the extreme value of 61, so it represents the typical respondent better."}, {"text": "The mean, 30", "is_correct": false, "rationale": "The mean of 30 is distorted by the outlier."}, {"text": "The range, 41", "is_correct": false, "rationale": "The range is a measure of spread, not of typical value."}, {"text": "The maximum, 61", "is_correct": false, "rationale": "The maximum is an extreme, not typical."}]'::jsonb, 0, 'medium', 'When data have outliers, the median is usually preferred to the mean.', NULL, 'Study module Criminology, Chapter 7: Criminological Research 1 and 2 (CRIM-7.2).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-7.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-7.3_01', 'criminology', 'Criminological Research 1 and 2', 'What does a null hypothesis state?', '[{"text": "That the researcher''s prediction is definitely true", "is_correct": false, "rationale": "The alternative hypothesis states the expected relationship."}, {"text": "That the study has no research problem", "is_correct": false, "rationale": "Every study has a research problem."}, {"text": "That there is no significant relationship or difference", "is_correct": true, "rationale": "The null hypothesis states no significant relationship or difference; the test decides whether to reject it."}, {"text": "That the variables cannot be measured", "is_correct": false, "rationale": "Variables in a hypothesis must be measurable."}]'::jsonb, 2, 'easy', 'Researchers reject or fail to reject the null hypothesis based on the data.', NULL, 'Study module Criminology, Chapter 7: Criminological Research 1 and 2 (CRIM-7.3).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-7.3', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-7.3_02', 'criminology', 'Criminological Research 1 and 2', 'Which is the best-formulated research question?', '[{"text": "Why is crime bad for everybody?", "is_correct": false, "rationale": "This question is vague and not researchable."}, {"text": "What should be done about all the problems of the police?", "is_correct": false, "rationale": "This question is too broad for a single study."}, {"text": "Is criminology an interesting subject for most students?", "is_correct": false, "rationale": "This question asks for opinion and has no research value."}, {"text": "How is police visibility related to street crime in Barangay X in 2025?", "is_correct": true, "rationale": "A good research question is specific, measurable and limited in scope, place and time."}]'::jsonb, 3, 'medium', 'Clear questions guide the choice of design and instruments.', NULL, 'Study module Criminology, Chapter 7: Criminological Research 1 and 2 (CRIM-7.3).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-7.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-7.3_03', 'criminology', 'Criminological Research 1 and 2', 'A study asks whether an anti-drug seminar changes students'' knowledge. Which is the correct null hypothesis?', '[{"text": "The seminar greatly improves the students'' knowledge", "is_correct": false, "rationale": "Predicting improvement is the alternative hypothesis."}, {"text": "Students who attend seminars never use drugs", "is_correct": false, "rationale": "This is a sweeping claim, not a testable null hypothesis."}, {"text": "There is no significant difference in scores before and after", "is_correct": true, "rationale": "The null hypothesis states that there is no significant difference."}, {"text": "The seminar is the best program in the country", "is_correct": false, "rationale": "This is an opinion, not a hypothesis."}]'::jsonb, 2, 'medium', 'A paired t-test could be used to compare the before-and-after scores.', NULL, 'Study module Criminology, Chapter 7: Criminological Research 1 and 2 (CRIM-7.3).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-7.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-7.3_04', 'criminology', 'Criminological Research 1 and 2', 'While writing the literature review, which practice is correct?', '[{"text": "Copy paragraphs from sources without citation", "is_correct": false, "rationale": "Copying without citation is plagiarism."}, {"text": "Use only sources that agree with the researcher''s views", "is_correct": false, "rationale": "A review should include different views to be balanced."}, {"text": "Use only social media posts as sources", "is_correct": false, "rationale": "Social media posts are rarely credible scholarly sources."}, {"text": "Use recent, relevant and credible sources, and cite them properly", "is_correct": true, "rationale": "A good review draws on credible and relevant sources and credits them."}]'::jsonb, 3, 'medium', 'The literature review shows the gap that the study will fill.', NULL, 'Study module Criminology, Chapter 7: Criminological Research 1 and 2 (CRIM-7.3).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-7.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-7.3_05', 'criminology', 'Criminological Research 1 and 2', 'A researcher is building an Input-Process-Output framework for a study of a jail''s livelihood program. Which arrangement is correct?', '[{"text": "Input: an improved program; Process: PDL profiles; Output: surveys and analysis", "is_correct": false, "rationale": "This reverses the order of input and output."}, {"text": "Input: surveys and analysis; Process: an improved program; Output: PDL profiles", "is_correct": false, "rationale": "This places the elements in the wrong boxes."}, {"text": "Input: the researcher''s opinion; Process: none; Output: the title of the study", "is_correct": false, "rationale": "Opinion and title are not parts of a research framework."}, {"text": "Input: PDL profiles and program resources; Process: surveys and analysis; Output: an improved program", "is_correct": true, "rationale": "In an IPO framework, inputs are the data and resources, the process is how they are studied, and the output is the result of the study."}]'::jsonb, 3, 'hard', 'A conceptual framework shows how the study''s variables and steps connect.', NULL, 'Study module Criminology, Chapter 7: Criminological Research 1 and 2 (CRIM-7.3).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-7.3', 'Creating') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-7.4_01', 'criminology', 'Criminological Research 1 and 2', 'What does informed consent in research mean?', '[{"text": "Participants must join the study once they are chosen", "is_correct": false, "rationale": "Participation must be voluntary."}, {"text": "The researcher decides alone who will be included without telling them", "is_correct": false, "rationale": "Participants must be informed and agree."}, {"text": "Participants agree after the study is already finished", "is_correct": false, "rationale": "Consent must be obtained before participation."}, {"text": "Participants freely agree after being told the purpose, risks and their rights", "is_correct": true, "rationale": "Informed consent is voluntary agreement based on full information, with the right to withdraw at any time."}]'::jsonb, 3, 'easy', 'Consent forms should be written in a language participants understand.', NULL, 'Study module Criminology, Chapter 7: Criminological Research 1 and 2 (CRIM-7.4).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-7.4', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-7.4_02', 'criminology', 'Criminological Research 1 and 2', 'How does anonymity differ from confidentiality in research?', '[{"text": "With anonymity the researcher publishes names; with confidentiality he hides them", "is_correct": false, "rationale": "Neither allows publishing names."}, {"text": "Anonymity: no one can identify them; confidentiality: identities are protected", "is_correct": true, "rationale": "Anonymity means no identifying link exists; confidentiality means identities are known to the researcher but protected."}, {"text": "Anonymity applies only to interviews; confidentiality only to surveys", "is_correct": false, "rationale": "Both apply to various methods."}, {"text": "They are the same and need not be distinguished", "is_correct": false, "rationale": "They are different safeguards."}]'::jsonb, 1, 'easy', 'Researchers should state which safeguard they use in the consent form.', NULL, 'Study module Criminology, Chapter 7: Criminological Research 1 and 2 (CRIM-7.4).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-7.4', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-7.4_03', 'criminology', 'Criminological Research 1 and 2', 'A student plans to interview persons deprived of liberty in a jail. Which practice is ethical?', '[{"text": "Get approvals and make sure participation is truly voluntary", "is_correct": true, "rationale": "PDLs are a vulnerable group, so approvals, voluntary consent and freedom from coercion are essential."}, {"text": "Have the warden order the PDLs to take part", "is_correct": false, "rationale": "Orders from the warden make participation coerced."}, {"text": "Promise the PDLs early release if they participate", "is_correct": false, "rationale": "False promises of release are deceptive and coercive."}, {"text": "Interview them without telling them it is research", "is_correct": false, "rationale": "Participants must know they are part of a study."}]'::jsonb, 0, 'medium', 'Ethics review boards look closely at research with vulnerable groups.', NULL, 'Study module Criminology, Chapter 7: Criminological Research 1 and 2 (CRIM-7.4).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-7.4', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-7.4_04', 'criminology', 'Criminological Research 1 and 2', 'A study will survey students aged 14 to 16. What consent is needed?', '[{"text": "Only the principal''s verbal approval", "is_correct": false, "rationale": "A principal''s approval does not replace parental consent."}, {"text": "Only the students'' consent, since they can read", "is_correct": false, "rationale": "Minors cannot give full legal consent alone."}, {"text": "Parental consent and the students'' own assent", "is_correct": true, "rationale": "For minors, researchers obtain consent from parents or guardians and assent from the minors themselves."}, {"text": "No consent, since it is only a survey", "is_correct": false, "rationale": "Surveys still require consent."}]'::jsonb, 2, 'medium', 'Assent respects the minor''s own choice to take part.', NULL, 'Study module Criminology, Chapter 7: Criminological Research 1 and 2 (CRIM-7.4).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-7.4', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-7.4_05', 'criminology', 'Criminological Research 1 and 2', 'A researcher collects respondents'' names and case details. Which practice follows the Data Privacy Act?', '[{"text": "Post the raw data online so others can check it", "is_correct": false, "rationale": "Posting raw data exposes personal information."}, {"text": "Share the data with anyone who asks politely", "is_correct": false, "rationale": "Sharing without a lawful basis violates the law."}, {"text": "Secure the data, code the names, and use it only for the study", "is_correct": true, "rationale": "R.A. 10173 requires lawful processing, security measures and use limited to the stated purpose."}, {"text": "Keep the data forever on a public computer", "is_correct": false, "rationale": "Data should be kept securely and only as long as needed."}]'::jsonb, 2, 'medium', 'Researchers should state how data will be stored and disposed of.', 'R.A. 10173 (Data Privacy Act of 2012)', 'Study module Criminology, Chapter 7: Criminological Research 1 and 2 (CRIM-7.4).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-7.4', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-7.5_01', 'criminology', 'Criminological Research 1 and 2', 'On a 4-point scale where 3.26 to 4.00 means ''strongly agree'', a statement has a weighted mean of 3.40. How is it interpreted?', '[{"text": "Strongly agree", "is_correct": true, "rationale": "3.40 falls within 3.26 to 4.00, so it is interpreted as ''strongly agree''."}, {"text": "Agree", "is_correct": false, "rationale": "''Agree'' would be the next lower range."}, {"text": "Disagree", "is_correct": false, "rationale": "''Disagree'' is a lower range still."}, {"text": "Strongly disagree", "is_correct": false, "rationale": "''Strongly disagree'' is the lowest range."}]'::jsonb, 0, 'medium', 'Interpretation must use the scale stated in the study.', NULL, 'Study module Criminology, Chapter 7: Criminological Research 1 and 2 (CRIM-7.5).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-7.5', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CRIM-7.5_02', 'criminology', 'Criminological Research 1 and 2', 'A test of the difference between two groups gives p = 0.03, with a significance level of 0.05. What should the researcher conclude?', '[{"text": "Accept the null hypothesis; there is no difference", "is_correct": false, "rationale": "A p-value below alpha leads to rejection of the null."}, {"text": "Reject the null hypothesis; the difference is significant", "is_correct": true, "rationale": "Since p is less than 0.05, the null hypothesis is rejected and the difference is statistically significant."}, {"text": "The study failed and must be repeated", "is_correct": false, "rationale": "A significant result does not mean the study failed."}, {"text": "The result cannot be interpreted at all", "is_correct": false, "rationale": "The p-value is interpreted against the significance level."}]'::jsonb, 1, 'medium', 'Statistical significance should be reported together with the size of the difference.', NULL, 'Study module Criminology, Chapter 7: Criminological Research 1 and 2 (CRIM-7.5).', 'generated', 'tos_2024', 1, FALSE, 'CRIM-7.5', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-1.1_01', 'corrections', 'Institutional Correction', 'Who wrote ''The State of the Prisons'' in 1777 and is regarded as a pioneer of prison reform?', '[{"text": "Cesare Beccaria", "is_correct": false, "rationale": "Beccaria wrote ''On Crimes and Punishments'' on criminal law reform."}, {"text": "Jeremy Bentham", "is_correct": false, "rationale": "Bentham designed the Panopticon prison and developed utilitarianism."}, {"text": "John Howard", "is_correct": true, "rationale": "John Howard, sheriff of Bedfordshire, exposed prison conditions and pushed for reform."}, {"text": "Alexander Maconochie", "is_correct": false, "rationale": "Maconochie developed the mark system on Norfolk Island."}]'::jsonb, 2, 'easy', 'Howard''s work led to reforms in sanitation, separation and supervision of prisoners.', NULL, 'Study module Correctional Administration, Chapter 1: Institutional Correction (CA-1.1).', 'generated', 'tos_2024', 1, FALSE, 'CA-1.1', 'Remembering') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-1.1_02', 'corrections', 'Institutional Correction', 'Who introduced the mark system on Norfolk Island, a forerunner of parole?', '[{"text": "Sir Walter Crofton", "is_correct": false, "rationale": "Crofton developed the Irish system with tickets of leave."}, {"text": "Zebulon Brockway", "is_correct": false, "rationale": "Brockway ran the Elmira Reformatory with indeterminate sentences."}, {"text": "John Howard", "is_correct": false, "rationale": "Howard was a prison reformer who wrote on prison conditions."}, {"text": "Alexander Maconochie", "is_correct": true, "rationale": "Maconochie let prisoners earn marks for work and good conduct to shorten their stay."}]'::jsonb, 3, 'easy', 'The mark system linked release to the prisoner''s own effort.', NULL, 'Study module Correctional Administration, Chapter 1: Institutional Correction (CA-1.1).', 'generated', 'tos_2024', 1, FALSE, 'CA-1.1', 'Remembering') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-1.1_03', 'corrections', 'Institutional Correction', 'By what name are the revised UN Standard Minimum Rules for the Treatment of Prisoners (2015) known?', '[{"text": "Mandela Rules", "is_correct": true, "rationale": "The 2015 revision of the Standard Minimum Rules is named after Nelson Mandela."}, {"text": "Bangkok Rules", "is_correct": false, "rationale": "The Bangkok Rules concern women prisoners and women offenders."}, {"text": "Tokyo Rules", "is_correct": false, "rationale": "The Tokyo Rules concern non-custodial measures."}, {"text": "Beijing Rules", "is_correct": false, "rationale": "The Beijing Rules concern juvenile justice."}]'::jsonb, 0, 'easy', 'The Mandela Rules set minimum standards for prison management and treatment.', NULL, 'Study module Correctional Administration, Chapter 1: Institutional Correction (CA-1.1).', 'generated', 'tos_2024', 1, FALSE, 'CA-1.1', 'Remembering') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-1.1_04', 'corrections', 'Institutional Correction', 'What do the UN Bangkok Rules (2010) cover?', '[{"text": "The treatment of juveniles in conflict with the law", "is_correct": false, "rationale": "Juvenile justice is covered by the Beijing Rules."}, {"text": "The use of non-custodial measures for all offenders", "is_correct": false, "rationale": "Non-custodial measures are covered by the Tokyo Rules."}, {"text": "The treatment of women prisoners and women offenders", "is_correct": true, "rationale": "The Bangkok Rules address the specific needs of women in prison and women offenders."}, {"text": "The extradition of prisoners between countries", "is_correct": false, "rationale": "Extradition is covered by treaties, not by the Bangkok Rules."}]'::jsonb, 2, 'easy', 'The Bangkok Rules supplement the Mandela Rules.', NULL, 'Study module Correctional Administration, Chapter 1: Institutional Correction (CA-1.1).', 'generated', 'tos_2024', 1, FALSE, 'CA-1.1', 'Remembering') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-1.1_05', 'corrections', 'Institutional Correction', 'How does retribution differ from deterrence as a justification for punishment?', '[{"text": "Retribution aims to prevent crime; deterrence punishes because it is deserved", "is_correct": false, "rationale": "This reverses the two ideas."}, {"text": "Retribution applies only to fines; deterrence only to imprisonment", "is_correct": false, "rationale": "Both justifications apply to many kinds of penalties."}, {"text": "Retribution and deterrence mean the same thing", "is_correct": false, "rationale": "They are distinct justifications."}, {"text": "Retribution punishes because it is deserved; deterrence aims to prevent future crime", "is_correct": true, "rationale": "Retribution looks back at the offense and imposes a deserved penalty; deterrence looks forward to discourage crime."}]'::jsonb, 3, 'easy', 'Other justifications include incapacitation, rehabilitation and restoration.', NULL, 'Study module Correctional Administration, Chapter 1: Institutional Correction (CA-1.1).', 'generated', 'tos_2024', 1, FALSE, 'CA-1.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-1.1_06', 'corrections', 'Institutional Correction', 'What is the difference between general and specific deterrence?', '[{"text": "General deters the offender; specific deters the public", "is_correct": false, "rationale": "This reverses the two ideas."}, {"text": "General applies to men; specific applies to women", "is_correct": false, "rationale": "Deterrence does not depend on sex."}, {"text": "General deters the public; specific deters the offender himself", "is_correct": true, "rationale": "General deterrence warns society through the example of punishment; specific deterrence discourages the punished offender from repeating."}, {"text": "General applies to fines; specific to imprisonment", "is_correct": false, "rationale": "Deterrence does not depend on the kind of penalty."}]'::jsonb, 2, 'easy', 'Certainty of punishment deters more than severity.', NULL, 'Study module Correctional Administration, Chapter 1: Institutional Correction (CA-1.1).', 'generated', 'tos_2024', 1, FALSE, 'CA-1.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-1.1_07', 'corrections', 'Institutional Correction', 'How does imprisoning a dangerous offender protect society through incapacitation?', '[{"text": "It ensures that he will never think about crime again", "is_correct": false, "rationale": "Incapacitation does not change the offender''s thoughts."}, {"text": "It removes his ability to commit crimes in the community", "is_correct": true, "rationale": "Incapacitation prevents crimes by physically removing the offender from society for a time."}, {"text": "It teaches the public about the law", "is_correct": false, "rationale": "Teaching the public is general deterrence."}, {"text": "It makes the victim forgive the offender", "is_correct": false, "rationale": "Forgiveness is part of restorative approaches, not incapacitation."}]'::jsonb, 1, 'easy', 'Incapacitation does not by itself reform the offender.', NULL, 'Study module Correctional Administration, Chapter 1: Institutional Correction (CA-1.1).', 'generated', 'tos_2024', 1, FALSE, 'CA-1.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-1.1_08', 'corrections', 'Institutional Correction', 'Why does the Indeterminate Sentence Law fix a minimum and a maximum term?', '[{"text": "To make every prisoner serve the maximum penalty", "is_correct": false, "rationale": "The point is to allow release before the maximum when deserved."}, {"text": "To let the prisoner choose the length of his sentence", "is_correct": false, "rationale": "Prisoners do not choose their sentences."}, {"text": "To individualize the penalty and allow parole once the minimum is served", "is_correct": true, "rationale": "Act 4103 aims to uplift and redeem offenders by allowing release on parole after the minimum, if they are fit."}, {"text": "To give judges power to change the sentence each year", "is_correct": false, "rationale": "Judges do not revise sentences yearly."}]'::jsonb, 2, 'easy', 'The Board of Pardons and Parole decides on parole.', 'Act No. 4103 (Indeterminate Sentence Law)', 'Study module Correctional Administration, Chapter 1: Institutional Correction (CA-1.1).', 'generated', 'tos_2024', 1, FALSE, 'CA-1.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-1.1_09', 'corrections', 'Institutional Correction', 'Why can Philippine courts not impose the death penalty today?', '[{"text": "R.A. 9346 prohibited the imposition of the death penalty", "is_correct": true, "rationale": "R.A. 9346 (2006) prohibited the death penalty and replaced it with reclusion perpetua or life imprisonment."}, {"text": "The Constitution requires the death penalty for heinous crimes", "is_correct": false, "rationale": "The Constitution does not require it; Congress may provide it only for heinous crimes."}, {"text": "The death penalty is imposed only by the Supreme Court", "is_correct": false, "rationale": "No court may impose it while R.A. 9346 is in force."}, {"text": "The death penalty applies only to foreigners", "is_correct": false, "rationale": "No such distinction exists."}]'::jsonb, 0, 'easy', 'Those whose sentences were reduced to reclusion perpetua by R.A. 9346 are not eligible for parole.', 'R.A. 9346; 1987 Constitution, Art. III, Sec. 19(1)', 'Study module Correctional Administration, Chapter 1: Institutional Correction (CA-1.1).', 'generated', 'tos_2024', 1, FALSE, 'CA-1.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-1.1_10', 'corrections', 'Institutional Correction', 'What does Article III, Section 19(2) of the Constitution say about the treatment of prisoners?', '[{"text": "Prisoners lose all rights once they are convicted", "is_correct": false, "rationale": "Prisoners keep their rights except those limited by their confinement."}, {"text": "Degrading punishment and subhuman facilities shall be dealt with by law", "is_correct": true, "rationale": "The provision directs that physical, psychological or degrading punishment and subhuman penal facilities be dealt with by law."}, {"text": "Prisoners may be punished in any way the warden chooses", "is_correct": false, "rationale": "Punishment inside prisons must follow the law and rules."}, {"text": "Prisoners must pay for the cost of their own detention", "is_correct": false, "rationale": "No constitutional rule requires prisoners to pay for detention."}]'::jsonb, 1, 'easy', 'Section 19(1) also bans excessive fines and cruel, degrading or inhuman punishment.', '1987 Constitution, Art. III, Sec. 19', 'Study module Correctional Administration, Chapter 1: Institutional Correction (CA-1.1).', 'generated', 'tos_2024', 1, FALSE, 'CA-1.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-1.1_11', 'corrections', 'Institutional Correction', 'Why are accessory penalties not usually stated separately in the judgment?', '[{"text": "Accessory penalties are only imposed by the warden", "is_correct": false, "rationale": "Accessory penalties are imposed by law, not by the warden."}, {"text": "The law deems them included with certain principal penalties", "is_correct": true, "rationale": "Article 73 presumes that accessory penalties are imposed whenever the court imposes the principal penalty to which they are attached."}, {"text": "Accessory penalties are always waived by the court", "is_correct": false, "rationale": "They are not waived; they follow by operation of law."}, {"text": "Accessory penalties apply only to light felonies", "is_correct": false, "rationale": "They attach to graver principal penalties, such as reclusion perpetua."}]'::jsonb, 1, 'easy', 'Examples include civil interdiction and perpetual absolute disqualification.', 'Revised Penal Code, Arts. 40-45 and 73', 'Study module Correctional Administration, Chapter 1: Institutional Correction (CA-1.1).', 'generated', 'tos_2024', 1, FALSE, 'CA-1.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-1.1_12', 'corrections', 'Institutional Correction', 'Why does modern penology give importance to rehabilitation?', '[{"text": "Most prisoners return to society, so reform helps reduce repeat offending", "is_correct": true, "rationale": "Since most prisoners will be released, preparing them to live lawfully protects the public."}, {"text": "Rehabilitation removes the need for any prison security", "is_correct": false, "rationale": "Security remains necessary alongside rehabilitation."}, {"text": "Rehabilitation means prisoners are never punished", "is_correct": false, "rationale": "Rehabilitation works within the sentence imposed."}, {"text": "Rehabilitation is cheaper than giving prisoners food", "is_correct": false, "rationale": "Basic needs must still be provided; rehabilitation is not a substitute."}]'::jsonb, 0, 'easy', 'Programs include education, livelihood, counseling and values formation.', NULL, 'Study module Correctional Administration, Chapter 1: Institutional Correction (CA-1.1).', 'generated', 'tos_2024', 1, FALSE, 'CA-1.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-1.2_01', 'corrections', 'Institutional Correction', 'A person is sentenced by the RTC to ten years of imprisonment. Where should he serve his sentence?', '[{"text": "In a BuCor national penitentiary", "is_correct": true, "rationale": "Under R.A. 10575, BuCor has custody of national (insular) prisoners sentenced to more than three years."}, {"text": "In a BJMP municipal jail", "is_correct": false, "rationale": "BJMP jails hold detainees and those with shorter sentences."}, {"text": "In a provincial jail", "is_correct": false, "rationale": "Provincial jails hold provincial prisoners with shorter sentences."}, {"text": "In a barangay detention cell", "is_correct": false, "rationale": "Barangays do not hold sentenced prisoners."}]'::jsonb, 0, 'medium', 'The commitment order directs the transfer of the convict to BuCor.', 'R.A. 10575 (Bureau of Corrections Act of 2013), Sec. 4', 'Study module Correctional Administration, Chapter 1: Institutional Correction (CA-1.2).', 'generated', 'tos_2024', 1, FALSE, 'CA-1.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-1.2_02', 'corrections', 'Institutional Correction', 'A person charged with theft in a city court is awaiting trial. Which agency holds him?', '[{"text": "The BuCor, in a penal colony", "is_correct": false, "rationale": "BuCor holds sentenced national prisoners."}, {"text": "The PNP, in a crime laboratory", "is_correct": false, "rationale": "The PNP does not hold detainees in crime laboratories."}, {"text": "The DSWD, in a youth center", "is_correct": false, "rationale": "The DSWD handles children, not adult detainees."}, {"text": "The BJMP, in the city jail", "is_correct": true, "rationale": "The BJMP has jurisdiction over district, city and municipal jails, including detainees awaiting trial."}]'::jsonb, 3, 'medium', 'The BJMP is under the DILG.', 'R.A. 6975, Secs. 60-63', 'Study module Correctional Administration, Chapter 1: Institutional Correction (CA-1.2).', 'generated', 'tos_2024', 1, FALSE, 'CA-1.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-1.2_03', 'corrections', 'Institutional Correction', 'Which office supervises and controls a provincial jail?', '[{"text": "The BJMP regional office", "is_correct": false, "rationale": "The BJMP covers district, city and municipal jails."}, {"text": "The Bureau of Corrections", "is_correct": false, "rationale": "BuCor runs national penitentiaries."}, {"text": "The provincial government", "is_correct": true, "rationale": "Provincial jails are under the provincial governments, headed by the governor."}, {"text": "The National Police Commission", "is_correct": false, "rationale": "NAPOLCOM administers the PNP."}]'::jsonb, 2, 'medium', 'Provincial jails are part of the correction pillar at the provincial level.', 'R.A. 7160 (Local Government Code)', 'Study module Correctional Administration, Chapter 1: Institutional Correction (CA-1.2).', 'generated', 'tos_2024', 1, FALSE, 'CA-1.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-1.2_04', 'corrections', 'Institutional Correction', 'At the change of shift, what should the outgoing and incoming jail guards do?', '[{"text": "Do a joint headcount and turn over the keys and logbook", "is_correct": true, "rationale": "A joint count and formal turnover fix accountability for the PDLs, keys and equipment."}, {"text": "Leave the keys in the cell block for the next shift", "is_correct": false, "rationale": "Keys must never be left where PDLs can reach them."}, {"text": "Skip the headcount if the last shift was quiet", "is_correct": false, "rationale": "Headcounts are required every shift."}, {"text": "Let a trusted PDL hand over the keys", "is_correct": false, "rationale": "PDLs must never handle keys."}]'::jsonb, 0, 'medium', 'Discrepancies are reported at once.', NULL, 'Study module Correctional Administration, Chapter 1: Institutional Correction (CA-1.2).', 'generated', 'tos_2024', 1, FALSE, 'CA-1.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-1.2_05', 'corrections', 'Institutional Correction', 'A warden is told to let a trusted PDL hold the cell keys to save manpower. How should he decide?', '[{"text": "Refuse; PDLs must never hold or handle keys", "is_correct": true, "rationale": "Key control is a basic security rule; giving keys to PDLs invites escapes and abuses."}, {"text": "Agree, if the PDL has good behavior", "is_correct": false, "rationale": "Good behavior does not make key control unnecessary."}, {"text": "Agree, but only during the day", "is_correct": false, "rationale": "The rule applies at all times."}, {"text": "Agree, if the PDL signs a receipt", "is_correct": false, "rationale": "A receipt does not cure the security risk."}]'::jsonb, 0, 'medium', 'Keys are kept in a controlled key box and issued only to authorized personnel.', NULL, 'Study module Correctional Administration, Chapter 1: Institutional Correction (CA-1.2).', 'generated', 'tos_2024', 1, FALSE, 'CA-1.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-1.2_06', 'corrections', 'Institutional Correction', 'A warden receives reliable information about a planned escape. What is the best decision?', '[{"text": "Ignore it until an escape attempt actually happens", "is_correct": false, "rationale": "Waiting allows the plan to proceed."}, {"text": "Announce the information to all PDLs in a meeting", "is_correct": false, "rationale": "Announcing it tips off the planners."}, {"text": "Release the PDLs involved to avoid trouble", "is_correct": false, "rationale": "Release without a court order is illegal."}, {"text": "Tighten security and conduct a surprise search (greyhound operation)", "is_correct": true, "rationale": "Acting on the intelligence with stronger security and a surprise search can prevent the escape."}]'::jsonb, 3, 'medium', 'The warden also reports to higher headquarters.', NULL, 'Study module Correctional Administration, Chapter 1: Institutional Correction (CA-1.2).', 'generated', 'tos_2024', 1, FALSE, 'CA-1.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-1.2_07', 'corrections', 'Institutional Correction', 'A policy will apply to all national penitentiaries. Who issues it?', '[{"text": "The Chief of the BJMP, under the DILG", "is_correct": false, "rationale": "The BJMP covers city, municipal and district jails."}, {"text": "The provincial governor", "is_correct": false, "rationale": "Governors supervise provincial jails only."}, {"text": "The Chief of the PNP", "is_correct": false, "rationale": "The PNP has no authority over penitentiaries."}, {"text": "The BuCor Director General, under the DOJ", "is_correct": true, "rationale": "R.A. 10575 places BuCor under the DOJ, headed by a Director General."}]'::jsonb, 3, 'medium', 'The Director General is assisted by Deputy Directors General.', 'R.A. 10575', 'Study module Correctional Administration, Chapter 1: Institutional Correction (CA-1.2).', 'generated', 'tos_2024', 1, FALSE, 'CA-1.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-1.2_08', 'corrections', 'Institutional Correction', 'A municipal jail is badly overcrowded. Which agency is responsible for addressing it?', '[{"text": "The BJMP, under the DILG", "is_correct": true, "rationale": "Municipal jails are under the BJMP, which is attached to the DILG."}, {"text": "The BuCor, under the DOJ", "is_correct": false, "rationale": "BuCor runs national penitentiaries."}, {"text": "The PPA, under the DOJ", "is_correct": false, "rationale": "The PPA supervises probationers and parolees."}, {"text": "The DSWD", "is_correct": false, "rationale": "The DSWD handles children and social welfare."}]'::jsonb, 0, 'medium', 'Decongestion often needs coordination with the courts and prosecutors.', 'R.A. 6975', 'Study module Correctional Administration, Chapter 1: Institutional Correction (CA-1.2).', 'generated', 'tos_2024', 1, FALSE, 'CA-1.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-1.2_09', 'corrections', 'Institutional Correction', 'A jail''s population is far above its capacity. Which plan best addresses it?', '[{"text": "Stop admitting PDLs, even with valid commitment orders", "is_correct": false, "rationale": "Jails must admit PDLs with valid commitment orders."}, {"text": "Coordinate with courts on pending cases and process PDLs'' time allowances", "is_correct": true, "rationale": "Decongestion uses legal means such as speedy trial coordination, paralegal help and timely processing of GCTA."}, {"text": "Release PDLs at random to reduce the number", "is_correct": false, "rationale": "Release without legal basis is unlawful."}, {"text": "Ignore the problem until a new jail is built", "is_correct": false, "rationale": "Overcrowding harms safety and health and must be acted on."}]'::jsonb, 1, 'medium', 'Paralegal programs help PDLs whose cases are delayed.', NULL, 'Study module Correctional Administration, Chapter 1: Institutional Correction (CA-1.2).', 'generated', 'tos_2024', 1, FALSE, 'CA-1.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-1.2_10', 'corrections', 'Institutional Correction', 'A jail officer is caught smuggling cellphones into the jail. What should the warden do?', '[{"text": "Warn him privately and let him continue", "is_correct": false, "rationale": "A private warning does not address a serious violation."}, {"text": "Relieve him and file administrative and criminal cases", "is_correct": true, "rationale": "Accountability requires relief from duty pending investigation and the filing of proper charges."}, {"text": "Transfer him without any investigation", "is_correct": false, "rationale": "Transfer without investigation passes on the problem."}, {"text": "Ignore it, since cellphones are not drugs", "is_correct": false, "rationale": "Contraband of any kind threatens jail security."}]'::jsonb, 1, 'medium', 'Corruption of personnel is a major source of contraband.', NULL, 'Study module Correctional Administration, Chapter 1: Institutional Correction (CA-1.2).', 'generated', 'tos_2024', 1, FALSE, 'CA-1.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-1.3_01', 'corrections', 'Institutional Correction', 'A person is brought to the jail without a commitment order from the court. What should the jail do?', '[{"text": "Admit him now and ask for the order next month", "is_correct": false, "rationale": "Holding him without an order is illegal detention."}, {"text": "Admit him if the arresting officer insists", "is_correct": false, "rationale": "Insistence does not replace the legal requirement."}, {"text": "Hold him in the jail lobby without records", "is_correct": false, "rationale": "Unrecorded holding is unlawful and dangerous."}, {"text": "Refuse admission until a valid order is shown", "is_correct": true, "rationale": "A jail may hold a person only on a valid commitment order or other lawful authority."}]'::jsonb, 3, 'medium', 'The commitment order states the legal basis for detention.', NULL, 'Study module Correctional Administration, Chapter 1: Institutional Correction (CA-1.3).', 'generated', 'tos_2024', 1, FALSE, 'CA-1.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-1.3_02', 'corrections', 'Institutional Correction', 'A newly committed PDL arrives at the jail. Which step comes before assigning him to a cell?', '[{"text": "Assignment to a livelihood program", "is_correct": false, "rationale": "Programs come after admission and classification."}, {"text": "Approval of his visitors'' list", "is_correct": false, "rationale": "Visitors'' lists come after admission."}, {"text": "Release on recognizance", "is_correct": false, "rationale": "Release requires a court order."}, {"text": "Search, booking and medical examination", "is_correct": true, "rationale": "Admission includes a body search, booking (records, photographs, fingerprints) and a medical check before housing."}]'::jsonb, 3, 'medium', 'The PDL also undergoes orientation and classification.', NULL, 'Study module Correctional Administration, Chapter 1: Institutional Correction (CA-1.3).', 'generated', 'tos_2024', 1, FALSE, 'CA-1.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-1.3_03', 'corrections', 'Institutional Correction', 'A release order for a PDL arrives by fax late at night. What should the jail do before releasing him?', '[{"text": "Verify the order''s authenticity with the issuing court", "is_correct": true, "rationale": "Release orders must be verified to prevent escapes through fake documents."}, {"text": "Release him at once, since the fax looks official", "is_correct": false, "rationale": "A fax can be forged."}, {"text": "Ignore the order until the PDL''s family complains", "is_correct": false, "rationale": "Valid orders must be acted on promptly once verified."}, {"text": "Release him only if he pays a fee", "is_correct": false, "rationale": "Release cannot depend on payment."}]'::jsonb, 0, 'medium', 'The jail also checks for other pending cases before release.', NULL, 'Study module Correctional Administration, Chapter 1: Institutional Correction (CA-1.3).', 'generated', 'tos_2024', 1, FALSE, 'CA-1.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-1.3_04', 'corrections', 'Institutional Correction', 'A visitor brings food for a PDL. What should the jail staff do?', '[{"text": "Pass it on without inspection, since it is only food", "is_correct": false, "rationale": "Food can hide contraband."}, {"text": "Inspect the food and items before they are passed on", "is_correct": true, "rationale": "Food and items are common ways to smuggle contraband, so they are inspected."}, {"text": "Refuse all food, since visitors may not bring any", "is_correct": false, "rationale": "Rules usually allow food within limits."}, {"text": "Let the PDL inspect the food himself", "is_correct": false, "rationale": "PDLs cannot inspect their own items."}]'::jsonb, 1, 'medium', 'Visitors are also registered and searched under the jail''s rules.', NULL, 'Study module Correctional Administration, Chapter 1: Institutional Correction (CA-1.3).', 'generated', 'tos_2024', 1, FALSE, 'CA-1.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-1.3_05', 'corrections', 'Institutional Correction', 'While escorting a high-risk PDL to court, the PDL asks to stop by his house. What should the escort do?', '[{"text": "Allow a short stop if the PDL promises to behave", "is_correct": false, "rationale": "Promises do not change security rules."}, {"text": "Allow it if the family pays for the fuel", "is_correct": false, "rationale": "Payment would be corruption."}, {"text": "Refuse and go straight to the court", "is_correct": true, "rationale": "Escorts follow the authorized route without unauthorized stops, which could allow escape or ambush."}, {"text": "Let the PDL decide the route", "is_correct": false, "rationale": "The escort, not the PDL, controls movement."}]'::jsonb, 2, 'medium', 'High-risk PDLs are escorted with enough personnel and restraints.', NULL, 'Study module Correctional Administration, Chapter 1: Institutional Correction (CA-1.3).', 'generated', 'tos_2024', 1, FALSE, 'CA-1.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-1.3_06', 'corrections', 'Institutional Correction', 'The court orders a PDL''s hearing to be held by videoconference. What should the jail do?', '[{"text": "Bring the PDL to court anyway, ignoring the order", "is_correct": false, "rationale": "The court''s order must be followed."}, {"text": "Arrange the remote appearance from a secure room in the jail", "is_correct": true, "rationale": "Courts may allow remote appearances; the jail sets up the link from a secure place."}, {"text": "Postpone the hearing until the PDL is released", "is_correct": false, "rationale": "The jail has no power to postpone a hearing."}, {"text": "Let the PDL use his own cellphone for the hearing", "is_correct": false, "rationale": "PDLs are not allowed personal cellphones."}]'::jsonb, 1, 'medium', 'Remote hearings reduce escort risks and costs.', 'Supreme Court guidelines on videoconferencing hearings', 'Study module Correctional Administration, Chapter 1: Institutional Correction (CA-1.3).', 'generated', 'tos_2024', 1, FALSE, 'CA-1.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-1.3_07', 'corrections', 'Institutional Correction', 'A PDL is found with a cellphone during a search. How should it be handled?', '[{"text": "Let him keep it if he uses it only for family calls", "is_correct": false, "rationale": "Unauthorized phones are contraband regardless of their use."}, {"text": "Return it to him after a day", "is_correct": false, "rationale": "Returning contraband defeats security."}, {"text": "Confiscate and record it, and file a disciplinary case with a hearing", "is_correct": true, "rationale": "Contraband is seized and documented, and discipline follows due process."}, {"text": "Punish him at once without any record", "is_correct": false, "rationale": "Discipline without a record or hearing violates due process."}]'::jsonb, 2, 'medium', 'The source of the contraband is also investigated.', NULL, 'Study module Correctional Administration, Chapter 1: Institutional Correction (CA-1.3).', 'generated', 'tos_2024', 1, FALSE, 'CA-1.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-1.3_08', 'corrections', 'Institutional Correction', 'A PDL accused of fighting is placed in isolation without being told why or given a chance to explain. What is wrong with this?', '[{"text": "Nothing, since jail discipline needs no procedure", "is_correct": false, "rationale": "Discipline must follow due process."}, {"text": "Isolation can only be ordered by a court", "is_correct": false, "rationale": "Wardens may impose discipline through disciplinary boards."}, {"text": "Discipline requires notice and a hearing before a penalty", "is_correct": true, "rationale": "The Mandela Rules and jail regulations require that PDLs be told the charge and given a chance to be heard."}, {"text": "Fighting is not a disciplinary offense in jails", "is_correct": false, "rationale": "Fighting is a disciplinary offense."}]'::jsonb, 2, 'medium', 'Prolonged solitary confinement is prohibited by the Mandela Rules.', 'UN Standard Minimum Rules for the Treatment of Prisoners (Mandela Rules), Rules 39-45', 'Study module Correctional Administration, Chapter 1: Institutional Correction (CA-1.3).', 'generated', 'tos_2024', 1, FALSE, 'CA-1.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-1.3_09', 'corrections', 'Institutional Correction', 'The evening headcount is one PDL short. What should the officers do first?', '[{"text": "Wait until the morning count to see if he returns", "is_correct": false, "rationale": "Delay gives an escapee more time."}, {"text": "Lock down, recount, and report at once while searching", "is_correct": true, "rationale": "A discrepancy may mean an escape; lockdown, recount, immediate reporting and search are needed."}, {"text": "Record the correct number to avoid trouble", "is_correct": false, "rationale": "Falsifying records is a serious offense."}, {"text": "Ask the other PDLs to find him", "is_correct": false, "rationale": "PDLs cannot be given custodial tasks."}]'::jsonb, 1, 'medium', 'Escape plans are part of every jail''s contingency planning.', NULL, 'Study module Correctional Administration, Chapter 1: Institutional Correction (CA-1.3).', 'generated', 'tos_2024', 1, FALSE, 'CA-1.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-1.3_10', 'corrections', 'Institutional Correction', 'Police bring a 16-year-old to a city jail for detention. What should the jail do?', '[{"text": "Keep him away from adults; refer him to social welfare", "is_correct": true, "rationale": "R.A. 9344 bars detaining children in jails with adults; they are turned over to social welfare or a Bahay Pag-asa."}, {"text": "Hold him in the same cell as adult detainees", "is_correct": false, "rationale": "Children must never be held with adults."}, {"text": "Hold him in a separate cell for a few weeks", "is_correct": false, "rationale": "Jails are not proper facilities for children."}, {"text": "Admit him with adults if his parents agree", "is_correct": false, "rationale": "Parental agreement does not change the law."}]'::jsonb, 0, 'medium', 'Children in conflict with the law are handled under the juvenile justice system.', 'R.A. 9344, as amended by R.A. 10630', 'Study module Correctional Administration, Chapter 1: Institutional Correction (CA-1.3).', 'generated', 'tos_2024', 1, FALSE, 'CA-1.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-1.4_01', 'corrections', 'Institutional Correction', 'Why is containment the first priority when a riot breaks out in one cell block?', '[{"text": "It allows the rioters to calm down on their own", "is_correct": false, "rationale": "Containment is an active security measure."}, {"text": "It lets the warden avoid reporting the incident", "is_correct": false, "rationale": "Incidents must be reported."}, {"text": "It ensures that all PDLs are released", "is_correct": false, "rationale": "Containment keeps PDLs secured, not released."}, {"text": "It keeps the riot from spreading and prevents escapes", "is_correct": true, "rationale": "Isolating the area protects the rest of the facility and the perimeter while the response is organized."}]'::jsonb, 3, 'hard', 'After containment, the crisis team plans how to restore order with minimum force.', NULL, 'Study module Correctional Administration, Chapter 1: Institutional Correction (CA-1.4).', 'generated', 'tos_2024', 1, FALSE, 'CA-1.4', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-1.4_02', 'corrections', 'Institutional Correction', 'Why should a jail notify the police and nearby units right after an escape?', '[{"text": "The escapee will surely return on his own", "is_correct": false, "rationale": "Escapees seldom return voluntarily."}, {"text": "Notification is needed only after a week", "is_correct": false, "rationale": "Delay reduces the chance of recapture."}, {"text": "The police have no role in recapturing escapees", "is_correct": false, "rationale": "Police help in recapture operations."}, {"text": "Pursuit is most effective while the trail is fresh", "is_correct": true, "rationale": "Early notice allows checkpoints and pursuit before the escapee gets far."}]'::jsonb, 3, 'hard', 'Negligent guards may be liable under Article 224 of the Revised Penal Code.', 'Revised Penal Code, Arts. 157 and 223-224', 'Study module Correctional Administration, Chapter 1: Institutional Correction (CA-1.4).', 'generated', 'tos_2024', 1, FALSE, 'CA-1.4', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-1.4_03', 'corrections', 'Institutional Correction', 'Many PDLs fall ill after lunch. Why should samples of the food be kept?', '[{"text": "To serve the food again at the next meal", "is_correct": false, "rationale": "Suspect food must never be served again."}, {"text": "To show the food to visitors as an example", "is_correct": false, "rationale": "Display serves no purpose."}, {"text": "To throw it away later without testing", "is_correct": false, "rationale": "Discarding samples destroys evidence."}, {"text": "To find the cause of the poisoning and fix responsibility", "is_correct": true, "rationale": "Testing the samples shows what caused the illness and who is accountable."}]'::jsonb, 3, 'hard', 'Sick PDLs receive medical care first.', NULL, 'Study module Correctional Administration, Chapter 1: Institutional Correction (CA-1.4).', 'generated', 'tos_2024', 1, FALSE, 'CA-1.4', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-1.4_04', 'corrections', 'Institutional Correction', 'Contraband keeps getting into a jail despite cell searches. Why should the warden study the entry points?', '[{"text": "Cell searches are the only way to stop contraband", "is_correct": false, "rationale": "Searches alone treat the symptom."}, {"text": "Contraband is made by the PDLs inside their cells", "is_correct": false, "rationale": "Most contraband, such as phones, comes from outside."}, {"text": "Contraband comes from outside, so its source must be closed", "is_correct": true, "rationale": "Repeated searches find contraband but do not stop it; controlling entry points stops the supply."}, {"text": "Entry points have no link to contraband", "is_correct": false, "rationale": "Entry points are the main channel."}]'::jsonb, 2, 'hard', 'Staff corruption is often part of the problem.', NULL, 'Study module Correctional Administration, Chapter 1: Institutional Correction (CA-1.4).', 'generated', 'tos_2024', 1, FALSE, 'CA-1.4', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-1.4_05', 'corrections', 'Institutional Correction', 'PDLs take a guard hostage and demand to talk to the media. Which response is best?', '[{"text": "Give in to all of their demands at once to free the guard", "is_correct": false, "rationale": "Giving in to everything encourages future incidents."}, {"text": "Storm the area immediately without any plan", "is_correct": false, "rationale": "An unplanned assault endangers the hostage."}, {"text": "Contain the area and let trained negotiators handle it", "is_correct": true, "rationale": "Containment, negotiation and a coordinated crisis team give the best chance of a safe resolution."}, {"text": "Open the gates so the PDLs can leave", "is_correct": false, "rationale": "Releasing PDLs is unlawful and dangerous."}]'::jsonb, 2, 'hard', 'Negotiation buys time to plan and to protect lives.', NULL, 'Study module Correctional Administration, Chapter 1: Institutional Correction (CA-1.4).', 'generated', 'tos_2024', 1, FALSE, 'CA-1.4', 'Evaluating') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-1.4_06', 'corrections', 'Institutional Correction', 'A fire breaks out in a jail at night. Which action is most appropriate?', '[{"text": "Open all of the gates and let the PDLs run out on their own", "is_correct": false, "rationale": "Opening the gates leads to escapes and chaos."}, {"text": "Keep all cells locked until the fire is out", "is_correct": false, "rationale": "Leaving PDLs locked in a fire endangers lives."}, {"text": "Wait for the morning shift before acting", "is_correct": false, "rationale": "Delay can be deadly."}, {"text": "Move the PDLs under guard to a set safe area, per the fire plan", "is_correct": true, "rationale": "A fire plan provides safe evacuation while keeping PDLs in custody."}]'::jsonb, 3, 'hard', 'Fire drills prepare staff and PDLs for evacuation.', 'R.A. 9514', 'Study module Correctional Administration, Chapter 1: Institutional Correction (CA-1.4).', 'generated', 'tos_2024', 1, FALSE, 'CA-1.4', 'Evaluating') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-1.4_07', 'corrections', 'Institutional Correction', 'Which plan best prepares a jail for a strong earthquake?', '[{"text": "Plan to release all of the PDLs whenever the ground shakes", "is_correct": false, "rationale": "Releasing PDLs is not a lawful response."}, {"text": "Leave planning to the PDLs'' leaders", "is_correct": false, "rationale": "Planning is a duty of management."}, {"text": "Set safe areas inside the perimeter, hold drills, count after", "is_correct": true, "rationale": "Preparedness keeps PDLs safe and in custody during and after an earthquake."}, {"text": "Have no plan, since earthquakes cannot be predicted", "is_correct": false, "rationale": "Unpredictability is the reason to prepare."}]'::jsonb, 2, 'hard', 'PDLs who return after a calamity may earn a special time allowance for loyalty.', 'Revised Penal Code, Art. 98, as amended by R.A. 10592', 'Study module Correctional Administration, Chapter 1: Institutional Correction (CA-1.4).', 'generated', 'tos_2024', 1, FALSE, 'CA-1.4', 'Evaluating') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-1.4_08', 'corrections', 'Institutional Correction', 'A jail in a flood-prone area faces a strong typhoon. Which decision is best?', '[{"text": "Wait until the flood enters the cells before acting", "is_correct": false, "rationale": "Waiting risks drowning and escapes."}, {"text": "Release the PDLs to their families during the typhoon", "is_correct": false, "rationale": "Release needs a lawful basis."}, {"text": "Transfer PDLs early to a safer facility, with stocks of food and water", "is_correct": true, "rationale": "Early transfer, done lawfully, protects lives while keeping custody; supplies prepare for isolation."}, {"text": "Move only the guards to safety", "is_correct": false, "rationale": "PDLs'' lives must be protected too."}]'::jsonb, 2, 'hard', 'The courts are informed of transfers of detainees.', NULL, 'Study module Correctional Administration, Chapter 1: Institutional Correction (CA-1.4).', 'generated', 'tos_2024', 1, FALSE, 'CA-1.4', 'Evaluating') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-2.1_01', 'corrections', 'Non-Institutional Correction', 'Which body recommends executive clemency and grants parole?', '[{"text": "Parole and Probation Administration", "is_correct": false, "rationale": "The PPA supervises probationers and parolees."}, {"text": "Bureau of Corrections", "is_correct": false, "rationale": "BuCor runs national penitentiaries."}, {"text": "National Police Commission", "is_correct": false, "rationale": "NAPOLCOM administers the PNP."}, {"text": "Board of Pardons and Parole", "is_correct": true, "rationale": "The Board of Pardons and Parole grants parole and recommends pardon and other clemency to the President."}]'::jsonb, 3, 'easy', 'The Board is attached to the DOJ.', 'Act No. 4103, as amended', 'Study module Correctional Administration, Chapter 2: Non-Institutional Correction (CA-2.1).', 'generated', 'tos_2024', 1, FALSE, 'CA-2.1', 'Remembering') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-2.1_02', 'corrections', 'Non-Institutional Correction', 'Which form of clemency postpones the execution of a sentence?', '[{"text": "Commutation", "is_correct": false, "rationale": "Commutation reduces the sentence."}, {"text": "Absolute pardon", "is_correct": false, "rationale": "Absolute pardon frees the convict from the penalty."}, {"text": "Reprieve", "is_correct": true, "rationale": "A reprieve temporarily delays the execution of a sentence."}, {"text": "Amnesty", "is_correct": false, "rationale": "Amnesty wipes out the offense, usually political."}]'::jsonb, 2, 'easy', 'Reprieves were usually granted in death penalty cases.', '1987 Constitution, Art. VII, Sec. 19', 'Study module Correctional Administration, Chapter 2: Non-Institutional Correction (CA-2.1).', 'generated', 'tos_2024', 1, FALSE, 'CA-2.1', 'Remembering') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-2.1_03', 'corrections', 'Non-Institutional Correction', 'What happens if a person granted a conditional pardon violates its conditions?', '[{"text": "He may be rearrested to serve the rest of his sentence", "is_correct": true, "rationale": "The President may order rearrest and recommitment, and he may also be prosecuted under Article 159."}, {"text": "Nothing, because a pardon cannot be withdrawn", "is_correct": false, "rationale": "A conditional pardon depends on compliance with its conditions."}, {"text": "His original conviction is erased", "is_correct": false, "rationale": "Violation revives, not erases, the penalty."}, {"text": "He is automatically placed on probation", "is_correct": false, "rationale": "Probation is a separate court-granted privilege."}]'::jsonb, 0, 'easy', 'A conditional pardon is like a contract between the State and the grantee.', 'Revised Penal Code, Art. 159', 'Study module Correctional Administration, Chapter 2: Non-Institutional Correction (CA-2.1).', 'generated', 'tos_2024', 1, FALSE, 'CA-2.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-2.1_04', 'corrections', 'Non-Institutional Correction', 'What does commutation of sentence do?', '[{"text": "It erases the crime as if it never happened", "is_correct": false, "rationale": "Erasing the offense is amnesty."}, {"text": "It postpones the sentence for a time", "is_correct": false, "rationale": "Postponing is a reprieve."}, {"text": "It reduces the penalty to a lighter one", "is_correct": true, "rationale": "Commutation replaces the sentence with a lighter penalty or shorter term."}, {"text": "It sets the convict free under supervision", "is_correct": false, "rationale": "Release under supervision describes parole."}]'::jsonb, 2, 'easy', 'Commutation partially extinguishes criminal liability.', 'Revised Penal Code, Art. 94', 'Study module Correctional Administration, Chapter 2: Non-Institutional Correction (CA-2.1).', 'generated', 'tos_2024', 1, FALSE, 'CA-2.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-2.1_05', 'corrections', 'Non-Institutional Correction', 'Why can the President not pardon an accused whose case is still on appeal?', '[{"text": "Pardon is allowed only for minor offenses", "is_correct": false, "rationale": "Pardon may cover grave offenses too."}, {"text": "The Constitution allows pardon only after final conviction", "is_correct": true, "rationale": "Article VII, Section 19 allows pardon only after conviction by final judgment."}, {"text": "Only the Supreme Court may grant pardons", "is_correct": false, "rationale": "Pardon is an executive act, not a judicial one."}, {"text": "Pardon is allowed only before the case is filed", "is_correct": false, "rationale": "Pardon comes after, not before, conviction."}]'::jsonb, 1, 'easy', 'An accused who wants a pardon must first withdraw his appeal.', '1987 Constitution, Art. VII, Sec. 19', 'Study module Correctional Administration, Chapter 2: Non-Institutional Correction (CA-2.1).', 'generated', 'tos_2024', 1, FALSE, 'CA-2.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-2.1_06', 'corrections', 'Non-Institutional Correction', 'A law repeals the crime for which a PDL is serving his sentence. How does this affect him?', '[{"text": "He must still serve the full sentence anyway", "is_correct": false, "rationale": "Favorable laws apply to those already serving."}, {"text": "He benefits, as favorable penal laws apply retroactively", "is_correct": true, "rationale": "Article 22 gives retroactive effect to penal laws favorable to the accused, unless he is a habitual criminal."}, {"text": "He benefits only if he pays a fine", "is_correct": false, "rationale": "No fine is required."}, {"text": "He loses all his time allowances", "is_correct": false, "rationale": "Repeal does not cancel earned allowances."}]'::jsonb, 1, 'easy', 'Decriminalization is one of the non-executive ways a sentence may end.', 'Revised Penal Code, Art. 22', 'Study module Correctional Administration, Chapter 2: Non-Institutional Correction (CA-2.1).', 'generated', 'tos_2024', 1, FALSE, 'CA-2.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-2.2_01', 'corrections', 'Non-Institutional Correction', 'An accused is sentenced to four years of imprisonment and wants probation. When must he apply?', '[{"text": "Within the period for perfecting an appeal", "is_correct": true, "rationale": "The application must be filed with the trial court within the period for perfecting an appeal."}, {"text": "Any time while serving his sentence", "is_correct": false, "rationale": "Probation is not available once he starts serving."}, {"text": "Only after his appeal is decided", "is_correct": false, "rationale": "Generally, filing an appeal bars probation, except under R.A. 10707''s rule on modified judgments."}, {"text": "Within one year from conviction", "is_correct": false, "rationale": "No one-year period exists."}]'::jsonb, 0, 'medium', 'Filing an application for probation is a waiver of the right to appeal.', 'P.D. 968, Sec. 4, as amended by R.A. 10707', 'Study module Correctional Administration, Chapter 2: Non-Institutional Correction (CA-2.2).', 'generated', 'tos_2024', 1, FALSE, 'CA-2.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-2.2_02', 'corrections', 'Non-Institutional Correction', 'An accused is sentenced to eight years of imprisonment. Can he apply for probation?', '[{"text": "No, the maximum term exceeds six years", "is_correct": true, "rationale": "P.D. 968 disqualifies those sentenced to a maximum term of more than six years."}, {"text": "Yes, if it is his first offense", "is_correct": false, "rationale": "A first offense does not cure the disqualification."}, {"text": "Yes, if the victim agrees", "is_correct": false, "rationale": "The victim''s consent does not make him eligible."}, {"text": "No, unless he pays a bond", "is_correct": false, "rationale": "A bond does not make him eligible."}]'::jsonb, 0, 'medium', 'Other disqualifications include crimes against national security and prior convictions with certain penalties.', 'P.D. 968, Sec. 9, as amended by R.A. 10707', 'Study module Correctional Administration, Chapter 2: Non-Institutional Correction (CA-2.2).', 'generated', 'tos_2024', 1, FALSE, 'CA-2.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-2.2_03', 'corrections', 'Non-Institutional Correction', 'The trial court gave a non-probationable sentence, but on appeal it was reduced to a probationable one. Can the accused still apply?', '[{"text": "No, because he has already appealed", "is_correct": false, "rationale": "R.A. 10707 created this exception to the bar on appeal."}, {"text": "No, because only the trial court''s sentence counts", "is_correct": false, "rationale": "The modified decision is the one that counts."}, {"text": "Yes, based on the modified decision before it becomes final", "is_correct": true, "rationale": "R.A. 10707 allows probation based on the modified, probationable judgment, applied for before it becomes final."}, {"text": "Yes, but only after serving half of the sentence", "is_correct": false, "rationale": "No service is required first."}]'::jsonb, 2, 'medium', 'This corrected the harsh result when a wrongly heavy sentence was later reduced on appeal.', 'P.D. 968, Sec. 4, as amended by R.A. 10707', 'Study module Correctional Administration, Chapter 2: Non-Institutional Correction (CA-2.2).', 'generated', 'tos_2024', 1, FALSE, 'CA-2.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-2.2_04', 'corrections', 'Non-Institutional Correction', 'The court orders a post-sentence investigation. Within what period must the probation officer submit his report?', '[{"text": "15 days", "is_correct": false, "rationale": "The court decides within 15 days after receiving the report."}, {"text": "30 days", "is_correct": false, "rationale": "Thirty days is not the period set by law."}, {"text": "90 days", "is_correct": false, "rationale": "Ninety days is longer than the law allows."}, {"text": "60 days", "is_correct": true, "rationale": "The probation officer submits the report within 60 days from receipt of the order."}]'::jsonb, 3, 'medium', 'The investigation covers the offender''s background, character and risk.', 'P.D. 968, Sec. 7', 'Study module Correctional Administration, Chapter 2: Non-Institutional Correction (CA-2.2).', 'generated', 'tos_2024', 1, FALSE, 'CA-2.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-2.2_05', 'corrections', 'Non-Institutional Correction', 'After probation is granted, within how many hours must the probationer present himself to the probation officer?', '[{"text": "24 hours", "is_correct": false, "rationale": "Twenty-four hours is not the period in the law."}, {"text": "48 hours", "is_correct": false, "rationale": "Forty-eight hours is not the period in the law."}, {"text": "72 hours", "is_correct": true, "rationale": "A mandatory condition is reporting within 72 hours of receiving the probation order."}, {"text": "7 days", "is_correct": false, "rationale": "Seven days is too long."}]'::jsonb, 2, 'medium', 'He must also report at least once a month thereafter.', 'P.D. 968, Sec. 10', 'Study module Correctional Administration, Chapter 2: Non-Institutional Correction (CA-2.2).', 'generated', 'tos_2024', 1, FALSE, 'CA-2.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-2.2_06', 'corrections', 'Non-Institutional Correction', 'A probationer was sentenced to one year of imprisonment. What is the longest probation period the court may set?', '[{"text": "One year", "is_correct": false, "rationale": "The period may be up to two years, not limited to one."}, {"text": "Two years", "is_correct": true, "rationale": "If the sentence is not more than one year, probation may not exceed two years."}, {"text": "Six years", "is_correct": false, "rationale": "Six years is the limit for longer sentences."}, {"text": "Ten years", "is_correct": false, "rationale": "Ten years is beyond what the law allows."}]'::jsonb, 1, 'medium', 'For sentences above one year, probation may not exceed six years.', 'P.D. 968, Sec. 14', 'Study module Correctional Administration, Chapter 2: Non-Institutional Correction (CA-2.2).', 'generated', 'tos_2024', 1, FALSE, 'CA-2.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-2.2_07', 'corrections', 'Non-Institutional Correction', 'A probationer repeatedly fails to report and is seen with known drug dealers. What may happen?', '[{"text": "The probation officer may jail him without any court order", "is_correct": false, "rationale": "Only the court may order arrest and revocation."}, {"text": "Nothing, since probation cannot be revoked", "is_correct": false, "rationale": "Probation may be revoked for violations."}, {"text": "The court may issue a warrant and, after a hearing, revoke probation", "is_correct": true, "rationale": "On violation, the court may order arrest, hold a summary hearing, and revoke or modify probation."}, {"text": "He is given a new probation automatically", "is_correct": false, "rationale": "No automatic new probation exists."}]'::jsonb, 2, 'medium', 'An order revoking probation is not appealable.', 'P.D. 968, Sec. 15', 'Study module Correctional Administration, Chapter 2: Non-Institutional Correction (CA-2.2).', 'generated', 'tos_2024', 1, FALSE, 'CA-2.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-2.2_08', 'corrections', 'Non-Institutional Correction', 'A person is convicted of selling dangerous drugs under Section 5 of R.A. 9165. Can he apply for probation?', '[{"text": "Yes, if the drugs were small in amount", "is_correct": false, "rationale": "The amount does not lift the disqualification for sale."}, {"text": "No, drug traffickers are disqualified from probation", "is_correct": true, "rationale": "Section 24 of R.A. 9165 disqualifies those convicted of drug trafficking or pushing from probation."}, {"text": "Yes, if he is a first-time offender", "is_correct": false, "rationale": "First offense does not lift the disqualification."}, {"text": "No, unless the PDEA agrees", "is_correct": false, "rationale": "PDEA''s agreement has no effect on eligibility."}]'::jsonb, 1, 'medium', 'First-time minor offenders for drug use may get suspended sentence or probation under R.A. 9165.', 'R.A. 9165, Sec. 24', 'Study module Correctional Administration, Chapter 2: Non-Institutional Correction (CA-2.2).', 'generated', 'tos_2024', 1, FALSE, 'CA-2.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-2.2_09', 'corrections', 'Non-Institutional Correction', 'A probationer has completed his probation and the court orders his final discharge. What is the effect?', '[{"text": "He must still serve the original prison sentence in full", "is_correct": false, "rationale": "Probation replaces service of the sentence."}, {"text": "He remains under supervision for life", "is_correct": false, "rationale": "Supervision ends with final discharge."}, {"text": "He can no longer be employed by government", "is_correct": false, "rationale": "His rights are restored, not further limited."}, {"text": "His civil rights return and his liability for it ends", "is_correct": true, "rationale": "Final discharge restores civil rights lost by the conviction and totally extinguishes criminal liability for that offense."}]'::jsonb, 3, 'medium', 'Civil liability to the victim is a separate matter.', 'P.D. 968, Sec. 16', 'Study module Correctional Administration, Chapter 2: Non-Institutional Correction (CA-2.2).', 'generated', 'tos_2024', 1, FALSE, 'CA-2.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-2.2_10', 'corrections', 'Non-Institutional Correction', 'A respected resident of a remote town is appointed to help a probation officer supervise probationers there. What is his role?', '[{"text": "Parole officer (PPA)", "is_correct": false, "rationale": "Parole officers supervise parolees and are employees of the PPA."}, {"text": "Volunteer probation aide", "is_correct": true, "rationale": "Volunteer probation aides assist probation officers in supervising probationers in the community."}, {"text": "Probation officer (PPA)", "is_correct": false, "rationale": "Probation officers are employees of the PPA."}, {"text": "Jail officer", "is_correct": false, "rationale": "Jail officers work inside jails."}]'::jsonb, 1, 'medium', 'Volunteers extend the reach of the probation system.', 'P.D. 968, Sec. 28', 'Study module Correctional Administration, Chapter 2: Non-Institutional Correction (CA-2.2).', 'generated', 'tos_2024', 1, FALSE, 'CA-2.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-2.3_01', 'corrections', 'Non-Institutional Correction', 'A PDL is serving an indeterminate sentence of 6 years and 1 day to 12 years. When may he first be considered for parole?', '[{"text": "After serving the maximum of 12 years", "is_correct": false, "rationale": "Serving the maximum means full service, not parole."}, {"text": "After serving the minimum of 6 years and 1 day", "is_correct": true, "rationale": "Under Act 4103, the Board may grant parole once the PDL has served the minimum and is found fit for release."}, {"text": "After serving one year", "is_correct": false, "rationale": "One year is below the minimum."}, {"text": "Only after a presidential pardon", "is_correct": false, "rationale": "Parole is granted by the Board, not through pardon."}]'::jsonb, 1, 'medium', 'Good conduct time allowances count toward the period served.', 'Act No. 4103, Sec. 5', 'Study module Correctional Administration, Chapter 2: Non-Institutional Correction (CA-2.3).', 'generated', 'tos_2024', 1, FALSE, 'CA-2.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-2.3_02', 'corrections', 'Non-Institutional Correction', 'A PDL is serving reclusion perpetua for murder. Is he eligible for parole under the Indeterminate Sentence Law?', '[{"text": "No, reclusion perpetua is not covered by the law", "is_correct": true, "rationale": "The ISL does not apply to those sentenced to life imprisonment or reclusion perpetua; R.A. 9346 also bars their parole."}, {"text": "Yes, after he has served at least ten years", "is_correct": false, "rationale": "No such ten-year rule applies under the ISL."}, {"text": "Yes, as long as he keeps good behavior", "is_correct": false, "rationale": "Good behavior does not make the ISL apply."}, {"text": "No, unless he is over sixty years old", "is_correct": false, "rationale": "Age does not make the ISL apply."}]'::jsonb, 0, 'medium', 'Such PDLs may seek executive clemency instead.', 'Act No. 4103, Sec. 2; R.A. 9346, Sec. 3', 'Study module Correctional Administration, Chapter 2: Non-Institutional Correction (CA-2.3).', 'generated', 'tos_2024', 1, FALSE, 'CA-2.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-2.3_03', 'corrections', 'Non-Institutional Correction', 'A habitual delinquent is sentenced to imprisonment. How does the Indeterminate Sentence Law apply to him?', '[{"text": "It applies with an extra reward of parole", "is_correct": false, "rationale": "Habitual delinquents get no special parole reward."}, {"text": "It applies only if he pleads guilty", "is_correct": false, "rationale": "A guilty plea does not remove the exclusion."}, {"text": "It does not apply; habitual delinquents are excluded", "is_correct": true, "rationale": "Act 4103 excludes habitual delinquents from its benefits."}, {"text": "It applies once he reaches old age", "is_correct": false, "rationale": "Age does not remove the exclusion."}]'::jsonb, 2, 'medium', 'Other exclusions include those who escaped or violated a conditional pardon.', 'Act No. 4103, Sec. 2', 'Study module Correctional Administration, Chapter 2: Non-Institutional Correction (CA-2.3).', 'generated', 'tos_2024', 1, FALSE, 'CA-2.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-2.3_04', 'corrections', 'Non-Institutional Correction', 'A convict is sentenced to ten months of imprisonment. Does the Indeterminate Sentence Law apply?', '[{"text": "Yes, he gets a minimum and maximum term", "is_correct": false, "rationale": "Short terms are not split into minimum and maximum."}, {"text": "No, it does not apply to terms not exceeding one year", "is_correct": true, "rationale": "The ISL excludes those whose maximum term does not exceed one year; a straight penalty is imposed."}, {"text": "Yes, he may be paroled after one month", "is_correct": false, "rationale": "Parole under the ISL is not available for such terms."}, {"text": "No, because he must apply for probation instead", "is_correct": false, "rationale": "He may apply for probation, but that is a separate matter from the ISL."}]'::jsonb, 1, 'medium', 'Probation may be available for him if he qualifies.', 'Act No. 4103, Sec. 2', 'Study module Correctional Administration, Chapter 2: Non-Institutional Correction (CA-2.3).', 'generated', 'tos_2024', 1, FALSE, 'CA-2.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-2.3_05', 'corrections', 'Non-Institutional Correction', 'A PDL''s records show he has served his minimum term with good conduct. Which body decides whether he will be paroled?', '[{"text": "Parole and Probation Administration", "is_correct": false, "rationale": "The PPA supervises parolees after release."}, {"text": "Trial court that convicted him", "is_correct": false, "rationale": "The trial court does not grant parole."}, {"text": "Bureau of Corrections", "is_correct": false, "rationale": "BuCor submits records but does not grant parole."}, {"text": "Board of Pardons and Parole", "is_correct": true, "rationale": "The BPP evaluates and grants parole."}]'::jsonb, 3, 'medium', 'The institution forwards the PDL''s carpeta and prison record to the Board.', 'Act No. 4103, Sec. 5', 'Study module Correctional Administration, Chapter 2: Non-Institutional Correction (CA-2.3).', 'generated', 'tos_2024', 1, FALSE, 'CA-2.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-2.3_06', 'corrections', 'Non-Institutional Correction', 'After his release on parole, who supervises the parolee?', '[{"text": "A parole and probation officer of the PPA", "is_correct": true, "rationale": "The Parole and Probation Administration supervises parolees through its officers."}, {"text": "The warden of his former jail", "is_correct": false, "rationale": "The warden''s custody ends at release."}, {"text": "The barangay captain of his area", "is_correct": false, "rationale": "Barangay officials may help but are not the supervisors."}, {"text": "The judge who convicted him", "is_correct": false, "rationale": "Judges do not supervise parolees."}]'::jsonb, 0, 'medium', 'The parolee reports regularly to his supervising officer.', 'Act No. 4103, Sec. 6', 'Study module Correctional Administration, Chapter 2: Non-Institutional Correction (CA-2.3).', 'generated', 'tos_2024', 1, FALSE, 'CA-2.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-2.3_07', 'corrections', 'Non-Institutional Correction', 'A parolee commits a new offense while on parole. What may the Board of Pardons and Parole do?', '[{"text": "Nothing, since a grant of parole can never be revoked", "is_correct": false, "rationale": "Parole can be revoked for violations."}, {"text": "Give him a second parole at once as a final chance", "is_correct": false, "rationale": "There is no automatic second parole."}, {"text": "Reduce his sentence as a warning", "is_correct": false, "rationale": "Violation leads to recommitment, not reduction."}, {"text": "Order his arrest and recommitment for the rest of his term", "is_correct": true, "rationale": "Act 4103 lets the Board order the rearrest of a parolee who violates his conditions, to serve the remaining sentence."}]'::jsonb, 3, 'medium', 'He may also be prosecuted for the new offense.', 'Act No. 4103, Sec. 8', 'Study module Correctional Administration, Chapter 2: Non-Institutional Correction (CA-2.3).', 'generated', 'tos_2024', 1, FALSE, 'CA-2.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-2.3_08', 'corrections', 'Non-Institutional Correction', 'A parolee still has four years left on his maximum sentence. How long does his parole supervision last?', '[{"text": "Until his maximum term ends, unless finally released earlier", "is_correct": true, "rationale": "Supervision covers the unexpired portion of the maximum sentence; the Board may issue a final release earlier for good conduct."}, {"text": "For six months only from the date of his release", "is_correct": false, "rationale": "Six months is not the period under the law."}, {"text": "For the rest of his life, even after the maximum term", "is_correct": false, "rationale": "Supervision ends when the maximum term expires."}, {"text": "Until he finds a job and can support himself", "is_correct": false, "rationale": "Employment does not end supervision."}]'::jsonb, 0, 'medium', 'A final certificate of release ends his supervision.', 'Act No. 4103, Sec. 6', 'Study module Correctional Administration, Chapter 2: Non-Institutional Correction (CA-2.3).', 'generated', 'tos_2024', 1, FALSE, 'CA-2.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-2.3_09', 'corrections', 'Non-Institutional Correction', 'Which records of the PDL does the institution send to the Board of Pardons and Parole for its review?', '[{"text": "The carpeta and prison record", "is_correct": true, "rationale": "The carpeta (case file) and prison record show the sentence, conduct and program participation."}, {"text": "The PDL''s social media posts", "is_correct": false, "rationale": "Social media posts are not the institutional record."}, {"text": "The PDL''s bank statements", "is_correct": false, "rationale": "Bank statements are not part of the review."}, {"text": "The PDL''s school report cards", "is_correct": false, "rationale": "School records are not the institutional record."}]'::jsonb, 0, 'medium', 'Incomplete records often delay parole review.', NULL, 'Study module Correctional Administration, Chapter 2: Non-Institutional Correction (CA-2.3).', 'generated', 'tos_2024', 1, FALSE, 'CA-2.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-2.3_10', 'corrections', 'Non-Institutional Correction', 'A parolee wants to move to another province for work. What should he do?', '[{"text": "Move at once without telling anyone", "is_correct": false, "rationale": "Moving without approval violates his conditions."}, {"text": "Stop reporting, since he will be far away", "is_correct": false, "rationale": "Failing to report is a violation."}, {"text": "Get prior approval so his supervision can be transferred", "is_correct": true, "rationale": "Parolees must obtain approval to change residence, and supervision is transferred to the new area."}, {"text": "Ask his former jail warden for permission", "is_correct": false, "rationale": "The warden no longer has authority over him."}]'::jsonb, 2, 'medium', 'The conditions of parole are stated in the release document.', NULL, 'Study module Correctional Administration, Chapter 2: Non-Institutional Correction (CA-2.3).', 'generated', 'tos_2024', 1, FALSE, 'CA-2.3', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-2.4_01', 'corrections', 'Non-Institutional Correction', 'Under R.A. 10592, how many days of good conduct time allowance per month are earned in the first two years?', '[{"text": "20 days", "is_correct": true, "rationale": "Twenty days per month are granted during the first two years."}, {"text": "23 days", "is_correct": false, "rationale": "Twenty-three days apply from the third to the fifth year."}, {"text": "25 days", "is_correct": false, "rationale": "Twenty-five days apply from the sixth to the tenth year."}, {"text": "30 days", "is_correct": false, "rationale": "Thirty days apply from the eleventh year onward."}]'::jsonb, 0, 'easy', 'GCTA applies to both preventive imprisonment and service of sentence.', 'Revised Penal Code, Art. 97, as amended by R.A. 10592', 'Study module Correctional Administration, Chapter 2: Non-Institutional Correction (CA-2.4).', 'generated', 'tos_2024', 1, FALSE, 'CA-2.4', 'Remembering') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-2.4_02', 'corrections', 'Non-Institutional Correction', 'Who may grant good conduct time allowances under R.A. 10592?', '[{"text": "The trial judge who convicted the PDL", "is_correct": false, "rationale": "Judges do not grant GCTA."}, {"text": "The President of the Philippines only", "is_correct": false, "rationale": "The President grants clemency, not GCTA."}, {"text": "The BuCor Director, BJMP Chief or jail warden", "is_correct": true, "rationale": "Article 99, as amended, vests this authority in the Director of BuCor, the Chief of the BJMP and wardens of provincial, district, city or municipal jails."}, {"text": "The barangay captain where the PDL lives", "is_correct": false, "rationale": "Barangay officials have no role in GCTA."}]'::jsonb, 2, 'easy', 'Grants are made through management screening committees.', 'Revised Penal Code, Art. 99, as amended by R.A. 10592', 'Study module Correctional Administration, Chapter 2: Non-Institutional Correction (CA-2.4).', 'generated', 'tos_2024', 1, FALSE, 'CA-2.4', 'Remembering') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-2.4_03', 'corrections', 'Non-Institutional Correction', 'Why can a time allowance not be taken back once it has been granted?', '[{"text": "The law says allowances once granted shall not be revoked", "is_correct": true, "rationale": "Article 99, as amended, provides that time allowances once granted shall not be revoked."}, {"text": "Allowances are always granted by the President alone", "is_correct": false, "rationale": "Allowances are granted by correctional authorities."}, {"text": "Allowances are only temporary favors", "is_correct": false, "rationale": "Once granted, they are permanent."}, {"text": "Allowances are given only after release", "is_correct": false, "rationale": "Allowances are credited during detention and service."}]'::jsonb, 0, 'easy', 'Misbehavior affects future grants, not those already given.', 'Revised Penal Code, Art. 99, as amended by R.A. 10592', 'Study module Correctional Administration, Chapter 2: Non-Institutional Correction (CA-2.4).', 'generated', 'tos_2024', 1, FALSE, 'CA-2.4', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-2.4_04', 'corrections', 'Non-Institutional Correction', 'What extra allowance may a PDL earn by teaching, studying or mentoring?', '[{"text": "15 days per month, on top of GCTA", "is_correct": true, "rationale": "R.A. 10592 adds 15 days per month for teaching, studying or mentoring service."}, {"text": "5 days per year, instead of GCTA", "is_correct": false, "rationale": "The allowance is monthly and additional to GCTA."}, {"text": "30 days per year, only at release", "is_correct": false, "rationale": "It is credited monthly, not only at release."}, {"text": "None, because only work counts", "is_correct": false, "rationale": "Teaching, studying and mentoring are expressly rewarded."}]'::jsonb, 0, 'easy', 'This encourages participation in education and mentoring programs.', 'Revised Penal Code, Art. 97, as amended by R.A. 10592', 'Study module Correctional Administration, Chapter 2: Non-Institutional Correction (CA-2.4).', 'generated', 'tos_2024', 1, FALSE, 'CA-2.4', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-2.4_05', 'corrections', 'Non-Institutional Correction', 'Which of the following partially extinguishes criminal liability?', '[{"text": "Absolute pardon", "is_correct": false, "rationale": "Absolute pardon totally extinguishes liability."}, {"text": "Good conduct allowances", "is_correct": true, "rationale": "Article 94 lists conditional pardon, commutation and good conduct allowances as partial extinction."}, {"text": "Death of the convict", "is_correct": false, "rationale": "Death totally extinguishes criminal liability."}, {"text": "Amnesty", "is_correct": false, "rationale": "Amnesty totally extinguishes liability."}]'::jsonb, 1, 'easy', 'Total extinction is covered by Article 89.', 'Revised Penal Code, Arts. 89 and 94', 'Study module Correctional Administration, Chapter 2: Non-Institutional Correction (CA-2.4).', 'generated', 'tos_2024', 1, FALSE, 'CA-2.4', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-2.4_06', 'corrections', 'Non-Institutional Correction', 'Why is an absolute pardon a total, but a conditional pardon only a partial, extinction of criminal liability?', '[{"text": "A conditional pardon can be undone if its conditions are broken", "is_correct": true, "rationale": "The conditional pardon''s effect depends on compliance, so liability is only partly extinguished."}, {"text": "A conditional pardon is granted only by the trial courts", "is_correct": false, "rationale": "Both pardons are executive acts."}, {"text": "An absolute pardon applies only to light offenses", "is_correct": false, "rationale": "Absolute pardons may cover grave offenses."}, {"text": "An absolute pardon is granted only after death", "is_correct": false, "rationale": "Pardons are granted to living convicts."}]'::jsonb, 0, 'easy', 'Violation of a conditional pardon is punished under Article 159.', 'Revised Penal Code, Arts. 89, 94 and 159', 'Study module Correctional Administration, Chapter 2: Non-Institutional Correction (CA-2.4).', 'generated', 'tos_2024', 1, FALSE, 'CA-2.4', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-2.5_01', 'corrections', 'Non-Institutional Correction', 'A detainee who agreed in writing to follow the rules has been held for two years. The maximum penalty for his offense is two years. What should happen?', '[{"text": "He should be released, though his trial continues", "is_correct": true, "rationale": "Article 29 orders release when preventive imprisonment equals the possible maximum penalty, without prejudice to the trial."}, {"text": "He must stay until the trial ends", "is_correct": false, "rationale": "Continued detention would exceed the possible penalty."}, {"text": "He must serve two more years after conviction", "is_correct": false, "rationale": "He has already been credited the full period."}, {"text": "He should be transferred to BuCor", "is_correct": false, "rationale": "There is no basis to transfer him."}]'::jsonb, 0, 'hard', 'This prevents detainees from being held longer than any sentence they could receive.', 'Revised Penal Code, Art. 29, as amended by R.A. 10592', 'Study module Correctional Administration, Chapter 2: Non-Institutional Correction (CA-2.5).', 'generated', 'tos_2024', 1, FALSE, 'CA-2.5', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-2.5_02', 'corrections', 'Non-Institutional Correction', 'A detainee did not agree to follow the rules for convicted prisoners and spent 20 months in preventive imprisonment. How much is credited to his sentence?', '[{"text": "20 months", "is_correct": false, "rationale": "Full credit requires the written agreement."}, {"text": "10 months", "is_correct": false, "rationale": "One-half is not the rule."}, {"text": "16 months", "is_correct": true, "rationale": "Without the written agreement, he is credited with four-fifths of the period: 4/5 x 20 = 16 months."}, {"text": "None", "is_correct": false, "rationale": "He still gets partial credit."}]'::jsonb, 2, 'hard', 'The agreement is made in writing with the assistance of counsel.', 'Revised Penal Code, Art. 29, as amended by R.A. 10592', 'Study module Correctional Administration, Chapter 2: Non-Institutional Correction (CA-2.5).', 'generated', 'tos_2024', 1, FALSE, 'CA-2.5', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-2.5_03', 'corrections', 'Non-Institutional Correction', 'During an earthquake, a PDL left the jail and returned within 48 hours after the calamity was declared over. What allowance may he receive?', '[{"text": "A deduction of one-fifth of his sentence", "is_correct": true, "rationale": "Article 98 grants one-fifth for PDLs who evaded during a calamity and gave themselves up within 48 hours after it passed."}, {"text": "A deduction of two-fifths of his sentence", "is_correct": false, "rationale": "Two-fifths is for those who chose to stay."}, {"text": "No deduction, since he left the jail", "is_correct": false, "rationale": "The law rewards his return."}, {"text": "Immediate release", "is_correct": false, "rationale": "The allowance reduces the sentence; it does not mean release."}]'::jsonb, 0, 'hard', 'This is the special time allowance for loyalty.', 'Revised Penal Code, Art. 98, as amended by R.A. 10592', 'Study module Correctional Administration, Chapter 2: Non-Institutional Correction (CA-2.5).', 'generated', 'tos_2024', 1, FALSE, 'CA-2.5', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-2.5_04', 'corrections', 'Non-Institutional Correction', 'During a calamity, a PDL chose to stay in the jail even though he could have left. What allowance may he receive?', '[{"text": "A deduction of one-fifth of his sentence", "is_correct": false, "rationale": "One-fifth is for those who left and returned."}, {"text": "A deduction of two-fifths of his sentence", "is_correct": true, "rationale": "R.A. 10592 grants two-fifths to PDLs who chose to stay despite the calamity."}, {"text": "No deduction, since he did nothing", "is_correct": false, "rationale": "Choosing to stay is rewarded by law."}, {"text": "An additional 15 days per month", "is_correct": false, "rationale": "Fifteen days per month is the allowance for teaching, studying or mentoring."}]'::jsonb, 1, 'hard', 'The reward recognizes loyalty during emergencies.', 'Revised Penal Code, Art. 98, as amended by R.A. 10592', 'Study module Correctional Administration, Chapter 2: Non-Institutional Correction (CA-2.5).', 'generated', 'tos_2024', 1, FALSE, 'CA-2.5', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-2.5_05', 'corrections', 'Non-Institutional Correction', 'A recidivist detainee asks for credit for his preventive imprisonment. How should his request be evaluated?', '[{"text": "Grant full credit, since all detainees are covered", "is_correct": false, "rationale": "Not all detainees are covered."}, {"text": "Deny it; recidivists are excluded from the credit", "is_correct": true, "rationale": "Article 29, as amended, excludes recidivists, habitual delinquents, escapees and persons charged with heinous crimes."}, {"text": "Grant double credit, since he has more experience", "is_correct": false, "rationale": "There is no double credit in the law."}, {"text": "Grant it only if his first case was minor", "is_correct": false, "rationale": "The exclusion does not depend on the first offense."}]'::jsonb, 1, 'hard', 'Exclusions are applied as the law states them.', 'Revised Penal Code, Art. 29, as amended by R.A. 10592', 'Study module Correctional Administration, Chapter 2: Non-Institutional Correction (CA-2.5).', 'generated', 'tos_2024', 1, FALSE, 'CA-2.5', 'Evaluating') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-2.5_06', 'corrections', 'Non-Institutional Correction', 'A warden grants 20 days per month of GCTA to a PDL in his fourth year of good conduct. Is this correct?', '[{"text": "Yes; it is 20 days for every year", "is_correct": false, "rationale": "Twenty days apply only to the first two years."}, {"text": "No; from the third to the fifth year it is 23 days", "is_correct": true, "rationale": "Article 97 grants 23 days per month from the third to the fifth year."}, {"text": "No; it should be 30 days in the fourth year", "is_correct": false, "rationale": "Thirty days apply from the eleventh year."}, {"text": "Yes; the warden may choose any number", "is_correct": false, "rationale": "The allowance is fixed by law."}]'::jsonb, 1, 'hard', 'Correct computation affects the PDL''s release date.', 'Revised Penal Code, Art. 97, as amended by R.A. 10592', 'Study module Correctional Administration, Chapter 2: Non-Institutional Correction (CA-2.5).', 'generated', 'tos_2024', 1, FALSE, 'CA-2.5', 'Evaluating') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-2.5_07', 'corrections', 'Non-Institutional Correction', 'A jail officer says that a PDL''s earned time allowances will be cancelled because he misbehaved this month. How should this be evaluated?', '[{"text": "Correct; allowances can be revoked at any time", "is_correct": false, "rationale": "Granted allowances cannot be revoked."}, {"text": "Correct; misbehavior cancels all past allowances", "is_correct": false, "rationale": "Past grants stay; only future grants are affected."}, {"text": "Incorrect; granted allowances cannot be revoked", "is_correct": true, "rationale": "Article 99 makes granted allowances irrevocable, though misbehavior can bar future grants."}, {"text": "Incorrect; misbehavior has no effect at all", "is_correct": false, "rationale": "Misbehavior can still affect future allowances and discipline."}]'::jsonb, 2, 'hard', 'Disciplinary measures for the misbehavior follow due process.', 'Revised Penal Code, Art. 99, as amended by R.A. 10592', 'Study module Correctional Administration, Chapter 2: Non-Institutional Correction (CA-2.5).', 'generated', 'tos_2024', 1, FALSE, 'CA-2.5', 'Evaluating') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-2.5_08', 'corrections', 'Non-Institutional Correction', 'A PDL in his eleventh year of good conduct also teaches in the jail school. How many days per month may he earn in total?', '[{"text": "30 days", "is_correct": false, "rationale": "Thirty days is GCTA alone."}, {"text": "25 days", "is_correct": false, "rationale": "Twenty-five days apply to the sixth to tenth years."}, {"text": "15 days", "is_correct": false, "rationale": "Fifteen days is the teaching allowance alone."}, {"text": "45 days", "is_correct": true, "rationale": "From the eleventh year he earns 30 days of GCTA, plus 15 days for teaching: 45 days per month."}]'::jsonb, 3, 'hard', 'Both allowances are credited together.', 'Revised Penal Code, Art. 97, as amended by R.A. 10592', 'Study module Correctional Administration, Chapter 2: Non-Institutional Correction (CA-2.5).', 'generated', 'tos_2024', 1, FALSE, 'CA-2.5', 'Evaluating') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-3.1_01', 'corrections', 'Therapeutic Modalities', 'Which treatment approach uses the community of PDLs itself as the main agent of change?', '[{"text": "Therapeutic Community", "is_correct": true, "rationale": "The Therapeutic Community is a self-help, social learning approach where the community helps each member change."}, {"text": "Solitary confinement", "is_correct": false, "rationale": "Solitary confinement isolates, which is the opposite."}, {"text": "Electroconvulsive therapy", "is_correct": false, "rationale": "Electroconvulsive therapy is a psychiatric treatment, not a correctional modality."}, {"text": "Work release only", "is_correct": false, "rationale": "Work release is a program, not a community-based treatment model."}]'::jsonb, 0, 'easy', 'The BJMP and BuCor use the Therapeutic Community Modality Program.', NULL, 'Study module Correctional Administration, Chapter 3: Therapeutic Modalities (CA-3.1).', 'generated', 'tos_2024', 1, FALSE, 'CA-3.1', 'Remembering') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-3.1_02', 'corrections', 'Therapeutic Modalities', 'Which component of the Therapeutic Community teaches job skills for life after release?', '[{"text": "Vocational and survival skills", "is_correct": true, "rationale": "The vocational and survival skills component prepares PDLs for work and daily living."}, {"text": "Behavior management", "is_correct": false, "rationale": "Behavior management shapes conduct through rules and consequences."}, {"text": "Emotional and psychological", "is_correct": false, "rationale": "The emotional and psychological component deals with feelings."}, {"text": "Intellectual and spiritual", "is_correct": false, "rationale": "The intellectual and spiritual component develops thinking and values."}]'::jsonb, 0, 'easy', 'The four components work together in the TC program.', NULL, 'Study module Correctional Administration, Chapter 3: Therapeutic Modalities (CA-3.1).', 'generated', 'tos_2024', 1, FALSE, 'CA-3.1', 'Remembering') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-3.1_03', 'corrections', 'Therapeutic Modalities', 'Why does behavior management in the Therapeutic Community use rewards and sanctions?', '[{"text": "To reinforce good behavior and discourage harmful behavior", "is_correct": true, "rationale": "Behavior shaping applies operant conditioning: rewards strengthen prosocial behavior and sanctions weaken harmful behavior."}, {"text": "To punish PDLs as harshly as possible", "is_correct": false, "rationale": "The aim is change, not harshness."}, {"text": "To let PDLs do as they please without rules", "is_correct": false, "rationale": "Clear rules are central to behavior management."}, {"text": "To decide which PDLs will be released", "is_correct": false, "rationale": "Release is decided by courts and the Board."}]'::jsonb, 0, 'easy', 'Consistent consequences make the rules meaningful.', NULL, 'Study module Correctional Administration, Chapter 3: Therapeutic Modalities (CA-3.1).', 'generated', 'tos_2024', 1, FALSE, 'CA-3.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-3.1_04', 'corrections', 'Therapeutic Modalities', 'What does the emotional and psychological component of the Therapeutic Community address?', '[{"text": "Training PDLs in carpentry and welding skills", "is_correct": false, "rationale": "Vocational skills belong to another component."}, {"text": "Teaching PDLs to read and write", "is_correct": false, "rationale": "Literacy belongs to the intellectual component."}, {"text": "Helping PDLs understand and manage feelings", "is_correct": true, "rationale": "This component helps PDLs handle emotions through counseling and group sessions."}, {"text": "Organizing sports competitions", "is_correct": false, "rationale": "Sports belong to recreational programs."}]'::jsonb, 2, 'easy', 'Unmanaged emotions often contribute to offending.', NULL, 'Study module Correctional Administration, Chapter 3: Therapeutic Modalities (CA-3.1).', 'generated', 'tos_2024', 1, FALSE, 'CA-3.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-3.1_05', 'corrections', 'Therapeutic Modalities', 'Why are education and spiritual programs part of rehabilitation?', '[{"text": "They replace the need for any security in the jail", "is_correct": false, "rationale": "Security is still needed."}, {"text": "They are only ways to pass the time", "is_correct": false, "rationale": "These programs have rehabilitative aims."}, {"text": "They are required for every PDL''s release by law", "is_correct": false, "rationale": "They help, but release follows legal processes."}, {"text": "They change thinking and values and improve chances of a lawful life", "is_correct": true, "rationale": "Education and values formation help PDLs think differently and find lawful work."}]'::jsonb, 3, 'easy', 'The Alternative Learning System is offered in many jails.', NULL, 'Study module Correctional Administration, Chapter 3: Therapeutic Modalities (CA-3.1).', 'generated', 'tos_2024', 1, FALSE, 'CA-3.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-3.1_06', 'corrections', 'Therapeutic Modalities', 'Why does cognitive therapy focus on a PDL''s ''thinking errors''?', '[{"text": "Thinking has no link to behavior", "is_correct": false, "rationale": "Thought and behavior are closely linked."}, {"text": "It aims to make PDLs forget their crimes", "is_correct": false, "rationale": "The aim is change, not forgetting."}, {"text": "It is used only for PDLs with physical illnesses", "is_correct": false, "rationale": "It is used for behavior, not physical illness."}, {"text": "Changing distorted thinking helps change behavior", "is_correct": true, "rationale": "Cognitive approaches hold that how people think shapes how they act, so correcting distortions changes behavior."}]'::jsonb, 3, 'easy', 'Examples of thinking errors include blaming others and minimizing harm.', NULL, 'Study module Correctional Administration, Chapter 3: Therapeutic Modalities (CA-3.1).', 'generated', 'tos_2024', 1, FALSE, 'CA-3.1', 'Understanding') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-3.2_01', 'corrections', 'Therapeutic Modalities', 'A PDL never finished high school. Which program should the jail offer him?', '[{"text": "Alternative Learning System (ALS) classes", "is_correct": true, "rationale": "ALS lets PDLs complete basic education inside the facility."}, {"text": "Solitary confinement for reflection", "is_correct": false, "rationale": "Isolation does not provide education."}, {"text": "Early release to study outside", "is_correct": false, "rationale": "Release needs a legal basis."}, {"text": "Work in the jail kitchen only", "is_correct": false, "rationale": "Kitchen work alone does not give education."}]'::jsonb, 0, 'medium', 'Studying may also earn time allowances.', 'Revised Penal Code, Art. 97, as amended by R.A. 10592', 'Study module Correctional Administration, Chapter 3: Therapeutic Modalities (CA-3.2).', 'generated', 'tos_2024', 1, FALSE, 'CA-3.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-3.2_02', 'corrections', 'Therapeutic Modalities', 'A PDL has a long history of drug dependence. Which program suits him?', '[{"text": "A longer stay in isolation", "is_correct": false, "rationale": "Isolation does not treat dependence."}, {"text": "No program, since drugs are not allowed in jail", "is_correct": false, "rationale": "Absence of drugs does not end dependence."}, {"text": "Therapeutic Community modality or drug rehabilitation program", "is_correct": true, "rationale": "The TC modality and drug rehabilitation programs address addiction and behavior."}, {"text": "Transfer to a jail with no programs", "is_correct": false, "rationale": "Moving him to a place without programs ignores his needs."}]'::jsonb, 2, 'medium', 'Untreated dependence raises the risk of relapse and reoffending.', NULL, 'Study module Correctional Administration, Chapter 3: Therapeutic Modalities (CA-3.2).', 'generated', 'tos_2024', 1, FALSE, 'CA-3.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-3.2_03', 'corrections', 'Therapeutic Modalities', 'A PDL will be released in six months. Which program should start now?', '[{"text": "Pre-release preparation, with job and family reintegration", "is_correct": true, "rationale": "Pre-release programs prepare PDLs for work, housing and family life after release."}, {"text": "Nothing, since release will take care of itself", "is_correct": false, "rationale": "Unprepared release increases the risk of reoffending."}, {"text": "Transfer to a maximum security facility", "is_correct": false, "rationale": "Higher security is not needed for reintegration."}, {"text": "Suspension of all his visits", "is_correct": false, "rationale": "Family contact supports reintegration."}]'::jsonb, 0, 'medium', 'Coordination with the PPA, LGUs and families is part of reintegration.', NULL, 'Study module Correctional Administration, Chapter 3: Therapeutic Modalities (CA-3.2).', 'generated', 'tos_2024', 1, FALSE, 'CA-3.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-3.2_04', 'corrections', 'Therapeutic Modalities', 'PDLs make handicrafts that are sold at the jail''s outlet. What is the purpose of this program?', '[{"text": "To make the jail a profitable business for staff", "is_correct": false, "rationale": "Earnings are not for the personal profit of staff."}, {"text": "To build skills and earn income through livelihood", "is_correct": true, "rationale": "Livelihood programs build skills and let PDLs earn for themselves and their families."}, {"text": "To punish PDLs with forced labor", "is_correct": false, "rationale": "Participation is part of rehabilitation, not punishment."}, {"text": "To keep PDLs away from their families", "is_correct": false, "rationale": "Livelihood helps support families."}]'::jsonb, 1, 'medium', 'Earnings are handled under the facility''s rules.', NULL, 'Study module Correctional Administration, Chapter 3: Therapeutic Modalities (CA-3.2).', 'generated', 'tos_2024', 1, FALSE, 'CA-3.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-3.2_05', 'corrections', 'Therapeutic Modalities', 'A PDL complains that he has been denied medical care for weeks. What should the jail do?', '[{"text": "Give him access to proper medical care at once", "is_correct": true, "rationale": "The Mandela Rules require health care for PDLs equal to that in the community."}, {"text": "Tell him that PDLs have no right to medical care", "is_correct": false, "rationale": "PDLs keep their right to health care."}, {"text": "Make him pay before seeing a doctor", "is_correct": false, "rationale": "Basic health care must not depend on payment."}, {"text": "Wait until his release to treat him", "is_correct": false, "rationale": "Delay can worsen his condition."}]'::jsonb, 0, 'medium', 'Health care is a State responsibility for persons in custody.', 'UN Standard Minimum Rules for the Treatment of Prisoners (Mandela Rules), Rule 24', 'Study module Correctional Administration, Chapter 3: Therapeutic Modalities (CA-3.2).', 'generated', 'tos_2024', 1, FALSE, 'CA-3.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-3.2_06', 'corrections', 'Therapeutic Modalities', 'A PDL of a minority faith wants to practice his religion. How should the jail respond?', '[{"text": "Forbid it, since only one religion is allowed", "is_correct": false, "rationale": "Freedom of religion covers all faiths."}, {"text": "Allow it only if he converts first", "is_correct": false, "rationale": "Forced conversion violates religious freedom."}, {"text": "Allow and assist it within security rules", "is_correct": true, "rationale": "The Mandela Rules protect religious practice, subject to security needs."}, {"text": "Ignore the request completely", "is_correct": false, "rationale": "Ignoring the request denies his rights."}]'::jsonb, 2, 'medium', 'Religious programs also support rehabilitation.', 'UN Standard Minimum Rules for the Treatment of Prisoners (Mandela Rules), Rules 65-66', 'Study module Correctional Administration, Chapter 3: Therapeutic Modalities (CA-3.2).', 'generated', 'tos_2024', 1, FALSE, 'CA-3.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-3.2_07', 'corrections', 'Therapeutic Modalities', 'A PDL''s family lives far away and cannot visit often. How can the jail help maintain contact?', '[{"text": "Ban all contact with them until he is released", "is_correct": false, "rationale": "Family ties support rehabilitation."}, {"text": "Arrange regulated contact, such as video calls", "is_correct": true, "rationale": "Regulated contact, including video visits, keeps family ties while keeping security."}, {"text": "Allow him to keep a personal cellphone", "is_correct": false, "rationale": "Personal cellphones are contraband."}, {"text": "Tell him to forget his family", "is_correct": false, "rationale": "Family support reduces reoffending."}]'::jsonb, 1, 'medium', 'Video visitation was widely used in jails during the pandemic.', NULL, 'Study module Correctional Administration, Chapter 3: Therapeutic Modalities (CA-3.2).', 'generated', 'tos_2024', 1, FALSE, 'CA-3.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-3.2_08', 'corrections', 'Therapeutic Modalities', 'Under the Mandela Rules, how much outdoor exercise should PDLs who are not doing outdoor work have each day?', '[{"text": "At least one hour, if weather permits", "is_correct": true, "rationale": "Rule 23 provides at least one hour of suitable exercise in the open air daily, if weather permits."}, {"text": "At least ten minutes per week", "is_correct": false, "rationale": "Ten minutes a week is far below the standard."}, {"text": "None, since exercise is a privilege", "is_correct": false, "rationale": "Exercise is a minimum standard, not a privilege."}, {"text": "Only on national holidays", "is_correct": false, "rationale": "It is daily, not only on holidays."}]'::jsonb, 0, 'medium', 'Exercise supports physical and mental health.', 'UN Standard Minimum Rules for the Treatment of Prisoners (Mandela Rules), Rule 23', 'Study module Correctional Administration, Chapter 3: Therapeutic Modalities (CA-3.2).', 'generated', 'tos_2024', 1, FALSE, 'CA-3.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-3.2_09', 'corrections', 'Therapeutic Modalities', 'A woman PDL gives birth while in custody. How should decisions about her infant be made?', '[{"text": "Based on the best interests of the child", "is_correct": true, "rationale": "The Bangkok Rules require decisions on children staying with mothers to be based on the child''s best interests."}, {"text": "Based only on the jail''s convenience", "is_correct": false, "rationale": "Convenience is not the standard."}, {"text": "The infant must always be removed at once", "is_correct": false, "rationale": "Automatic removal ignores the child''s interests."}, {"text": "The infant must stay with her until age ten", "is_correct": false, "rationale": "No fixed age applies; the child''s interests decide."}]'::jsonb, 0, 'medium', 'Facilities must meet the needs of mothers and infants.', 'UN Bangkok Rules, Rules 49-52', 'Study module Correctional Administration, Chapter 3: Therapeutic Modalities (CA-3.2).', 'generated', 'tos_2024', 1, FALSE, 'CA-3.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-3.2_10', 'corrections', 'Therapeutic Modalities', 'A PDL with a known mental illness acts strangely and refuses meals. How should the jail respond?', '[{"text": "Punish him for disobedience", "is_correct": false, "rationale": "Punishing illness worsens it and violates rights."}, {"text": "Refer him to mental health services for assessment", "is_correct": true, "rationale": "Symptoms of illness need assessment and treatment, not punishment."}, {"text": "Ignore him until he behaves normally", "is_correct": false, "rationale": "Ignoring him risks his health."}, {"text": "Transfer him to a crowded cell", "is_correct": false, "rationale": "Crowding may make his condition worse."}]'::jsonb, 1, 'medium', 'R.A. 11036 protects the rights of persons with mental health conditions.', 'R.A. 11036 (Mental Health Act)', 'Study module Correctional Administration, Chapter 3: Therapeutic Modalities (CA-3.2).', 'generated', 'tos_2024', 1, FALSE, 'CA-3.2', 'Applying') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-3.3_01', 'corrections', 'Therapeutic Modalities', 'Why does the Therapeutic Community use a ''family'' structure with peer responsibility?', '[{"text": "Peers confront and support each other in the community", "is_correct": true, "rationale": "The TC uses the community as method: members hold each other accountable and model change."}, {"text": "It saves the jail from hiring any staff", "is_correct": false, "rationale": "Staff still guide and supervise the program."}, {"text": "It lets the strongest PDLs control all the others", "is_correct": false, "rationale": "The TC is structured to prevent abuse by strong members."}, {"text": "It is only a way to group PDLs by age", "is_correct": false, "rationale": "Grouping is by program structure, not just age."}]'::jsonb, 0, 'hard', 'Social learning inside the community supports lasting change.', NULL, 'Study module Correctional Administration, Chapter 3: Therapeutic Modalities (CA-3.3).', 'generated', 'tos_2024', 1, FALSE, 'CA-3.3', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-3.3_02', 'corrections', 'Therapeutic Modalities', 'Why do reintegration programs involve the PDL''s family and community before release?', '[{"text": "Families must pay for the PDL''s programs", "is_correct": false, "rationale": "Programs are not paid for by families."}, {"text": "Communities decide whether the PDL will be released", "is_correct": false, "rationale": "Release is decided by courts and the Board."}, {"text": "Families are needed only to sign papers", "is_correct": false, "rationale": "Their role goes beyond paperwork."}, {"text": "Support and acceptance after release reduce reoffending", "is_correct": true, "rationale": "Family and community support help with housing, work and acceptance, which lower recidivism."}]'::jsonb, 3, 'hard', 'Stigma can push former PDLs back into crime.', NULL, 'Study module Correctional Administration, Chapter 3: Therapeutic Modalities (CA-3.3).', 'generated', 'tos_2024', 1, FALSE, 'CA-3.3', 'Analyzing') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-3.3_03', 'corrections', 'Therapeutic Modalities', 'Which program design is most likely to reduce reoffending after release?', '[{"text": "Continuing aftercare with job placement and supervision", "is_correct": true, "rationale": "Aftercare and job support address the needs that often lead to reoffending."}, {"text": "Release with no follow-up or support", "is_correct": false, "rationale": "Unsupported release leaves needs unmet."}, {"text": "Longer sentences for every PDL", "is_correct": false, "rationale": "Longer sentences alone do not reduce recidivism."}, {"text": "Banning former PDLs from their barangays", "is_correct": false, "rationale": "Banishment increases marginalization."}]'::jsonb, 0, 'hard', 'The PPA and LGUs share responsibility for aftercare.', NULL, 'Study module Correctional Administration, Chapter 3: Therapeutic Modalities (CA-3.3).', 'generated', 'tos_2024', 1, FALSE, 'CA-3.3', 'Evaluating') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, subject_id, topic, question_text, options, correct_answer_index, difficulty, explanation, legal_basis, remediation_hint, source, template_id, version, is_active, tos_code, bloom_level) VALUES ('tos24_CA-3.3_04', 'corrections', 'Therapeutic Modalities', 'A town proposes to bar all former PDLs from any job in the local government. How should this policy be evaluated?', '[{"text": "It is ideal, since former PDLs cannot change", "is_correct": false, "rationale": "Rehabilitation assumes people can change."}, {"text": "It is required by the Constitution", "is_correct": false, "rationale": "The Constitution does not require such bans."}, {"text": "It has no effect on reintegration", "is_correct": false, "rationale": "Employment strongly affects reintegration."}, {"text": "It hinders reintegration; a case-by-case review is fairer", "is_correct": true, "rationale": "Blanket bans increase stigma and unemployment, which raise reoffending; case-by-case review balances safety and fairness."}]'::jsonb, 3, 'hard', 'Some positions may lawfully have specific requirements, but blanket exclusion is broad.', NULL, 'Study module Correctional Administration, Chapter 3: Therapeutic Modalities (CA-3.3).', 'generated', 'tos_2024', 1, FALSE, 'CA-3.3', 'Evaluating') ON CONFLICT DO NOTHING;
